// 単語ごとの例文（英語・日本語訳・強調する語）。出典：田中コーパス／Tatoebaプロジェクト（CC BY 2.0 FR）。 ※make_examples.py で自動生成
EXAMPLES[1]=["I am the tallest of the three.","私は三人のうちで一番背が高い。","the"];
EXAMPLES[2]=["I really don't want to go.","私はどうしても行きたくない。","to"];
EXAMPLES[3]=["He was running and calling for help.","彼は走りながら助けを求めた。","and"];
EXAMPLES[4]=["I often get a letter from him.","私はたびたび彼から手紙をもらう。","a"];
EXAMPLES[5]=["He wanted to be in the newspapers.","彼は新聞に自分の顔を発表したかった。","in"];
EXAMPLES[6]=["I spent three hours repairing the car.","私はその車を修理するのに３時間かかった。","I"];
EXAMPLES[7]=["There is no man but desires peace.","平和を望まないものはいない。","is"];
EXAMPLES[8]=["What was it that you gave him?","一体何を彼にあげたのですか。","that"];
EXAMPLES[9]=["I have known him for ten years.","彼とは１０年来の知り合いだ。","for"];
EXAMPLES[10]=["It is strange that you should fail.","君が失敗するなんて不思議だ。","you"];
EXAMPLES[11]=["I lost no time in doing it.","時を移さずそうした。","it"];
EXAMPLES[12]=["I passed on the job to him.","その仕事を彼にゆずった。","on"];
EXAMPLES[13]=["I went to nikko along with them.","私は彼らと一緒に日光へ行きました。","with"];
EXAMPLES[14]=["This is his answer to my letter.","これが私の手紙に対する彼の返事だ。","This"];
EXAMPLES[15]=["It was very nice seeing you again.","あなたに会えてとてもうれしかったです。","was"];
EXAMPLES[16]=["She'll be getting married next year.","彼女は来年結婚する。","be"];
EXAMPLES[17]=["Jane is as old as I am.","ジェーンは私と同じ年齢です。","as"];
EXAMPLES[18]=["We are all convinced of his success.","私たちはみんな彼の成功を確信している。","are"];
EXAMPLES[19]=["I have a little money this month.","今月はとても金欠だ。","have"];
EXAMPLES[20]=["Meg didn't even look at me.","メグは私を見もしなかった。","at"];
EXAMPLES[21]=["He paid the money into his account.","彼はそのお金を口座に払い込んだ。","He"];
EXAMPLES[22]=["Rome was not built in a day.","一朝一夕にはできない。","not"];
EXAMPLES[23]=["It is cheaper to go by bus.","バスで行った方が安くつく。","by"];
EXAMPLES[24]=["There was no one but admired him.","彼をほめない人など誰もいなかった。","but"];
EXAMPLES[25]=["He is far from being a gentleman.","決して彼は紳士ではない。","from"];
EXAMPLES[26]=["My father lives and works in Tokyo.","父は東京にいて、そこで働いています。","My"];
EXAMPLES[27]=["We delayed the meeting for a week.","私たちは会議を一週間延ばした。","We"];
EXAMPLES[28]=["I waited for him for an hour.","私は彼を１時間待った。","an"];
EXAMPLES[29]=["He will go along with your plan.","彼はあなたの計画に同調するだろう。","your"];
EXAMPLES[30]=["I'm surprised you came at all.","そもそも君が来たとは驚いた。","all"];
EXAMPLES[31]=["Don't be so hard on me.","キツイなあ。","so"];
EXAMPLES[32]=["He turned to his friends for help.","彼は友人たちに助けを求めた。","his"];
EXAMPLES[33]=["They are going to emigrate to America.","彼らはアメリカに移住するつもりです。","They"];
EXAMPLES[34]=["He is a good match for me.","彼なら相手にとって不足なし。","me"];
EXAMPLES[35]=["This car is bigger than that one.","この車はあの車より大きい。","one"];
EXAMPLES[36]=["I can see his hand in this.","これは彼の手がけたものと私には分かる。","can"];
EXAMPLES[37]=["This will do for the time being.","当分の間これでやっていける。","will"];
EXAMPLES[38]=["Repeat what I have just told you.","私が今あなたに言ったことを繰り返しなさい。","just"];
EXAMPLES[39]=["I don't like what he said.","私は彼が言った事が気に食わない。","like"];
EXAMPLES[40]=["He doesn't know much about Japan.","彼は日本について良く知りません。","about"];
EXAMPLES[41]=["He has set up a new business.","彼は新しい商売を始めた。","up"];
EXAMPLES[42]=["Sorry, but he is out now.","あいにくですが、彼は外出中です。","out"];
EXAMPLES[43]=["This is what I was waiting for.","これを待ち望んでいました。","what"];
EXAMPLES[44]=["She had already gone when I arrived.","私が着いたとき彼女はもう出た後だった。","when"];
EXAMPLES[45]=["Do you happen to know his name?","あなたは彼の名前を偶然知っていませんか。","Do"];
EXAMPLES[46]=["She has no more than 100 dollars.","彼女は１００ドルしか持っていない。","no"];
EXAMPLES[47]=["He who makes no mistakes makes nothing.","過ちのない者は何も作り出せない。","who"];
EXAMPLES[48]=["They made their way through the crowd.","彼らは群集をかき分けて進んだ。","their"];
EXAMPLES[49]=["I can play baseball, tennis, volleyball, and so on.","私は野球、テニス、バレーボールなどをすることができます。","and so on"];
EXAMPLES[50]=["I had to help with the housework.","家の手伝いをしないといけなかったの。","had"];
EXAMPLES[51]=["I'll get there before you will.","私が先にそこへ着くよ。","there"];
EXAMPLES[52]=["I managed to get there in time.","わたしはどうにかそこに着くのに間に合った。","time"];
EXAMPLES[53]=["Do you get on with your friends?","友達と仲良くやっていますか。","get"];
EXAMPLES[54]=["She did not answer all the questions.","彼女は必ずしもすべての質問に答えたわけではない。","She"];
EXAMPLES[55]=["I am always forgetting people's names.","私はいつも人の名前を忘れてばかりいる。","people"];
EXAMPLES[56]=["His car looks as good as new.","彼の車は新車同然に見える。","new"];
EXAMPLES[57]=["How is it she does not come?","どうして彼女は来ないのか。","How"];
EXAMPLES[58]=["Please help yourself to some more cake.","もっとケーキをご自由に食べてください。","some"];
EXAMPLES[59]=["We came upon them in new york.","我々はニューヨークで彼らに出くわした。","them"];
EXAMPLES[60]=["He is also very famous in Japan.","彼は日本でもとても有名だ。","also"];
EXAMPLES[61]=["Everything is ready now for our start.","さあ出発の準備はすべて出来ました。","now"];
EXAMPLES[62]=["He is taller than any other boy.","彼は他のどの少年よりも背が高い。","other"];
EXAMPLES[63]=["The child is lonesome for its mother.","子供は母親にあいたがっている。","its"];
EXAMPLES[64]=["That has no bearing on our plan.","それは我々の計画とはなんの関係もない。","our"];
EXAMPLES[65]=["Not only he but I am wrong.","彼ばかりでなく私もまちがっている。","only"];
EXAMPLES[66]=["I will remember your kindness for good.","永久にあなたの親切を忘れません。","good"];
EXAMPLES[67]=["I haven't seen him for years.","何年も彼に会ってません。","him"];
EXAMPLES[68]=["We learned what we should do first.","私たちは最初に何をすべきかを習った。","first"];
EXAMPLES[69]=["After a while, he came to.","しばらくして、彼は正気づいた。","After"];
EXAMPLES[70]=["I don't know what to do.","私はどうしてよいのかわかりません。","know"];
EXAMPLES[71]=["I can't see what you mean.","君の言うことの意味が分からない。","see"];
EXAMPLES[72]=["I am two years younger than he.","私は彼より２歳若い。","two"];
EXAMPLES[73]=["How can I make a long-distance call?","どうすれば長距離電話がかけられますか。","make"];
EXAMPLES[74]=["I think he is a good man.","思うに彼は善人だ。","think"];
EXAMPLES[75]=["We talked over the plan with him.","我々はその計画について彼と話し合った。","over"];
EXAMPLES[76]=["I will not see him any more.","私はもう彼に会わない。","any"];
EXAMPLES[77]=["Could you please make room for me?","場所を空けて下さいませんか。","Could"];
EXAMPLES[78]=["Please get these letters off right away.","これらの手紙をすぐに郵送してください。","these"];
EXAMPLES[79]=["That's what I want to say!","それはこっちのセリフですよ。","want"];
EXAMPLES[80]=["Would you please call him back later?","後ほど、またお電話いただけますか。","back"];
EXAMPLES[81]=["He backed us up in the case.","彼はその事件で私たちを支援してくれた。","us"];
EXAMPLES[82]=["I am assumed to go to London.","私はロンドンに行くことになっている。","go"];
EXAMPLES[83]=["Well, I think jogging is good.","ええと、私はジョギングはよいと思う。","Well"];
EXAMPLES[84]=["He said that you ought to go.","あなたは行くべきだと彼は言った。","said"];
EXAMPLES[85]=["Would you please tell me the way?","どうぞ道を教えてくださいませんか。","way"];
EXAMPLES[86]=["I'm very grateful for your help.","あなたの援助に大変感謝しています。","very"];
EXAMPLES[87]=["Take as much as you want to.","欲しいだけ取りなさい。","much"];
EXAMPLES[88]=["He did not know where to go.","彼はどこへ行ったらいいか分からなかった。","where"];
EXAMPLES[89]=["May I have your name, please?","あなたの名前は何ですか。","May"];
EXAMPLES[90]=["Well, here we are at last!","やっと着いた。","here"];
EXAMPLES[91]=["I need some help with my work.","私の仕事には手助けがいる。","need"];
EXAMPLES[92]=["It is really quite a good story.","それは実に全くよい話だ。","really"];
EXAMPLES[93]=["Why do you have to work late?","なぜ残業しないといけないのですか。","work"];
EXAMPLES[94]=["That's right, isn't it?","ねえ、そうでしょう。","right"];
EXAMPLES[95]=["Did you live in sasayama last year?","あなたは去年篠山に住んでいましたか。","year"];
EXAMPLES[96]=["The day is getting longer and longer.","日はだんだん長くなる。","day"];
EXAMPLES[97]=["I've got too much to do.","私はやるべきことを山積みにしている。","too"];
EXAMPLES[98]=["She was a wakahata before she married.","結婚する前、彼女は若畑家の人だった。","before"];
EXAMPLES[99]=["Why don't you come with me?","私と一緒に来ない。","Why"];
EXAMPLES[100]=["We have to call off the meeting.","ミーティングを中止しなければならない。","off"];
EXAMPLES[101]=["Do you take me for a fool?","君は僕を馬鹿だと思っていたね。","take"];
EXAMPLES[102]=["I still have some feelings for her.","彼女にはまだ未練がある。","still"];
EXAMPLES[103]=["My leaving early made them feel sorry.","私が早く去るので彼らは残念がった。","made"];
EXAMPLES[104]=["He gains many friends through his honesty.","彼は正直なので多くの友人がいる。","many"];
EXAMPLES[105]=["It's about time you got here!","君はとっくにここにいなきゃいけないはずだ。","got"];
EXAMPLES[106]=["He never seems to feel the cold.","彼は決して寒さを感じないようだ。","never"];
EXAMPLES[107]=["Are those the people you saw yesterday?","あの人たちが昨日あなたが会った方々ですか。","those"];
EXAMPLES[108]=["I don't know what to say.","何を言えばよいのか分からない。","say"];
EXAMPLES[109]=["Life is a long and winding road.","人生は長い曲がりくねった道だ。","Life"];
EXAMPLES[110]=["My wife is ignorant of the world.","妻は世間知らずです。","world"];
EXAMPLES[111]=["He walked up and down the room.","彼は部屋をあちこち歩いた。","down"];
EXAMPLES[112]=["She was a great help to me.","彼女はとても私の助けになった。","great"];
EXAMPLES[113]=["Well, we've finished at last.","ああ、やっと終わった。","last"];
EXAMPLES[114]=["He is by far the best student.","彼はとてもできる生徒だ。","best"];
EXAMPLES[115]=["What a thoughtless man to do that!","そんなことをするなんて何と無分別な男だ。","man"];
EXAMPLES[116]=["I'm filled with love for you.","あなたを愛することでいっぱい。","love"];
EXAMPLES[117]=["Do you look up to your parents?","あなたは両親を尊敬していますか。","look"];
EXAMPLES[118]=["It's no use arguing with him.","彼と論議しても無駄だ。","use"];
EXAMPLES[119]=["Have something to eat just in case.","念のため、何か食べておきなさい。","something"];
EXAMPLES[120]=["It was not long before she came.","彼女はほどなくやってきた。","long"];
EXAMPLES[121]=["My father may be at home now.","父は今家にいるだろう。","home"];
EXAMPLES[122]=["I bought the same shirt as yours.","君と同じシャツを買った。","same"];
EXAMPLES[123]=["He called me up almost every day.","彼は毎日のように電話をしてきた。","every"];
EXAMPLES[124]=["It is probable that Jane will come.","十中八九ジェーンは来るだろう。","come"];
EXAMPLES[125]=["My watch loses three minutes a week.","私の時計は週に３分遅れる。","three"];
EXAMPLES[126]=["He is much taller than I am.","彼は僕よりずっと背が高い。","am"];
EXAMPLES[127]=["There was no objection on his part.","彼のほうには異議はなかった。","part"];
EXAMPLES[128]=["I looked around, but saw nobody.","私は見回したけれど誰もいなかった。","around"];
EXAMPLES[129]=["I am always at home on Sundays.","私は日曜日にいつも家にいる。","always"];
EXAMPLES[130]=["Any bed is better than no bed.","どんなベッドでもないよりはよい。","better"];
EXAMPLES[131]=["How old will you be next year?","来年は何歳になりますか。","old"];
EXAMPLES[132]=["He is doing it with my help.","彼は私を頼りにしている。","help"];
EXAMPLES[133]=["He is not a high school student.","彼は高等学校の生徒ではありません。","high"];
EXAMPLES[134]=["We need another person to play cards.","トランプをするのにもう一人必要だ。","another"];
EXAMPLES[135]=["She drinks a little wine at times.","彼女は時々酒を飲む。","a little"];
EXAMPLES[136]=["There are some boys under the tree.","木の下に何人かの少年がいます。","under"];
EXAMPLES[137]=["How did such a thing come about?","どうしてそんなことが起こったのか。","thing"];
EXAMPLES[138]=["It must have rained during the night.","夜の間にきっと雨が降ったのだろう。","during"];
EXAMPLES[139]=["I like to watch a baseball game.","私は野球の試合を見るのが好きだ。","game"];
EXAMPLES[140]=["Please give me leave to go home.","家に帰る許可を下さい。","give"];
EXAMPLES[141]=["What subjects are you taking at school?","君は学校で何の科目を取っていますか。","school"];
EXAMPLES[142]=["He acted like he owned the place.","彼が大きな顔をしていた。","place"];
EXAMPLES[143]=["Jane begged to see my new house.","ジェーンは私の新居を見たいと頼んだ。","house"];
EXAMPLES[144]=["Never again did she enter the house.","２度と彼女はその家の敷居をまたがなかった。","again"];
EXAMPLES[145]=["We've fixed on starting next Sunday.","我々は次の日曜日に出発することに決めた。","next"];
EXAMPLES[146]=["We haven't known each other long.","我々は知り合ってからまだ日が浅い。","each"];
EXAMPLES[147]=["Did you hear my show last night?","昨日の晩、私のショーを聞いてくれた？","show"];
EXAMPLES[148]=["He did the work against his will.","彼はいやいやその仕事をした。","against"];
EXAMPLES[149]=["This is the end of my story.","これで私の話は終わりです。","end"];
EXAMPLES[150]=["This work must be finished by tomorrow.","この仕事は明日までに終えなければならない。","must"];
EXAMPLES[151]=["I feel as if I were dreaming.","私はまるで夢を見ているようです。","feel"];
EXAMPLES[152]=["You look just like your big brother.","君はお兄さんにそっくりだよ。","big"];
EXAMPLES[153]=["I'm sure he will come tomorrow.","彼は明日きっとくると思います。","sure"];
EXAMPLES[154]=["Would you like to join our team?","私たちのチームに入りませんか。","team"];
EXAMPLES[155]=["She broke with her family long ago.","彼女は随分前に家族と縁を切った。","family"];
EXAMPLES[156]=["Can I put this up for you?","これ荷物を上にあげてもよろしい。","put"];
EXAMPLES[157]=["Can I use your toilet, please?","トイレをお借りできますか。","please"];
EXAMPLES[158]=["He might be away at the moment.","ひょっとすると彼は今留守かもしれない。","might"];
EXAMPLES[159]=["I don't have much money now.","今あまりお金を持っていません。","money"];
EXAMPLES[160]=["He will be back in a second.","彼は今すぐ帰ってきます。","second"];
EXAMPLES[161]=["She is very free with her money.","彼女はとても気前よくお金を出す。","free"];
EXAMPLES[162]=["He has a large number of books.","彼はたくさんの本を持っている。","number"];
EXAMPLES[163]=["She made for the car right away.","彼女は直ちに車の方へ向かった。","away"];
EXAMPLES[164]=["They left there the day before yesterday.","一昨日、彼らはそこを出発した。","left"];
EXAMPLES[165]=["I would often play tennis with him.","私は彼とよくテニスをしたものです。","play"];
EXAMPLES[166]=["Night coming on, we went home.","夜になったので、帰宅した。","Night"];
EXAMPLES[167]=["I plan to stay in the city.","市内に滞在する予定です。","city"];
EXAMPLES[168]=["He asked me what my name was.","彼は私に何という名前ですかとたずねた。","name"];
EXAMPLES[169]=["This book has a lot of pictures.","この本は写真が多い。","lot"];
EXAMPLES[170]=["Your opinion is quite different from mine.","あなたの意見は私のとは全く異なる。","different"];
EXAMPLES[171]=["She has something to do with the group.","彼女はそのグループと何か関係がある。","group"];
EXAMPLES[172]=["We reached the top of the mountain.","私達は山頂に着いた。","top"];
EXAMPLES[173]=["The women are relaxing on the piano.","その女性達はピアノでくつろいでいる。","women"];
EXAMPLES[174]=["Would you care for some more cake?","ケーキをもう少しいかがですか。","care"];
EXAMPLES[175]=["We got to know each other in London.","私たちはロンドンで知り合った。","each other"];
EXAMPLES[176]=["He succeeded to his father's business.","彼は親父の後を継いだ。","business"];
EXAMPLES[177]=["Once she arrives, we can start.","いったん彼女が到着すれば私たちは出発できます。","start"];
EXAMPLES[178]=["All systems are go.","すべて準備完了。","systems"];
EXAMPLES[179]=["She is going to France next week.","彼女は来週フランスへ行く。","week"];
EXAMPLES[180]=["Today, we have to sleep outdoors.","今日は我々は野宿しないといけない。","Today"];
EXAMPLES[181]=["That has nothing to do with you.","あなたには関係ない。","nothing"];
EXAMPLES[182]=["John has already come to the station.","ジョンはすでに駅に来ていました。","already"];
EXAMPLES[183]=["Who is going to try this case?","誰がこの事件を裁くのでしょうか。","case"];
EXAMPLES[184]=["They have very little to live on.","彼らは暮らしに余裕がない。","live"];
EXAMPLES[185]=["I haven't finished my homework yet.","まだ宿題が終わらない。","yet"];
EXAMPLES[186]=["I don't have time to read.","本を読む暇がありません。","read"];
EXAMPLES[187]=["Do as you were told to do.","言いつけられたとおりにしなさい。","told"];
EXAMPLES[188]=["Don't speak with your mouth full.","口に物を入れたままでしゃべってはいけない。","full"];
EXAMPLES[189]=["This report isn't to the point.","この報告書は要領をえていない。","point"];
EXAMPLES[190]=["Please tell me what happened to him.","彼に何があったのか話してください。","tell"];
EXAMPLES[191]=["I have no idea what you mean.","私はあなたの言うことがさっぱりわかりません。","mean"];
EXAMPLES[192]=["They spent four hours discussing their plan.","彼らは計画について４時間を費やした。","four"];
EXAMPLES[193]=["They aren't such a bad lot.","彼らはそんなに悪い連中ではない。","bad"];
EXAMPLES[194]=["You must have been working too hard.","きっと働きすぎですよ。","hard"];
EXAMPLES[195]=["Let's run to the bus stop.","バスの停留所まで走りましょう。","stop"];
EXAMPLES[196]=["His music was not popular at home.","彼の音楽は本国では人気がなかった。","music"];
EXAMPLES[197]=["There was little water in the well.","井戸にはほとんど水がなかった。","water"];
EXAMPLES[198]=["I will do everything in my power.","私にできることは何でもしよう。","power"];
EXAMPLES[199]=["This room is too small for us.","この部屋は私たちにとって狭すぎる。","small"];
EXAMPLES[201]=["What he said was over my head.","その人の言ったことはさっぱりわからない。","head"];
EXAMPLES[202]=["He took a taxi to the station.","彼は駅までタクシーに乗った。","took"];
EXAMPLES[203]=["Do you have a dress in white?","白いドレスはありますか。","white"];
EXAMPLES[204]=["I'd like to call my family.","家族に連絡したいのですが。","call"];
EXAMPLES[205]=["Many animals have been destroyed by men.","多くの動物が人間によって滅ぼされた。","men"];
EXAMPLES[206]=["Let me have a try at it.","私にそれをやらせてみてください。","try"];
EXAMPLES[207]=["His job has to do with telephones.","彼の職業は電話と関係がある。","job"];
EXAMPLES[208]=["As many men as came were welcomed.","来た人たちはみな歓迎された。","came"];
EXAMPLES[209]=["So far everything has been going well.","これまでのところすべてが順調だ。","far"];
EXAMPLES[210]=["Yes. we should be very careful.","うん。十分に注意しなければいけないな。","Yes"];
EXAMPLES[211]=["Please don't run about the room.","部屋の中を走り回らないでちょうだい。","run"];
EXAMPLES[212]=["What line of work are you in?","ご商売は何ですか。","line"];
EXAMPLES[213]=["We all shall die sooner or later.","われわれは遅かれ早かれ死ぬだろう。","later"];
EXAMPLES[214]=["She is less beautiful than her sister.","彼女はお姉さんほど美しくない。","less"];
EXAMPLES[215]=["Our city has no water service yet.","私の町にはまだ水道が無い。","service"];
EXAMPLES[216]=["This is the American way of life.","これがアメリカ風の生活様式だ。","American"];
EXAMPLES[217]=["He traveled abroad in his own country.","彼は自分の国の中を広く旅行した。","country"];
EXAMPLES[218]=["When did you open your new store?","いつ開店したのか。","open"];
EXAMPLES[219]=["Thank you very much for your help.","おかげさまで助かりました。","Thank"];
EXAMPLES[220]=["Spring is the season I like the best.","春は、私が一番好きな季節です。","season"];
EXAMPLES[221]=["Speak louder so everyone can hear you.","みんなに聞こえるようにもっと大きな声で話しなさい。","everyone"];
EXAMPLES[222]=["The children were playing at keeping house.","子供たちはままごとをして遊んでいた。","children"];
EXAMPLES[223]=["I have a general idea of what he means.","彼がいおうとするところは大体分かる。","general"];
EXAMPLES[224]=["What is the area of this house?","この家の広さはどのくらいありますか。","area"];
EXAMPLES[225]=["Under the table was a black cat.","テーブルの下には黒猫がいた。","black"];
EXAMPLES[226]=["This hat goes together with the dress.","この帽子はよく服とあう。","together"];
EXAMPLES[227]=["He was kind enough to help me.","彼は親切にも私を助けてくれた。","kind"];
EXAMPLES[228]=["How long does it take by car?","車でどれくらいかかりますか。","car"];
EXAMPLES[229]=["We have five English lessons a week.","私達は１週間に５回英語の授業がある。","five"];
EXAMPLES[230]=["I'm not fond of her face.","彼女の顔は好きではありません。","face"];
EXAMPLES[231]=["This story is believed to be true.","この話は本当だと信じられています。","story"];
EXAMPLES[232]=["There is nothing so important as friendship.","友情ほど重要なものはない。","important"];
EXAMPLES[233]=["I hope my dream will come true.","願いが現実になるとよいのだが。","hope"];
EXAMPLES[234]=["They will get married in due course.","彼らはやがてそのうち結婚するだろう。","course"];
EXAMPLES[235]=["I would like the least expensive one.","なるべく安いほうがいいです。","least"];
EXAMPLES[236]=["He wanted to hear about the news.","彼はそのニュースを詳しく聞きたがった。","news"];
EXAMPLES[237]=["He paid 1,000 yen for this book.","彼はこの本に千円払った。","book"];
EXAMPLES[238]=["He brought me a piece of information.","ニュースを一つ持ってきた。","information"];
EXAMPLES[239]=["I've never woken up this early.","私はこんなに早く目覚めたことはない。","early"];
EXAMPLES[240]=["What's the local time in Tokyo now?","東京は今何時でしょうか。","local"];
EXAMPLES[241]=["But of course that was a long time ago.","でも、もちろん、ずっと昔のことだけど。","of course"];
EXAMPLES[242]=["She is able to sing very well.","彼女はとても上手に歌うことができる。","able"];
EXAMPLES[243]=["Don't forget to post the letter.","その手紙を出すのを忘れるな。","post"];
EXAMPLES[244]=["He likes that video game very much.","彼はそのテレビゲームがとても好きだ。","video"];
EXAMPLES[245]=["Have an old head on young shoulders.","若いのにしっかりしている。","young"];
EXAMPLES[246]=["May I have a talk with you?","あなたとお話ししたいことがあるのですが。","talk"];
EXAMPLES[247]=["I entered this school two years ago.","私はこの学校に２年前に入学した。","ago"];
EXAMPLES[248]=["What do you have in your hand?","手に何をもっていますか。","hand"];
EXAMPLES[249]=["I often hear her play the piano.","彼女がピアノを弾く音が聞こえることがよくある。","often"];
EXAMPLES[250]=["He always leaves his work half done.","彼はいつも仕事をやりかけにしておく。","half"];
EXAMPLES[251]=["The level of the school is high.","その学校のレベルは高い。","level"];
EXAMPLES[252]=["She failed to understand a single word.","彼女は、ひとこともわからなかった。","single"];
EXAMPLES[253]=["She has become more and more beautiful.","彼女はますます美しくなった。","become"];
EXAMPLES[254]=["The problem will soon be dealt with.","その問題はまもなく処理されるだろう。","problem"];
EXAMPLES[255]=["He is sound in both mind and body.","彼は心身ともに健康だ。","body"];
EXAMPLES[256]=["He has come back from the office.","彼は事務所から帰ったばかりだ。","office"];
EXAMPLES[257]=["You really have a passion for food.","君は食べ物に目がないね。","food"];
EXAMPLES[258]=["His house is on the south side of the river.","彼の家は川の南側にある。","south"];
EXAMPLES[259]=["I'll take care of your child tonight.","今夜あなたの子どもの世話をしましょう。","take care of"];
EXAMPLES[260]=["I believe he is a nice guy.","彼はいいやつだと思う。","guy"];
EXAMPLES[261]=["My family is under the control of mother.","私の家では母がにらみをきかせている。","control"];
EXAMPLES[262]=["He is always true to his friends.","彼はいつも友人に対して忠実だ。","true"];
EXAMPLES[263]=["I have to support a large family.","私は大家族を養わなければならない。","large"];
EXAMPLES[264]=["Can I go out of the room?","部屋からでてきてもいいですか。","room"];
EXAMPLES[265]=["She has a lot of history books.","彼女はたくさんの歴史の本を持っています。","history"];
EXAMPLES[266]=["I think I've lost my ticket.","切符をなくしてしまったようだ。","lost"];
EXAMPLES[267]=["The little girl laughed her tears away.","少女は笑って涙をごまかした。","girl"];
EXAMPLES[268]=["I will go along with your plan.","私はあなたの計画に賛成です。","along"];
EXAMPLES[269]=["He hid his friend from the police.","彼は友人を警察からかくまった。","friend"];
EXAMPLES[270]=["I couldn't understand him at first.","私は最初に彼の言うことがわからなかった。","understand"];
EXAMPLES[271]=["A nice room, isn't it?","素敵な部屋ですね。","nice"];
EXAMPLES[272]=["No living thing could live without air.","空気がなければ生物は生きていけないだろう。","air"];
EXAMPLES[273]=["Yeah, I asked about six times.","６回ぐらい聞いたよ。","Yeah"];
EXAMPLES[274]=["I don't like the idea much.","その考えはあまり気に入らない。","idea"];
EXAMPLES[275]=["Tom is the tallest in his class.","トムは彼のクラスでもっとも背が高い。","class"];
EXAMPLES[276]=["He is very close with his money.","彼はお金についてはたいへん締まり屋だ。","close"];
EXAMPLES[277]=["Even a child can answer the question.","子供でさえその質問に答えられる。","question"];
EXAMPLES[278]=["Let's wait until he wakes up.","彼が目を覚ますまで待ちましょう。","wait"];
EXAMPLES[279]=["She dreamed a happy dream last night.","昨夜彼女はよい夢をみた。","happy"];
EXAMPLES[280]=["The old woman was ill in bed.","老婦人は病気で寝ていた。","woman"];
EXAMPLES[281]=["She is more human in thinking than you.","彼女はあなたよりも考え方が人間的だ。","human"];
EXAMPLES[283]=["Let's leave it up to him.","彼に任せよう。","leave"];
EXAMPLES[284]=["I feel good in a special way.","僕は特別気持ちがいい。","special"];
EXAMPLES[285]=["In the north it is cold in winter.","北の方では冬が寒いです。","north"];
EXAMPLES[286]=["I saw my friend to the station.","私は友達を駅まで送った。","saw"];
EXAMPLES[287]=["I have no time to watch tv.","わたしにはテレビを見る時間が無い。","watch"];
EXAMPLES[289]=["He runs to the station every morning.","彼は毎朝駅まで走ります。","morning"];
EXAMPLES[290]=["You don't have to stay home.","あなたは家にいなくてもよろしい。","stay"];
EXAMPLES[291]=["The light was on in the room.","部屋には明かりがついていた。","light"];
EXAMPLES[292]=["I saw him caught by the police.","私は彼が警察に捕まえられるのを見た。","police"];
EXAMPLES[293]=["In short, he was too honest.","要するに、彼はあまりにも正直すぎた。","short"];
EXAMPLES[294]=["He has a big future in baseball.","彼は野球で将来十分見込みがある。","future"];
EXAMPLES[295]=["I don't like it, either.","私も好きではありません。","either"];
EXAMPLES[296]=["What time do you usually turn in?","あなたはいつもは何時に寝ますか。","turn"];
EXAMPLES[297]=["At your age you should know better.","いい年してそんな馬鹿なまねよせ。","age"];
EXAMPLES[298]=["He has enough money to buy it.","それを買うだけのお金がある。","buy"];
EXAMPLES[299]=["Our library is on the third floor.","私達の図書館は三階です。","third"];
EXAMPLES[300]=["A red dress looks good on her.","赤い服は彼女によく似合う。","red"];
EXAMPLES[301]=["You must help her, and soon!","君は彼女を助けなければいけない。しかもすぐに。","soon"];
EXAMPLES[302]=["I doubt the truth of the report.","私は、その報告の真実性を疑う。","report"];
EXAMPLES[303]=["Feel light at heart; feel happy.","明るい気分になる。","heart"];
EXAMPLES[304]=["When do you plan to check out?","あなたのチェックアウトはいつですか。","check"];
EXAMPLES[305]=["There are several forms of government.","政治の形態にはいくつかある。","forms"];
EXAMPLES[306]=["Do you have anything further to say?","何かこれ以上言うことがありますか。","further"];
EXAMPLES[307]=["There are many doubts to a child.","子供には疑問がたくさんあります。","child"];
EXAMPLES[308]=["Don't make fun of that child.","その子をからかってはいけない。","fun"];
EXAMPLES[309]=["You had better act upon his advice.","彼の助言に従って行動すべきだ。","act"];
EXAMPLES[310]=["I called him up on the phone.","私は彼を電話に呼び出した。","phone"];
EXAMPLES[311]=["He knows the art of making friends.","彼は友達を作るコツを知っている。","art"];
EXAMPLES[312]=["There is a market in the town.","その町には市場がある。","market"];
EXAMPLES[313]=["My plan is to buy a car.","私の計画は車を買うことです。","plan"];
EXAMPLES[314]=["The train was ten minutes behind time.","その列車は１０分遅れていた。","behind"];
EXAMPLES[315]=["Tom gets up at six every morning.","トムは毎朝６時に起きる。","six"];
EXAMPLES[316]=["The station is to the west of the hotel.","駅はホテルの西の方にある。","west"];
EXAMPLES[317]=["Is there a mcdonald's near here?","近くにマクドナルドは？","near"];
EXAMPLES[318]=["It is easy to read this book.","この本は読みやすい。","easy"];
EXAMPLES[319]=["You are very trying to me sometimes.","君には時々我慢が出来なくなる。","sometimes"];
EXAMPLES[320]=["We saw him walk across the street.","彼が通りを渡るのが見えた。","street"];
EXAMPLES[321]=["He walked in front of his men.","彼は部下たちの前を歩いた。","front"];
EXAMPLES[322]=["I'll meet to you at eight.","８時にお会いしましょう。","meet"];
EXAMPLES[323]=["I want to study abroad next year.","来年、私は外国に留学したい。","study"];
EXAMPLES[324]=["My father has visited London many times.","私の父はロンドンを何度も訪れたことがある。","father"];
EXAMPLES[325]=["Let's sing the song in English.","その歌を英語で歌いましょう。","song"];
EXAMPLES[326]=["Miss march gave me an English dictionary.","マーチ先生は私に英語の辞書をくださった。","march"];
EXAMPLES[327]=["That's too bad.","それは大変だねえ・・・。","That's too bad"];
EXAMPLES[328]=["He goes to London once a month.","彼は月に一度ロンドンにいく。","month"];
EXAMPLES[329]=["I went outside early in the morning.","私は朝早く外に出た。","outside"];
EXAMPLES[330]=["My father never gave me much advice.","父は私にあまり忠告しなかった。","gave"];
EXAMPLES[331]=["My mother knows how to make cakes.","私の母はケーキの作り方を知っている。","mother"];
EXAMPLES[332]=["We should wait here for the moment.","さしあたって、ここで待つべきです。","moment"];
EXAMPLES[333]=["I found something interesting in the town.","町中で、珍しい物を見つけました。","town"];
EXAMPLES[334]=["I like summer holidays better than school.","学校より夏休みのほうがいいです。","summer"];
EXAMPLES[335]=["Let's stop and take a rest.","ちょっととまって一休みしよう。","rest"];
EXAMPLES[336]=["He made a fine job of it.","彼はその仕事をりっぱにやった。","fine"];
EXAMPLES[337]=["This coffee is too strong for me.","このコーヒーは私にはこすぎる。","strong"];
EXAMPLES[338]=["Miss smith teaches English at this school.","スミス先生はこの学校で英語を教えています。","Miss"];
EXAMPLES[339]=["I am a lover of the beautiful.","私は美を愛する人間である。","beautiful"];
EXAMPLES[340]=["This machine is now out of date.","この機械はもう時代遅れだ。","date"];
EXAMPLES[341]=["Which period of history are you studying?","あなたは歴史のどの時代を研究していますか。","period"];
EXAMPLES[342]=["We are to get married in June.","私たちは６月前に結婚する予定です。","June"];
EXAMPLES[343]=["In Japan, school starts in April.","日本では学校は４月から始まる。","April"];
EXAMPLES[344]=["He wants to be a tennis player.","彼はテニスの選手になりたい。","player"];
EXAMPLES[345]=["Can the star be seen tomorrow night?","明日の夜は星が見えますか。","star"];
EXAMPLES[346]=["I was called on in English class.","英語の時間に当てられた。","English"];
EXAMPLES[347]=["I am paid 10 dollars an hour.","私は一時間につき十ドルもらっています。","hour"];
EXAMPLES[348]=["The police acquainted him with the event.","警官は彼に事件を知らせた。","event"];
EXAMPLES[349]=["Huh? oh, I'm sorry.","ん？あ、悪い。","sorry"];
EXAMPLES[350]=["You will learn to love your baby.","そのうち赤ん坊が可愛くなるよ。","learn"];
EXAMPLES[351]=["He approached the boy reading a book.","彼は本を読んでいる少年に近付いた。","boy"];
EXAMPLES[352]=["I guess you're right, Jane.","あなたの言う通りだと思うわ、ジェーン。","guess"];
EXAMPLES[353]=["He is the king of the night.","彼は夜の帝王だ。","king"];
EXAMPLES[354]=["We've been living here since July.","我々はここに７月以来住んでいる。","July"];
EXAMPLES[355]=["It is the role of a student to study.","勉強するのが学生の本分だ。","role"];
EXAMPLES[356]=["What is the most popular movie now?","今人気のある映画は何ですか。","movie"];
EXAMPLES[357]=["They go to church on Sunday morning.","彼らは日曜日の朝教会へ行く。","church"];
EXAMPLES[358]=["I can't stand this hot summer.","今年の暑い夏には耐えられません。","hot"];
EXAMPLES[359]=["Our town is on the east side of the river.","私たちの町はその川の東岸にある。","east"];
EXAMPLES[360]=["We took a walk in the park.","私たちは公園を散歩した。","park"];
EXAMPLES[362]=["I couldn't hear the sound well.","その音がよく聞こえなかった。","sound"];
EXAMPLES[363]=["They usually go to school by bicycle.","彼らは普段自転車で登校します。","usually"];
EXAMPLES[364]=["He is cool, isn't he?","彼は冷静ですね。","cool"];
EXAMPLES[366]=["It is more than I can stand.","それはもう我慢が出来ない。","stand"];
EXAMPLES[367]=["I have just finished reading the book.","私はその本を読み終えたところです。","reading"];
EXAMPLES[368]=["They had to work all year round.","彼らは一年中働かなければならなかった。","round"];
EXAMPLES[369]=["His head was hurt by the fall.","彼は落ちて頭を怪我した。","fall"];
EXAMPLES[370]=["It is abnormal to eat so much.","そんなに食べるのは異常だ。","eat"];
EXAMPLES[371]=["Can I take your picture with us?","一緒に写真に入っていただけますか。","picture"];
EXAMPLES[372]=["The news came out of the blue.","その知らせは突然やってきた。","blue"];
EXAMPLES[373]=["Miss green asked two questions of me.","グリーン先生は私に二つの質問をした。","green"];
EXAMPLES[374]=["Don't speak so fast, please.","そんなに速く話さないで下さい。","fast"];
EXAMPLES[375]=["I felt as if I were dreaming.","まるで夢を見ているかのような気分だった。","felt"];
EXAMPLES[376]=["I am looking forward to seeing you.","君に会うのを楽しみにしている。","forward"];
EXAMPLES[377]=["She has little knowledge of science.","彼女は少ししか科学の知識がない。","science"];
EXAMPLES[378]=["My brother is good at playing tennis.","私の兄はテニスをするのが得意だ。","brother"];
EXAMPLES[379]=["Would you like another cup of coffee?","コーヒーのおかわりはいかがですか。","cup"];
EXAMPLES[380]=["John cannot be living in London now.","ジョンは今ロンドンに住んでいるはずがない。","cannot"];
EXAMPLES[381]=["It happened last October.","それは去年の１０月に起こった。","October"];
EXAMPLES[382]=["A little language goes a long way.","ちょっと言葉を知っていればずいぶん役にたつよ。","language"];
EXAMPLES[383]=["She began to talk to the dog.","彼女はその犬に話し始めた。","dog"];
EXAMPLES[384]=["There is no school during August.","８月には授業がない。","August"];
EXAMPLES[385]=["My birthday is in November.","私の誕生日は１１月です。","November"];
EXAMPLES[386]=["She is a friend of the poor.","彼女は貧しい人達の味方です。","poor"];
EXAMPLES[387]=["I didn't enjoy it very much.","余り楽しくなかったな。","enjoy"];
EXAMPLES[388]=["I'm taking an exam in January.","一月に試験を受ける予定です。","January"];
EXAMPLES[389]=["Lend your money and lose your friend.","金を貸して友を失え。","lose"];
EXAMPLES[390]=["We stood at the door and waited.","われわれはドアのそばに立ってまった。","door"];
EXAMPLES[391]=["Pick up your things and go away.","荷物を持って出て行け。","Pick"];
EXAMPLES[392]=["You look nice with your hair short.","髪を短くして素敵だよ。","hair"];
EXAMPLES[393]=["She speaks English with a foreign accent.","彼女は外国なまりのある英語を話す。","foreign"];
EXAMPLES[394]=["He lived in matsue for seven years.","彼は松江に７年間住んでいた。","seven"];
EXAMPLES[395]=["Won't you go for a walk?","散歩にお出かけになりませんか。","walk"];
EXAMPLES[396]=["I found it difficult to please him.","彼の機嫌をとるのは難しいとわかった。","difficult"];
EXAMPLES[397]=["He works in a big city hospital.","彼は大きな市立病院に勤務しておられます。","hospital"];
EXAMPLES[398]=["Bob usually goes to bed at ten.","ボブは普通１０時に寝る。","bed"];
EXAMPLES[399]=["Popular or not, it is right.","人気があろうとなかろうとそれは正しい。","Popular"];
EXAMPLES[400]=["December is the last month of the year.","十二月は一年の最後の月だ。","December"];
EXAMPLES[401]=["Our idea did not work in practice.","私たちの考えは実際には役に立たなかった。","practice"];
EXAMPLES[402]=["She should listen more to other people.","彼女はもっと他人の言うことを聞くべきだ。","listen"];
EXAMPLES[403]=["Don't forget to bolt the door.","戸締まりをするのを忘れるな。","forget"];
EXAMPLES[404]=["We came in sight of the sea.","私達は海の見えるところへやって来た。","sea"];
EXAMPLES[405]=["Babies often fall down.","赤ん坊はよく転ぶ。","fall down"];
EXAMPLES[406]=["Don't try to pass the buck.","責任逃れをするな。","pass"];
EXAMPLES[407]=["Do you have a table for five?","五人の席はありますか。","table"];
EXAMPLES[408]=["He will be back in ten minutes.","彼は十分たったら戻る。","ten"];
EXAMPLES[409]=["I had a good night's sleep.","ぐっすり寝ました。","sleep"];
EXAMPLES[410]=["It took many years to build it.","それを建てるのに何年もかかった。","build"];
EXAMPLES[411]=["Can I have this box carried upstairs?","この箱を２階へ運んでもらえますか。","box"];
EXAMPLES[412]=["Get down to your work straight away.","すぐに仕事にとりかかれ。","straight"];
EXAMPLES[413]=["She wears the same watch as mine.","彼女は私のと同じ時計をしている。","mine"];
EXAMPLES[414]=["I'll look forward to it.","それは楽しみです。","look forward to"];
EXAMPLES[415]=["They visit us from time to time.","彼らは時々私たちを訪れる。","visit"];
EXAMPLES[416]=["I hung a picture on the wall.","私は壁に絵を掛けた。","wall"];
EXAMPLES[417]=["You will be able to speak English.","英語を話せるようになるだろう。","speak"];
EXAMPLES[418]=["What is the name of this river?","この川は何というのですか。","river"];
EXAMPLES[419]=["We had a short vacation in February.","私たちは２月に短い休暇をとった。","February"];
EXAMPLES[420]=["She will write a letter after school.","彼女は放課後手紙を書くつもりです。","write"];
EXAMPLES[421]=["He is by far the best student.","彼は誰よりもはるかに良く出来る学生だ。","student"];
EXAMPLES[422]=["She has an eye for the beautiful.","彼女は審美眼を持っている。","eye"];
EXAMPLES[423]=["She came down to breakfast at eight.","彼女は８時に朝食を食べに降りてきた。","eight"];
EXAMPLES[424]=["He died from the cold last night.","彼はゆうべの寒さで死んだ。","cold"];
EXAMPLES[425]=["I'd like to sleep late tomorrow.","私は明日遅くまで寝ていたい。","tomorrow"];
EXAMPLES[426]=["The teacher told us a funny story.","その先生は私たちにおもしろい話をしてくれた。","funny"];
EXAMPLES[427]=["The bus landed us at the station.","バスは我々を駅まで運んでくれた。","station"];
EXAMPLES[428]=["There is no living on the island.","その島に住むことは不可能だ。","island"];
EXAMPLES[429]=["I saw the boy in brown shoes.","その男の子は茶色の靴を履いていました。","brown"];
EXAMPLES[430]=["Would you join me in a drink?","一杯付き合いませんか。","join"];
EXAMPLES[431]=["I have something to tell him quickly.","至急話したいことがあるのです。","quickly"];
EXAMPLES[432]=["Some of the essays are very interesting.","そのエッセイの中にはたいへんおもしろいものもあります。","interesting"];
EXAMPLES[433]=["He is old enough to travel alone.","彼は、一人旅できる年齢だ。","travel"];
EXAMPLES[434]=["Our team has the game on ice.","我々のチームが試合に勝つことは間違いない。","ice"];
EXAMPLES[435]=["Be sure to drop me a line.","短い手紙でもいいからきっと書いてね。","drop"];
EXAMPLES[437]=["We'll welcome you at any time.","私たちはいつでもあなたを歓迎します。","welcome"];
EXAMPLES[438]=["Would you please wait for a minute?","少々お待ちいただけますか。","minute"];
EXAMPLES[439]=["I'm not going to sell it.","それは売らないつもりです。","sell"];
EXAMPLES[440]=["John seems very honest by nature.","ジョンは生まれつき非常に正直のように思われる。","nature"];
EXAMPLES[441]=["How do you spend the new year?","新年をどのように過ごすのですか。","spend"];
EXAMPLES[442]=["I will clean up yesterday's work.","昨日の仕事を片づけるつもりです。","clean"];
EXAMPLES[443]=["English has become my favorite subject.","英語は私の好きな学科になった。","favorite"];
EXAMPLES[444]=["He wrote a paper on the subject.","彼はその問題について論文を書いた。","subject"];
EXAMPLES[445]=["I was late for the last train.","私は終電車に乗り遅れた。","train"];
EXAMPLES[446]=["What will you do on Friday?","あなたは金曜日に何をするつもりですか。","Friday"];
EXAMPLES[447]=["I read the letter again and again.","私はその手紙を何度も何度も読んだ。","letter"];
EXAMPLES[448]=["My sister showed me a new watch.","姉が僕に新しい時計を見せてくれた。","sister"];
EXAMPLES[449]=["I am interested in swimming.","私は泳ぐことに興味があります。","interested in"];
EXAMPLES[450]=["He dropped his books on the floor.","彼は床に本を落とした。","floor"];
EXAMPLES[451]=["The ship was soon out of sight.","船はすぐに見えなくなった。","ship"];
EXAMPLES[452]=["Winter has gone. spring has come.","冬が去り、春が来た。","spring"];
EXAMPLES[453]=["Does this bus go to the beach?","このバスは、海岸に行きますか。","beach"];
EXAMPLES[454]=["I have been busy since last Sunday.","私はこの前の日曜日からずっと忙しい。","Sunday"];
EXAMPLES[455]=["Why did you choose such a subject?","なぜこのような科目を選んだの？","choose"];
EXAMPLES[456]=["Some day my dream will come true.","いつか私の夢は実現する。","dream"];
EXAMPLES[457]=["She is rich but he is poor.","彼女は金持ちだが彼は貧乏だ。","rich"];
EXAMPLES[458]=["I will get in touch with you.","いずれご連絡いたします。","touch"];
EXAMPLES[459]=["You won't get it so easily.","そうは問屋がおろさない。","easily"];
EXAMPLES[460]=["I went to see the movies yesterday.","私は昨日映画を見に行きました。","yesterday"];
EXAMPLES[461]=["That's very sweet of you.","君はとてもやさしいんだね。","sweet"];
EXAMPLES[462]=["It's bad luck to say that.","縁起でもないこと言うなよ。","luck"];
EXAMPLES[463]=["I bought this hat for 2000 yen.","私はこの帽子を２０００円で買った。","bought"];
EXAMPLES[464]=["That is the same color as mine.","それは僕のと同じ色だ。","color"];
EXAMPLES[465]=["I motioned for her to sit down.","彼女に座るように手で合図した。","sit"];
EXAMPLES[466]=["A doctor was called in right away.","すぐに医者を呼んだ。","doctor"];
EXAMPLES[467]=["This fish is not fit to eat.","この魚は食用にならない。","fish"];
EXAMPLES[468]=["I feel like going on a trip.","旅に出かけたい気がする。","trip"];
EXAMPLES[469]=["Will you give me something to drink?","何か飲むものをくれませんか。","drink"];
EXAMPLES[470]=["The lake is the deepest in Japan.","その湖は日本で一番深い湖である。","Japan"];
EXAMPLES[471]=["I used to go skiing in winter.","私はよく冬にスキーにいったものだ。","winter"];
EXAMPLES[472]=["He isn't much of a teacher.","彼はたいした教師ではない。","teacher"];
EXAMPLES[473]=["The shop is across from the bank.","店は銀行の向かいにある。","shop"];
EXAMPLES[474]=["She has been sick for a week.","彼女が病気になってから１週間になります。","sick"];
EXAMPLES[475]=["He came back at nine o'clock.","彼は９時に帰ってきた。","nine"];
EXAMPLES[476]=["There were many people in the hall.","ホールには人がいっぱいいた。","hall"];
EXAMPLES[477]=["We're having a party next Saturday.","来週の土曜にパーティーを開くつもりです。","Saturday"];
EXAMPLES[478]=["I'll leave tomorrow, weather permitting.","天気さえ良ければ私は明日出発します。","weather"];
EXAMPLES[479]=["He is no longer full of activity.","彼に気力がない。","activity"];
EXAMPLES[480]=["What's on the air this evening?","今夜はどんな番組がありますか。","evening"];
EXAMPLES[481]=["Talking in the library is not allowed.","図書館ではおしゃべりをしてはいけません。","library"];
EXAMPLES[482]=["I remember I saw the queen.","私は女王に会ったことを覚えている。","queen"];
EXAMPLES[483]=["He gets up the tree without difficulty.","彼は簡単に木にのぼる。","tree"];
EXAMPLES[484]=["He made a speech out of turn.","彼は自分の番でないのに説得した。","speech"];
EXAMPLES[485]=["She kindly gave me a ride home.","彼女は親切にも車で家まで運んでくれた。","ride"];
EXAMPLES[486]=["The house which Tom built is wonderful.","トムの建てた家はすばらしい。","wonderful"];
EXAMPLES[488]=["I hear she's a famous actress.","彼女は有名な女優だそうだ。","famous"];
EXAMPLES[489]=["I feel sad every now and then.","私は時々悲しくなることがある。","sad"];
EXAMPLES[490]=["Don't speak with your mouth full.","口に食べ物を入れたまましゃべるな。","mouth"];
EXAMPLES[491]=["Actually this will be my fourth question.","実はこれで４度目の質問になります。","fourth"];
EXAMPLES[492]=["We have walked all around the lake.","私たちは湖をぐるりと回ってきた。","lake"];
EXAMPLES[493]=["Have you ever been to that village?","君はあの村へ行ったことがありますか。","village"];
EXAMPLES[494]=["Let the tea draw for ten minutes.","このお茶は、１０分間煎じなさい。","draw"];
EXAMPLES[495]=["He knows almost nothing about that animal.","彼はその動物についてほとんど知らない。","animal"];
EXAMPLES[496]=["I wish I had a better memory.","もう少し記憶力がよければなあ。","memory"];
EXAMPLES[497]=["He is quite ignorant of things Japanese.","彼は日本の事情をまったく知らない。","Japanese"];
EXAMPLES[498]=["Please get this work finished by Monday.","月曜日までにこの仕事を終えて下さい。","Monday"];
EXAMPLES[499]=["I asked him to open the window.","彼に窓を開けるように頼んだ。","window"];
EXAMPLES[500]=["She asked him to carry her bag.","彼女は彼にかばんを運んでほしいと頼んだ。","bag"];
EXAMPLES[501]=["I was invited to dinner by her.","私は彼女から食事に誘われた。","dinner"];
EXAMPLES[502]=["A cat can see in the dark.","猫は闇で物が見える。","cat"];
EXAMPLES[503]=["She went down to the fifth floor.","彼女は５階へ降りてきた。","fifth"];
EXAMPLES[504]=["This book is too dear for me.","この本は私に高すぎる。","dear"];
EXAMPLES[505]=["I parted from him on the bridge.","私は橋の上で彼と別れた。","bridge"];
EXAMPLES[506]=["He rode a horse to the sea.","彼は海まで馬に乗った。","horse"];
EXAMPLES[507]=["Look up the town on the map.","その町を地図で探してください。","map"];
EXAMPLES[508]=["I was invited to her birthday party.","彼女の誕生日パーティーに招かれました。","birthday"];
EXAMPLES[509]=["The apple of a person's eye.","何よりも大切にしているもの。","apple"];
EXAMPLES[510]=["To my surprise, he has failed.","驚いたことには、彼は失敗した。","surprise"];
EXAMPLES[511]=["I have not been busy since yesterday.","私は昨日から忙しくありません。","busy"];
EXAMPLES[512]=["We were excited to see the game.","私たちはその試合を見てわくわくした。","excited"];
EXAMPLES[513]=["He isn't back from the mountain.","彼はまだ山からもどっていない。","mountain"];
EXAMPLES[514]=["This fact shows that he is honest.","この事実から彼が正直な人だとわかる。","honest"];
EXAMPLES[515]=["What kind of sport do you like?","どんな種類のスポーツが好きですか。","sport"];
EXAMPLES[516]=["May I have a cup of tea?","紅茶を１杯いただけますか。","tea"];
EXAMPLES[517]=["We went to new york by plane.","我々は飛行機でニューヨークへ行った。","plane"];
EXAMPLES[518]=["I have nothing to do this afternoon.","私は今日の午後何もすることがない。","afternoon"];
EXAMPLES[519]=["I have to get some new clothes.","わたし新しい服を買わなくちゃ。","clothes"];
EXAMPLES[520]=["Tom took part in the summer festival.","トムは夏祭りに参加した。","festival"];
EXAMPLES[521]=["There were two hundred people in the room.","その部屋には２００人の人々がいた。","hundred"];
EXAMPLES[522]=["Warm this morning, isn't it?","今朝は暖かいですね。","Warm"];
EXAMPLES[523]=["How does this bear on my future?","これが私の将来とどう関係しますか。","bear"];
EXAMPLES[524]=["Does this bus go to the museum?","このバスは美術館まで行きますか。","museum"];
EXAMPLES[525]=["I am tired from a long walk.","長いこと歩いて私は今疲れている。","tired"];
EXAMPLES[526]=["She set a child in the chair.","彼女は子供をいすに座らせた。","chair"];
EXAMPLES[527]=["Try to jump as high as possible.","できるだけ高く飛び上がるようにしなさい。","jump"];
EXAMPLES[528]=["All the flowers in the garden are yellow.","庭の花はすべて黄色だ。","yellow"];
EXAMPLES[529]=["I'll do the shopping for you.","私が買い物をしてあげましょう。","shopping"];
EXAMPLES[530]=["She has a soft and clear voice.","彼女は澄んだ声をしている。","soft"];
EXAMPLES[531]=["He wanted to teach English at school.","彼は学校で英語を教えたかった。","teach"];
EXAMPLES[532]=["The new tv drama is quite interesting.","今度のテレビドラマはたいへんおもしろい。","drama"];
EXAMPLES[533]=["A dog bit her on the leg.","犬が彼女の足をかんだ。","leg"];
EXAMPLES[534]=["It is one thing to promise, and another to perform.","約束することと実行することは別のことだ。","perform"];
EXAMPLES[535]=["Mary paid five dollars for her lunch.","メアリーは昼食代を五ドル払った。","lunch"];
EXAMPLES[536]=["We'll have little snow this winter.","今年の冬は雪が少ないだろう。","snow"];
EXAMPLES[537]=["This is how I usually cook fish.","こうして私はいつも魚を料理する。","cook"];
EXAMPLES[538]=["The teacher told us to be quiet.","先生は私たちに静かにするように言った。","quiet"];
EXAMPLES[539]=["He ought to have been an actor.","彼は俳優になるべきだった。","actor"];
EXAMPLES[540]=["The train will be twenty minutes late.","電車は２０分遅れるでしょう。","twenty"];
EXAMPLES[541]=["Mary is cute. so is Jane.","メアリーはかわいらしい。ジェーンもそうです。","cute"];
EXAMPLES[542]=["He paid at most ten thousand dollars.","彼はせいぜい１万ドル払っただけだ。","thousand"];
EXAMPLES[543]=["My mother said it with a smile.","母は微笑みながら言いました。","smile"];
EXAMPLES[544]=["A bird is singing in the tree.","鳥が木の上で歌っている。","bird"];
EXAMPLES[545]=["I walked as slowly as I could.","私はできるだけゆっくりと歩きました。","slowly"];
EXAMPLES[546]=["Well then, I'll have chicken.","それじゃ、僕はチキンをもらいましょう。","chicken"];
EXAMPLES[547]=["She will visit her mother next Tuesday.","彼女は次の火曜日に母を訪ねるつもりです。","Tuesday"];
EXAMPLES[548]=["We should know the result by Thursday.","木曜までには結果が分かるはずだ。","Thursday"];
EXAMPLES[549]=["Water the flowers before you have breakfast.","朝ごはんの前に花に水をやりなさい。","breakfast"];
EXAMPLES[550]=["The pictures are of her own painting.","その絵は彼女が自分でかいたものである。","painting"];
EXAMPLES[551]=["I read about him in the newspaper.","私は新聞で彼について読んだ。","newspaper"];
EXAMPLES[552]=["You should be a thought more careful.","もうほんのちょっと気をつけねば。","careful"];
EXAMPLES[553]=["She has been absent since last Wednesday.","彼女はこの前の水曜日からずっと休んでいる。","Wednesday"];
EXAMPLES[554]=["He is concerned about his parent's health.","彼は両親の健康を心配している。","parent"];
EXAMPLES[555]=["A tree is known by its fruit.","子を見れば親がわかる。","fruit"];
EXAMPLES[556]=["This book will give you great pleasure.","この本はとても楽しく読めます。","pleasure"];
EXAMPLES[557]=["Excuse me. may I get by?","すみません、通してください。","Excuse"];
EXAMPLES[558]=["The Japanese live on rice.","日本人は米を食べて生きている。","rice"];
EXAMPLES[559]=["I want you to sing the song.","私はあなたにその歌をうたってもらいたい。","sing"];
EXAMPLES[560]=["He is very good at playing baseball.","彼は野球をするのがとてもうまい。","baseball"];
EXAMPLES[561]=["The game got more and more exciting.","その試合はますます面白くなった。","exciting"];
EXAMPLES[562]=["I take my hat off to you.","君には脱帽するよ。","hat"];
EXAMPLES[563]=["This bike is used by my brother.","この自転車は私の兄に使われる。","bike"];
EXAMPLES[564]=["You have not eaten the cake yet.","ケーキをまだ食べ終わっていない。","cake"];
EXAMPLES[565]=["He's not much as a singer.","彼は大した歌手ではない。","singer"];
EXAMPLES[566]=["I just wanna nose around a bit.","ちょっと調べてることがあるから。","nose"];
EXAMPLES[567]=["What is the price of this cap?","この帽子はいくらですか。","cap"];
EXAMPLES[568]=["Her hair fell over her shoulder.","彼女の髪は肩にたれている。","shoulder"];
EXAMPLES[569]=["We do not have any more bread.","もうこれ以上パンはありません。","bread"];
EXAMPLES[570]=["Did you visit the tower of London?","ロンドン塔を訪れましたか。","tower"];
EXAMPLES[571]=["I am a junior high school student.","私は、中学生です。","junior"];
EXAMPLES[572]=["I like the white of an egg.","私は卵の白身が好きです。","egg"];
EXAMPLES[573]=["Father got me to wash his car.","父は私に自動車を洗わせました。","wash"];
EXAMPLES[574]=["American students are falling behind in math.","アメリカの学生は数学で遅れをとっている。","math"];
EXAMPLES[575]=["I felt hungry after the long walk.","長く歩いてきたので空腹を感じた。","hungry"];
EXAMPLES[576]=["My uncle lived abroad for many years.","私のおじは何年も外国で生活した。","uncle"];
EXAMPLES[577]=["We also went to the temple.","その寺へも行った。","temple"];
EXAMPLES[578]=["I usually take a bath after dinner.","私はたいてい夕食後に入浴する。","bath"];
EXAMPLES[579]=["I am a junior high school student.","私は、中学生です。","junior high school"];
EXAMPLES[580]=["You really have an ear for music.","君は音楽がよくわかるね。","ear"];
EXAMPLES[581]=["I see a book on the desk.","机の上に本が見える。","desk"];
EXAMPLES[582]=["He succeeded in swimming across the river.","彼は首尾よくその川を泳いで渡った。","swimming"];
EXAMPLES[583]=["The movie starts at ten o'clock.","映画は１０時から始まる。","clock"];
EXAMPLES[584]=["The flower died for want of water.","その花は水がなくて困っている。","flower"];
EXAMPLES[586]=["We are not on the telephone yet.","私達はまだ電話をつりつけていません。","telephone"];
EXAMPLES[587]=["I want you to meet my cousin.","私のいとこに会ってほしい。","cousin"];
EXAMPLES[588]=["Can I speak to the head nurse?","婦長と話したいのですが。","nurse"];
EXAMPLES[589]=["The summer vacation ended all too soon.","夏休みはとても早く終わった。","vacation"];
EXAMPLES[590]=["When does his train arrive at Kyoto?","彼が乗った列車はいつ京都に着きますか。","arrive"];
EXAMPLES[591]=["No fewer than thirty people were present.","３０人もの人が出席した。","thirty"];
EXAMPLES[593]=["Do you collect anything?","何か集めていますか。","collect"];
EXAMPLES[594]=["Could you spell your name, please?","あなたのお名前のスペルをお願いします。","spell"];
EXAMPLES[595]=["One should always do one's best.","人はいつも全力を尽くすべきです。","do one's best"];
EXAMPLES[596]=["Are you going to the theater tonight?","今夜劇場にいくつもりですか。","theater"];
EXAMPLES[597]=["He has no less than twelve children.","彼には子供が１２人もいる。","twelve"];
EXAMPLES[598]=["I am afraid I ate something bad.","私は何か悪いものを食べたようだ。","ate"];
EXAMPLES[599]=["That dinner they had together was delicious.","二人が一緒に食べた夕食はとてもおいしかった。","delicious"];
EXAMPLES[600]=["The water came up to my knees.","水は私のひざの高さだった。","knees"];
EXAMPLES[601]=["She was born in the purple.","彼女は名門の生まれだ。","purple"];
EXAMPLES[602]=["I'll be as quiet as a mouse.","できるだけ静かにしますので。","mouse"];
EXAMPLES[603]=["Do you go to an elementary school?","あなたは小学校に通っているの。","elementary school"];
EXAMPLES[604]=["That is not a tiger.","あれはトラではない。","tiger"];
EXAMPLES[605]=["I paid a matter of fifty dollars.","私はおよそ５０ドル払った。","fifty"];
EXAMPLES[606]=["Would you like some more beef?","もう少しビーフをいかがですか。","beef"];
EXAMPLES[607]=["We have a cold autumn this year.","今年は寒い秋です。","autumn"];
EXAMPLES[608]=["It is lonely to live alone.","一人で生活するのは寂しい。","lonely"];
EXAMPLES[609]=["What I bought yesterday was these shoes.","私が昨日買ったのはこの靴なんです。","shoes"];
EXAMPLES[610]=["My grandfather takes a walk every morning.","私の祖父は毎朝散歩します。","grandfather"];
EXAMPLES[611]=["I want to brush up my English.","私は英語をやり直したい。","brush"];
EXAMPLES[613]=["We are going to climb that mountain.","あの山に私達は登るつもりです。","climb"];
EXAMPLES[614]=["She is in bed with a fever.","彼女は熱があって寝ている。","fever"];
EXAMPLES[615]=["I am determined to be a scientist.","科学者になる決心をしている。","scientist"];
EXAMPLES[616]=["This dish goes very well with sake.","この料理は酒によく合う。","dish"];
EXAMPLES[617]=["Don't you want to swim today?","今日は泳ぎたくはないですか。","swim"];
EXAMPLES[618]=["My class is made up of forty students.","私のクラスには４０人の生徒がいます。","forty"];
EXAMPLES[619]=["My home is on the eighth floor.","私の家は８階にあります。","eighth"];
EXAMPLES[620]=["The boy was watching the sheep.","少年は羊の番をしている。","sheep"];
EXAMPLES[622]=["His opinion is quite different from ours.","彼の意見は我々の意見とはまったく違っている。","ours"];
EXAMPLES[623]=["He is looked after by his aunt.","その子供は彼の叔母さんの世話になっている。","aunt"];
EXAMPLES[624]=["He is too shy to talk to girls.","彼はとても内気で女の子と話が出来ない。","shy"];
EXAMPLES[625]=["There were some students in the classroom.","教室には何人かの生徒がいました。","classroom"];
EXAMPLES[626]=["Farmers work hard in the winter, too.","農夫は冬も一生懸命働いているのだよ。","Farmers"];
EXAMPLES[627]=["Would you like some more salad?","もう少しサラダはいかがですか。","salad"];
EXAMPLES[628]=["What kind of soup is this?","これはどんなスープですか。","soup"];
EXAMPLES[629]=["My grandmother can't see very well.","祖母はあまりよく目が見えない。","grandmother"];
EXAMPLES[630]=["We are fifteen in all.","全員で十五名です。","fifteen"];
EXAMPLES[631]=["You can wait till the cows come home.","いつまででも待つがいいさ。","cows"];
EXAMPLES[632]=["Don't eat like a pig.","そんなにがつがつ食べるんじゃないよ。","pig"];
EXAMPLES[633]=["Are there many animals in the zoo?","動物園にはたくさんの動物がいますか。","zoo"];
EXAMPLES[634]=["He had his homework done before supper.","彼は夕飯の前に宿題を終えていた。","homework"];
EXAMPLES[635]=["Eleven o'clock is good for me.","１１時でしたら行けます。","Eleven"];
EXAMPLES[636]=["We have lunch at noon every day.","私達はいつも正午に昼食を食べる。","noon"];
EXAMPLES[637]=["I hear the drum.","太鼓の音が聞こえる。","drum"];
EXAMPLES[638]=["I have a very old stamp.","私は非常に古い切手を持っている。","stamp"];
EXAMPLES[639]=["This is the diary which she kept.","これは彼女がつけた日記です。","diary"];
EXAMPLES[640]=["She had a bad tooth taken out.","彼女は悪い歯を抜いてもらった。","tooth"];
EXAMPLES[641]=["He is up to some monkey business.","彼は何かいたずらをしようとしている。","monkey"];
EXAMPLES[642]=["We had few sunny days this summer.","今年の夏は晴れの日がほとんどなかった。","sunny"];
EXAMPLES[644]=["I'd like to buy this doll.","この人形が欲しいのですが。","doll"];
EXAMPLES[645]=["A rabbit is running in the garden.","ウサギが庭の中をかけています。","rabbit"];
EXAMPLES[647]=["Look up the word in your dictionary.","その単語を辞書で調べてごらん。","dictionary"];
EXAMPLES[648]=["It appears that he is a musician.","彼は音楽家のようだ。","musician"];
EXAMPLES[649]=["Can I borrow something to write with?","何か書くものを貸してくれますか。","borrow"];
EXAMPLES[650]=["My father is a bank clerk.","私の父は銀行員です。","clerk"];
EXAMPLES[651]=["I don't care a bean.","ぜんぜん気にしない。","bean"];
EXAMPLES[652]=["She advised him to use a bicycle.","彼女は彼に自転車を使うように言った。","bicycle"];
EXAMPLES[653]=["She and hers are all very well.","彼女も彼女の家族もみなとてもげんきだ。","hers"];
EXAMPLES[654]=["Tom told us that he had a headache.","トムは頭が痛いと私たちに言った。","headache"];
EXAMPLES[655]=["Our school is larger than theirs.","私たちの学校は彼らより大きい。","theirs"];
EXAMPLES[656]=["He took a pencil in his hand.","彼は鉛筆を手に持った。","pencil"];
EXAMPLES[657]=["I will be sixteen next birthday.","私は次の誕生日で１６歳になる。","sixteen"];
EXAMPLES[658]=["Could you bring me another hot towel?","おしぼりをもう一本ください。","towel"];
EXAMPLES[659]=["What do you call this vegetable in English?","この野菜は英語で何と言いますか。","vegetable"];
EXAMPLES[660]=["He is sixty, if a day.","あの人は少なくとも６０歳にはなっている。","sixty"];
EXAMPLES[661]=["It was about the tenth hour.","時は１０時ごろだった。","tenth"];
EXAMPLES[662]=["The airplane soon went out of sight.","飛行機はまもなく見えなくなった。","airplane"];
EXAMPLES[663]=["Did you bring an umbrella with you?","傘を持ってきましたか。","umbrella"];
EXAMPLES[665]=["My sister will be thirteen years old next summer.","私の妹は次の夏には１３歳になる。","thirteen"];
EXAMPLES[667]=["I am seventeen years old, too.","私も１７歳です。","seventeen"];
EXAMPLES[668]=["I bought a book and he a ruler.","私は本を買い、彼は定規を買った。","ruler"];
EXAMPLES[669]=["I was eighteen then.","そのとき私は１８歳だった。","eighteen"];
