EXAMPLES[974]=["The situation is better, if anything.","事態はどちらかと言えば良い方だ。","situation"];
EXAMPLES[975]=["We live in the age of technology.","我々は科学技術の時代に住んでいる。","technology"];
EXAMPLES[977]=["I had no choice but to go.","私は行くより仕方なかった。","choice"];
EXAMPLES[979]=["What's currently hot?","今人気を呼んでいるもの。","currently"];
EXAMPLES[980]=["Driving a car is really very simple.","車を運転することは本当は簡単なことである。","simple"];
EXAMPLES[981]=["Tom did it simply for the money.","トムはお金だけのためにそれをしたのだ。","simply"];
EXAMPLES[982]=["Not all of the staff was present.","スタッフ全員が、出席したわけではありません。","staff"];
EXAMPLES[983]=["Has John decided on a career yet?","ジョンはもう職業を決めましたか。","career"];
EXAMPLES[984]=["Give me some paper to write on.","書くために紙を少し下さい。","paper"];
EXAMPLES[985]=["That old bridge is anything but safe.","あの古い橋は安全なんてものではない。","safe"];
EXAMPLES[986]=["They gave different versions of the accident.","彼らはその事故について異なる説明をした。","versions"];
EXAMPLES[987]=["The voice reminded me of my mother.","その声を聞いて私は母を思い出した。","voice"];
EXAMPLES[988]=["Our company makes use of the internet.","我々の会社ではインターネットを利用している。","internet"];
EXAMPLES[989]=["Is this all you have, sir?","お荷物はこれで全部ですか。","sir"];
EXAMPLES[990]=["Every student has access to the library.","学生は誰でも図書館を利用できる。","access"];
EXAMPLES[991]=["The lake is deep at this point.","その湖はこの地点が深い。","deep"];
EXAMPLES[992]=["Mark the words that you cannot understand.","分からない語に印をつけなさい。","Mark"];
EXAMPLES[993]=["Why did you turn down his offer?","なぜ彼の申し出を断ったのですか。","offer"];
EXAMPLES[995]=["Why do you take such a risk?","どうしてそんな危険を犯すのですか。","risk"];
EXAMPLES[996]=["He found a ball in the garden.","彼は庭でボールを見つけた。","ball"];
EXAMPLES[997]=["There is a card on the desk.","机の上に一枚のカードがある。","card"];
EXAMPLES[998]=["They got to the hotel after dark.","日没後彼らはその旅館に着いた。","dark"];
EXAMPLES[1000]=["When he saw the police officer, he ran away.","警官を見ると、彼は逃げた。","officer"];
EXAMPLES[1001]=["There was no response to my question.","私の質問に何の応答もなかった。","response"];
EXAMPLES[1002]=["He is known as a rock singer.","彼はロック歌手として知られている。","rock"];
EXAMPLES[1003]=["I want to learn standard English.","私は標準英語を勉強したい。","standard"];
EXAMPLES[1004]=["I'll show my album to you.","私のアルバムをあなたにお見せします。","album"];
EXAMPLES[1006]=["I think you're on the right track.","いい線いってるよ。","track"];
EXAMPLES[1007]=["Eight is the double of four.","８は４の２倍です。","double"];
EXAMPLES[1008]=["I speak in my normal voice when I'm working the phone.","電話では普通の声で話すよ。","normal"];
EXAMPLES[1009]=["I work best under pressure.","僕は追い込まれると一番仕事をする。","pressure"];
EXAMPLES[1010]=["Tv has taken the place of radio.","テレビがラジオに取って代わった。","radio"];
EXAMPLES[1011]=["We read the full text of his speech.","私たちは彼の演説の全文を読んだ。","text"];
EXAMPLES[1012]=["He lives in the western part of town.","彼は町の西部に住んでいる。","western"];
EXAMPLES[1013]=["Does he have anything to do with the campaign?","彼はその運動に関係があるのですか。","campaign"];
EXAMPLES[1014]=["He was seen to cross the street.","彼が通りを横切るのが見られた。","cross"];
EXAMPLES[1015]=["Hi, Bill. how are you?","やあ、ビル。元気？","Hi"];
EXAMPLES[1016]=["Would you like to leave a message?","何か伝言はありますか。","message"];
EXAMPLES[1017]=["She was nearly hit by a bicycle.","彼女はあやうく自転車にひかれるところだった。","nearly"];
EXAMPLES[1018]=["I asked for a seat in the smoking section.","喫煙席を頼んだのですが。","section"];
EXAMPLES[1019]=["He was driving the car at full speed.","彼は全力で車を走らせていた。","speed"];
EXAMPLES[1020]=["English is studied in China, too.","英語は中国でも勉強されています。","China"];
EXAMPLES[1021]=["How often have you been to Europe?","何回ヨーロッパにいったことがあるのですか。","Europe"];
EXAMPLES[1022]=["The british government is against the plan.","イギリス政府はその計画に反対です。","british"];
EXAMPLES[1023]=["What do Chinese people have for breakfast?","中国人は朝食に何を食べますか。","Chinese"];
EXAMPLES[1024]=["He answered that he knew no French.","彼はフランス語は知らないと答えた。","French"];
EXAMPLES[1025]=["He can both speak and write russian.","彼はロシア語が話せるし書くことができる。","russian"];
EXAMPLES[1026]=["The town has a european air.","その町はヨーロッパ風のところがある。","european"];
EXAMPLES[1027]=["She can make all her own clothes.","彼女は自分の服は自分で作る事ができる。","own"];
EXAMPLES[1028]=["The rain kept us from going out.","雨のため我々は外出できなかった。","rain"];
EXAMPLES[1029]=["He put his foot through the floor.","彼は床を踏みぬいた。","foot"];
EXAMPLES[1030]=["I have money enough to buy it.","私はそれを買うだけのお金がある。","enough"];
EXAMPLES[1031]=["You must not shout at him.","彼を怒鳴りつけてはいけない。","shout"];
EXAMPLES[1032]=["He cannot have done such a thing.","彼はそんなことをしたはずがない。","such"];
EXAMPLES[1033]=["That's a hard question to answer.","それは答えにくい質問だ。","answer"];
EXAMPLES[1034]=["It was his habit to rise early.","早起きは彼の習慣だった。","rise"];
EXAMPLES[1035]=["It's up to you to decide.","決定するのは君次第だ。","decide"];
EXAMPLES[1036]=["There is nothing new under the sun.","この世に全く新しきものなし。","sun"];
EXAMPLES[1037]=["The word is no longer in use.","その語は今はもう使われていない。","word"];
EXAMPLES[1038]=["That ship goes abroad from this port.","あの船はこの港から外国に行きます。","port"];
EXAMPLES[1039]=["Do you hold him in great account?","彼を重視しているのですか。","hold"];
EXAMPLES[1040]=["Please remember me to all your family.","ご家族によろしく。","remember"];
EXAMPLES[1041]=["I went to bed later than usual.","わたしはいつもより遅く床に就いた。","usual"];
EXAMPLES[1042]=["They will set up a new company.","彼らは新しい会社を創設するつもりだ。","set"];
EXAMPLES[1043]=["I was constrained to tell a lie.","私はやむなく嘘をついた。","lie"];
EXAMPLES[1044]=["The people at large are against war.","一般大衆は戦争に反対している。","war"];
EXAMPLES[1045]=["Why don't you wear summer clothes?","夏服を着ればいいのに。","wear"];
EXAMPLES[1046]=["She gave us some useful information.","彼女は私たちに役に立つ情報をくれました。","useful"];
EXAMPLES[1047]=["They were really cut from the same cloth.","本当に瓜二つだわ。","cloth"];
EXAMPLES[1048]=["Don't let anyone enter the room.","誰も部屋に入れてはいけない。","enter"];
EXAMPLES[1049]=["Smoking is a danger to your health.","喫煙は健康にとって危険な物だ。","health"];
EXAMPLES[1050]=["You may invite whoever wants to come.","誰でも来たい人を招待してよい。","invite"];
EXAMPLES[1051]=["You must speak in a loud voice.","あなたは大声で話さなければならない。","loud"];
EXAMPLES[1052]=["We can't really throw it away!","本当に捨てるわけにはいかないよ。","throw"];
EXAMPLES[1053]=["I'll finish it in one hour.","１時間で終わります。","finish"];
EXAMPLES[1054]=["I can't abide such a person.","私はそんな人は、我慢ができない。","person"];
EXAMPLES[1055]=["Oh, don't worry about that.","そんな事は気にしないでください。","worry"];
EXAMPLES[1056]=["His wife opened the door for him.","彼の妻は彼のためにドアを開けた。","wife"];
EXAMPLES[1057]=["The dog didn't eat the meat.","その犬は肉を食べなかった。","meat"];
EXAMPLES[1059]=["I wish I could give up smoking.","私は煙草をやめればいいのだが。","wish"];
EXAMPLES[1060]=["We came in sight of the hill.","丘の見える所にやってきた。","hill"];
EXAMPLES[1061]=["There is little hope of his success.","彼の成功の望みはほとんどない。","success"];
EXAMPLES[1062]=["I think the wind's dropping off.","風が弱くなってきたようだね。","wind"];
EXAMPLES[1063]=["This bridge is built of stone.","この橋は石で作られている。","stone"];
EXAMPLES[1064]=["This pork is a bit off.","この豚肉は少しいたんでいる。","pork"];
EXAMPLES[1065]=["Someone who wants to touch me inside.","ただ一人待ち続けていた。","inside"];
EXAMPLES[1066]=["There is no factory in this village.","この村には工場は一つもない。","factory"];
EXAMPLES[1067]=["That's Tom's house with the red roof.","屋根が赤いあの家がトムの家だ。","roof"];
EXAMPLES[1068]=["Don't look back on your past.","過ぎたことを振り返ってはいけない。","past"];
EXAMPLES[1069]=["I'm a good sailor.","私は船酔いしない。","sailor"];
EXAMPLES[1070]=["Don't put sugar in my coffee.","私のコーヒーには砂糖を入れないで下さい。","sugar"];
EXAMPLES[1071]=["This old house is made of wood.","この古い家は木材でできている。","wood"];
EXAMPLES[1072]=["You seem to have the wrong number.","番号をお間違いのようですが。","seem"];
EXAMPLES[1073]=["Don't wake up the sleeping child.","寝ている子供を起こすな。","wake"];
EXAMPLES[1074]=["I can't pay for the car.","私はその車の代金を払うことが出来ない。","pay"];
EXAMPLES[1075]=["Pass me the salt, will you?","塩を回して下さい。","salt"];
EXAMPLES[1076]=["There's more cloud today than yesterday.","今日は昨日より雲が多い。","cloud"];
EXAMPLES[1077]=["I will ask him about it tomorrow.","明日そのことについて彼に尋ねるつもりです。","ask"];
EXAMPLES[1078]=["This house and this land is mine!","この土地とこの家は私の物ですよ。","land"];
EXAMPLES[1079]=["The earth is a beautiful planet.","地球は美しい惑星だ。","planet"];
EXAMPLES[1080]=["There is little water in the pond.","その池にはほとんど水がない。","pond"];
EXAMPLES[1081]=["This book gave me a good laugh.","この本は笑えたよ。","laugh"];
EXAMPLES[1082]=["Winter does not look real without snow.","冬はやっぱり雪がないとね。","real"];
EXAMPLES[1083]=["A new teacher stood before the class.","新しい先生がみんなの目の前に立った。","stood"];
EXAMPLES[1084]=["He came back home a while ago.","彼は先程家に帰ってきた。","while"];
EXAMPLES[1085]=["Don't give up if you fail.","失敗してもあきらめてはいけない。","fail"];
EXAMPLES[1086]=["The policeman caught him by the arm.","警官は彼の腕をつかんだ。","arm"];
EXAMPLES[1087]=["She enjoyed herself at the party yesterday.","昨日彼女はパーティーで楽しんだ。","enjoyed"];
EXAMPLES[1088]=["All the boys spoke each in turn.","少年たちは順々にしゃべった。","spoke"];
EXAMPLES[1089]=["Nothing but peace can save the world.","平和しか世界を救うことはできない。","save"];
EXAMPLES[1090]=["I tried in vain to open it.","それを開けようとしたがだめだった。","tried"];
EXAMPLES[1091]=["He sold his house for 50000 dollars.","彼は家を５万ドルで売った。","sold"];
EXAMPLES[1092]=["I was foolish enough to believe him.","私は愚かにも彼を信じてしまった。","foolish"];
EXAMPLES[1093]=["I watched a baseball game on television.","私はテレビで野球の試合を見た。","watched"];
EXAMPLES[1094]=["She played a trick on my sister.","彼女は私の妹にいたずらをした。","played"];
EXAMPLES[1095]=["We hardly realize how important it is.","それがどんなに重要かほとんどわかっていない。","realize"];
EXAMPLES[1096]=["This is just between you and me.","ここだけの話なんだけど。","between"];
EXAMPLES[1097]=["The promise I made then still holds.","あのとき私がした約束は有効だ。","then"];
EXAMPLES[1098]=["My camera is much better than yours.","私のカメラはあなたのカメラよりずっといい。","yours"];
EXAMPLES[1099]=["I feel a great joy for this job.","私はこの仕事に大きな喜びを感じている。","joy"];
EXAMPLES[1100]=["I feel a little weak today.","今日はちょっとふらふらする。","weak"];
EXAMPLES[1101]=["It's not even worth a thought.","思う価値さえない。","thought"];
EXAMPLES[1102]=["Tom is two years senior to me.","トムは私より２つ年上である。","senior"];
EXAMPLES[1103]=["Don't waste your time and money.","時間と金を無駄に使うな。","waste"];
EXAMPLES[1104]=["All's fish that comes to the net.","網にかかったものは何でも魚だ。","net"];
EXAMPLES[1105]=["I have known her for two years.","私は彼女を２年間知っている。","her"];
EXAMPLES[1106]=["I waved my hand to them.","私は彼らに向かって手を振った。","waved"];
EXAMPLES[1107]=["He stood up when I went in.","私が入っていくと彼は立ち上がった。","went"];
EXAMPLES[1108]=["You'll have to start at once.","すぐに出発しなければならないでしょう。","once"];
EXAMPLES[1109]=["She bought a toy for her child.","彼女は子供におもちゃを買ってやりました。","toy"];
EXAMPLES[1110]=["She used to play tennis on Sunday.","日曜日には彼女はテニスをしたものだった。","used"];
EXAMPLES[1111]=["John is too fat to run fast.","ジョンは速く走るには太りすぎている。","fat"];
EXAMPLES[1112]=["I don't dislike him at all.","私は決して彼が嫌いなのではない。","dislike"];
EXAMPLES[1113]=["English is studied all over the world.","英語は世界中で学ばれている。","studied"];
EXAMPLES[1114]=["I'm not worried about the price.","お金はいくらかかってもかまいません。","worried"];
EXAMPLES[1115]=["I hear from my mother every month.","私は母から毎月便りをもらう。","hear"];
EXAMPLES[1116]=["The doctor is a man of culture.","その医者は教養のある人だ。","culture"];
EXAMPLES[1117]=["The moon is low in the sky.","月が空に低く出ている。","low"];
EXAMPLES[1118]=["Where in Japan did you grow up?","日本のどこであなたは育ちましたか。","grow"];
EXAMPLES[1119]=["Could I have another glass of beer?","ビールをもう一杯いただけますか。","beer"];
EXAMPLES[1120]=["We may as well begin without him.","彼なしで始めてもよかろう。","begin"];
EXAMPLES[1121]=["To work all night, or not.","夜を徹するか否か。","or"];
EXAMPLES[1122]=["Two boys are absent from school today.","今日は二人の男生徒が学校を休んでいる。","absent"];
EXAMPLES[1123]=["If you can, come with us.","もし来れたら、私たちと一緒に来なさい。","If"];
EXAMPLES[1124]=["The sky lightened as it stopped raining.","雨がやんで空が明るくなった。","stopped"];
EXAMPLES[1125]=["He has quite a few friends.","彼はかなり多数の友達がいる。","a few"];
EXAMPLES[1126]=["Don't be scared of making mistakes.","失敗を怖がることはありません。","be scared of"];
EXAMPLES[1127]=["When does his train arrive at Kyoto?","彼が乗った列車はいつ京都に着きますか。","arrive at"];
EXAMPLES[1128]=["May I ask about your family?","家族について聞いてもいいですか。","ask about"];
EXAMPLES[1129]=["Why not talk to her about it directly?","なぜ、彼女に直接言わないの。","talk to"];
EXAMPLES[1130]=["For example, do you like English?","例えば、君は英語が好きですか。","For example"];
EXAMPLES[1131]=["A host of friends came to see me off.","たくさんの友人が見送りにやってきた。","host"];
EXAMPLES[1132]=["We made the most of the opportunity.","私たちはその機会を最大限に利用した。","most of"];
EXAMPLES[1133]=["Put it back in the nest.","それを巣に戻しなさい。","nest"];
EXAMPLES[1134]=["I want to go abroad.","私は外国へ行きたい。","go abroad"];
EXAMPLES[1136]=["What do your words add up to?","結局お言葉はどういう意味になるのですか。","add"];
EXAMPLES[1138]=["There is only one day left, whether we like it or not.","泣いても笑ってもあと一日。","one day"];
EXAMPLES[1139]=["Yesterday she sat for the entrance examination.","昨日彼女は入学試験を受けた。","sat"];
EXAMPLES[1140]=["You have only to ask for it.","あなたはそれを求めさえすればよい。","ask for"];
EXAMPLES[1141]=["This medicine does not agree with me.","この薬は僕に合わない。","medicine"];
EXAMPLES[1142]=["The boy turned out to be clever.","その少年は賢いことがわかった。","clever"];
EXAMPLES[1143]=["Where does the airport bus leave from?","空港までいくバスは、どこからでますか。","airport"];
EXAMPLES[1144]=["She has a big problem, though.","でも彼女、大問題を抱えているのです。","though"];
EXAMPLES[1145]=["Let's finish up in a hurry.","急いで終わりにしよう。","hurry"];
EXAMPLES[1146]=["He is better off than ever before.","彼はかつてなかったほど裕福である。","ever"];
EXAMPLES[1147]=["On the other hand we learned a great deal from the experience.","他方でその経験から学んだものも大きかった。","from the experience"];
EXAMPLES[1148]=["What is the meaning of this word?","この単語の意味は何ですか。","meaning"];
EXAMPLES[1149]=["May the new year bring you happiness!","今年もよい年でありますように。","happiness"];
EXAMPLES[1150]=["I'll call back at four o'clock.","私は４時に電話をかけなおすつもりです。","call back"];
EXAMPLES[1151]=["What do you think of his idea?","彼の考えをどう思いますか。","think of"];
EXAMPLES[1152]=["Did you make out what he said?","彼の言うことがわかったか。","Did"];
EXAMPLES[1153]=["Who will look after your dog tomorrow?","明日は誰が犬の世話をするのですか。","look after"];
EXAMPLES[1154]=["He is no better than a fool.","彼はでくの坊にすぎない。","fool"];
EXAMPLES[1156]=["They're not afraid of hard work.","彼らは一生懸命に働く。","afraid"];
EXAMPLES[1158]=["Can you make sense of this poem?","君はこの詩が理解できるかい。","poem"];
EXAMPLES[1159]=["Be kind to old people.","老人をいたわりなさい。","kind to"];
EXAMPLES[1160]=["It's a pain in the neck.","ほとほと困っています。","neck"];
EXAMPLES[1162]=["I finished the work for myself.","私は独力でその仕事を終えた。","work for"];
EXAMPLES[1163]=["I want to live in comfort.","私は快適な生活がしたい。","live in"];
EXAMPLES[1164]=["I would rather die than do it.","私はそれをするよりむしろ死にたい。","die"];
EXAMPLES[1165]=["Tom offered to lend me the money.","トムは私に金を貸そうと申し出た。","lend"];
EXAMPLES[1167]=["This is a matter of capital importance.","これは最も重要な問題だ。","capital"];
EXAMPLES[1168]=["This is worth one million yen.","これは百万円の価値がある。","million"];
EXAMPLES[1169]=["What has brought you here so early?","なぜこんなに早く来たの？","brought"];
EXAMPLES[1170]=["We have lived in Osaka six years.","私達は６年間大阪に住んでいた。","lived"];
EXAMPLES[1171]=["Try on that shirt.","あのシャツを着てみなさい。","Try on"];
EXAMPLES[1172]=["She came out with some strange tunings.","彼女は奇妙なことを口にした。","strange"];
EXAMPLES[1174]=["I went home to change my clothes.","着替えをするために家に帰った。","change"];
EXAMPLES[1175]=["She put the magazine on the table.","テーブルにその雑誌を置いた。","magazine"];
EXAMPLES[1176]=["What did you talk about?","君は何について話しましたか。","talk about"];
EXAMPLES[1177]=["I don't think I can get along with him.","彼とうまくやっていく自信がない。","get along with"];
EXAMPLES[1178]=["He discovered how to open the box.","彼は箱の開け方をわかった。","discovered"];
EXAMPLES[1179]=["I worked on the farm all day.","１日中農場で働いていた。","farm"];
EXAMPLES[1180]=["He didn't explain it at all.","彼は全然それを説明しなかった。","explain"];
EXAMPLES[1181]=["Let's sit here on the grass.","ここの芝生に座りましょう。","grass"];
EXAMPLES[1182]=["Where on earth did you meet him?","一体どこで彼に会ったんだ。","earth"];
EXAMPLES[1183]=["He tried to keep dry as best he could.","彼は出来るだけ濡れないようにした。","dry"];
EXAMPLES[1185]=["Why don't I try to do something about the garden?","庭の手入れでもしようかな。","try to"];
EXAMPLES[1186]=["Your advice is always helpful to me.","君の助言はいつも私の役に立つ。","advice"];
EXAMPLES[1187]=["The students missed class three times in a row.","その学生達は続けて３回授業に出席しなかった。","row"];
EXAMPLES[1188]=["He is about to leave for London.","彼はまさにロンドンへ出発しようとしている。","leave for"];
EXAMPLES[1189]=["May I introduce my friend to you.","私の友人を紹介したいのですが。","introduce"];
EXAMPLES[1190]=["Let's keep in touch.","交際を続けましょう。","keep in touch"];
EXAMPLES[1191]=["Can you make yourself understood in English?","君は英語で話しが通じますか。","understood"];
EXAMPLES[1192]=["I'll bring it to you tomorrow.","明日そちらへ持ってまいります。","bring"];
EXAMPLES[1193]=["Congratulations on being accepted to the school you've always wanted to go to.","行きたい学校に入れてよかったね。","go to"];
EXAMPLES[1194]=["I didn't believe him at first.","最初は彼のこと信じなかった。","believe"];
EXAMPLES[1195]=["What do you want to do in the future?","君は将来何をしたいですか。","in the future"];
EXAMPLES[1196]=["There is no knowing what may happen.","何が起こるか知る由もない。","happen"];
EXAMPLES[1197]=["Were you to take it back?","君はそれを取り返すはずでしたか。","take it back"];
EXAMPLES[1199]=["She sang a Japanese song for us.","彼女は私たちに日本の歌をうたってくれた。","sang"];
EXAMPLES[1200]=["The girl singing over there is my sister.","あそこで歌っている少女は私の妹です。","over there"];
EXAMPLES[1201]=["We should make good use of dictionaries when studying a foreign language.","外国語を学ぶときは辞書をよく利用しましょう。","foreign language"];
EXAMPLES[1202]=["I hung a picture on the wall.","私は壁に絵を掛けた。","on the wall"];
EXAMPLES[1203]=["Please stand by me when I need you.","困った時にいつでも味方になってください。","stand by"];
EXAMPLES[1204]=["Because I want to be a translator.","なぜなら私は翻訳家になりたいからです。","Because"];
EXAMPLES[1205]=["The important thing is to listen carefully.","大切なことは注意して聞く事だ。","carefully"];
EXAMPLES[1206]=["My brother goes to college in kobe.","兄は神戸の大学に行っています。","college"];
EXAMPLES[1208]=["Even a little child knows its name.","小さな子どもでもその名前を知っている。","Even"];
EXAMPLES[1209]=["He could not carry out his plan.","彼は自分の計画を実行することが出来なかった。","carry"];
EXAMPLES[1210]=["The teacher looked over the exam papers.","先生は答案を調べた。","exam"];
EXAMPLES[1211]=["He is by no means bright.","彼は決して頭のいい方ではない。","bright"];
EXAMPLES[1212]=["He cried out and ran away.","彼は悲鳴をあげて逃げて行った。","cried"];
EXAMPLES[1213]=["You are not to break the law.","法律を犯してはいけない。","law"];
EXAMPLES[1214]=["For example, do you like English?","例えば、君は英語が好きですか。","example"];
EXAMPLES[1215]=["Don't find fault with other people.","他人のあら捜しをするな。","find"];
EXAMPLES[1217]=["A policeman was sent for at once.","すぐに巡査が呼びにやられた。","sent"];
EXAMPLES[1219]=["The reason for your failure is that you did not try hard enough.","あなたが失敗したのは努力が足りなかったからだ。","try hard"];
EXAMPLES[1220]=["You learn a lot about your own country if you live abroad.","外国に住むと自分の国のことが良く分かる。","live abroad"];
EXAMPLES[1221]=["From now on let us study in the morning.","午後は午前中に勉強するようにしよう。","From now on"];
EXAMPLES[1222]=["My eyes get tired very easily.","目が疲れやすいです。","get tired"];
EXAMPLES[1228]=["I'm looking for a gift for my wife.","妻への贈り物を探しているんです。","I'm looking for a gift"];
EXAMPLES[1230]=["I'll take this one.","これをもらいます。","I'll take this one"];
EXAMPLES[1232]=["May I try it on?","試着できますか。","May I try it on"];
EXAMPLES[1236]=["Let's meet at the station at eight tomorrow morning.","明日の朝８時に駅で会いましょう。","Let's meet at the station"];
EXAMPLES[1239]=["I can't say but that I agree with you.","君に賛成だとしか言えない。","I agree with you"];
EXAMPLES[1240]=["Mm-hm. I think so too.","ウン、僕もその通りだと思うよ。","I think so too"];
EXAMPLES[1241]=["It's up to you to decide whether or not to go.","行くべきかどうかを決めるのは君次第だ。","It's up to you"];
EXAMPLES[1242]=["That's a good idea.","そりゃいい考えだ。","That's a good idea"];
EXAMPLES[1243]=["Now that you say it, I think you're right.","そう言えばそうだ。","you're right"];
EXAMPLES[1246]=["Have a nice weekend!","良い週末を。","Have a nice weekend"];
EXAMPLES[1249]=["He came back at nine o'clock.","彼は９時に帰ってきた。","at nine o'clock"];
EXAMPLES[1254]=["Excuse me, could you say that again more slowly?","すみません、もう一度ゆっくり言ってください。","could you say that again"];
EXAMPLES[1256]=["What does this mean?","これはどういう意味ですか。","What does this mean"];
EXAMPLES[1260]=["You should always be careful in your speech.","言葉遣いにはいつも気をつけるべきです。","be careful"];
EXAMPLES[1261]=["Please help yourself to more cake.","ケーキをもっと召し上がってください。","help yourself"];
EXAMPLES[1263]=["May I take a message?","何か伝えておきましょうか。","May I take a message"];
EXAMPLES[1264]=["Can I leave a message?","伝言をお願いしたいのですが。","Can I leave a message"];
EXAMPLES[1267]=["You can't miss it.","見逃すことはありませんよ。","You can't miss it"];
EXAMPLES[1268]=["Could you tell me the way?","道を教えてくれませんか。","Could you tell me the way"];
EXAMPLES[1273]=["How was your weekend?","週末はどうだった？","How was your weekend"];
EXAMPLES[1274]=["I went to the zoo.","私は動物園へ行った。","I went to the zoo"];
EXAMPLES[1275]=["I'm doing my homework.","私は私の宿題をしています。","I'm doing my homework"];
EXAMPLES[1278]=["Please turn off the light.","ライトのスイッチを切ってください。","turn off the light"];
EXAMPLES[1280]=["I'm looking forward to it.","私は楽しみにしています。","I'm looking forward to it"];
EXAMPLES[1282]=["No, I don't think so.","そうは思えないねえ。","I don't think so"];
EXAMPLES[1283]=["I guess it depends on the weather.","天気次第だと私は思う。","it depends"];
EXAMPLES[1284]=["I prefer tea to coffee.","わたしはコーヒーよりも茶をこのむ。","I prefer tea"];
EXAMPLES[1286]=["Thank you for your help.","手伝ってくれてどうもありがとう。","Thank you for your help"];
EXAMPLES[1288]=["That's all right as far as I am concerned.","私に関する限り、それでよろしい。","That's all right"];
EXAMPLES[1291]=["I'd love to see the movie.","ぜひその映画を見たい。","I'd love to"];
EXAMPLES[1292]=["That sounds good to me.","私はそれでもかまいませんよ。","sounds good to me"];
EXAMPLES[1293]=["Let's see. I bought it last week.","ええと、買ったのは先週でした。","Let's see"];
EXAMPLES[1294]=["I have no idea why it is so.","ぼくにはまるでその理由がわからない。","I have no idea"];
EXAMPLES[1295]=["What time is it now?","今の時刻は。","What time is it now"];
EXAMPLES[1296]=["I made a mistake through doing it in a hurry.","私はあわててやったので間違いをおかした。","I made a mistake"];
EXAMPLES[1297]=["Let's try again.","もう一度やってみましょう。","Let's try again"];
EXAMPLES[1301]=["Let's take a taxi.","タクシーに乗ろうよ。","Let's take a taxi"];
EXAMPLES[1302]=["How's the weather there?","そっちの天気は？","How's the weather there"];
EXAMPLES[1304]=["He didn't take an umbrella with him.","彼はかさをもっていかなかった。","take an umbrella"];
EXAMPLES[1306]=["I like playing tennis and golf.","テニスとゴルフが好きですね。","I like playing tennis"];
EXAMPLES[1307]=["Do you play any sports?","何かスポーツをしますか。","Do you play any sports"];
EXAMPLES[1311]=["Better luck next time.","次はきっとうまくいきますよ。","Better luck next time"];
EXAMPLES[1314]=["I'm afraid I can't help you.","お役に立てないと思います。","I'm afraid I can't"];
EXAMPLES[1316]=["That's fine with me.","私は結構ですよ。","That's fine with me"];
EXAMPLES[1317]=["What do you think of his idea?","彼の考えをどう思いますか。","What do you think"];
EXAMPLES[1321]=["It's on me.","僕のおごりですよ。","It's on me"];
EXAMPLES[1325]=["I'll do my best.","出来るだけがんばります。","I'll do my best"];
EXAMPLES[1326]=["Please tell me what happened to him.","彼に何があったのか話してください。","what happened"];
EXAMPLES[1327]=["I feel much better today.","今日はずっと具合いい。","I feel much better"];
EXAMPLES[1328]=["I have a headache now.","いま頭が痛い。","I have a headache"];
EXAMPLES[1329]=["You should see a doctor.","お医者様に診察してもらいなさい。","You should see a doctor"];
EXAMPLES[1330]=["Take this medicine when you have a cold.","かぜをひいたらこの薬を飲むんだよ。","Take this medicine"];
EXAMPLES[1331]=["Let's take a break.","さぁ、休憩をとろう。","Let's take a break"];
EXAMPLES[1334]=["I'm afraid we're going to be late for school.","学校に遅れそうだね。","we're going to be late"];
EXAMPLES[1339]=["You shouldn't have done it.","君はそれをするべきではなかったのに。","You shouldn't have"];
EXAMPLES[1342]=["That's very kind of you.","どうもご親切さま。","That's very kind of you"];
EXAMPLES[1344]=["I'm glad to hear that she is unmarried.","彼女が独身だとはうれしいね。","I'm glad to hear that"];
EXAMPLES[1347]=["What a surprise to see you here!","ここで君に会うとは驚きだ。","What a surprise"];
EXAMPLES[1348]=["I'll miss you.","あなたがいなくて寂しくなるでしょう。","I'll miss you"];
EXAMPLES[1349]=["Let's keep in touch.","交際を続けましょう。","Let's keep in touch"];
EXAMPLES[1352]=["Could you take our picture?","私たちのしゃしんをとっていただけますか。","Could you take our picture"];
EXAMPLES[1355]=["What would you like to eat?","何を召し上がりますか。","What would you like"];
EXAMPLES[1359]=["Did you make this doll by yourself?","この人形は君一人で作ったの？","Did you make this"];
EXAMPLES[1360]=["Let me give you a hand.","手伝いましょう。","Let me give you a hand"];
EXAMPLES[1363]=["The same to you.","ご同様に。","same to you"];
EXAMPLES[1374]=["I'll think about it and get back to you.","考えて返事します。","I'll think about it"];
EXAMPLES[1376]=["Come on in and make yourself at home.","適当に入って勝手にやって。","make yourself at home"];
EXAMPLES[1377]=["Would you like some tea or some coffee?","紅茶またはコーヒーはいかが？","Would you like some tea"];
EXAMPLES[1386]=["We had a kid just last year.","去年、子供が生まれたばかりです。","kid"];
EXAMPLES[1387]=["There is a fan on the desk.","机の上に扇風機があります。","fan"];
EXAMPLES[1388]=["Please write down your contact address here.","連絡先をここに書いてください。","contact"];
EXAMPLES[1390]=["Mary put her piano up for sale.","メアリーは自分のピアノを売りに出した。","sale"];
EXAMPLES[1391]=["How much is the tour?","そのツアーはいくらですか。","tour"];
EXAMPLES[1393]=["Computer supplies are very expensive in Japan.","日本ではコンピューター用品が非常に高い。","Computer"];
EXAMPLES[1395]=["Don't you have a sense of justice?","君には心配することが無いのか。","justice"];
EXAMPLES[1396]=["He is being carried away by a student movement.","彼は学生運動熱に浮かされている。","movement"];
EXAMPLES[1397]=["He was shown the photo by her.","彼は彼女にその写真を見せられた。","photo"];
EXAMPLES[1398]=["Safety is the most important thing.","安全が最も重要な事である。","Safety"];
EXAMPLES[1399]=["I often dream of the same scene.","私はよく同じ夢を見る。","scene"];
EXAMPLES[1400]=["I doubt the truth of his statement.","彼の言うことはくさい。","statement"];
EXAMPLES[1401]=["Who coaches the team?","そのチームは誰がコーチをしているのですか。","coaches"];
EXAMPLES[1404]=["She walked about in search of the dress.","彼女はそのドレスを探すのに歩き回った。","search"];
EXAMPLES[1405]=["They set up their backs against the claim.","その要求に対して怒った。","claim"];
EXAMPLES[1406]=["May I use your car, dad?","お父さん、車を使っても良いですか。","dad"];
EXAMPLES[1407]=["Your plan must fit in with mine.","あなたの計画を私に合わせなさい。","fit"];
EXAMPLES[1408]=["Generally speaking, what she says is right.","概して言えば、彼女の言うことは正しい。","Generally"];
EXAMPLES[1409]=["I prefer a hotel by the airport.","空港の近くのホテルを希望します。","hotel"];
EXAMPLES[1410]=["He is married to an American lady.","彼はアメリカの婦人と結婚している。","lady"];
EXAMPLES[1411]=["Everyone looked on me as a leader.","みんなが私をリーダーと認めた。","leader"];
EXAMPLES[1412]=["Everybody's fault is nobody's fault.","みんなの責任は、誰の責任でもない。","nobody"];
EXAMPLES[1414]=["I lead a regular life.","私は規則的な生活をしています。","regular"];
EXAMPLES[1415]=["Would you like to wait in the bar?","バーでお待ちになりますか。","bar"];
EXAMPLES[1416]=["Young and old went to battle.","老いも若きも戦争にいった。","battle"];
EXAMPLES[1417]=["He got hurt seriously in the traffic accident.","彼はその交通事故で大怪我をした。","seriously"];
EXAMPLES[1418]=["You will be able to dance well.","あなたは上手に踊れるようになるだろう。","dance"];
EXAMPLES[1420]=["I know none of the three men.","私はその３人の誰も知らない。","none"];
EXAMPLES[1421]=["I feel much worse today than yesterday.","昨日より今日のほうがずっと気分が悪い。","worse"];
EXAMPLES[1422]=["This is the worst hotel in town.","これは町で一番ひどいホテルです。","worst"];
EXAMPLES[1423]=["My school has a band.","私の学校にはバンドがあります。","band"];
EXAMPLES[1424]=["Please speak as clearly as you can.","出来るだけはっきり言ってください。","clearly"];
EXAMPLES[1425]=["Will you make every effort to come?","何とか都合して来てください。","effort"];
EXAMPLES[1426]=["How many days are there before Christmas?","クリスマスまであと何日ありますか。","Christmas"];
EXAMPLES[1427]=["We took a direct road to town.","私たちは町へ直行した。","direct"];
EXAMPLES[1428]=["Her marriage brought happiness to her parents.","彼女は結婚して両親は幸せだ。","marriage"];
EXAMPLES[1429]=["Her skin is as white as snow.","彼女の肌は雪のように白い。","skin"];
EXAMPLES[1431]=["I didn't catch what he said.","私は彼の言ったことがわからなかった。","catch"];
EXAMPLES[1432]=["The damage is done.","もう手遅れだ。","damage"];
EXAMPLES[1433]=["The new machine will be in use.","その新しい機械が用いられるようになるだろう。","machine"];
EXAMPLES[1434]=["He is a doctor and a university professor.","あの人は医者でありまた大学の先生でもある。","professor"];
EXAMPLES[1436]=["He was made captain of the team.","彼はそのチームの主将になった。","captain"];
EXAMPLES[1437]=["His story was highly amusing to us.","彼の話はとても面白かった。","highly"];
EXAMPLES[1438]=["You must not get away from reality.","現実から逃げてはいけないよ。","reality"];
EXAMPLES[1439]=["He understands everything right on the spot.","彼は何でもすぐに理解する。","spot"];
EXAMPLES[1440]=["This problem is a real challenge.","この問題はとても難しい。","challenge"];
EXAMPLES[1441]=["Feel free to comment on any point made here.","これについて、自由に批評して下さい。","comment"];
EXAMPLES[1442]=["I work for a travel agency.","私は、旅行会社に勤めています。","agency"];
EXAMPLES[1443]=["Where did you get your camera repaired?","どこでカメラを修理してもらったのですか。","camera"];
EXAMPLES[1445]=["I like pop music.","私はポップスが好きです。","pop"];
EXAMPLES[1446]=["She is a trial to her parents.","両親は彼女に手を焼いている。","trial"];
EXAMPLES[1447]=["Won't you have some more coffee?","コーヒーをもう少しいかがですか。","coffee"];
EXAMPLES[1448]=["I stand for freedom of speech for everyone.","私は、あらゆる人の言論の自由に賛成だ。","freedom"];
EXAMPLES[1449]=["We'll give an interview in the afternoon.","午後に面接を行います。","interview"];
EXAMPLES[1450]=["Because the channel was changed he got angry.","チャンネルを変えたので彼は怒った。","channel"];
EXAMPLES[1451]=["There is little water in the glass.","コップにはほとんど水がありません。","glass"];
EXAMPLES[1454]=["He has powerful arms.","彼は腕の力が強い。","powerful"];
EXAMPLES[1455]=["She asked the police for protection.","彼女は警察に保護を求めた。","protection"];
EXAMPLES[1458]=["This box will serve as a table.","この箱はテーブルの代用となる。","serve"];
EXAMPLES[1459]=["Spring is slow in coming this year.","今年は春が来るのが遅い。","slow"];
EXAMPLES[1460]=["He was at the bottom of the class.","彼はクラスのびりだった。","bottom"];
EXAMPLES[1461]=["The trouble may lie in the engine.","故障はエンジンにあるのかもしれない。","engine"];
EXAMPLES[1462]=["He is my good partner.","彼は私のよきパートナーだ。","partner"];
EXAMPLES[1464]=["I feel like a brand new person.","とても気分がリフレッシュされる。","brand"];
EXAMPLES[1465]=["The students stood waiting for a bus.","学生達はバスを待ちながら立っていた。","bus"];
EXAMPLES[1466]=["His old car don't get a cent.","彼の古い車じゃ、一銭にもならないよ。","cent"];
EXAMPLES[1467]=["I took no count of what he said.","彼の言ったことなど問題にしなかった。","count"];
EXAMPLES[1469]=["Are you the owner of this house?","あなたはこの家の主人ですか。","owner"];
EXAMPLES[1470]=["Please put it on the scale.","はかりの上にそれを置いてください。","scale"];
EXAMPLES[1471]=["He passed the examination with the highest score.","彼は試験に一番に合格した。","score"];
EXAMPLES[1472]=["We moved here separately three years ago.","私たちは３年前ここに引っ越してきた。","separately"];
EXAMPLES[1474]=["His sister makes too much of fashion.","彼の姉はファッションのことを考えすぎる。","fashion"];
EXAMPLES[1475]=["They decided to pull down the old building.","古い建物を取り壊すことに決めた。","pull"];
EXAMPLES[1476]=["Can you push the door open?","ドアを押し開けられますか。","push"];
EXAMPLES[1478]=["That's a matter of prime importance.","それは最も重要な問題だ。","prime"];
EXAMPLES[1479]=["Please give me a ring this evening.","今晩私に電話して下さい。","ring"];
EXAMPLES[1481]=["She kept body and soul together in such days.","彼女はあのような時代をやっと生きてきた。","soul"];
EXAMPLES[1482]=["You are now an adult.","君はもう大人だ。","adult"];
EXAMPLES[1483]=["He is an artist in a sense.","彼はある意味で芸術家だ。","artist"];
EXAMPLES[1484]=["Haven't you got a cheaper edition?","もっと安い本はないですか。","edition"];
EXAMPLES[1486]=["I am in favor of the option.","私はその意見に賛成だ。","option"];
EXAMPLES[1487]=["Somebody called my name in the dark.","暗闇で誰かが私の名前を呼んだ。","Somebody"];
EXAMPLES[1489]=["He wants to go back to the wild.","彼は野生に戻りたいと思っている。","wild"];
EXAMPLES[1490]=["It is good to be a winner.","勝者となることはよいことである。","winner"];
EXAMPLES[1491]=["We made camp near the lake.","我々は湖の近くでキャンプをした。","camp"];
EXAMPLES[1492]=["He is quite young in spirit.","彼はまったく気が若い。","spirit"];
EXAMPLES[1493]=["There is a television in my room.","私の部屋にはテレビがある。","television"];
EXAMPLES[1494]=["Don't be a trouble to mother.","お母さんに心配をかけるな。","trouble"];
EXAMPLES[1495]=["The eastern sky was getting light.","東の空が白み始めていた。","eastern"];
EXAMPLES[1497]=["This is a little gift for you.","これはお土産です。","gift"];
EXAMPLES[1498]=["What time did you shut the shop?","店を何時に閉めましたか。","shut"];
EXAMPLES[1499]=["Write down your date of birth here.","ここに誕生日を書いてください。","birth"];
EXAMPLES[1500]=["Give me a copy of this book.","この本を１部ください。","copy"];
EXAMPLES[1502]=["How lucky to meet you here.","ここで会えるとはなんて運がいいのだろう。","lucky"];
EXAMPLES[1504]=["Could you tell me my balance?","残高を教えてくれますか。","balance"];
EXAMPLES[1505]=["Who is the boss of this company?","この会社の社長は誰ですか。","boss"];
EXAMPLES[1506]=["He has no connection with this affair.","彼はこの事件とは関係ない。","connection"];
EXAMPLES[1507]=["She doesn't care about her dress.","彼女は服装に気を使わない。","dress"];
EXAMPLES[1509]=["Don't give way to their request.","彼らの要求に屈してはいけません。","request"];
EXAMPLES[1510]=["Stick with it and you'll succeed.","成功するまでへこたれるな。","Stick"];
EXAMPLES[1511]=["He turned up the volume on the television.","彼はテレビの音量を大きくした。","volume"];
EXAMPLES[1512]=["Your sister has a sense of beauty.","あなたのお姉さんは審美感があるね。","beauty"];
EXAMPLES[1513]=["The accident took place at that corner.","その事故は、その角で起きた。","corner"];
EXAMPLES[1515]=["I think he is a good driver.","彼は運転が上手いと私は思う。","driver"];
EXAMPLES[1517]=["I fly into a rage easily.","すぐに腹がたちます。","fly"];
EXAMPLES[1518]=["I wish there was more variety in my work.","もっと仕事に変化があったならばなあ。","variety"];
EXAMPLES[1519]=["Youth comes but once in life.","一生のうちで青春なんて一度しかない。","Youth"];
EXAMPLES[1520]=["Tom can speak German as well as English.","トムは英語の他にドイツ語も話せる。","German"];
EXAMPLES[1522]=["To this day we call them indians.","今日まで彼らはインディアンと呼ばれている。","indians"];
EXAMPLES[1524]=["What did you do over the weekend?","週末はどうされましたか。","weekend"];
EXAMPLES[1525]=["It is expensive to live in Japan.","日本で暮らすのは高くつく。","expensive"];
EXAMPLES[1526]=["It is all over with me. it can't be helped.","万事休すだ。もうどうしようもない。","it can't be helped"];
EXAMPLES[1529]=["We talked until two in the morning.","僕らは夜中の２時まで話していた。","until"];
EXAMPLES[1530]=["I'm sorry to bother you.","邪魔してすみません。","sorry to bother you"];
EXAMPLES[1532]=["That's cheap, isn't it?","それは安いですね。","cheap"];
EXAMPLES[1534]=["He went there instead of his father.","彼は父の代わりにそこへ行った。","instead"];
EXAMPLES[1535]=["What about having fish for dinner?","ディナーに魚はどうですか。","What about"];
EXAMPLES[1536]=["They are having lunch in the garden.","彼らは庭で昼食をとっている。","garden"];
EXAMPLES[1537]=["I have to look for my pen.","私のペンをさがさなければならない。","look for"];
EXAMPLES[1538]=["Please speak more slowly.","もっとゆっくり言ってください。","Please speak more slowly"];
EXAMPLES[1539]=["We had to call off the game because of rain.","雨のために試合を中止せざるを得なかった。","because of"];
EXAMPLES[1540]=["Could you show me the way to the bus stop?","バス停までの道を教えてくれませんか。","Could you show me the way"];
EXAMPLES[1544]=["May I borrow this book?","この本を借りてもいいですか。","May I borrow this book"];
EXAMPLES[1545]=["Please turn off the light.","ライトのスイッチを切ってください。","Please turn off the light"];
EXAMPLES[1546]=["Shall I help you?","お手伝いしようか。","Shall I help you"];
EXAMPLES[1547]=["Let me help you to do the work.","あなたの仕事の手助けをさせて下さい。","Let me help you"];
EXAMPLES[1548]=["Just to watch it made me nervous.","見ていてハラハラさせられた。","nervous"];
EXAMPLES[1550]=["There is a car in front of the building.","ビルの前に車があります。","in front of"];
EXAMPLES[1552]=["I have to take an examination in history tomorrow.","あすは歴史の試験を受けなくてはならない。","have to"];
EXAMPLES[1553]=["If you have any questions, please let me know.","もしご質問があればお知らせください。","let me know"];
EXAMPLES[1554]=["This desk was too heavy to lift.","この机は重くて持ち上がらなかった。","heavy"];
EXAMPLES[1556]=["There's no need to get so angry.","そんなに怒る必要はない。","need to"];
EXAMPLES[1557]=["I'll be right back.","じきに戻って来ます。","I'll be right back"];
EXAMPLES[1560]=["Can you break away from your parents?","君は親元から飛び出せるか。","break"];
EXAMPLES[1561]=["Let's eat out tonight.","今晩、外食しましょう。","Let's eat out tonight"];
EXAMPLES[1562]=["I will win the game next time.","この次は試合に勝つぞ。","win"];
EXAMPLES[1564]=["To keep early hours makes you healthy.","早寝早起きすると健康になります。","healthy"];
EXAMPLES[1565]=["Let's set up a sign here.","ここへ看板を立てよう。","sign"];
EXAMPLES[1567]=["Maybe you'd better come with us.","ことによると、きみにも一緒にきてもらう。","Maybe"];
EXAMPLES[1568]=["How often have you been to Europe?","何回ヨーロッパにいったことがあるのですか。","How often"];
EXAMPLES[1569]=["I didn't mean to hurt you.","君の心を傷つけるつもりはなかった。","hurt"];
EXAMPLES[1574]=["There is a river beside the house.","その家の側には川がある。","beside"];
EXAMPLES[1578]=["You should not speak ill of others.","他人のを悪口を言うべきでない。","should"];
EXAMPLES[1582]=["I'll look forward to it.","それは楽しみです。","look forward to"];
EXAMPLES[1585]=["You had better not drive a car.","君は車を運転しない方がいい。","drive"];
EXAMPLES[1587]=["I'm on my way to visit a friend who's in the hospital.","友人を見舞いに行く所です。","I'm on my way"];
EXAMPLES[1591]=["You are as tall as I am.","君は僕と同じ背の高さです。","tall"];
EXAMPLES[1592]=["Are you busy now?","今は忙しいですか。","Are you busy now"];
EXAMPLES[1594]=["We have plenty of time.","時間はたっぷりあります。","We have plenty of time"];
EXAMPLES[1597]=["They were all sold out.","それはすべて売り切れた。","sold out"];
EXAMPLES[1600]=["This was how he entered the university.","このようにして、彼はその大学に入学した。","university"];
EXAMPLES[1603]=["Lots of famous people come here.","たくさんの有名人がここに来ます。","Lots of"];
EXAMPLES[1605]=["Who was this machine invented by?","この機械は誰によって発明されましたか。","invented"];
EXAMPLES[1607]=["Ten to one he will get married to her.","十中八、九まで彼は彼女と結婚するだろう。","get married"];
EXAMPLES[1610]=["She put the money in the bank.","彼女はその金を銀行に預けた。","bank"];
EXAMPLES[1612]=["He will win the first prize.","彼は一番をとるだろう。","prize"];
EXAMPLES[1617]=["Such a thing cannot be found everywhere.","そんなものはどこでも見られるわけではない。","everywhere"];
EXAMPLES[1619]=["This plant is good to eat.","この植物は食べられる。","plant"];
EXAMPLES[1620]=["Are you going to take part in the next race?","次のレースに参加するつもりですか。","take part in"];
EXAMPLES[1622]=["I hit upon a good idea then.","その時私は良い考えを思い付いた。","hit"];
EXAMPLES[1623]=["Where can I try this on?","どこで試着できますか。","can I try this on"];
EXAMPLES[1624]=["Why was it that she got angry?","彼女が腹を立てたのはいったいなぜだろう。","angry"];
EXAMPLES[1625]=["She may well be proud of her only son.","彼女が一人息子を自慢するのはもっともだ。","be proud of"];
EXAMPLES[1626]=["It's a hard, dirty job.","それはたいへんで、きたない仕事なのだ。","dirty"];
EXAMPLES[1629]=["You ought not to break your promise.","約束を破るべきではありません。","promise"];
EXAMPLES[1630]=["I'm going to attend to the customer.","その客の応対は私がします。","customer"];
EXAMPLES[1632]=["This is twice as large as that.","これはあれの２倍の大きさがある。","twice"];
EXAMPLES[1635]=["He took no notice of my advice.","彼は私の忠告を無視した。","notice"];
EXAMPLES[1636]=["The accident happened before my very eyes.","その事故は私のまさにすぐ目の前で起こった。","accident"];
EXAMPLES[1637]=["She has no more than 100 dollars.","彼女は１００ドルしか持っていない。","more than"];
EXAMPLES[1639]=["My poor English cost me my job.","英語が下手だったので職を失った。","cost"];
EXAMPLES[1640]=["How long can I keep this book?","この本どのくらいお借りしていいですか。","keep"];
EXAMPLES[1642]=["I think that they will be late.","彼らは遅れると思います。","late"];
EXAMPLES[1644]=["This vending machine is out of order.","この自動販売機は故障しています。","order"];
EXAMPLES[1646]=["Let's get started right away.","今すぐ始めよう。","right away"];
EXAMPLES[1647]=["The show was far from being a failure.","そのショーは失敗どころではなかった。","far from"];
EXAMPLES[1648]=["Please pick up the pen from the floor.","床からペンを取ってください。","pick up"];
EXAMPLES[1651]=["He paid no attention to my advice.","彼は私の忠告に全く注意を払わなかった。","attention"];
EXAMPLES[1652]=["My husband is always reading in bed.","夫はいつもベッドで本を読むんです。","husband"];
EXAMPLES[1654]=["We can call English an international language.","私達は英語を国際語と呼ぶことができます。","international"];
EXAMPLES[1657]=["It's boring to wait for a train.","電車は待つことが退屈だ。","boring"];
EXAMPLES[1659]=["I am glad to hear the news.","私はその知らせを聞いてうれしい。","glad"];
EXAMPLES[1660]=["We saw a lake far below.","ずっと下の方に湖が見えた。","below"];
EXAMPLES[1662]=["The sea is very wide.","海はとても広い。","wide"];
EXAMPLES[1664]=["I've found something amazing!","すっごくいいものを見つけたよ！","amazing"];
EXAMPLES[1665]=["How long does it take by car?","車でどれくらいかかりますか。","How long does it take"];
EXAMPLES[1666]=["Can you give me a better price?","もっと安い価格になりませんか。","price"];
EXAMPLES[1668]=["Anyway, I'm getting more experience.","とにかく経験になります。","Anyway"];
EXAMPLES[1670]=["Is this the right way to the station?","駅へはこの道を行けばいいのですか。","Is this the right way"];
EXAMPLES[1672]=["I got off at the wrong station.","私は駅を間違えて下車しました。","I got off at the wrong station"];
EXAMPLES[1673]=["The room looks out on the ocean.","その部屋は海を見渡している。","ocean"];
EXAMPLES[1674]=["Would you please tell me when to get off?","いつ降りたらよいか教えて下さい。","please tell me when to get off"];
EXAMPLES[1677]=["Oh, you're going home tonight!","今夜帰省されるのですね。","tonight"];
EXAMPLES[1678]=["Don't forget to take an umbrella with you.","忘れずに傘を持って行きなさい。","take an umbrella with you"];
EXAMPLES[1679]=["Even a child knows right from wrong.","子供でさえ善と悪の区別がつく。","wrong"];
EXAMPLES[1682]=["You only imagine you've heard it.","それは君の空耳だ。","imagine"];
EXAMPLES[1684]=["He cannot write English without making mistakes.","彼は英語を書くと必ず間違える。","without"];
EXAMPLES[1686]=["I heard the news through the grapevine.","その知らせは人つてに聞いたよ。","through"];
EXAMPLES[1687]=["He has never been heard of since.","それ以来彼のうわさは聞いていない。","since"];
EXAMPLES[1690]=["Can I turn on the tv?","テレビつけてもいい？","turn on"];
EXAMPLES[1691]=["How are you feeling today?","今日は気分はいかがですか。","How are you feeling"];
EXAMPLES[1692]=["I forgot to turn off the tv before going to bed.","寝る前にテレビを消すのを忘れた。","turn off"];
EXAMPLES[1693]=["I have a fever.","熱があるんです。","I have a fever"];
EXAMPLES[1694]=["My friends celebrated my birthday.","友達が私の誕生日を祝ってくれた。","celebrated"];
EXAMPLES[1695]=["Don't be afraid of seeing the doctor.","医者にかかるのを怖がっては行けません。","be afraid of"];
EXAMPLES[1696]=["There is an exception to every rule.","どの規則にも例外がある。","rule"];
EXAMPLES[1697]=["Let's get off the bus.","バスから降りましょう。","get off"];
EXAMPLES[1698]=["I caught a cold.","私は風邪をひいた。","I caught a cold"];
EXAMPLES[1699]=["Your wallet is on the television set.","あなたの財布はテレビの上にありますよ。","wallet"];
EXAMPLES[1701]=["Why did he run away?","なぜ彼は逃げたのですか。","run away"];
EXAMPLES[1704]=["He is the last man to steal.","彼は盗みなどする人ではない。","steal"];
EXAMPLES[1706]=["Mary looked at herself in the mirror.","メアリーは鏡で自分を見た。","mirror"];
EXAMPLES[1707]=["You can stay with us for the time being.","君はしばらくの間私達のところにいてもよい。","stay with"];
EXAMPLES[1708]=["Don't stay up late every night.","毎晩遅くまで起きていてはいけない。","Don't stay up late"];
EXAMPLES[1710]=["Let's get something quick to drink.","急いで何か飲みましょう。","quick"];
EXAMPLES[1712]=["I'm a little tired.","私は少し疲れた。","I'm a little tired"];
EXAMPLES[1716]=["There's a hole in my coat.","私のコートには穴が開いている。","hole"];
EXAMPLES[1718]=["Don't cut your finger.","指を切らないでよ。","finger"];
EXAMPLES[1720]=["I'm not in good shape now.","最近調子が良くありません。","shape"];
EXAMPLES[1721]=["How many cars has that company bought?","その会社は車を何台買ったか。","company"];
EXAMPLES[1722]=["I prefer tea to coffee.","わたしはコーヒーよりも茶をこのむ。","I prefer tea to coffee"];
EXAMPLES[1723]=["Her dress is not to my taste.","彼女のドレスは私の趣味には合わない。","taste"];
EXAMPLES[1725]=["In fact, he loves her.","実際は彼は彼女を愛している。","In fact"];
EXAMPLES[1727]=["You should prepare a room for the visitor.","客のために部屋を準備しておきなさい。","visitor"];
EXAMPLES[1729]=["It's boiling in here.","ここはうだるように暑い。","boiling"];
EXAMPLES[1730]=["He grew up to be a doctor.","彼は成長して医者になった。","grew"];
EXAMPLES[1731]=["My brother has joined the baseball club.","弟は野球部に入った。","joined"];
EXAMPLES[1736]=["He has many acquaintances but few friends.","彼には知人は多いが友人は少ない。","few"];
EXAMPLES[1737]=["We won the match.","私たちはその試合に勝った。","We won the match"];
EXAMPLES[1738]=["He gave a good piece of advice.","彼は良い忠告を一つしてくれた。","piece"];
EXAMPLES[1741]=["He had every reason for doing so.","彼がそうしたのも無理はない。","reason"];
EXAMPLES[1742]=["I could live peacefully here.","ここでなら平和に暮らせるだろう。","peacefully"];
EXAMPLES[1744]=["I think I can handle it.","何とかできると思うよ。","handle"];
EXAMPLES[1750]=["We spent more money than was expected.","私たちは予想以上にたくさんの金を使った。","more"];
EXAMPLES[1751]=["What's your purpose in studying English?","英語を学ぶ目的は何ですか。","purpose"];
EXAMPLES[1753]=["Will you excuse me for just a moment?","ちょっと失礼してよいでしょうか。","just a moment"];
EXAMPLES[1754]=["The line is busy again.","また話し中だ。","The line is busy"];
EXAMPLES[1757]=["Tommy, can you hear me?","トミー、聞こえるかい？","can you hear me"];
EXAMPLES[1758]=["Move up to the front, please.","前のほうに進んで下さい。","Move"];
EXAMPLES[1760]=["He bought his daughter a new dress.","彼は娘に新しいドレスを買ってやった。","daughter"];
EXAMPLES[1762]=["Be kind to old people.","老人をいたわりなさい。","Be kind to"];
EXAMPLES[1764]=["I gather that they'll agree with us.","彼らは私達と同意見だと思う。","agree with"];
EXAMPLES[1766]=["I've got to fix my hair.","髪を整えないと。","fix"];
EXAMPLES[1767]=["She felt a pain in her side.","彼女はわき腹に痛みを感じた。","side"];
EXAMPLES[1769]=["I can't find my key.","鍵が見つからない。","I can't find my key"];
EXAMPLES[1771]=["I can't get anywhere with it.","手も足も出ない。","anywhere"];
EXAMPLES[1775]=["I feel that something is wrong.","何かおかしいと思います。","something is wrong"];
EXAMPLES[1777]=["I can't think out the design any more.","もうこれ以上、デザインを考えられない。","design"];
EXAMPLES[1778]=["You share his interest in this book?","君も彼のようにこの本に興味があるのか。","share"];
EXAMPLES[1780]=["You may be surprised to receive this letter.","この手紙を受け取って驚いたかもしれません。","receive"];
EXAMPLES[1781]=["She was injured in the traffic accident.","彼女は交通事故でけがをした。","injured"];
EXAMPLES[1784]=["She decided not to attend the meeting.","彼女は会議には出席しないことを決めた。","attend"];
EXAMPLES[1785]=["I go every year.","毎年行きます。","every year"];
EXAMPLES[1787]=["Take your time. there's no hurry.","ごゆっくりどうぞ。急ぐ必要はありません。","Take your time"];
EXAMPLES[1791]=["I will protect you from danger.","私はあなたを危険から守りましょう。","protect"];
EXAMPLES[1794]=["She came late as usual.","いつもの通り、彼女は遅れてやって来た。","as usual"];
EXAMPLES[1796]=["Even a child would notice the difference.","子供でも違いがわかるだろう。","difference"];
EXAMPLES[1798]=["You can speak as you actually feel.","実際感じたままを話してよい。","actually"];
EXAMPLES[1800]=["He seems to have been rich in those days.","彼は当時金持ちだったらしい。","in those days"];
EXAMPLES[1802]=["Don't be so noisy, please.","どうかそんなに騒がないで下さい。","noisy"];
EXAMPLES[1803]=["My father has given up smoking recently.","父は最近タバコをやめました。","recently"];
EXAMPLES[1805]=["The fact is we were not invited.","実のところ我々は招待されなかった。","fact"];
EXAMPLES[1807]=["Out of sight, out of mind.","目に見えないものは忘れられる。","sight"];
EXAMPLES[1808]=["It can't be judged in me.","私では判断できません。","judged"];
EXAMPLES[1810]=["You've got nothing to complain of.","君には不満が全くない。","complain"];
EXAMPLES[1811]=["I'll be back by six o'clock.","私は六時までに戻る。","I'll be back by six"];
EXAMPLES[1812]=["You can reach me at this number.","ここへお電話くだされば、連絡がとれます。","reach"];
EXAMPLES[1813]=["I have an appointment at 3.","私は３時に約束があるのです。","I have an appointment"];
EXAMPLES[1816]=["I hope you'll get his support.","彼の援助が得られるといいわね。","support"];
EXAMPLES[1818]=["It doesn't matter when you come.","いつ来てもかまわないよ。","matter"];
EXAMPLES[1824]=["You finally succeeded in getting a job.","君は仕事を得るのに成功した。","finally"];
EXAMPLES[1826]=["The baby began to cry like anything.","赤ちゃんは猛烈に泣き始めた。","cry"];
EXAMPLES[1827]=["He fell in love with the girl at first sight.","彼は一目でその少女と恋に落ちた。","at first"];
EXAMPLES[1829]=["I got a good grade in English.","私は英語でよい成績を取った。","grade"];
EXAMPLES[1831]=["He warned me that I would fail.","彼は私に失敗するだろうと警告した。","warned"];
EXAMPLES[1832]=["The house is comfortable to live in.","その家は住み心地がよい。","comfortable"];
EXAMPLES[1834]=["This does not square with your story.","これは君の話と合わない。","square"];
EXAMPLES[1835]=["This is a kind of food.","これは食べ物の一種です。","a kind of"];
EXAMPLES[1836]=["He's got money to burn.","彼はお金を腐るほど持っている。","burn"];
EXAMPLES[1837]=["I would have done it at that time.","その時にしていただろう。","at that time"];
EXAMPLES[1838]=["Let's continue the game after lunch.","昼食後にゲームを続けよう。","continue"];
EXAMPLES[1839]=["He is the manager of a hotel.","彼はホテルの経営者です。","manager"];
EXAMPLES[1840]=["You are not at all wrong.","君は必ずしも間違ってはいない。","not at all"];
EXAMPLES[1841]=["My father consented to my going abroad.","父は私が外国へ行くことを承知した。","abroad"];
EXAMPLES[1842]=["Our teacher is fresh out of college.","私たちの先生は大学をでたばかりです。","fresh"];
EXAMPLES[1843]=["Why were you silent all the time?","なぜ君はその間黙っていたにですか。","silent"];
EXAMPLES[1844]=["She has been to hawaii several times.","彼女はハワイに何度も行ったことがある。","several"];
EXAMPLES[1845]=["You can do it however you like.","自分の好きなようにやってよろしい。","however"];
EXAMPLES[1846]=["She takes a great interest in English.","彼女は英語に大いに興味がある。","interest"];
EXAMPLES[1847]=["Well, we've finished at last.","ああ、やっと終わった。","at last"];
EXAMPLES[1848]=["I think it's somewhere around here.","このあたりにあると思うのですが。","somewhere"];
EXAMPLES[1849]=["It's for free.","無料です。","for free"];
EXAMPLES[1850]=["It is no less than ten miles to the hospital.","病院まで１０マイルもある。","less than"];
EXAMPLES[1851]=["I wonder if what I wrote was correct.","私の書いたことが正しかったかしら。","correct"];
EXAMPLES[1852]=["They'll probably come by car.","たぶん彼らは車で来るでしょう。","probably"];
EXAMPLES[1853]=["The police held the angry crowd back.","警察は怒った群衆を引き止めた。","held"];
EXAMPLES[1856]=["He won't come, will he?","彼は来ないのでしょう。","won"];
EXAMPLES[1857]=["Where can we exchange yen into dollars?","どこで邦貨をドルに変えられるか。","exchange"];
EXAMPLES[1858]=["Why don't we shake on it?","それに決めましょうか。","shake"];
EXAMPLES[1859]=["Don't raise your voice at me.","大きな声でどなるな。","raise"];
EXAMPLES[1860]=["You will never get him to agree.","彼の同意は得られないだろう。","agree"];
EXAMPLES[1861]=["The best fish smell when they are three days old.","よい魚も３日たてば臭くなる。","smell"];
EXAMPLES[1862]=["He can speak both English and French.","彼は英語とフランス語をしゃべることができます。","both"];
EXAMPLES[1863]=["There's narrow road to the village.","その村までは狭い道が１本通っている。","narrow"];
EXAMPLES[1864]=["I graduated from university last year.","私は去年大学を卒業した。","graduated"];
EXAMPLES[1865]=["She will be back within a week.","彼女は１週間以内に戻ります。","within"];
EXAMPLES[1866]=["It is dangerous to drink too much.","あまり酒を飲み過ぎるのは、危険だ。","dangerous"];
EXAMPLES[1867]=["She is beginning to play the piano.","彼女はピアノを弾き始めるところだ。","beginning"];
EXAMPLES[1869]=["How can I get to heaven?","どうすれば天国に行けるのでしょうか。","heaven"];
EXAMPLES[1870]=["I was late as a result of the train delay.","僕は電車が遅延したので遅刻した。","as a result of"];
EXAMPLES[1871]=["Don't let him know her address.","彼女の住所を彼に知らせてはいけない。","address"];
EXAMPLES[1873]=["He found the box under the table.","彼はテーブルの下にその箱を見つけた。","found"];
EXAMPLES[1874]=["She got her daughter a personal computer.","彼女は娘にパソコンを買ってやった。","personal"];
EXAMPLES[1875]=["He is far in advance of the other students.","彼は他の学生よりずっと進んでいる。","in advance"];
EXAMPLES[1878]=["He is more gentle than kind.","彼は親切というよりむしろ気がやさしい。","gentle"];
EXAMPLES[1879]=["He will be back in a second.","彼は今すぐ帰ってきます。","a second"];
EXAMPLES[1880]=["He is nothing but an ordinary man.","彼は普通の人にすぎない。","ordinary"];
EXAMPLES[1881]=["She has become more and more beautiful.","彼女はますます美しくなった。","more and more"];
EXAMPLES[1882]=["Every sentence in this book is important.","この本の中の文はどれも大切です。","sentence"];
EXAMPLES[1883]=["He would often sit up until late at night.","彼はよく夜遅くまで起きていたものだった。","up until"];
EXAMPLES[1884]=["I know the whole of the story.","私はその話の全体を知っている。","whole"];
EXAMPLES[1886]=["It was the calm before the storm.","嵐の前の静けさだった。","calm"];
EXAMPLES[1887]=["Thousands of people were there.","何千もの人々がそこにいた。","Thousands of"];
EXAMPLES[1889]=["I'm really unhappy about this.","私は非常に不愉快だ。","unhappy"];
EXAMPLES[1890]=["I can't put up with his violence any longer.","彼の暴力にはもう我慢できない。","violence"];
EXAMPLES[1892]=["Don't make an enemy of him.","彼を敵に回すな。","enemy"];
EXAMPLES[1893]=["Someone must have left the window open.","誰か窓を開けっ放しにしていたに違いない。","Someone"];
EXAMPLES[1895]=["May I bother you for a moment?","ねえ、ちょっといい？","bother"];
EXAMPLES[1896]=["Did you have a fight with Ken?","ケンとけんかしたのか。","fight"];
EXAMPLES[1897]=["His proposal is not worth talking about.","彼の提案は話にとりあげるほどのこともない。","worth"];
EXAMPLES[1898]=["To read books is custom with me.","本を読むのは、私の習慣である。","custom"];
EXAMPLES[1902]=["His latest novel is well worth reading.","彼の最近の小説は読む価値が充分ある。","latest"];
EXAMPLES[1903]=["Trees shelter my house from the wind.","木が私の家を風から守ってくれている。","shelter"];
EXAMPLES[1904]=["The crowd made for the nearest door.","人々は近くの出口へと向かった。","crowd"];
EXAMPLES[1905]=["What he said there was surprisingly difficult.","彼がそこで言ったことは驚くほど難しかった。","surprisingly"];
EXAMPLES[1907]=["The old man died of cancer.","その老人はガンで死んだ。","cancer"];
EXAMPLES[1908]=["Fill in your name and address here.","ここに名前と住所を書きなさい。","Fill"];
EXAMPLES[1909]=["He will pay 20 dollars at most.","彼はせいぜい２０ドルしか払わないだろう。","at most"];
EXAMPLES[1911]=["How far is the next gas station?","次のスタンドまでどのくらいありますか。","gas"];
EXAMPLES[1912]=["I haven't read both of her novels.","彼女の小説の両方とも読んだわけではない。","both of"];
EXAMPLES[1913]=["They are afraid that nuclear war will break out.","彼らは核戦争の心配をしている。","nuclear"];
EXAMPLES[1914]=["I disagree with you on the matter.","その問題に関してはあなたと意見が違う。","disagree"];
EXAMPLES[1915]=["But my heart goes to destroy the truth.","心は真実を破壊していく。","destroy"];
EXAMPLES[1916]=["Let's eat out tonight.","今晩、外食しましょう。","eat out"];
EXAMPLES[1917]=["It's raining, but I would like to go out.","雨が降っているが、私は外出したい。","would like to"];
EXAMPLES[1919]=["My mother baked a cake for my birthday.","母は私の誕生日にケーキを焼いてくれた。","baked"];
EXAMPLES[1921]=["He has got baseball on the brain.","彼は野球に凝っている。","brain"];
EXAMPLES[1926]=["She encouraged him to write a novel.","彼女は彼に小説を書くように励ました。","encouraged"];
EXAMPLES[1928]=["They believe in a life after death.","彼らは来世を信じている。","death"];
EXAMPLES[1929]=["Who is the inventor of the radio?","ラジオを発明した人は誰ですか。","inventor"];
EXAMPLES[1930]=["We were born on the same day.","私たちは同じ日に生まれた。","born"];
EXAMPLES[1931]=["He got out of the habit of smoking.","彼はたばこを吸う習慣をやめた。","habit"];
EXAMPLES[1932]=["I met him at the barber's.","理髪店で彼に会った。","barber"];
EXAMPLES[1933]=["Call the police in an emergency.","非常の場合は警察を呼びなさい。","emergency"];
EXAMPLES[1934]=["Do you get on with your friends?","友達と仲良くやっていますか。","get on"];
EXAMPLES[1935]=["The wall gave way in the earthquake.","壁が地震で崩れた。","earthquake"];
EXAMPLES[1936]=["Have something to eat just in case.","念のため、何か食べておきなさい。","just in case"];
EXAMPLES[1937]=["The news of his death spread abroad.","彼が死んだという知らせが広まった。","spread"];
EXAMPLES[1938]=["Books such as these are too difficult for him.","このような本は彼には難しすぎる。","such as"];
EXAMPLES[1939]=["This is the big tough world.","世の中なんて、そんなものだ。","tough"];
EXAMPLES[1940]=["Her name was often on his lips.","彼は彼女の名前をよく口にした。","lips"];
EXAMPLES[1942]=["The president is getting into the car.","大統領は車に乗り込むところです。","president"];
EXAMPLES[1943]=["This hotel is relatively expensive for this town.","このホテルはこの町にしては比較的高い。","relatively"];
EXAMPLES[1944]=["My mother does not always get up early.","母はいつも早起きとはかぎらない。","not always"];
EXAMPLES[1945]=["He drove carelessly and had an accident.","彼は不注意な運転で事故を起こした。","drove"];
EXAMPLES[1946]=["Jane will be excited to see the flowers.","ジェーンはその花を見て興奮するだろう。","be excited"];
EXAMPLES[1947]=["I cut a branch from the tree.","その木の枝を切った。","branch"];
EXAMPLES[1948]=["They believe in a life after death.","彼らは来世を信じている。","believe in"];
EXAMPLES[1949]=["Tom and I have nothing in common.","トムと私は共通したところが何もない。","common"];
EXAMPLES[1950]=["The tie doesn't go with my dress.","そのネクタイは私の服には合わない。","tie"];
EXAMPLES[1951]=["We can get many coals here.","ここで石炭をたくさん取ることができる。","coals"];
EXAMPLES[1952]=["Would you care for some more cake?","ケーキをもう少しいかがですか。","care for"];
EXAMPLES[1953]=["I agree to his plan.","私は彼の計画に賛成します。","agree to"];
EXAMPLES[1954]=["Please feel free to call me up.","どうぞ遠慮なく電話をください。","feel free to"];
EXAMPLES[1955]=["In case of emergency, call the police.","緊急の時には警察へ電話しなさい。","In case of"];
EXAMPLES[1957]=["We should be headed for world peace.","私たちは世界平和を目標に進むべきだ。","peace"];
EXAMPLES[1958]=["You are made to be a poet.","君は生まれながらの詩人だ。","poet"];
EXAMPLES[1960]=["Have something to eat just in case.","念のため、何か食べておきなさい。","in case"];
EXAMPLES[1962]=["She is as beautiful as a rose.","彼女はバラのように美しい。","rose"];
EXAMPLES[1964]=["She is said to be a domestic woman.","彼女は家庭的な女性だそうです。","domestic"];
EXAMPLES[1965]=["I feel like going out rather than staying at home today.","今日は家にいるより出かけたい気分だ。","rather than"];
EXAMPLES[1966]=["He will pay 20 dollars at most.","彼はせいぜい２０ドルしか払わないだろう。","most"];
EXAMPLES[1967]=["We have run out of cream.","クリームを使い切ってしまった。","run out of"];
EXAMPLES[1969]=["He is not very strict about it.","彼はその事にはあまりやかましくない。","strict"];
EXAMPLES[1972]=["I have a little money with me.","私は少しは金の持ち合わせがある。","little"];
EXAMPLES[1973]=["I wonder which of you will win.","君たちのどっちが勝つのだろう。","wonder"];
EXAMPLES[1974]=["I bought a camera free of tax.","私は無税でカメラを買った。","tax"];
EXAMPLES[1975]=["I don't know what to do.","私はどうしてよいのかわかりません。","what to"];
EXAMPLES[1978]=["I'll be in trouble if the story gets out.","その話が漏れると私は困ったことになる。","be in trouble"];
EXAMPLES[1979]=["He took as much care as possible.","彼はできるだけ気をつけていた。","possible"];
EXAMPLES[1980]=["You won't find a better job in a hurry.","それ以上の仕事はちょっと見つからないだろう。","in a hurry"];
EXAMPLES[1981]=["After the accident, he was banned from driving.","事故のあとで彼は運転を禁止された。","banned"];
EXAMPLES[1983]=["I'd like to make an overseas call.","国際電話をかけたいのですが。","overseas"];
EXAMPLES[1984]=["We will discuss the problem with them.","我々はその問題を彼らと討論します。","discuss"];
EXAMPLES[1985]=["Life is very flat in a small village.","小さな村では生活はひどく単調です。","flat"];
EXAMPLES[1986]=["Are you satisfied with your daily life?","君は毎日の生活に満足していますか。","daily"];
EXAMPLES[1989]=["So far everything has been going well.","これまでのところすべてが順調だ。","So far"];
EXAMPLES[1990]=["Please come in one by one.","どうぞ一人ずつお入りください。","one by one"];
EXAMPLES[1991]=["I have been writing letters all day long.","私は１日中手紙を書いていた。","all day long"];
EXAMPLES[1992]=["No one should desert his friends.","誰でも友人を見捨てるべきではない。","desert"];
EXAMPLES[1993]=["We ought to be ready for whatever comes.","何が起ころうと、覚悟しておくべきだ。","be ready for"];
EXAMPLES[1995]=["Does she belong to the tennis club?","彼女はテニス部に入ってますか。","belong"];
EXAMPLES[1997]=["What would our lives be like without electricity?","電気がなかったら、我々の生活はどんなだろう？","electricity"];
EXAMPLES[1998]=["He has established himself as a musician.","彼は音楽家として身を立てた。","established"];
EXAMPLES[1999]=["She was amazed to hear the news.","彼女は知らせを聞いて驚いた。","amazed"];
EXAMPLES[2000]=["We went down to the valley where the village is.","私たちはその村がある谷まで降りていった。","valley"];
EXAMPLES[2001]=["It is difficult to satisfy everyone.","みんなを満足させるのは難しい。","satisfy"];
EXAMPLES[2002]=["We transported the computer to the office.","私たちはそのコンピューターを職場へ運んだ。","transported"];
EXAMPLES[2003]=["To tell the truth, he is not a human being.","本当のことを言えば彼は人間ではない。","human being"];
EXAMPLES[2004]=["It was a great blow to us.","それは私達にとってひどい打撃だった。","blow"];
EXAMPLES[2005]=["Believe it or not, that is true.","信じようと信じまいと、それは真実だ。","Believe it or not"];
EXAMPLES[2007]=["Who are you to tell me to get out?","何の権限で私に出て行けと言うのだ。","get out"];
EXAMPLES[2008]=["Although tired, she kept on working.","疲れていたが彼女は働き続けた。","Although"];
EXAMPLES[2009]=["This beautiful dress is made of silk.","この美しいドレスは絹で出来ている。","silk"];
EXAMPLES[2011]=["If it's convenient come here tonight.","もし都合がよかったら今夜ここに来てください。","convenient"];
EXAMPLES[2012]=["There are a lot of students in the gym.","体育館にたくさんの生徒がいます。","gym"];
EXAMPLES[2013]=["In case I am late, please go ahead of me.","私が遅れたら先に行って下さい。","go ahead"];
EXAMPLES[2016]=["The number of working women is increasing.","働く女性の数は増えている。","increasing"];
EXAMPLES[2018]=["On the other hand we learned a great deal from the experience.","他方でその経験から学んだものも大きかった。","On the other hand"];
EXAMPLES[2019]=["The water supply was turned off.","水道の水が止められた。","supply"];
EXAMPLES[2020]=["He is not coming, according to her.","彼女の話では彼は来ないそうだ。","according to"];
EXAMPLES[2021]=["I lead a fast way of living.","放蕩生活を送る。","lead"];
EXAMPLES[2023]=["This survey is too long to finish quickly.","この調査は長すぎて早く終える事ができない。","survey"];
EXAMPLES[2024]=["Could you let me see your notes?","ノートを見せてくれないか。","let"];
EXAMPLES[2025]=["He works hard so that he can study abroad.","彼は留学できるように一生懸命勉強している。","so that"];
EXAMPLES[2026]=["What sort of work do you do?","どんな仕事をしていますか。","sort"];
EXAMPLES[2027]=["We traveled on foot.","私たちは歩いて旅行した。","on foot"];
EXAMPLES[2028]=["She passed the jewel off as her own.","彼女はその宝石を自分のものとして通した。","jewel"];
EXAMPLES[2031]=["She cut me dead in the street.","彼女は道で会っても僕をわざと無視した。","dead"];
EXAMPLES[2032]=["We had a very good time indeed.","とてもおもしろかったよ。","indeed"];
EXAMPLES[2033]=["The people set up a new government.","国民は新しい政府を作った。","government"];
EXAMPLES[2034]=["The countryside is beautiful in the spring.","田舎は春がきれいだ。","countryside"];
EXAMPLES[2035]=["He did an amount of work.","彼はかなりの仕事をした。","amount"];
EXAMPLES[2037]=["How do you like the climate of Japan?","日本の気候はどうですか。","climate"];
EXAMPLES[2038]=["My telephone is out of order.","私の電話は故障している。","out of order"];
EXAMPLES[2040]=["The teacher was surrounded by her students.","先生は学生たちに囲まれた。","surrounded"];
EXAMPLES[2042]=["She gives instruction in English.","彼女は英語を教えている。","instruction"];
EXAMPLES[2043]=["He was the only person to survive the fire.","その火事で生き残ったのは、彼だけだった。","survive"];
EXAMPLES[2046]=["I rode my bicycle to the store.","私は店まで自転車で行った。","store"];
EXAMPLES[2047]=["We were as one in our opinion.","われわれは意見が一致した。","opinion"];
EXAMPLES[2048]=["I worked hard day after day.","私は毎日毎日熱心に働いた。","day after day"];
EXAMPLES[2049]=["You don't want to be lazy.","怠けてはいけない。","lazy"];
EXAMPLES[2050]=["That week had nothing to do with discrimination.","その週間は差別とは関係がなかった。","discrimination"];
EXAMPLES[2053]=["She is a bit like her mother.","彼女は、母親に少し似ている。","bit"];
EXAMPLES[2054]=["It is all over with me. it can't be helped.","万事休すだ。もうどうしようもない。","all over"];
EXAMPLES[2056]=["The steam ship has gone out of sight.","汽船は見えなくなった。","steam"];
EXAMPLES[2057]=["He could no longer stand the pain.","痛くて我慢しきれなくなった。","pain"];
EXAMPLES[2060]=["When do you plan to check out?","あなたのチェックアウトはいつですか。","check out"];
EXAMPLES[2061]=["The old man captured a big fish.","その老人は大きな魚を捕まえた。","captured"];
EXAMPLES[2065]=["He came from a tiny mountain town.","彼は山の中のちっぽけな町からやってきた。","tiny"];
EXAMPLES[2066]=["The weather is sure to be wet.","きっと雨になりますよ。","wet"];
EXAMPLES[2067]=["He helped me to get over the difficulties.","彼は私がその困難を克服するのを助けてくれた。","get over"];
EXAMPLES[2068]=["You are under arrest.","あなたを逮捕します。","arrest"];
EXAMPLES[2069]=["My child is curious to know everything.","私の子供は何でも知りたがる。","curious"];
EXAMPLES[2071]=["He called it unfair.","彼はそれは不公平だと言った。","unfair"];
EXAMPLES[2072]=["Ken seems to have a terrible cold.","ケンはひどい風邪をひいているようだ。","terrible"];
EXAMPLES[2073]=["I hope to see you again.","またお会いしたいと思います。","hope to"];
EXAMPLES[2074]=["Do you not accept my offer?","私の申し出を受けないと言うのですか。","accept"];
EXAMPLES[2076]=["You'll have to ask someone else.","他の誰かに聞いて下さい。","else"];
EXAMPLES[2079]=["The Japanese government made an important decision.","日本政府は重要な決定を行った。","decision"];
EXAMPLES[2081]=["He carried out the plan he had made in detail.","彼は緻密に立てた計画を実行した。","in detail"];
EXAMPLES[2084]=["Above all, we must be healthy.","何よりもまず健康でなければならない。","Above"];
EXAMPLES[2085]=["Does that price include breakfast?","それは朝食こみの値段ですか。","include"];
EXAMPLES[2087]=["I hear from my mother every month.","私は母から毎月便りをもらう。","hear from"];
EXAMPLES[2088]=["I'll apply for the job today.","今日その仕事を申し込もう。","apply"];
EXAMPLES[2089]=["He is old enough to drive a car.","彼は自動車を運転できる年齢だ。","enough to"];
EXAMPLES[2090]=["You may depend on it that it won't happen again.","こんなことは二度と起こしません。","depend on"];
EXAMPLES[2091]=["London was bombed several times.","ロンドンは数回爆撃を受けた。","bombed"];
EXAMPLES[2093]=["There is only a small audience today.","今日は客の入りが悪い。","audience"];
EXAMPLES[2094]=["Girl as she is, she is brave.","彼女は女の子だが、勇敢だ。","brave"];
EXAMPLES[2096]=["This bridge is made of iron.","この橋は鉄製です。","iron"];
EXAMPLES[2098]=["We stand against free trade.","私達は自由貿易には反対である。","trade"];
EXAMPLES[2100]=["I'm not in good shape now.","最近調子が良くありません。","in good shape"];
EXAMPLES[2101]=["Fill in your name and address here.","ここに名前と住所を書きなさい。","Fill in"];
EXAMPLES[2102]=["Is there a flight in the afternoon?","午後の便はありますか。","flight"];
EXAMPLES[2103]=["You'll get lost.","迷子になってしまいますよ。","get lost"];
EXAMPLES[2105]=["Why were you silent all the time?","なぜ君はその間黙っていたにですか。","all the time"];
EXAMPLES[2110]=["He betrayed her secret to his friends.","彼は彼女の秘密を彼の友人に漏らした。","secret"];
EXAMPLES[2111]=["I have given up on that case.","私はその事件ではもう匙を投げた。","given"];
EXAMPLES[2112]=["Jane has made great progress in Japanese.","ジェーンは日本語が大いに進歩した。","progress"];
EXAMPLES[2114]=["Neither of the two answers are right.","その２つの答えはどちらも正しくない。","Neither"];
EXAMPLES[2115]=["As a whole, the plan seems to be good.","全体として、その計画は良いようです。","As a whole"];
EXAMPLES[2116]=["I paid 800 yen for this book.","私はこの本に八百円を払った。","yen"];
EXAMPLES[2117]=["I used to debate the problem with her.","私はよく彼女とその問題を議論したものだ。","debate"];
EXAMPLES[2120]=["He had to go through a lot of hardships.","彼は多くの苦難を経験した。","go through"];
EXAMPLES[2121]=["I took no note of the time.","時間がたつのに気がつかなかった。","note"];
EXAMPLES[2122]=["As it is, I am awake.","実際は、僕は起きている。","awake"];
EXAMPLES[2123]=["Everything's a little crazy right now.","まったくお手上げだ。","crazy"];
EXAMPLES[2126]=["I took his part in the discussion.","私は討論で彼の方を持った。","discussion"];
EXAMPLES[2127]=["Please drop by my home.","私の家へお立ち寄りください。","drop by"];
EXAMPLES[2129]=["What relation is she to you?","彼女とはどんな間柄ですか。","relation"];
EXAMPLES[2131]=["I count on Tom.","トムをあてにしているんだ。","count on"];
EXAMPLES[2132]=["The chances are that he will succeed.","たぶん彼は成功するだろう。","succeed"];
EXAMPLES[2133]=["Death is certain to come to everybody.","死は誰にでもやってくる。","certain"];
EXAMPLES[2135]=["The modern Japanese politics is bad.","最近の日本の政治はよくない。","modern"];
EXAMPLES[2136]=["I can't get rid of my cold.","風邪が抜けない。","get rid of"];
EXAMPLES[2137]=["I am easily affected by cold weather.","私は寒さに弱い。","affected"];
EXAMPLES[2138]=["His clothes didn't match his age.","彼の服は年齢に合っていなかった。","match"];
EXAMPLES[2139]=["You must not live beyond your means.","収入以上の生活をしてはいけない。","beyond"];
EXAMPLES[2140]=["Tom can ski as well as his brother.","トムは兄と同じくらい上手にスキーができる。","as well"];
EXAMPLES[2141]=["She seemed to be satisfied with the result of the exam.","彼女は試験の結果に満足しているようだった。","be satisfied with"];
EXAMPLES[2142]=["He closed the door quietly behind him.","彼は入った後ドアを静かに閉めた。","quietly"];
EXAMPLES[2143]=["The story turned my blood cold.","その話を聞いてぞっとした。","blood"];
EXAMPLES[2144]=["I forget sad things when I fall asleep.","悲しいことは寝ると忘れる。","fall asleep"];
EXAMPLES[2145]=["They were watching for the signal to start.","彼らは出発の合図を待っていた。","signal"];
EXAMPLES[2146]=["All the students protested against the war.","学生はみんな戦争に抗議した。","protested"];
EXAMPLES[2148]=["Your house is fantastic.","なんて素敵な家なんでしょう。","fantastic"];
EXAMPLES[2149]=["These boots belong to her.","この靴は彼女のものだ。","belong to"];
EXAMPLES[2150]=["I am very pleased with my job.","私は自分の仕事が気に入っている。","pleased"];
EXAMPLES[2151]=["Do you have a school uniform?","制服はあるの。","uniform"];
EXAMPLES[2152]=["He is a complete stranger to me.","彼は私のすべてを知らない人だ。","stranger"];
EXAMPLES[2153]=["He is our next door neighbor.","彼は私達の隣に住んでいる人です。","neighbor"];
EXAMPLES[2154]=["What you need the most now is courage.","君が今一番必要なものは勇気です。","courage"];
EXAMPLES[2155]=["I ate a quarter of a cake.","私はケーキを４分の１食べた。","quarter"];
EXAMPLES[2156]=["Get out of the classroom.","教室から出て行きなさい。","Get out of"];
EXAMPLES[2157]=["From now on let us study in the morning.","午後は午前中に勉強するようにしよう。","From now"];
EXAMPLES[2158]=["I went into the army.","私は陸軍に入った。","army"];
EXAMPLES[2160]=["Can I ride this horse for a while?","しばらくこの馬に乗ってもいいですか。","for a while"];
EXAMPLES[2161]=["I was able to solve the problem.","私はその問題を解くことができた。","solve"];
EXAMPLES[2162]=["The doctor is looking for medicine that is effective for this illness.","医者はこの病気に効く薬を探している。","effective"];
EXAMPLES[2163]=["Students often pursue their teacher with questions.","学生はしばしば先生を質問攻めにする。","pursue"];
EXAMPLES[2164]=["Language keeps in step with the times.","言葉は時代とともに移りゆく。","step"];
EXAMPLES[2168]=["The condition seems to be bad recently.","最近調子が悪そうですね。","condition"];
EXAMPLES[2169]=["He was a burden to his parents.","彼は、両親の負担になった。","burden"];
EXAMPLES[2170]=["The weather is a shade better today.","天気は今日の方が少しはましだ。","shade"];
EXAMPLES[2171]=["She married a rich merchant.","彼女は金持ちの商人と結婚した。","merchant"];
EXAMPLES[2172]=["She believes her son is still alive.","彼女はまだ息子が生きていると信じている。","son"];
EXAMPLES[2173]=["Nobody but John has heard of it.","その事を聞いたのはジョンしかいない。","heard"];
EXAMPLES[2176]=["What will you do after graduation?","卒業したらどうするつもりですか。","graduation"];
EXAMPLES[2177]=["By the way, what do you do?","ところで、あなたの仕事は何ですか。","By the way"];
EXAMPLES[2178]=["That movie will be released by and by.","その映画はまもなく公開される。","released"];
EXAMPLES[2179]=["The summer heat is rolling in.","夏の暑さがやってきた。","heat"];
EXAMPLES[2180]=["Perhaps it will rain in the afternoon.","たぶん午後は雨が降るだろう。","Perhaps"];
EXAMPLES[2181]=["There was no one there besides me.","そこには私以外にはだれもいなかった。","besides"];
EXAMPLES[2182]=["They were successful in solving the problem.","彼らはうまくその問題を解決した。","successful"];
EXAMPLES[2184]=["Come as soon as possible.","できるだけ早く来なさい。","as soon as possible"];
EXAMPLES[2185]=["Let me help you, if necessary.","もし必要ならば手伝わせて下さい。","necessary"];
EXAMPLES[2186]=["You may extend your stay in Tokyo.","東京滞在を延ばしてもいいですよ。","extend"];
EXAMPLES[2187]=["It's midnight already.","もう夜中を過ぎた。","midnight"];
EXAMPLES[2189]=["A child will depend on the television.","子供はテレビに依存する様になるものだ。","depend"];
EXAMPLES[2190]=["Why do I feel this way?","なぜこんな気分になるのだろう。","this way"];
EXAMPLES[2191]=["You may as well trust his story.","彼の話を信じたほうがよいであろう。","trust"];
EXAMPLES[2192]=["I wish I had seen the film.","その映画を見ておけばよかったなあ。","film"];
EXAMPLES[2193]=["I was at a loss for words.","私は言葉に詰まった。","loss"];
EXAMPLES[2195]=["After a while, he came to.","しばらくして、彼は正気づいた。","After a while"];
EXAMPLES[2196]=["Suddenly, he heard a strange sound.","突然、彼は奇妙な音を耳にした。","Suddenly"];
EXAMPLES[2198]=["He went there instead of his father.","彼は父の代わりにそこへ行った。","instead of"];
EXAMPLES[2200]=["She was ill with heart disease.","彼女は心臓が悪かった。","disease"];
EXAMPLES[2201]=["The years pass by quickly.","年月が過ぎるのは早い。","pass by"];
EXAMPLES[2203]=["Could you charge it to my room?","料金は部屋につけておいていただけますか。","charge"];
EXAMPLES[2204]=["I meant to have written to you.","あなたに手紙を書くつもりだったのだが。","meant"];
EXAMPLES[2205]=["Such behavior may bring about an accident.","そのような行動が事故を引き起こすかもしれない。","behavior"];
EXAMPLES[2207]=["What is the title of the book?","その本のタイトルは何ですか。","title"];
EXAMPLES[2209]=["When he saw the police officer, he ran away.","警官を見ると、彼は逃げた。","police officer"];
EXAMPLES[2210]=["You ought to be ashamed of yourself.","少しは恥を知りなさい。","ashamed"];
EXAMPLES[2211]=["He is the image of his father.","父親にそっくりだ。","image"];
EXAMPLES[2213]=["I will go there even if it rains.","たとえ雨が降っても私はそこへ行きます。","even if"];
EXAMPLES[2215]=["Fortunately, the weather was good.","幸運にも天気がよかった。","Fortunately"];
EXAMPLES[2216]=["This is an exception to the rule.","これはその規則の例外である。","exception"];
EXAMPLES[2217]=["That girl is certainly a hard worker.","あの少女は本当によく勉強する。","certainly"];
EXAMPLES[2218]=["Surely the weather will become fine.","きっと良い天気になるだろう。","Surely"];
EXAMPLES[2220]=["From now on, you must be responsible for what you do.","これからは自分のする事に責任を持ちなさい。","be responsible for"];
EXAMPLES[2221]=["It happened that he found the treasure.","彼は偶然宝物を見つけた。","treasure"];
EXAMPLES[2222]=["Your work didn't come up to our expectations.","君の仕事は私たちの期待に添わなかった。","up to"];
EXAMPLES[2223]=["He reads ten books a month at least.","彼は少なくとも月に１０冊は本を読む。","at least"];
EXAMPLES[2225]=["Do I have to focus it?","ピントはどうするのですか。","focus"];
EXAMPLES[2227]=["I fall behind him in this respect.","この点で私は彼に劣る。","respect"];
EXAMPLES[2228]=["Somehow I cannot settle down to work.","どうも仕事が手に着かない。","Somehow"];
EXAMPLES[2229]=["Please bear in mind what I said.","私が言ったことを覚えてください。","mind"];
EXAMPLES[2230]=["The rain kept the fire from spreading.","雨で火の手は広がらずにすんだ。","fire"];
EXAMPLES[2231]=["May god show us a better life!","もっと良い暮らしができますように。","god"];
EXAMPLES[2232]=["The dog is blind in one eye.","その犬は片方の目が見えない。","blind"];
EXAMPLES[2233]=["She may not be aware of the danger.","彼女は危険に気付いていないかもしれない。","be aware of"];
EXAMPLES[2234]=["I saw my sister tear up the letter.","私は姉がその手紙をひきさくのを見た。","tear"];
EXAMPLES[2235]=["Do you have any employees who speak Japanese?","日本語の話せるスタッフがいますか。","employees"];
EXAMPLES[2236]=["Raw fish is not to my taste.","生の魚は私の口には合いません。","Raw"];
EXAMPLES[2239]=["The road is uphill all the way.","道はずっとのぼりだ。","road"];
EXAMPLES[2241]=["His son wants to be a lawyer.","彼の息子は弁護士になりたがっている。","lawyer"];
EXAMPLES[2242]=["Is there a parking lot?","駐車場は、ありますか。","parking lot"];
EXAMPLES[2243]=["She's as pretty as her sister.","彼女は妹に劣らずきれいだ。","pretty"];
EXAMPLES[2245]=["The speaker couldn't make himself heard.","話し手は自分の言うことを聞いてもらえなかった。","himself"];
EXAMPLES[2246]=["I'm very sleepy today, too.","今日もとても眠い。","sleepy"];
EXAMPLES[2247]=["She is quite ignorant of the world.","彼女は全く世間知らずだ。","quite"];
EXAMPLES[2248]=["Don't be scared of making mistakes.","失敗を怖がることはありません。","scared"];
EXAMPLES[2249]=["You can get ahead in the world.","君は成功するよ。","ahead"];
EXAMPLES[2250]=["You must keep your teeth clean.","歯をきれいにしておかなければならない。","teeth"];
EXAMPLES[2251]=["They shoot them off over the lake.","湖の上に打ち上げるから。","shoot"];
EXAMPLES[2252]=["Please say hello to him for me.","彼によろしく言ってください。","hello"];
EXAMPLES[2253]=["Go along this street for a mile.","このとおりを一マイル行きなさい。","mile"];
EXAMPLES[2254]=["I am going to be an engineer.","私は技師になるつもりです。","engineer"];
EXAMPLES[2256]=["The yen is weaker than the dollar.","円はドルより安い。","dollar"];
EXAMPLES[2257]=["What a lovely day it is today!","今日は何という気持ちのよい日だろう。","lovely"];
EXAMPLES[2258]=["I have to prepare for the test.","試験勉強をしなくちゃ。","prepare"];
EXAMPLES[2260]=["She drinks a little wine at times.","彼女は時々酒を飲む。","wine"];
EXAMPLES[2262]=["This is the core of the problem.","これがその問題の核心である。","core"];
EXAMPLES[2263]=["I consider him to be an excellent teacher.","僕は、彼をすばらしい先生だと考えている。","excellent"];
EXAMPLES[2264]=["You'd better stay on your guard.","油断してはいけません。","guard"];
EXAMPLES[2265]=["I want to stress this point.","私はこの点を力説したい。","stress"];
EXAMPLES[2267]=["I am looking for an assistant.","私は助手を探している。","assistant"];
EXAMPLES[2269]=["You don't have to kick yourself.","自分を責めることはない。","kick"];
EXAMPLES[2270]=["Will you mail this letter for me?","この手紙を投函してくれませんか。","mail"];
EXAMPLES[2271]=["He bought a new pair of shoes.","彼は新しい靴を一足買った。","pair"];
EXAMPLES[2272]=["I wish I were a prince.","私が王子様だったらいいのに。","prince"];
EXAMPLES[2274]=["Were there any stars in the sky?","空に星が出ていた？","sky"];
EXAMPLES[2277]=["Thank you in advance for your help.","ご協力をお願いします。","advance"];
EXAMPLES[2278]=["The boat was rolling down the river.","船はどんどん川を下って入った。","boat"];
EXAMPLES[2279]=["He doesn't mix well.","彼は人つきあいがよくない。","mix"];
EXAMPLES[2280]=["They had a good command of French.","彼らはフランス語をうまく使いこなせる。","command"];
EXAMPLES[2281]=["There are many birds in this forest.","この森にはたくさんの鳥がいる。","forest"];
EXAMPLES[2282]=["There is a limit to everything.","あらゆるものに限界がある。","limit"];
EXAMPLES[2283]=["Before long, the moon came out.","まもなく月がでた。","moon"];
EXAMPLES[2284]=["The soldier gave water to me.","その兵士は、私に水をくれた。","soldier"];
EXAMPLES[2285]=["English is not my native language.","英語は私の母国語ではない。","native"];
EXAMPLES[2287]=["The writer is well known to us.","その作家は私たちによく知られています。","writer"];
EXAMPLES[2288]=["What do you mean by communication?","コミュニケーションと言う語はどういう意味であろうか。","communication"];
EXAMPLES[2291]=["I always take some exercise before breakfast.","朝食前にいつも体操をします。","exercise"];
EXAMPLES[2293]=["She regarded the story as a joke.","彼女はその話を冗談だと考えた。","joke"];
EXAMPLES[2294]=["He got a loan from the bank.","彼は銀行からお金を借りた。","loan"];
EXAMPLES[2295]=["We had dinner at a restaurant.","私たちはレストランで夕食をとった。","restaurant"];
EXAMPLES[2296]=["We look forward to your entries.","ご参加お待ちしております。","entries"];
EXAMPLES[2297]=["She was a girl with golden hair.","彼女は金髪の少女だった。","golden"];
EXAMPLES[2298]=["Did you make that mistake on purpose?","あなたはわざとその間違いをしたのか。","mistake"];
EXAMPLES[2299]=["John is waiting for Mary on the platform.","ジョンはプラットホームでメアリーを待っている。","platform"];
EXAMPLES[2300]=["He was away from the swimming pool.","彼はプールから離れていた。","pool"];
EXAMPLES[2302]=["The train arrived ten minutes behind schedule.","列車は１０分遅れて到着した。","schedule"];
EXAMPLES[2303]=["You had better not smoke so much.","あなたはタバコをすわない方がよい。","smoke"];
EXAMPLES[2304]=["The question foxed me completely.","その質問は私には全く理解できなかった。","foxed"];
EXAMPLES[2305]=["You are in need of a holiday.","君は休暇が必要だ。","holiday"];
EXAMPLES[2306]=["Please give me a glass of milk.","ミルクを一杯下さい。","milk"];
EXAMPLES[2307]=["Each of them carried their own pack.","めいめいが自分の荷物を持って行った。","pack"];
EXAMPLES[2309]=["A big tree fell in the storm.","大きな木が嵐で倒れた。","storm"];
EXAMPLES[2311]=["She lives in an apartment above us.","彼女はわれわれの上のアパートに住んでいます。","apartment"];
EXAMPLES[2312]=["Keep your dog chained up to the tree.","犬を木につないでおいて下さい。","chained"];
EXAMPLES[2314]=["My mother is busy in the kitchen.","母は台所で忙しくしている。","kitchen"];
EXAMPLES[2317]=["The man lay asleep all day long.","その男は一日中眠っていた。","lay"];
EXAMPLES[2318]=["Mother made me a pure white dress.","母は私に真っ白いドレスを作ってくれた。","pure"];
EXAMPLES[2319]=["Do you feel secure about the future?","将来について心配はありませんか。","secure"];
EXAMPLES[2320]=["I am used to driving a truck.","トラックを運転するのには慣れている。","truck"];
EXAMPLES[2321]=["Basically, I agree with your opinion.","基本的にあなたの意見に賛成です。","Basically"];
EXAMPLES[2325]=["It wasn't a very interesting novel.","あまり面白味のない小説だった。","novel"];
EXAMPLES[2326]=["Do you have any shirt in white?","白いシャツはありますか。","shirt"];
EXAMPLES[2327]=["How did you get to the stadium?","競技場にはどうやっていったの？","stadium"];
EXAMPLES[2329]=["He was the champion for three years.","彼は三年間チャンピオンの座を守った。","champion"];
EXAMPLES[2330]=["We have run out of cream.","クリームを使い切ってしまった。","cream"];
EXAMPLES[2333]=["There is an orange on the table.","テーブルの上にオレンジがある。","orange"];
EXAMPLES[2336]=["The doctor tells me not to touch alcohol.","私は医者に酒を止められている。","alcohol"];
EXAMPLES[2340]=["Few people can speak a foreign language perfectly.","外国語を完璧に話せる人はほとんどいない。","perfectly"];
EXAMPLES[2342]=["When did you get the concert ticket?","いつコンサートのチケットを買ったの。","ticket"];
EXAMPLES[2344]=["We are going to cycle to the lake tomorrow.","私たちはあす湖まで自転車で行きます。","cycle"];
EXAMPLES[2345]=["Can you tell me when to switch the machine off?","いつその機械を止めたいいか私に教えて下さい。","switch"];
EXAMPLES[2347]=["She put aside a lot of money.","彼女はお金をたくさん貯金している。","aside"];
EXAMPLES[2348]=["Who can put a bell on the cat?","だれがその猫に鈴をつけられるか。","bell"];
EXAMPLES[2349]=["She seems to have found a boyfriend.","彼女にいい人ができたらしい。","boyfriend"];
EXAMPLES[2350]=["I think his life is in danger.","彼の生命は危険な状態にあると思います。","danger"];
EXAMPLES[2351]=["He put the machine in motion.","彼はその機械を動かし始めた。","motion"];
EXAMPLES[2352]=["Please pay at the register.","レジでお願いします。","register"];
EXAMPLES[2353]=["This tool is of great use.","この道具は実に役に立つ。","tool"];
EXAMPLES[2354]=["This is the flag of Japan.","これは日本の国旗です。","flag"];
EXAMPLES[2355]=["He has a small frame.","彼は小柄な男です。","frame"];
EXAMPLES[2356]=["Our guest is waiting for us downstairs.","私たちの客が下で待っています。","guest"];
EXAMPLES[2357]=["She kissed me like anything.","彼女は、激しく私に接吻をした。","kissed"];
EXAMPLES[2358]=["He always speaks at random.","彼はいつも口からでまかせを言う。","random"];
EXAMPLES[2361]=["I assume that this idea will work well.","この考えは旨く行くだろう。","assume"];
EXAMPLES[2362]=["We'd like another bottle of wine.","ワインをもう一本ください。","bottle"];
EXAMPLES[2365]=["She has too much chat about her.","彼女は自慢が過ぎる。","chat"];
EXAMPLES[2366]=["I would like to buy some cheese.","チーズをいくらか買いたいのです。","cheese"];
EXAMPLES[2370]=["His dog was running in the yard.","彼の犬は庭の中を走っていた。","yard"];
EXAMPLES[2371]=["It is interesting to play basketball.","バスケットボールをするのはおもしろい。","basketball"];
EXAMPLES[2372]=["It's cold today so button your coat.","今日は寒いのでコートのボタンをかけなさい。","button"];
EXAMPLES[2373]=["Golf isn't my cup of tea.","ゴルフは僕の嫌いなスポーツです。","Golf"];
EXAMPLES[2375]=["This question is one of great importance.","この問題は非常に重要な問題だ。","importance"];
EXAMPLES[2378]=["Let's talk turkey.","腹を割って話し合おう。","turkey"];
EXAMPLES[2379]=["We sat around the fire in a circle.","私たちは火の周りに円を作って座った。","circle"];
EXAMPLES[2380]=["The concert will take place next Sunday.","音楽会は今度の日曜日に開かれる。","concert"];
EXAMPLES[2381]=["The plane crash was only last week.","飛行機事故はつい先週起こった。","crash"];
EXAMPLES[2382]=["He is in error about the matter.","彼はそのことについて考え違いしている。","error"];
EXAMPLES[2383]=["I cannot put up with this noise.","この騒音は我慢出来ない。","noise"];
EXAMPLES[2386]=["Could you show me where the bathroom is?","お手洗いはどこか教えて下さいませんか。","bathroom"];
EXAMPLES[2388]=["My new book is not yet in print.","私の新しい本はまだ出版されていない。","print"];
EXAMPLES[2389]=["Many students took part in the contest.","多くの学生がコンテストに参加しました。","contest"];
EXAMPLES[2391]=["There is nothing the matter with the motor.","モーターについては何も問題がない。","motor"];
EXAMPLES[2394]=["Let me sample your cake.","あなたの作ったケーキの味見をさせて下さい。","sample"];
EXAMPLES[2397]=["I replied automatically when I heard my name.","私の名前を聞いたとき思わず返事をした。","automatically"];
EXAMPLES[2400]=["He lives in a world of fantasy.","彼は空想の世界に生きている。","fantasy"];
EXAMPLES[2401]=["The man made to grab at me.","その男は私につかみかかった。","grab"];
EXAMPLES[2402]=["They met through her introduction.","彼らは彼女の紹介で会った。","introduction"];
EXAMPLES[2403]=["I got my license this summer.","私はこの夏に免許を取った。","license"];
EXAMPLES[2404]=["We're going to paint the wall.","壁を塗るつもりです。","paint"];
EXAMPLES[2405]=["My dream is to become a pilot.","私の夢はパイロットになることです。","pilot"];
EXAMPLES[2406]=["Who is the girl in the pink dress?","ピンクの服を着ている少女は誰ですか。","pink"];
EXAMPLES[2407]=["Are you taking any medicine regularly?","何か薬を常用していますか。","regularly"];
EXAMPLES[2409]=["He lives off campus.","彼は学外に住んでいる。","campus"];
EXAMPLES[2410]=["Please lock the door when you leave.","出かける時には、鍵をかけて下さい。","lock"];
EXAMPLES[2411]=["He is a man of musical ability.","彼は音楽的才能のある人だ。","musical"];
EXAMPLES[2417]=["I wonder what language they speak in brazil.","ブラジルではどんな言葉を使うのだろう？","brazil"];
EXAMPLES[2418]=["He married a canadian girl.","彼はカナダ人の女性と結婚した。","canadian"];
EXAMPLES[2419]=["He is an italian.","彼はイタリア人だ。","italian"];
EXAMPLES[2420]=["He and I can not speak spanish.","彼と私はスペイン語を話すことができない。","spanish"];
EXAMPLES[2423]=["I was late as a result of the train delay.","僕は電車が遅延したので遅刻した。","as a result"];
EXAMPLES[2424]=["Do you look up to your parents?","あなたは両親を尊敬していますか。","look up"];
EXAMPLES[2425]=["He wouldn't be available until four.","４時までは手があいていない。","available"];
EXAMPLES[2426]=["There is much more water in this lake now than in the past.","今はこの湖には昔よりずっとたくさんの水がある。","in the past"];
EXAMPLES[2427]=["Nowadays his father goes to work by car.","近ごろ彼の父は車で会社に行く。","Nowadays"];
EXAMPLES[2428]=["You will gain nothing from doing that.","そうしたところで君には何もなるまい。","gain"];
EXAMPLES[2430]=["We hold that economy will soon improve.","経済はすぐによくなると我々は考えている。","improve"];
EXAMPLES[2431]=["We'll need an extra ten dollars.","私達は余分に１０ドルが必要になろう。","extra"];
EXAMPLES[2432]=["Mother made a new piece of clothing.","母は新しい服を作った。","clothing"];
EXAMPLES[2433]=["I did not mean to disappoint her.","彼女をがっかりさせるつもりはなかったんだ。","disappoint"];
EXAMPLES[2435]=["You don't have to dress up.","盛装なさる必要はありません。","dress up"];
EXAMPLES[2436]=["I was able to find out his address.","私は彼の住所を調べて見つけ出すことができた。","find out"];
EXAMPLES[2437]=["I've made up my mind to come up with a better solution.","私はもっと良い解決策を提案すると決心した。","come up with"];
EXAMPLES[2439]=["The singer's voice melts your heart.","その歌手の歌は心をなごませてくれる。","melts"];
EXAMPLES[2440]=["Which direction is the park in?","公園はどちらの方向にありますか。","direction"];
EXAMPLES[2441]=["We were surprised to see his injuries.","我々は彼の傷を見て驚いた。","injuries"];
EXAMPLES[2442]=["It was his silence which made her angry.","彼女を怒らせたのは彼の沈黙だった。","silence"];
EXAMPLES[2443]=["This hat is too tight for me.","この帽子はきつすぎる。","tight"];
EXAMPLES[2444]=["It's ten o'clock sharp.","１０時きっかりです。","sharp"];
EXAMPLES[2445]=["You should take advantage of this chance.","君はこのチャンスを利用すべきだ。","advantage"];
EXAMPLES[2446]=["Tell me the object of your plan.","君の計画の目的を言って下さい。","object"];
EXAMPLES[2447]=["He stood on the surface of the moon.","彼は月の表面に立った。","surface"];
EXAMPLES[2448]=["He has a good knowledge of French.","彼はフランス語をよく知っている。","knowledge"];
EXAMPLES[2449]=["She phoned her husband to come immediately.","彼女は父にすぐ来るように電話した。","immediately"];
EXAMPLES[2450]=["Our experiment went wrong last week.","我々の実験は先週失敗した。","experiment"];
EXAMPLES[2451]=["What's the material?","材質は何ですか。","material"];
EXAMPLES[2452]=["I was late because of heavy traffic.","交通渋滞のため、私は遅れました。","traffic"];
EXAMPLES[2453]=["Could you reduce the price a little?","もっと安くなりますか。","reduce"];
EXAMPLES[2454]=["The picture looks better at a distance.","絵は少し離れたところに置くとより良く見える。","distance"];
EXAMPLES[2455]=["We made the most of the opportunity.","私たちはその機会を最大限に利用した。","opportunity"];
EXAMPLES[2456]=["I prefer going out to staying home.","私は家にいるより外出するのが好きだ。","prefer"];
EXAMPLES[2457]=["Don't mention our plan to anybody.","われわれの計画を誰にも言うな。","mention"];
EXAMPLES[2458]=["His speech made a good impression on me.","彼の演説は私によい印象を与えた。","impression"];
EXAMPLES[2459]=["That's an item from a famous company.","有名なブランドですね。","item"];
EXAMPLES[2460]=["He has done this for profit.","彼は営利のためにこれをした。","profit"];
EXAMPLES[2461]=["I saw the ship sink in the sea.","私は船が海に沈むのを見た。","sink"];
EXAMPLES[2462]=["I'm very concerned about her illness.","私は彼女の病気のことがとても気になる。","illness"];
EXAMPLES[2463]=["My brother was expert in handwork.","兄は手仕事がうまかった。","expert"];
EXAMPLES[2464]=["When are you going to quit smoking?","あなたはいつタバコを止めるつもりですか。","quit"];
EXAMPLES[2465]=["Come on, don't be silly.","馬鹿なまねするんじゃないよ。","silly"];
EXAMPLES[2466]=["He made his son a wealthy man.","彼は息子を金持ちにした。","wealthy"];
EXAMPLES[2467]=["Mary asked her son to behave himself.","メアリーは息子に行儀よくするように頼んだ。","behave"];
EXAMPLES[2469]=["Divide the cake between you two.","ケーキをあなた方２人で分けなさい。","Divide"];
EXAMPLES[2470]=["It is better to ignore this point.","この点は無視したほうがいい。","ignore"];
EXAMPLES[2471]=["Who organized that meeting?","その大会を準備したのは誰ですか。","organized"];
EXAMPLES[2472]=["We shall overcome all our difficulties.","われわれはあらゆる困難に勝たなければならない。","overcome"];
EXAMPLES[2473]=["We are attracted by what you are.","我々は君の人格にひかれているのだ。","attracted"];
EXAMPLES[2474]=["You never wanna breathe your last.","決して終わらない。","breathe"];
EXAMPLES[2475]=["I was much confused by his questions.","彼の質問にひどく面食らってしまった。","confused"];
EXAMPLES[2476]=["I'd like to reserve a seat.","席を予約したいのですが。","reserve"];
EXAMPLES[2477]=["The man lay asleep all day long.","その男は１日中寝ていた。","asleep"];
EXAMPLES[2478]=["I rarely catch a cold.","私はめったに風邪をひかない。","rarely"];
EXAMPLES[2479]=["Thanks to him, I could get a job.","彼のおかげで就職できた。","Thanks to"];
EXAMPLES[2480]=["Finish your homework by the time your father comes home.","お父さんが帰るまでに宿題をすませなさい。","by the time"];
EXAMPLES[2481]=["Do you have anything to say in particular?","何か特に言う事がありますか。","in particular"];
EXAMPLES[2482]=["I am to take over my father's business.","私が父の事業を受け継ぐことになっている。","take over"];
EXAMPLES[2483]=["In addition to English, he can speak French.","英語のほかに彼はフランス語も話せる。","In addition"];
EXAMPLES[2485]=["Even though I'm tired, I'll study hard.","私は疲れているけれども一生懸命勉強しよう。","Even though"];
EXAMPLES[2487]=["I wonder if you could do me a favor.","お願いを聞いてもらえないかな。","do me a favor"];
EXAMPLES[2488]=["When did you get back from London?","いつロンドンから戻りましたか。","get back"];
EXAMPLES[2489]=["I went out in spite of the rain.","私は雨にもかかわらず出かけた。","in spite of"];
EXAMPLES[2490]=["Keep in mind that smoking is not good for your health.","タバコは健康に良くないことを忘れないでね。","Keep in mind"];
EXAMPLES[2491]=["We were caught in a shower on the way to school.","私達は学校へ行く途中でにわか雨にあった。","on the way to"];
EXAMPLES[2492]=["I have to put down your new address.","あなたの新しい住所を書き留めなくては。","put down"];
EXAMPLES[2493]=["Don't rely on his help.","彼の援助を期待するな。","rely on"];
EXAMPLES[2494]=["His music and words appeal to young people.","彼の音楽と言葉は若者に受ける。","appeal to"];
EXAMPLES[2495]=["We had to call off the game because of rain.","雨のために試合を中止せざるを得なかった。","call off"];
EXAMPLES[2496]=["Have something to eat just in case.","念のため、何か食べておきなさい。","in case"];
EXAMPLES[2497]=["He studied ten hours a day on average.","彼は日に平均十時間は勉強した。","on average"];
EXAMPLES[2498]=["Did you make that mistake on purpose?","あなたはわざとその間違いをしたのか。","on purpose"];
EXAMPLES[2499]=["You stay away from her.","彼女に手をだすな。","stay away from"];
EXAMPLES[2501]=["There is nothing to do but apologize.","謝るしかない。","apologize"];
EXAMPLES[2502]=["You will succeed in the end.","最後は成功します。","succeed in"];
EXAMPLES[2503]=["Suffice it to say that, after all, this won't do.","結局これでは駄目だとだけ言っておこう。","after all"];
EXAMPLES[2506]=["No matter how fast you may walk, you can't catch up with him.","どんなに速く歩いてもあなたは彼に追いつけない。","catch up with"];
EXAMPLES[2507]=["We differ from them in some respects.","われわれはいくつかの点で彼らと違う。","differ from"];
EXAMPLES[2508]=["He didn't participate in the story.","彼はその話に参加しなかった。","participate in"];
EXAMPLES[2509]=["We all shall die sooner or later.","われわれは遅かれ早かれ死ぬだろう。","sooner or later"];
EXAMPLES[2510]=["Your hat is similar to mine.","あなたの帽子は私のに似ています。","similar to"];
EXAMPLES[2511]=["Mother will show off her children.","母親は自分の子供のよいところを見せびらかそうとする。","show off"];
EXAMPLES[2512]=["Why did you turn down his offer?","なぜ彼の申し出を断ったのですか。","turn down"];
EXAMPLES[2514]=["That's mostly right.","大体正しい。","mostly"];
EXAMPLES[2515]=["Dig in your homework now.","さっさと宿題をやりなさい。","Dig"];
EXAMPLES[2517]=["I will bite just a little bit.","一口で食べてみよう。","bite"];
EXAMPLES[2518]=["Let me treat you next time, then.","次はわたしにごちそうさせてください。","treat"];
EXAMPLES[2519]=["I would rather you stayed at home.","あなたに家にいてもらいたい。","rather"];
EXAMPLES[2520]=["She is apparently an honest woman.","彼女は一見正直そうに見える。","apparently"];
EXAMPLES[2521]=["She made a great discovery while yet a young student.","彼女はまだ若い研究生のうちに大発見をした。","discovery"];
EXAMPLES[2522]=["She died two days after his arrival.","彼の到着後２日して彼女は亡くなった。","arrival"];
EXAMPLES[2523]=["I agree with you to a degree.","幾分は君に賛成です。","degree"];
EXAMPLES[2524]=["She has finally achieved her end.","彼女はついに目的を達成した。","achieved"];
EXAMPLES[2525]=["What do you think of his attitude?","彼の態度をどう思いますか。","attitude"];
EXAMPLES[2526]=["I have great belief in the doctor.","私はその医者を非常に信用している。","belief"];
EXAMPLES[2528]=["I wish I could see the ancient world.","古代世界を見ることができればなあ。","ancient"];
EXAMPLES[2529]=["You don't have to be so formal.","固いこと言うなよ。","formal"];
EXAMPLES[2530]=["Father doesn't allow me to drive.","父は私が車を運転するのを許さない。","allow"];
EXAMPLES[2531]=["How does the first article run?","最初の条項には何と書いてあるか。","article"];
EXAMPLES[2532]=["This book contains a lot of photos.","この本にはたくさんの写真が入っている。","contains"];
EXAMPLES[2533]=["I seem to have a temperature.","どうも熱があるらしい。","temperature"];
EXAMPLES[2534]=["There was hardly anyone in the room.","部屋にはほとんど人はいなかった。","hardly"];
EXAMPLES[2535]=["I am unable to agree on that point.","その点は賛成しかねる。","unable"];
EXAMPLES[2536]=["I see the point of the argument.","論点がわかる。","argument"];
EXAMPLES[2538]=["What is the height of this mountain?","この山の高さはどのくらいですか。","height"];
EXAMPLES[2539]=["It was an ideal day for walking.","散歩には申し分のない日だった。","ideal"];
EXAMPLES[2540]=["This movie has won great popularity.","この映画は大変な人気を呼んだ。","popularity"];
EXAMPLES[2541]=["Get in touch with your agent right away.","すぐにあなたの代理人に連絡を取りなさい。","agent"];
EXAMPLES[2542]=["Why do American parents praise their children?","なぜアメリカ人の両親は自分の子供を誉めるのか。","praise"];
EXAMPLES[2543]=["He didn't like to be punished.","彼は罰を受けたくなかった。","punished"];
EXAMPLES[2544]=["My proposal met with a negative.","私の提案は反対にあった。","negative"];
EXAMPLES[2545]=["Our family consists of five members.","僕の家族は５人いる。","consists"];
EXAMPLES[2546]=["They were criticizing each other.","彼らは互いに非難しあっていた。","criticizing"];
EXAMPLES[2548]=["She was anxious to recover from illness.","彼女は病気が治ることを願った。","recover"];
EXAMPLES[2549]=["Can you translate English into Japanese?","あなたは英語を日本語に翻訳できますか。","translate"];
EXAMPLES[2550]=["We have known each other since childhood.","僕たちは子供のころからの知り合いです。","childhood"];
EXAMPLES[2551]=["He is sure to accomplish his purpose.","彼は必ず目的を達成するだろう。","accomplish"];
EXAMPLES[2553]=["You are responsible for what you do.","君は自分の行動に責任がある。","responsible"];
EXAMPLES[2554]=["We should not look down on poor people.","私たちは貧しい人々を見下してはいけない。","look down on"];
EXAMPLES[2555]=["We have plenty of time.","時間はたっぷりあります。","plenty of"];
EXAMPLES[2556]=["Could you send up some stomach medicine?","胃薬を持ってきてください。","stomach"];
EXAMPLES[2557]=["Do you have a vision of your future?","あなたは自分の将来のビジョンを持っていますか。","vision"];
EXAMPLES[2559]=["Nobody knows when the earthquake will occur.","いつ地震が起こるかは誰にもわからない。","occur"];
EXAMPLES[2560]=["The solution of the problem took three years.","その問題には３年かかった。","solution"];
EXAMPLES[2561]=["She could solve the problem with ease.","彼女は容易に問題を解くことができた。","ease"];
EXAMPLES[2562]=["Do you think he will be elected president again?","彼は再び大統領に選ばれると思いますか。","elected"];
EXAMPLES[2563]=["Would you like to visit the united states?","あなたはアメリカを訪れたいですか。","united"];
EXAMPLES[2565]=["The meeting went on in this manner.","会議はこのように行われた。","manner"];
EXAMPLES[2566]=["I am suffering from a bad cold.","私は今ひどい風邪をひいている。","suffering"];
EXAMPLES[2567]=["We are facing a crucial time.","今がわれわれにとって一番大切なときだ。","crucial"];
EXAMPLES[2568]=["That made him govern himself.","そのため彼は自制した。","govern"];
EXAMPLES[2570]=["He is the only one of my friends that is talented.","私の友人の中で才能があるのは彼だけだ。","talented"];
EXAMPLES[2571]=["He lost himself in his new research.","彼は新しい研究に我を忘れた。","research"];
EXAMPLES[2572]=["He has a firm purpose in life.","彼は人生に確固とした目的を持っている。","firm"];
EXAMPLES[2574]=["I went into the air force.","私は空軍に入った。","force"];
EXAMPLES[2575]=["What an impressive person he is!","彼はなんと印象的な人なのでしょう。","impressive"];
EXAMPLES[2576]=["You had better live on your salary.","自分の給料で生活したほうがいいよ。","salary"];
EXAMPLES[2577]=["I have a great deal to do.","私にはやることがたくさんある。","deal"];
EXAMPLES[2578]=["Be prompt to do what is asked.","頼まれた事はすぐにやりなさい。","prompt"];
EXAMPLES[2580]=["I gave my vote to Ken.","私はケンに投票した。","vote"];
EXAMPLES[2581]=["What's the name of the mountain range?","あの山脈の名前は何と言いますか。","range"];
EXAMPLES[2582]=["Her help is vital to the success of this plan.","この計画が成功するには彼女の援助がぜひ必要です。","vital"];
EXAMPLES[2583]=["He succeeded to his father's estate.","彼は彼の父の財産を受け継いだ。","estate"];
EXAMPLES[2584]=["The responsibility was in large part mine.","その責任は大部分私にあった。","responsibility"];
EXAMPLES[2586]=["You're taking a lot for granted.","虫がよすぎる。","granted"];
EXAMPLES[2588]=["This book is especially difficult to read.","この本は特に読むのが難しい。","especially"];
EXAMPLES[2590]=["There's something mysterious about her.","彼女にはどこか不思議なところがある。","mysterious"];
EXAMPLES[2594]=["She attributed her failure to her illness.","彼女は自分の失敗を病気のせいにした。","attributed"];
EXAMPLES[2595]=["We must prevent war at any cost.","何としても戦争は防がねばならない。","prevent"];
EXAMPLES[2597]=["The plan will be brought into effect tomorrow.","その計画は明日実行される。","effect"];
EXAMPLES[2599]=["Why do you accuse my son?","君はなぜ私の息子を非難するのか。","accuse"];
EXAMPLES[2603]=["The flowers died for lack of water.","花は水がなくて枯れた。","lack"];
EXAMPLES[2604]=["I had to work on an essay.","私は論文を書かなければならなかったの。","essay"];
EXAMPLES[2605]=["Let's try another approach to the matter.","その問題に別な取り組み方をしてみよう。","approach"];
EXAMPLES[2606]=["It is quite natural that he think so.","彼がそう思うのはまったく当然だ。","natural"];
EXAMPLES[2609]=["His experience qualifies him to do the job.","彼の経験があればその仕事をするのに十分だ。","qualifies"];
EXAMPLES[2610]=["It is not my intention to return.","帰るつもりはありません。","intention"];
EXAMPLES[2611]=["He arrived two days previously.","彼は２日前に着いた。","previously"];
EXAMPLES[2612]=["He had to feed his large family.","彼は大家族を養わなければならなかった。","feed"];
EXAMPLES[2613]=["He can speak neither English nor French.","彼は英語もフランス語も話せない。","nor"];
EXAMPLES[2614]=["They succeeded in the negotiation.","彼らはその交渉に成功した。","negotiation"];
EXAMPLES[2615]=["I was recently in an automobile accident.","最近自動車事故に遭いました。","automobile"];
EXAMPLES[2617]=["This matter is extremely important to us.","この問題は、私たちには非常に重要である。","extremely"];
EXAMPLES[2618]=["He echoes his wife in everything.","彼はすべて妻の言いなりになっている。","echoes"];
EXAMPLES[2619]=["Please show me your detailed plan.","どうか君の詳しい計画を見せて下さい。","detailed"];
EXAMPLES[2621]=["I hope it pans out.","うまく行くといいわね。","pans"];
EXAMPLES[2622]=["He stopped smoking for the improvement of his health.","彼は健康のためにたばこを吸うのをやめた。","improvement"];
EXAMPLES[2623]=["He is little short of a genius.","彼はほとんど天才です。","genius"];
EXAMPLES[2624]=["She is a credit to her class.","彼女はクラスの名誉だ。","credit"];
EXAMPLES[2625]=["I am free of debt.","私には借金がない。","debt"];
EXAMPLES[2627]=["He took a glance at the girl.","彼は少女をちらっと見た。","glance"];
EXAMPLES[2630]=["Will you permit me to go there?","そこに行ってもよろしいですか。","permit"];
EXAMPLES[2631]=["I have a concern in the business.","私はその事業に関係している。","concern"];
EXAMPLES[2632]=["I strained to hear what the president said.","大統領の言うことに耳を澄ました。","strained"];
EXAMPLES[2633]=["We're getting nowhere with these problems.","これらの問題は我々にはどうにもならない。","nowhere"];
EXAMPLES[2634]=["We don't meet very often recently.","最近あまり会わない。","recently"];
EXAMPLES[2635]=["He is my working mate.","彼は私の仕事仲間である。","mate"];
EXAMPLES[2636]=["Can you distinguish her from her sister?","彼女と彼女の姉を見分けられますか。","distinguish"];
EXAMPLES[2637]=["He looks quite sophisticated for his age.","彼は年の割にとても世慣れて見える。","sophisticated"];
EXAMPLES[2638]=["It's nothing to get upset about.","大丈夫、気にしないで。","upset"];
EXAMPLES[2639]=["Don't disturb me while I am studying.","私の勉強の邪魔をしないでくれ。","disturb"];
EXAMPLES[2640]=["He took a chance investing his money in the new company.","彼はその新しい会社に投資してみた。","investing"];
EXAMPLES[2642]=["I have decided to retire.","私は引退しようと決心しています。","retire"];
EXAMPLES[2644]=["She is by no means polite.","彼女は決して礼儀正しくない。","polite"];
EXAMPLES[2645]=["Now let me entertain you with music.","それでは音楽をお楽しみください。","entertain"];
EXAMPLES[2648]=["I am in a bind as my money has been stolen.","私はお金を盗まれ困っている。","bind"];
EXAMPLES[2649]=["The train was full of passengers.","列車は乗客でいっぱいだった。","passengers"];
EXAMPLES[2651]=["He works hard to earn his living.","彼は生計を立てるために一生懸命働いている。","earn"];
EXAMPLES[2652]=["This story is too complex for children.","この話は子供には複雑すぎる。","complex"];
EXAMPLES[2653]=["It was cold that day, and moreover it began to rain.","その日は寒く、おまけに雨まで降ってきた。","moreover"];
EXAMPLES[2655]=["He made mistakes on purpose to annoy me.","彼は私を困らせるために間違えた。","annoy"];
EXAMPLES[2656]=["He was a great influence on me.","彼から大きな影響を受けた。","influence"];
EXAMPLES[2657]=["We're too busy to attend to such detail.","忙しくてそんなところまで手が回らない。","detail"];
EXAMPLES[2658]=["Prior to the meeting, they had dinner.","会に先立って彼らは夕食をとった。","Prior"];
EXAMPLES[2660]=["She is engaged in writing a book.","彼女は本を書くことを契約した。","engaged"];
EXAMPLES[2661]=["I regret to say I cannot come.","お伺いできないのが残念です。","regret"];
EXAMPLES[2662]=["Some were playing tennis on the tennis court.","何人かがテニスコートでテニスをしていた。","court"];
EXAMPLES[2663]=["It is threatening to rain.","今にも一雨きそうだ。","threatening"];
EXAMPLES[2664]=["Money enables you to buy anything.","金があればなんでも買える。","enables"];
EXAMPLES[2665]=["Unfortunately I have no money with me.","あいにく私はお金を持っていない。","Unfortunately"];
EXAMPLES[2668]=["We hold out no expectation of success.","成功することはまったく期待してない。","expectation"];
EXAMPLES[2671]=["Every citizen ought to help them.","すべての市民は彼らを援助すべきです。","citizen"];
EXAMPLES[2674]=["Your thoughts are of no significance at all.","君の考えなどはどうだっていいことだ。","significance"];
EXAMPLES[2675]=["Mary has a flower in her hand.","マリーは花を持っている。","flower"];
EXAMPLES[2676]=["His failure is out of the question.","彼の失敗は考えられない。","failure"];
EXAMPLES[2680]=["It is remarkable for her not to understand.","彼女がわからないことは珍しい事だ。","remarkable"];
EXAMPLES[2682]=["The village was isolated by the heavy storm.","その村はひどい嵐によって孤立した。","isolated"];
EXAMPLES[2684]=["The idea is typical of him.","その意見はいかにも彼らしい。","typical"];
EXAMPLES[2687]=["His words carry little conviction.","彼の言葉は我々に説得力がほとんどない。","conviction"];
EXAMPLES[2688]=["Bill seems to be stuck on Mary.","ビルはどうもメアリーに惚れているらしい。","Bill"];
EXAMPLES[2689]=["You should emphasize that fact.","君はその事実を重視すべきだ。","emphasize"];
EXAMPLES[2690]=["America is a country of immigrants.","アメリカは移住者の国である。","immigrants"];
EXAMPLES[2691]=["I interpreted what he said in French into Japanese.","私は彼のフランス語を日本語に通訳した。","interpreted"];
EXAMPLES[2692]=["Snow is falling thick and fast.","雪が降りしきっている。","thick"];
EXAMPLES[2693]=["Physics is not easy to learn.","物理学は学ぶのが簡単ではない。","Physics"];
EXAMPLES[2694]=["Police can't be trigger happy.","警察は簡単に銃を使ってはいけない。","trigger"];
EXAMPLES[2695]=["Please let me know the status.","状況をお知らせください。","status"];
EXAMPLES[2696]=["Does he have anything to do with the political party?","彼はその政党と何か関係があるのか。","political"];
EXAMPLES[2697]=["At last he found out the truth.","ついに彼は真実を発見した。","truth"];
EXAMPLES[2698]=["I partly agree with you.","一部君の意見に賛成する。","partly"];
EXAMPLES[2699]=["We should observe our traffic rules.","交通規則を守らなければならない。","observe"];
EXAMPLES[2700]=["Drink water from a stream.","小川の水を飲む。","stream"];
EXAMPLES[2701]=["We oppose the government on this matter.","この件については、私達は政府に反対だ。","oppose"];
EXAMPLES[2702]=["He was not conscious of his own mistake.","彼は自分の間違いに気付いていなかった。","conscious"];
EXAMPLES[2703]=["We intend to look into that matter.","その件を調べてみるつもりです。","intend"];
EXAMPLES[2704]=["The operation is quite free from danger.","その操作に全く危険はありません。","operation"];
EXAMPLES[2705]=["I can recommend this book to you.","私はこの本をあなたに推薦できます。","recommend"];
EXAMPLES[2706]=["Her eyes are her best feature.","彼女の目が一番美しい。","feature"];
EXAMPLES[2707]=["You should take her illness into consideration.","あなたは彼女の病気を考慮すべきだ。","consideration"];
EXAMPLES[2708]=["Do I have to change my diet?","私は食事のとり方を変えるべきですか。","diet"];
EXAMPLES[2709]=["The population of Japan is less than America.","日本の人口はアメリカよりも少ない。","population"];
EXAMPLES[2710]=["This answer may not necessarily be wrong.","この答えが必ずしも間違いとは限らないだろう。","necessarily"];
EXAMPLES[2711]=["It is doubtful whether Bill will come.","ビルが来るかどうかは疑わしい。","whether"];
EXAMPLES[2713]=["His opinion comes into conflict with mine.","彼の意見は私のと合わない。","conflict"];
EXAMPLES[2714]=["Your proposal is a bit extreme.","君の提案は少し過激だ。","extreme"];
EXAMPLES[2715]=["I take my camera wherever I go.","どこへ行くにもカメラを持って行きます。","wherever"];
EXAMPLES[2716]=["I heard about it from another source last year.","私は去年、それを別の筋から聞いた。","source"];
EXAMPLES[2717]=["His objective is to pass the test.","彼の目的は合格することです。","objective"];
EXAMPLES[2721]=["The police found no clue.","警察は何の手がかりも見つけられなかった。","clue"];
EXAMPLES[2723]=["My bicycle has gone out of commission.","私の自転車はもう使えなくなった。","commission"];
EXAMPLES[2724]=["He is seeking a good job.","彼はよい仕事をさがしている。","seeking"];
EXAMPLES[2725]=["When did America become independent of England?","アメリカはいつイギリスから独立しましたか。","independent"];
EXAMPLES[2726]=["I proposed that she come with me.","私は、彼女も一緒に来れば、と提案した。","proposed"];
EXAMPLES[2727]=["It is difficult to understand his theory.","彼の理論を理解するのは難しい。","theory"];
EXAMPLES[2728]=["He seems to be a nice fellow.","彼はいい奴らしい。","fellow"];
EXAMPLES[2729]=["Who should look after the elderly?","だれが年配の人々の世話をするべきなのか。","elderly"];
EXAMPLES[2731]=["He is the proper person for the job.","その仕事には彼が適任だ。","proper"];
EXAMPLES[2733]=["She was absent due to a cold.","彼女は風邪を引いて欠席しました。","due"];
EXAMPLES[2737]=["To live is to suffer.","生きることは苦しむこと。","suffer"];
EXAMPLES[2739]=["Personally, I liked this one.","私はこれが気に入りました。","Personally"];
EXAMPLES[2741]=["They have preserved the building.","彼らはその建物を保存してきた。","preserved"];
EXAMPLES[2742]=["She is a very intelligent young lady.","彼女は若くて、とても頭のよい女性だ。","intelligent"];
EXAMPLES[2743]=["In our park, we have a nice slide for children to play on.","公園に子供が遊ぶのにちょうどよい滑り台がある。","slide"];
EXAMPLES[2745]=["She is constantly writing letters.","彼女はいつも手紙を書いている。","constantly"];
EXAMPLES[2746]=["The boat drifted about on the sea.","その船は海を漂流した。","drifted"];
EXAMPLES[2747]=["She is much concerned about the result.","彼女はその結果を大変気にしている。","result"];
EXAMPLES[2751]=["The moon is the earth's satellite.","月は地球の衛星だ。","satellite"];
EXAMPLES[2752]=["My son lives in a distant place.","息子は離れた所に住んでいる。","distant"];
EXAMPLES[2753]=["She had an easy delivery.","彼女は安産だった。","delivery"];
EXAMPLES[2754]=["He is anxious for her to come.","彼は彼女がくることを熱望している。","anxious"];
EXAMPLES[2755]=["A boy came running towards me.","少年が私の方へ駆けて来た。","towards"];
EXAMPLES[2757]=["I'm not very particular about food.","私は食べ物についてはうるさくありません。","particular"];
EXAMPLES[2760]=["She didn't appear to recognize me.","彼女は私と分からなかったようだ。","appear"];
EXAMPLES[2761]=["No one is to leave without permission.","誰も許可なしで出てはいけない。","permission"];
EXAMPLES[2763]=["Do you deny that you went there?","君はそこに行ったことを否定するのですか。","deny"];
EXAMPLES[2764]=["Please don't leave valuable things here.","大切なものはここに置かないで下さい。","valuable"];
EXAMPLES[2766]=["Let's wait till he comes back.","彼が戻るまで待とう。","till"];
EXAMPLES[2767]=["I haven't met him properly yet.","あの人にはまだ挨拶をしていない。","properly"];
EXAMPLES[2769]=["Why don't you tell her directly?","彼女に直接言ったらどうですか。","directly"];
EXAMPLES[2770]=["I have been occupied in reading books.","ずっと読書に没頭していた。","occupied"];
EXAMPLES[2771]=["Do not vary your plan so often.","そんなに計画を変更するな。","vary"];
EXAMPLES[2772]=["Don't stare others in the face.","他人の顔をじろじろ見るんじゃない。","stare"];
EXAMPLES[2773]=["She has been married to him for a decade now.","彼女が彼と結婚してからもう十年になる。","decade"];
EXAMPLES[2776]=["I found it difficult to convince her.","彼女を説得するのは難しいと分かった。","convince"];
EXAMPLES[2777]=["The police were able to find the criminal.","警察は犯人を見つけ出す事ができた。","criminal"];
EXAMPLES[2778]=["The government of the country is now stable.","その国の政府は安定している。","stable"];
EXAMPLES[2782]=["I saw my mother hide the cake.","私は母がケーキを隠すのを見た。","hide"];
EXAMPLES[2783]=["He is now on the way to recovery.","彼は今は回復に向かっている。","recovery"];
EXAMPLES[2784]=["He is in bonds.","彼は禁固の身だ。","bonds"];
EXAMPLES[2787]=["Her behavior is consistent with her words.","彼女の行動は言うことと一致している。","consistent"];
EXAMPLES[2789]=["This is the time he normally arrives.","この時間にいつも彼はきます。","normally"];
EXAMPLES[2790]=["What do you conclude from that?","あなたはそれからどんな結論を下しますか。","conclude"];
EXAMPLES[2791]=["He has a secret desire to play.","彼は密かに遊びたいと思っている。","desire"];
EXAMPLES[2792]=["How did he respond to the news?","彼はそのニュースに、どう反応した？","respond"];
EXAMPLES[2794]=["He is studying to be a minister.","彼は牧師になる勉強をしている。","minister"];
EXAMPLES[2796]=["The chairman of the meeting became ill.","会議の議長が病気になった。","chairman"];
EXAMPLES[2799]=["They refer to you as their friends.","彼らは君達のことを友人だといっている。","refer"];
EXAMPLES[2800]=["I'll have them repair my car.","彼らに私の車を修繕してもらおう。","repair"];
EXAMPLES[2801]=["I want to quit my current job.","今の仕事やめたいんだ。","current"];
EXAMPLES[2802]=["Obviously, he's not that kind of person.","明らかに彼はそのような人ではない。","Obviously"];
EXAMPLES[2806]=["Mary is a very social person.","メアリーはとても社交的な人です。","social"];
EXAMPLES[2808]=["The plan requires a large sum of money.","その計画にはたくさんのお金が必要だ。","sum"];
EXAMPLES[2809]=["You just take the rough with the smooth.","いい事も悪い事もあるよ。","rough"];
EXAMPLES[2811]=["My association with him did not last long.","彼とのつきあいは長く続かなかった。","association"];
EXAMPLES[2812]=["I did not yield to such a rule.","私はそのような規則に従わなかった。","yield"];
EXAMPLES[2813]=["He is a politician in all senses.","彼はあらゆる点で政治家だ。","politician"];
EXAMPLES[2814]=["I like to shop at that department store.","私はあのデパートで買い物するのが好きだ。","department"];
EXAMPLES[2815]=["I am interested in palm reading.","手相に興味がある。","palm"];
EXAMPLES[2817]=["Did he admit that he was wrong?","彼は自分の非を認めましたか。","admit"];
EXAMPLES[2818]=["Do not be so critical.","そう批判的にならないで。","critical"];
EXAMPLES[2819]=["Clear one's throat.","咳払いをする。","throat"];
EXAMPLES[2820]=["Can you adapt yourself to the new job?","新しい仕事に適応できますか。","adapt"];
EXAMPLES[2822]=["You and I have succeeded in our attempt.","あなたと私は、企てに成功した。","attempt"];
EXAMPLES[2823]=["How does America impress you?","アメリカの印象はいかがですか。","impress"];
EXAMPLES[2825]=["We got a little bored with each other.","私たちはお互い少しあきてきた。","bored"];
EXAMPLES[2827]=["You could try and be a bit more civilized.","もうちょっと上品にできないの。","civilized"];
EXAMPLES[2832]=["His work is now complete.","彼の仕事は完成している。","complete"];
EXAMPLES[2834]=["The boy is mad for a bicycle.","その子は自転車をとてもほしがっている。","mad"];
EXAMPLES[2835]=["Do good to those who hate you.","自分を憎む者にも親切にしなさい。","hate"];
EXAMPLES[2836]=["I've finally got used to urban life.","私はやっと都会の生活に慣れてきた。","urban"];
EXAMPLES[2837]=["He is a man of good reputation.","彼は評判のよい人だ。","reputation"];
EXAMPLES[2842]=["He's a contemporary of mine.","彼は私と同い年です。","contemporary"];
EXAMPLES[2844]=["I was very surprised at the huge fish.","私はそのものすごく大きな魚に大変驚いた。","huge"];
EXAMPLES[2845]=["I made an awful mistake in the test.","僕はテストでひどい間違いをした。","awful"];
EXAMPLES[2846]=["I don't like to have a doctor examine me.","医者に診てもらうのは好きじゃない。","examine"];
EXAMPLES[2848]=["Mainly, what he said is right.","彼の言ったことは大体正しい。","Mainly"];
EXAMPLES[2849]=["Men can not exist without air.","人は空気なしで生きられない。","exist"];
EXAMPLES[2850]=["Let's reserve that for another occasion.","それはまたの機会にとっておきましょう。","occasion"];
EXAMPLES[2851]=["May I accompany you on your walk?","散歩のお供をしてもよろしいでしょうか。","accompany"];
EXAMPLES[2854]=["Read this book at your leisure.","暇な時にこの本を読んでください。","leisure"];
EXAMPLES[2855]=["He is in a sense a representative of his company.","彼はある意味で会社の代表である。","representative"];
EXAMPLES[2856]=["The mass of people are against the plan.","大多数の人々はその計画に反対である。","mass"];
EXAMPLES[2857]=["What do his words imply?","彼の言葉は何を暗示しているのか。","imply"];
EXAMPLES[2859]=["He was not aware of the danger.","彼はその危険に気付いていなかった。","aware"];
EXAMPLES[2862]=["The teacher called the roll in class.","先生は出席を取った。","roll"];
EXAMPLES[2863]=["How many exposures would you like?","何枚撮りですか。","exposures"];
EXAMPLES[2864]=["He has hardly studied this term.","彼は今学期ほとんど勉強していない。","term"];
EXAMPLES[2866]=["He was otherwise than I thought.","彼は私が思ったのとは違っていた。","otherwise"];
EXAMPLES[2867]=["He is justly proud of his son.","彼が息子を自慢するのも当然だ。","proud"];
EXAMPLES[2868]=["This task is too much for me.","この仕事は私の手におえない。","task"];
EXAMPLES[2870]=["You had better do as I suggest.","君は私がすすめる通りにするほうがよい。","suggest"];
EXAMPLES[2871]=["You will derive much pleasure from reading.","読書から多くの楽しみを得るでしょう。","derive"];
EXAMPLES[2872]=["Get off the lawn!","芝生から出なさい。","lawn"];
EXAMPLES[2873]=["She composed herself before speaking.","彼女は話す前に気を鎮めた。","composed"];
EXAMPLES[2876]=["She is confident of her son's success.","彼女は息子の成功を確信している。","confident"];
EXAMPLES[2879]=["I have a chest cold.","せき風邪をひきました。","chest"];
EXAMPLES[2880]=["They looked on him as an authority.","彼らは彼を権威者とみなした。","authority"];
EXAMPLES[2882]=["I swear I will never do such a thing.","絶対にそんなことはしません。","swear"];
EXAMPLES[2883]=["That makes you even more attractive.","そうするといやが上にも美しく見える。","attractive"];
EXAMPLES[2886]=["Don't expose it to the rain.","それを雨にさらすな。","expose"];
EXAMPLES[2889]=["We need no more men at present.","現在はこれ以上の人手はいりません。","present"];
EXAMPLES[2891]=["It is dull to travel by ship.","船で旅行をするのはたいくつだ。","dull"];
EXAMPLES[2893]=["They should also be fair to others.","その人達はまた他人に公平であるべきだ。","fair"];
EXAMPLES[2894]=["He went to London via Paris.","彼はパリ経由でロンドンへ行った。","via"];
EXAMPLES[2895]=["Among those present was the mayor.","出席者の中に市長もいた。","mayor"];
EXAMPLES[2898]=["Put out your tongue, please.","舌を出してください。","tongue"];
EXAMPLES[2901]=["Do you have anything to declare?","申告する物はありますか。","declare"];
EXAMPLES[2903]=["He maintains his car well.","彼は自分の車をよく整備している。","maintains"];
EXAMPLES[2904]=["This is the passage to the sea.","これが海への通路だ。","passage"];
EXAMPLES[2905]=["I'm very bitter about that.","私はそれをとても苦々しく思う。","bitter"];
EXAMPLES[2906]=["That is the girl whom I know well.","あれは私がよく知っている少女です。","whom"];
EXAMPLES[2907]=["The two of them split up.","二人は別れたんだ。","split"];
EXAMPLES[2908]=["His brother is a very capable doctor.","彼の兄はとても優秀な医者だ。","capable"];
EXAMPLES[2910]=["There is quite a bit of water remaining.","水はかなり多く残っている。","remaining"];
EXAMPLES[2911]=["He is still dependent on his parents.","彼はまだ両親に頼っている。","dependent"];
EXAMPLES[2912]=["Let's not argue any more.","もう議論はやめよう。","argue"];
EXAMPLES[2913]=["The consequence was that she lost her job.","その結果、彼女は、職を失うこととなった。","consequence"];
EXAMPLES[2914]=["Good speech is the outcome of education.","良い言葉は教育の結果である。","outcome"];
EXAMPLES[2919]=["They visited me occasionally.","彼らは時々私を訪ねて来た。","occasionally"];
EXAMPLES[2920]=["His idea is practical.","彼の考えは現実的だ。","practical"];
EXAMPLES[2921]=["Let me help you wipe it off.","それをふきとるのを手伝ってあげよう。","wipe"];
EXAMPLES[2922]=["This is really a very strange affair.","これは全く不思議な事だ。","affair"];
EXAMPLES[2923]=["You shall have a reward.","私は君にほうびをやろう。","reward"];
EXAMPLES[2924]=["I gather that they'll agree with us.","彼らは私達と同意見だと思う。","gather"];
EXAMPLES[2925]=["I think I will advertise in the paper.","新聞に広告を出してみよう。","advertise"];
EXAMPLES[2926]=["She will fail eventually.","結局は、彼女も、失敗するだろう。","eventually"];
EXAMPLES[2927]=["I asked for their approval.","私は彼らの賛成を求めた。","approval"];
EXAMPLES[2928]=["I love that commercial.","私はあのｃｍが大好きです。","commercial"];
EXAMPLES[2929]=["Smoking is harmful to the health.","煙草を吸うのは体に悪い。","harmful"];
EXAMPLES[2930]=["We'll go along with your suggestion.","私たちは君の提案に賛成しよう。","suggestion"];
EXAMPLES[2931]=["She seemed happy in contrast to the man.","彼女はその男と違ってとても幸福そうだ。","contrast"];
EXAMPLES[2933]=["I was absorbed in reading a novel.","私は小説を読むのに熱中していた。","absorbed"];
EXAMPLES[2934]=["Are you for or against the proposal?","その提案に賛成ですか、それとも反対ですか。","proposal"];
EXAMPLES[2936]=["She promised to look into the matter immediately.","その問題をすぐ調べると彼女は約束した。","immediately"];
EXAMPLES[2938]=["Dismiss the trouble from one's mind.","頭から心配事を忘れ去る。","Dismiss"];
EXAMPLES[2941]=["She is constantly writing letters.","彼女はいつも手紙を書いている。","constantly"];
EXAMPLES[2942]=["Say your prayers before you eat.","食事の前に御祈りをしなさい。","prayers"];
EXAMPLES[2943]=["I agree to the proposal in principle.","その提案には原則的には賛成します。","principle"];
EXAMPLES[2946]=["Please remind me to post the letters.","手紙を出すのを忘れてたら、注意して下さい。","remind"];
EXAMPLES[2948]=["These clothes are not appropriate for a cold winter day.","この服は寒い冬の日には向かない。","appropriate"];
EXAMPLES[2949]=["You deserve to succeed.","君なら成功してもおかしくない。","deserve"];
EXAMPLES[2952]=["He has much economic knowledge.","彼は経済の知識をたくさん持っている。","economic"];
EXAMPLES[2953]=["I can convey my feelings in words.","私は言葉で気持ちを伝えることができます。","convey"];
EXAMPLES[2956]=["Is there an index to the book?","その本には索引がついていますか。","index"];
EXAMPLES[2957]=["She takes every circumstance into account.","彼女はすべての事情を利用する。","circumstance"];
EXAMPLES[2958]=["We had a conversation about baseball.","私達は野球についておしゃべりした。","conversation"];
EXAMPLES[2961]=["I am afraid it is a reject.","不良品ではないかと思います。","reject"];
EXAMPLES[2962]=["That's my province.","それは私の領分ですよ。","province"];
EXAMPLES[2963]=["The admission is ten dollars a person.","一人１０ドルです。","admission"];
EXAMPLES[2967]=["What will happen to the Japanese economy?","日本経済は今後どうなるのだろうか。","economy"];
EXAMPLES[2968]=["They're constructing a bridge over the river.","川に橋が架けられています。","constructing"];
EXAMPLES[2969]=["Can I be of any assistance to you?","私は何かお役に立ちましょうか。","assistance"];
EXAMPLES[2971]=["John is at his peak now.","ジョンは今絶頂だ。","peak"];
EXAMPLES[2974]=["Is this the first time you've had this symptom?","この症状が出たのは初めてですか。","symptom"];
EXAMPLES[2975]=["There are quite a lot of tribes in the world.","世界には実に多くの種族がいます。","tribes"];
EXAMPLES[2976]=["He went to a college of agriculture.","彼は農業大学へ行きました。","agriculture"];
EXAMPLES[2977]=["He is a fish dealer.","彼は魚屋です。","dealer"];
EXAMPLES[2978]=["It is unlike him to be late.","遅刻するなんて彼らしくない。","unlike"];
EXAMPLES[2980]=["We went to see a comedy in London.","私たちはロンドンに喜劇を見に行った。","comedy"];
EXAMPLES[2981]=["It is absolutely impossible to do so.","そうすることは全く不可能だ。","absolutely"];
EXAMPLES[2983]=["That which is evil is soon learned.","悪いことはすぐ覚える。","evil"];
EXAMPLES[2985]=["Let's suppose that he is here.","彼がここにいると仮定してみよう。","suppose"];
EXAMPLES[2987]=["Everyone is entitled to his own opinion.","誰でも自分の意見を持つ権利がある。","entitled"];
EXAMPLES[2989]=["She told me the story in confidence.","彼女は極秘で私にその話をした。","confidence"];
EXAMPLES[2990]=["Whenever he comes, he scolds us.","彼は来れば必ず私たちをしかる。","Whenever"];
EXAMPLES[2991]=["It's rush hour at Tokyo station.","東京駅はラッシュ中だ。","rush"];
EXAMPLES[2994]=["I am studying it in cooperation with them.","私は彼らと共同してそれを研究している。","cooperation"];
EXAMPLES[2996]=["I've detected a big mistake.","私は大きな誤りを見つけた。","detected"];
EXAMPLES[2999]=["I have three years left until retirement.","私は定年まで３年残っている。","retirement"];
EXAMPLES[3000]=["I am very sensitive to the cold.","私は寒さに敏感だ。","sensitive"];
EXAMPLES[3001]=["We look forward to your early reply.","お早い返事お待ちしています。","reply"];
EXAMPLES[3002]=["Our suggestions met with his opposition.","私たちの提案は彼の反対に合った。","opposition"];
EXAMPLES[3005]=["The company gave him enough pension to live on.","会社は生活するために十分な年金を与えた。","pension"];
EXAMPLES[3006]=["I am a poor correspondent.","私はめったに手紙を書かない。","correspondent"];
EXAMPLES[3007]=["What time are you going on duty?","君は何時に勤務につくの？","duty"];
EXAMPLES[3008]=["I am still attached to this bicycle.","私はまだこの自転車に愛着がある。","attached"];
EXAMPLES[3009]=["His sister is a popular tv personality.","彼の妹は人気のテレビタレントだよ。","personality"];
EXAMPLES[3010]=["The chance was fully taken advantage of.","その機会は十分に利用された。","fully"];
EXAMPLES[3011]=["His scheme went wrong in the end.","彼の計画は結局はうまくいかなかった。","scheme"];
EXAMPLES[3012]=["I want to have a telephone installed.","電話を引きたいのです。","installed"];
EXAMPLES[3014]=["Every spring the river floods here.","春になると川がここであふれる。","floods"];
EXAMPLES[3015]=["Now folks, let's go on.","さあ、みんな、先へ進もう。","folks"];
EXAMPLES[3016]=["He is not running in the coming election.","彼は今度の選挙には立たないだろう。","election"];
EXAMPLES[3018]=["A revolution broke out in that country.","その国に革命が起こった。","revolution"];
EXAMPLES[3019]=["You are the next in line for promotion.","君は次の昇任予定者です。","promotion"];
EXAMPLES[3020]=["Japan is an industrial country.","日本は産業国である。","industrial"];
EXAMPLES[3022]=["Don't lean too much on others.","あまり人を当てにするな。","lean"];
EXAMPLES[3023]=["The exhibition is well worth a visit.","その展覧会は十分訪れる価値がある。","exhibition"];
EXAMPLES[3024]=["I compromised with her on the point.","私はその点について彼女と妥協した。","compromised"];
EXAMPLES[3025]=["They are free from care and anxiety.","あの人達には何の心配事も不安もない。","anxiety"];
EXAMPLES[3028]=["We defeated them in baseball.","私達は野球で彼らを負かした。","defeated"];
EXAMPLES[3030]=["What was his reaction to this news?","このニュースに対する彼の反応はどうでしたか。","reaction"];
EXAMPLES[3031]=["I was forced to abandon the plan.","私はやむを得ずその計画をやめた。","abandon"];
EXAMPLES[3032]=["In a crisis, you must get in touch with your teacher.","危険な時には先生と連絡を取りなさい。","crisis"];
EXAMPLES[3033]=["I want to live in comfort.","私は快適な生活がしたい。","comfort"];
EXAMPLES[3034]=["No man is wise at all times.","いつでは賢い人なんていません。","wise"];
EXAMPLES[3035]=["I had a sustaining breakfast.","栄養のある朝食をとった。","sustaining"];
EXAMPLES[3036]=["If you are honest, I will hire you.","君が正直なら雇おう。","hire"];
EXAMPLES[3037]=["Slip on your shoes.","さっさと靴をはきなさい。","Slip"];
EXAMPLES[3038]=["He was entirely free of his worry.","彼の心配はすっかりなくなっていた。","entirely"];
EXAMPLES[3042]=["We will employ a man who can speak English.","英語を話せる人を雇います。","employ"];
EXAMPLES[3043]=["Don't hang up yet, please.","まだ電話を切らないで下さい。","hang"];
EXAMPLES[3047]=["They came to our aid at once.","彼らはすぐ私達を助けに来てくれた。","aid"];
EXAMPLES[3048]=["The result of the poll will be known soon.","投票結果はもうすぐわかるだろう。","poll"];
EXAMPLES[3049]=["His methods are not scientific.","彼の方法は科学的ではない。","scientific"];
EXAMPLES[3053]=["Ken couldn't recall his name.","ケンは彼の名前を思い出せなかった。","recall"];
EXAMPLES[3054]=["My thoughts are in agreement with them.","私の考えは彼らに賛成です。","agreement"];
EXAMPLES[3056]=["He gave an address to the nation on tv.","彼はテレビで国民に演説した。","nation"];
EXAMPLES[3058]=["What is the depth of the lake?","その湖の深さはどのくらいですか。","depth"];
EXAMPLES[3060]=["There is a threat of a storm.","嵐のきざしがある。","threat"];
EXAMPLES[3062]=["The method is behind the times now.","そのやり方は今や時代遅れだ。","method"];
EXAMPLES[3066]=["When did you have your last physical examination?","最後に健康診断をしたのはいつですか。","physical"];
EXAMPLES[3067]=["His story turned out to be false.","彼の話は誤りであることがわかった。","false"];
EXAMPLES[3072]=["He took the initiative in carrying out the plan.","彼はすぐに計画を実行した。","initiative"];
EXAMPLES[3074]=["According the tv, it will rain tomorrow.","テレビによれば明日は雨だそうだ。","According"];
EXAMPLES[3076]=["I can seldom find time for reading.","私には読書の時間がめったにない。","seldom"];
EXAMPLES[3079]=["He said to her under his breath.","彼は彼女に小声で言った。","breath"];
EXAMPLES[3083]=["He can speak French in addition to English.","彼は英語に加えフランス語も話すことができます。","addition"];
EXAMPLES[3085]=["He declined in health.","彼は健康が衰えた。","declined"];
EXAMPLES[3086]=["A male friend of mine called on me yesterday.","昨日私の男性の友人が私を訪ねてきた。","male"];
EXAMPLES[3087]=["Where did you have your suit made?","どこでスーツを作ったの？","suit"];
EXAMPLES[3089]=["He was merely sitting in the place.","彼はその場所でただ座っていた。","merely"];
EXAMPLES[3090]=["To all appearance it is true.","それは本当らしく見える。","appearance"];
EXAMPLES[3091]=["The foreigner speaks Japanese fairly well.","その外国人はかなりうまく日本語を話す。","fairly"];
EXAMPLES[3093]=["A fire broke out nearby.","近くで火事が起こった。","nearby"];
EXAMPLES[3094]=["We were finally able to settle the matter.","我々はついにその問題を解決することができた。","settle"];
EXAMPLES[3095]=["She contributed much to the company.","彼女は非常に会社に貢献した。","contributed"];
EXAMPLES[3097]=["This computer can cope with much work.","このコンピューターは多くの仕事に対処できる。","cope"];
EXAMPLES[3098]=["Some people don't believe in any religion.","宗教を信じない人もいます。","religion"];
EXAMPLES[3099]=["It took us three hours to come to a conclusion.","その結論に達するのに３時間かかった。","conclusion"];
EXAMPLES[3100]=["They will not stand for such treatment.","彼らはこのような仕打ちに我慢できないだろう。","treatment"];
EXAMPLES[3101]=["We have no alternative but to work.","働くより仕方ない。","alternative"];
EXAMPLES[3102]=["He did the reverse of what I asked.","彼は私が頼んだことの逆をやった。","reverse"];
EXAMPLES[3103]=["Formerly this building was a hospital.","昔はこの建物は病院だった。","Formerly"];
EXAMPLES[3104]=["Who is the victim of the accident?","その事故の犠牲者はだれですか。","victim"];
EXAMPLES[3108]=["How often do you feed the fish?","魚に何回えさをやっていますか。","feed"];
EXAMPLES[3109]=["He is less patient than his brother.","彼は兄さんほど我慢強くない。","patient"];
EXAMPLES[3110]=["She could not state her own opinion.","彼女は自分の意見を述べることができなかった。","state"];
EXAMPLES[3111]=["I hope you'll be happy forever.","お幸せに！","forever"];
EXAMPLES[3112]=["I'm going to propose to her.","彼女に求婚するつもりだ。","propose"];
EXAMPLES[3113]=["It is a very pleasant day today.","今日はとても気持ちの良い日だ。","pleasant"];
EXAMPLES[3114]=["The content of his speech was interesting.","彼のスピーチは面白かった。","content"];
EXAMPLES[3115]=["This watch is superior to that one.","この時計はあの時計よりも優れている。","superior"];
EXAMPLES[3116]=["I don't pretend to love him.","彼を愛しているふりはしない。","pretend"];
EXAMPLES[3118]=["We all made preparation for the meeting.","私たちはみんなその集まりの準備とした。","preparation"];
EXAMPLES[3119]=["I can't afford to buy that.","高すぎて手が出ません。","afford"];
EXAMPLES[3122]=["I was invited to her birthday party.","私は彼女の誕生日に招待された。","party"];
EXAMPLES[3124]=["I am in financial difficulties.","私は経済的に困っている。","financial"];
EXAMPLES[3126]=["They described the girl as being small.","彼らはその少女は小柄だと言った。","described"];
EXAMPLES[3127]=["The doctor decided to operate at once.","医者はすぐ手術することにした。","operate"];
EXAMPLES[3130]=["He has dozens of English books.","彼は何十冊も英語の本を持っている。","dozens"];
EXAMPLES[3132]=["He bends everybody to his will.","彼はだれでも自分の意志に従わせる。","bends"];
EXAMPLES[3133]=["The fish are striking well today.","今日は魚の食いつきがいい。","striking"];
EXAMPLES[3134]=["He was educated at a public school.","彼は公立学校で教育を受けた。","educated"];
EXAMPLES[3136]=["What evidence do you have?","どんな証拠があるというのだ。","evidence"];
EXAMPLES[3137]=["You've lost the ability to concentrate.","あなたは集中する力を失ってしまった。","concentrate"];
EXAMPLES[3139]=["It was extraordinary that he did not agree.","彼が同意しなかったのは変だ。","extraordinary"];
EXAMPLES[3141]=["His death was broadcast all over the world.","彼の死は世界中に放送された。","broadcast"];
EXAMPLES[3143]=["I have lost faith in that doctor.","私はもうあの医者を信用しない。","faith"];
EXAMPLES[3144]=["The father and his son were very alike.","その父親と息子は良く似ていた。","alike"];
EXAMPLES[3145]=["You must study grammar more.","あなたはもっと文法を勉強しなくてはいけない。","grammar"];
EXAMPLES[3146]=["There are always a lot of vehicles on this road.","この道はいつも多くの車が通る。","vehicles"];
EXAMPLES[3147]=["Please remain seated for a few minutes.","少しの間そのままでお願いします。","remain"];
EXAMPLES[3148]=["It was of great benefit to me.","私にはとても有益だった。","benefit"];
EXAMPLES[3149]=["At length, I found his house.","私はやっと彼の家を見つけた。","length"];
EXAMPLES[3154]=["We have decided to adopt your idea.","君の考えを採用することにした。","adopt"];
EXAMPLES[3155]=["He is a man of wisdom.","彼は知恵のある人だ。","wisdom"];
EXAMPLES[3156]=["I didn't know how to express myself.","私は言葉に窮した。","express"];
EXAMPLES[3159]=["I greet my teacher on the street.","道で先生に挨拶する。","greet"];
EXAMPLES[3160]=["They live in our block.","彼らは私たちと同じブロックに住んでいます。","block"];
EXAMPLES[3161]=["It is no use trying to escape.","逃げようとしても無駄だ。","escape"];
EXAMPLES[3162]=["She tried to obtain a ticket for the concert.","彼女はコンサートの切符を手に入れようとした。","obtain"];
EXAMPLES[3163]=["Now she is gradually getting well.","今では病気を少しずつよくなっています。","gradually"];
EXAMPLES[3164]=["It seems obvious that he is sick.","彼が病気だというのは明らかなようだ。","obvious"];
EXAMPLES[3165]=["That he is innocent is quite certain.","彼が無実であることは間違いない。","innocent"];
EXAMPLES[3167]=["This isn't exactly what I wanted.","私がほしかったのとは少し違います。","exactly"];
EXAMPLES[3168]=["There are seven continents on the earth.","世界には７大陸がある。","continents"];
EXAMPLES[3169]=["She has long arms and legs.","彼女は手も足も長い。","arms"];
EXAMPLES[3171]=["He made fun of me in public.","人前で笑い者にされた。","public"];
EXAMPLES[3173]=["Remove your shoes in a Japanese house.","日本の家の中では靴をぬぎなさい。","Remove"];
EXAMPLES[3175]=["He is getting along with his neighborhood.","彼は近所の人とうまくやっている。","neighborhood"];
EXAMPLES[3177]=["He's looking for a suitable job.","彼は自分に合った仕事を探している。","suitable"];
EXAMPLES[3178]=["His secretary seems to know the truth.","彼の秘書は真実を知っているようである。","secretary"];
EXAMPLES[3179]=["He didn't participate in the story.","彼はその話に参加しなかった。","participate"];
EXAMPLES[3180]=["Politics has much to do with me.","政治は国民生活に深い関係がある。","Politics"];
EXAMPLES[3181]=["He is very accurate in his work.","彼は仕事を大変正確にやる。","accurate"];
EXAMPLES[3182]=["A baby comes to chew foods.","赤ん坊が食べ物をかむようになる。","chew"];
EXAMPLES[3186]=["Did you understand the moral of this story?","この話の教訓がわかりましたか。","moral"];
EXAMPLES[3188]=["He put too much emphasis on the matter.","彼はその問題を強調しすぎた。","emphasis"];
EXAMPLES[3189]=["I don't particularly like her.","彼女はあまり好きでない。","particularly"];
EXAMPLES[3191]=["You must consider it before you answer.","答える前によく考えてもらわねばならない。","consider"];
EXAMPLES[3192]=["They are more emotional than we.","彼らは我々よりも感情的だ。","emotional"];
EXAMPLES[3194]=["You can easily identify him because he is very tall.","彼は背が高いからすぐに見分けられるでしょう。","identify"];
EXAMPLES[3195]=["Those books are always in great demand.","それらの本はいつも大変重要である。","demand"];
EXAMPLES[3197]=["Who is the author of this book?","この本の著者は誰ですか。","author"];
EXAMPLES[3198]=["He is a man of considerable means.","彼はかなりの資産家だ。","considerable"];
EXAMPLES[3199]=["I am responsible for his own conduct.","私は、自分の行動に責任がある。","conduct"];
EXAMPLES[3200]=["There is a broad street near my house.","私の家の近くを広い道路が走っている。","broad"];
EXAMPLES[3202]=["We found it impossible to persuade him.","彼を説得するのは不可能だった。","persuade"];
EXAMPLES[3203]=["He played up his achievements.","彼は自分がやり遂げたことを自慢した。","achievements"];
EXAMPLES[3204]=["Tom was a witness to the accident.","トムはその事故の目撃者だった。","witness"];
EXAMPLES[3206]=["I will associate with him in business.","私は彼と共同して仕事をやるつもりだ。","associate"];
EXAMPLES[3207]=["All of us aim at success.","私達はみんな成功を狙っている。","aim"];
EXAMPLES[3208]=["The company is in deficit.","会社が赤字になる。","deficit"];
EXAMPLES[3212]=["I met him on the previous day.","私はその前日彼にあった。","previous"];
EXAMPLES[3216]=["Television has a great appeal for him.","テレビは彼には大きな魅力がある。","appeal"];
EXAMPLES[3217]=["There is no substance in his speech.","彼の話は内容がない。","substance"];
EXAMPLES[3218]=["You should keep to the regulations.","あなたはその規則を守るべきだ。","regulations"];
EXAMPLES[3219]=["The trees will soon be bare.","木はまもなく葉が落ちるだろう。","bare"];
EXAMPLES[3220]=["Why should you suspect me?","なぜあなたは私を疑うのですか。","suspect"];
EXAMPLES[3221]=["Take the battery off the machine.","その機械からバッテリーをはずせ。","battery"];
EXAMPLES[3222]=["Living on a small income is hard.","少ない収入で生活する事は難しい。","income"];
EXAMPLES[3223]=["Don't find fault with your friend.","友達のあらさがしをするな。","fault"];
EXAMPLES[3226]=["He died after a brief illness.","彼は短い病気の後で死んだ。","brief"];
EXAMPLES[3227]=["It is useless to talk to him.","彼に話しかけても無駄だ。","useless"];
EXAMPLES[3228]=["We cannot really predict anything.","我々は本当に何も予言できはしない。","predict"];
EXAMPLES[3230]=["The accident happened all of a sudden.","事故は突然に起きた。","sudden"];
EXAMPLES[3231]=["Is there a transfer point?","乗り換えはありますか。","transfer"];
EXAMPLES[3233]=["My brother's room is always a mess.","弟の部屋はいつも雑然としている。","mess"];
EXAMPLES[3235]=["The water will soon drain away.","水はすぐにはけるだろう。","drain"];
EXAMPLES[3236]=["I believe the truth of her remark.","彼女の話は本当だと思う。","remark"];
EXAMPLES[3237]=["Many students were present at the lecture.","多くの学生が講義に出席した。","lecture"];
EXAMPLES[3238]=["The resolution to the problem was close at hand.","その問題を解決するのはもうすぐだった。","resolution"];
EXAMPLES[3240]=["You can bet your boots on that.","そのことは心配ないよ。","bet"];
EXAMPLES[3241]=["It's characteristic of him to be late.","遅刻するのはいかにも彼らしい。","characteristic"];
EXAMPLES[3242]=["My education has made me what I am.","教育のおかげで私は今日のようになった。","education"];
EXAMPLES[3243]=["Whatever you do, carry it through.","何をするのであれ、必ずやり遂げなさい。","Whatever"];
EXAMPLES[3244]=["That's the cause of his failure.","それが彼の失敗の原因だ。","cause"];
EXAMPLES[3245]=["You want commitment, don't you?","確約が欲しいんだね。","commitment"];
EXAMPLES[3246]=["You must be the temporary we asked for.","私たちが探していたバイトの方ね。","temporary"];
EXAMPLES[3247]=["We got involved in a traffic accident.","我々は交通事故に巻きこまれた。","involved"];
EXAMPLES[3248]=["What about going out for a meal?","食事にしませんか。","meal"];
EXAMPLES[3249]=["I'd like to replace it.","弁償させてくれよ。","replace"];
EXAMPLES[3253]=["The majority was for him.","多数が彼に賛成だった。","majority"];
EXAMPLES[3254]=["How much money does he possess?","彼はお金をいくら持っていますか。","possess"];
EXAMPLES[3259]=["She was slightly better yesterday.","彼女は昨日少し具合がよかった。","slightly"];
EXAMPLES[3261]=["Don't rely too much on others.","余り他人に頼っては行けない。","rely"];
EXAMPLES[3263]=["The purchase is on the company's account.","その買い物は会社の払いになります。","purchase"];
EXAMPLES[3264]=["It is in this room that the summit will be held.","サミットが開かれるのはこの部屋です。","summit"];
EXAMPLES[3267]=["Well may she admire her father.","彼女が父親を尊敬するのはごく当然だ。","admire"];
EXAMPLES[3268]=["He's a student of Japanese literature.","彼は日本文学の研究者だ。","literature"];
EXAMPLES[3269]=["We should face up to this issue.","我々はこの問題に立ち向かうべきだ。","issue"];
EXAMPLES[3270]=["I rent a room by the month.","私は月ぎめで部屋を借りている。","rent"];
EXAMPLES[3271]=["These two are widely different from each other.","これら二つの間には大きな違いがある。","widely"];
EXAMPLES[3272]=["It would be a satisfaction to me.","そうしてもらったら私は満足だ。","satisfaction"];
EXAMPLES[3273]=["He rubbed his eyes with his hands.","彼は手で目をこすった。","rubbed"];
EXAMPLES[3274]=["Are you completely through with your homework?","宿題は完全に終えたのですか。","completely"];
EXAMPLES[3275]=["The snow will soon disappear.","雪はすぐに消えるだろう。","disappear"];
EXAMPLES[3277]=["I calculate he will be late coming home.","彼の帰りは遅いと思う。","calculate"];
EXAMPLES[3278]=["She is determined to leave the company.","彼女は会社を辞めようと決心している。","determined"];
EXAMPLES[3280]=["We have had a heavy crop this year.","今年は豊作だった。","crop"];
EXAMPLES[3282]=["I have a pain in my little toe.","足の小指が痛む。","toe"];
EXAMPLES[3283]=["I can't seize the meaning.","その意味がわかりません。","seize"];
EXAMPLES[3284]=["Your imagination is running away with you.","思いすごしですよ。","imagination"];
EXAMPLES[3286]=["The child was full of curiosity.","その子は好奇心いっぱいだった。","curiosity"];
EXAMPLES[3287]=["My dog has a long tail.","私の犬はしっぽが長い。","tail"];
EXAMPLES[3288]=["He knows no foreign language except English.","彼は英語以外の外国語は全く知らない。","except"];
EXAMPLES[3289]=["This string is strong.","このひもは強い。","string"];
EXAMPLES[3290]=["The appointed day is close at hand.","約束の日がせまっている。","appointed"];
EXAMPLES[3292]=["I came to Tokyo to attend a conference.","会議に出席するために東京に来ました。","conference"];
EXAMPLES[3293]=["The explanation is by no means satisfactory.","その説明は決して満足すべきものではない。","explanation"];
EXAMPLES[3295]=["I saw a man coming toward me.","私に向かってやって来る人が見えた。","toward"];
EXAMPLES[3296]=["She exerted herself to pass the examination.","彼女は試験に合格しようと努力した。","examination"];
EXAMPLES[3297]=["They are strongly opposing my proposal.","彼らは私の提案に強く反対している。","strongly"];
EXAMPLES[3298]=["I fear that it will rain tomorrow.","明日雨になるのではないかと心配です。","fear"];
EXAMPLES[3299]=["Her ability took her to the top.","彼女は有能だったので第一人者になった。","ability"];
EXAMPLES[3300]=["I've lost a little weight.","少しやせました。","weight"];
EXAMPLES[3301]=["He was excluded from the team.","彼はそのチームから除外された。","excluded"];
EXAMPLES[3304]=["You are right to a certain extent.","あなたはある程度まで正しい。","extent"];
EXAMPLES[3305]=["The settlement is a matter of time.","解決は時間の問題だ。","settlement"];
EXAMPLES[3306]=["He lives in an enormous house.","彼は巨大な家に住んでいる。","enormous"];
EXAMPLES[3307]=["I was not aware of his presence.","私は彼がいることに気がつかなかった。","presence"];
EXAMPLES[3311]=["You'd better leave off such a radical idea.","そのような過激な考えはやめるべきだ。","radical"];
EXAMPLES[3314]=["Try to avoid making any more trouble.","これ以上面倒を起こさないでくれ。","avoid"];
EXAMPLES[3316]=["Get up as early as you possibly can.","何とかして出来るだけ早く起きなさい。","possibly"];
EXAMPLES[3317]=["It is likely to be fine tomorrow.","明日は天気になりそうだ。","likely"];
EXAMPLES[3319]=["The very opposite is the truth.","まさにその反対が真実なのです。","opposite"];
EXAMPLES[3320]=["The district is short of water.","その地域は水が不足している。","district"];
EXAMPLES[3321]=["I wish you could have seen him pitch.","彼の投球を見せたかったよ。","pitch"];
EXAMPLES[3322]=["He will be reading a historical novel.","彼は歴史小説を読んでいるだろう。","historical"];
EXAMPLES[3327]=["You had better make a clean breast of everything.","君はすべてのことを打ち明けるほうがよい。","breast"];
EXAMPLES[3328]=["That is an actual fact.","それは実際にあった事だ。","actual"];
EXAMPLES[3329]=["He is very eager to go there.","彼はしきりにそこへ行きたがっている。","eager"];
EXAMPLES[3330]=["She knows many proverbs.","彼女はことわざをいくつも知っている。","proverbs"];
EXAMPLES[3333]=["This word is also French in origin.","この語もまたフランス語が起源である。","origin"];
EXAMPLES[3334]=["I had no notion that you were coming.","君がくるとは僕は思わなかった。","notion"];
EXAMPLES[3336]=["No doubt he will pass the examination.","おそらく彼は試験にパスするだろう。","doubt"];
EXAMPLES[3339]=["He took delight in talking with friends.","友人と話すのが楽しかった。","delight"];
EXAMPLES[3340]=["Shortly after the accident, the police came.","事故の後すぐ警察がやってきた。","Shortly"];
EXAMPLES[3342]=["My daughter is in labor.","私の娘は分娩中だ。","labor"];
EXAMPLES[3343]=["He is known to the entire country.","彼は国全体に知られています。","entire"];
EXAMPLES[3344]=["When we think this way, many problems arise.","このように考えると多くの問題が起きてくる。","arise"];
EXAMPLES[3345]=["The company is incorporated in Japan.","その会社は日本で登記されている。","incorporated"];
EXAMPLES[3346]=["She is a mere child, you know.","彼女はまだほんの子供ですよ。","mere"];
EXAMPLES[3349]=["I wonder if you are truly happy.","あなたは本当に幸せなのかしら。","truly"];
EXAMPLES[3350]=["We are in favor of your plan.","私たちはあなたの計画に賛成している。","favor"];
EXAMPLES[3353]=["There used to be a prison here.","ここには刑務所があった。","prison"];
EXAMPLES[3355]=["There's a possibility of war.","戦争が起こるかもしれない。","possibility"];
EXAMPLES[3357]=["She said she had a slight cold.","彼女は風邪気味だと言った。","slight"];
EXAMPLES[3358]=["She had the kindness to inform us.","彼女は親切にも私たちに知らせてくれた。","inform"];
EXAMPLES[3360]=["There are some depressions in the road.","その道路にはくぼんだ所がいくつかある。","depressions"];
EXAMPLES[3361]=["You'll never know unless you try.","物は試し。","unless"];
EXAMPLES[3362]=["We understand the necessity of studying.","私たちは勉強の必要性を理解している。","necessity"];
EXAMPLES[3364]=["We have a severe winter this year.","今年の冬は寒い。","severe"];
EXAMPLES[3366]=["He is living apart from his wife.","彼は妻と別居している。","apart"];
EXAMPLES[3367]=["He cast off the problem from his mind.","彼はその問題を頭の中から放り出した。","cast"];
EXAMPLES[3369]=["She was walking along a garden path.","彼女は庭の小道を歩いていた。","path"];
EXAMPLES[3370]=["I appreciate your coming all the way.","はるばる来ていただいてありがとうございます。","appreciate"];
EXAMPLES[3371]=["Let's get cracking at 8.","８時から始めよう。","cracking"];
EXAMPLES[3372]=["Don't hesitate to ask questions.","質問をするのをためらわないで下さい。","hesitate"];
EXAMPLES[3373]=["What he said was to the contrary.","彼が言った事はそれと反対の趣旨だった。","contrary"];
EXAMPLES[3374]=["I'm depending on you.","頼んだぞ。","depending"];
EXAMPLES[3375]=["How many people are there in this household?","この家族は何人家族ですか。","household"];
EXAMPLES[3376]=["I'm running out of laughter.","私は笑いを忘れる。","laughter"];
EXAMPLES[3378]=["Crime doesn't pay.","犯罪は割に合わない。","Crime"];
EXAMPLES[3379]=["I'm not frightened of anything.","私は何も恐くありません。","frightened"];
EXAMPLES[3380]=["I mortgaged my house.","家を抵当に入れました。","mortgaged"];
EXAMPLES[3381]=["Well you can indicate everything you see.","そうすれば目にみえるものならなんだって。","indicate"];
EXAMPLES[3383]=["I have no shortage of dictionaries.","私は辞書には不自由しない。","shortage"];
EXAMPLES[3385]=["The property passed from father to son.","財産は父から息子へと譲られた。","property"];
EXAMPLES[3386]=["It might not freeze tonight.","今夜は凍てつかないかもしれない。","freeze"];
EXAMPLES[3387]=["She closely resembles her mother.","彼女は母親によく似ている。","closely"];
EXAMPLES[3389]=["Put it on my father's account.","父の勘定につけといてください。","account"];
EXAMPLES[3391]=["He has a slight edge on you.","彼の方が君より一枚上手だ。","edge"];
EXAMPLES[3393]=["Make sure you get plenty of rest.","十分に休息を取るようにしなさい。","plenty"];
EXAMPLES[3398]=["It is in order to hear your voice well.","それは、おまえの声をよく聞くためだよ。","in order to"];
EXAMPLES[3400]=["A number of books were stolen.","何冊かの本が盗まれた。","A number of"];
EXAMPLES[3401]=["He will end up in prison.","彼は最後は刑務所に入ることになろう。","end up"];
EXAMPLES[3402]=["We finally published the book.","ついにその本を出版した。","published"];
EXAMPLES[3403]=["She got it at her own expense.","自前で買ったのです。","expense"];
EXAMPLES[3404]=["He suggested a plan similar to mine.","彼は私のとよく似た計画を提案した。","similar"];
EXAMPLES[3406]=["Your idea has no foundation at all.","あなたの意見はまったく根拠がない。","foundation"];
EXAMPLES[3407]=["Let's compare this dictionary with that one.","この辞書とあの辞書を比べてみよう。","compare"];
EXAMPLES[3408]=["Whichever road you may take, it will lead to the station.","どの道を行っても駅に出ます。","lead to"];
EXAMPLES[3410]=["The fire consumed the whole house.","その火事で家は全焼した。","consumed"];
EXAMPLES[3411]=["He came to Tokyo in search of employment.","彼は仕事を求めて東京へやってきた。","employment"];
EXAMPLES[3412]=["I heard the news by chance.","私はそのニュースを偶然に聞いてしまった。","by chance"];
EXAMPLES[3413]=["I am not going to betray you.","私はあなたを裏切りませんよ。","betray"];
EXAMPLES[3415]=["A new road is under construction.","新しい道路が建設中である。","construction"];
EXAMPLES[3416]=["It takes a long time to convert.","変換にはかなりの時間がかかる。","convert"];
EXAMPLES[3417]=["I have no family to provide for.","私に養うべき家族がありません。","provide"];
EXAMPLES[3418]=["That custom has little currency in Japan.","その習慣は日本ではほとんど行われていない。","currency"];
EXAMPLES[3419]=["She seemed happy in contrast to the man.","彼女はその男と違ってとても幸福そうだ。","in contrast"];
EXAMPLES[3422]=["Both of us began to smile almost at the same time.","私たち二人はほとんど同時に笑い始めた。","at the same time"];
EXAMPLES[3423]=["They have preserved the building.","彼らはその建物を保存してきた。","preserved"];
EXAMPLES[3424]=["Let's analyze the machine.","その機械を分解してみよう。","analyze"];
EXAMPLES[3426]=["He had some sympathy for the child.","その子供にいくらか同情した。","sympathy"];
EXAMPLES[3428]=["He could manage a week's holiday.","彼はなんとか１週間の休暇を手に入れた。","manage"];
EXAMPLES[3430]=["She doesn't drive for fear of an accident.","彼女は事故を恐れて車を運転しない。","for fear of"];
EXAMPLES[3431]=["He made a speech on behalf of our company.","彼が会社を代表して演説しました。","on behalf of"];
EXAMPLES[3432]=["He resigned his post on account of illness.","彼は病気のため辞職した。","on account of"];
EXAMPLES[3433]=["I don't like artificial flowers.","私は造花が好きではない。","artificial"];
EXAMPLES[3435]=["What are the measures of times?","時間の単位は何か。","measures"];
EXAMPLES[3437]=["What has become of him since then?","彼はそれからどうなりましたか。","since then"];
EXAMPLES[3440]=["The desk is made of wood.","その机は木製である。","made of"];
EXAMPLES[3441]=["I telephoned to make sure that he was coming.","彼が来ることを確かめるために電話をした。","make sure"];
EXAMPLES[3442]=["I can't tolerate this noise any longer.","この騒音にはもう我慢することができません。","tolerate"];
EXAMPLES[3443]=["When will you go on a journey?","いつ旅行においでになりますか。","journey"];
EXAMPLES[3444]=["They don't get along together.","二人の間がしっくり行かない。","get along"];
EXAMPLES[3445]=["Keep up with the times.","時代に遅れないように。","Keep up with"];
EXAMPLES[3449]=["She was embarrassed at what she had said.","彼女は自分が言ってしまったことに困惑した。","embarrassed"];
EXAMPLES[3451]=["That's a brilliant idea.","それはすばらしい考えですね。","brilliant"];
EXAMPLES[3453]=["We had frequent snowfalls last year.","去年はよく雪が降った。","frequent"];
EXAMPLES[3455]=["How did you come by those rare books?","あの珍本をどうやって手に入れたのですか。","rare"];
EXAMPLES[3456]=["May we know your bank account?","あなたの銀行口座を教えていただけますか。","bank account"];
EXAMPLES[3457]=["The school is located on a hill.","その学校は丘の上にある。","located"];
EXAMPLES[3458]=["What you have said doesn't apply to you.","君の今言ったことは、君にあてはまらない。","apply to"];
EXAMPLES[3461]=["Make another appointment at the front desk.","次の予約の日を受付で決めてください。","appointment"];
EXAMPLES[3462]=["She used to live in luxury.","彼女は昔、豪勢な生活をしたものだ。","luxury"];
EXAMPLES[3464]=["There is no means to get in touch with him.","彼に連絡をとる手段が何もない。","in touch"];
EXAMPLES[3465]=["The children tried to imitate their teacher.","子供たちは先生のまねをしようとした。","imitate"];
EXAMPLES[3466]=["The assignment was too much for me.","その宿題は私の手には負えなかった。","assignment"];
EXAMPLES[3468]=["He is capable of running a mile in four minutes.","彼は４分で１マイル走ることができる。","capable of"];
EXAMPLES[3469]=["Let's try to arrange something.","何とか手配してあげましょう。","arrange"];
EXAMPLES[3470]=["Which of your parents do you take after?","あなたはご両親のどちらに似ていますか。","take after"];
EXAMPLES[3471]=["He was guilty of making a mistake.","彼は間違いを犯していた。","guilty of"];
EXAMPLES[3472]=["He likes to work out the difficult questions.","彼は難問を解くのが好きだ。","work out"];
EXAMPLES[3473]=["Which of the composers do you like best?","作曲家の中では誰が一番好きですか。","composers"];
EXAMPLES[3474]=["There is little furniture in my house.","私の家には家具がほとんどない。","furniture"];
EXAMPLES[3475]=["My explanation was not sufficient.","私の説明不足でした。","sufficient"];
EXAMPLES[3476]=["They could barely make ends meet.","彼らは生きていくのがやっとだった。","barely"];
EXAMPLES[3478]=["I have an urgent matter to attend to.","急いでする事がある。","urgent"];
EXAMPLES[3479]=["They are generous with their money.","彼らは金離れがよい。","generous"];
EXAMPLES[3480]=["You ought not to be cruel to animals.","動物に対してむごいことをしてはいけない。","cruel"];
EXAMPLES[3482]=["She is a reflection of her mother.","彼女は母親にそっくりだ。","reflection"];
EXAMPLES[3483]=["She spoke to me in a whisper.","彼女は私に小声で話した。","whisper"];
EXAMPLES[3484]=["Please deposit the money in a bank.","銀行にそのお金を預けてください。","deposit"];
EXAMPLES[3485]=["I must make an apology to her.","私は彼女に謝らなければならない。","apology"];
EXAMPLES[3486]=["He is the last man to deceive me.","彼は決して私をだますような人間ではない。","deceive"];
EXAMPLES[3487]=["I can't endure the noise.","その騒音に我慢できない。","endure"];
EXAMPLES[3488]=["I put my car at his disposal.","私の車を彼に自由に使わせた。","disposal"];
EXAMPLES[3490]=["Where is the bus terminal?","バスターミナルはどこですか。","terminal"];
EXAMPLES[3492]=["He cut the envelope open.","彼は封筒を切って開けた。","envelope"];
EXAMPLES[3493]=["It takes two to make a quarrel.","けんかをするには二人の人間が必要だ。","quarrel"];
EXAMPLES[3494]=["My uncle comes to see me from time to time.","私のおじはときどき私を訪ねて来る。","from time to time"];
EXAMPLES[3497]=["In the meantime, he went to sleep.","そうしているうちに彼は眠ってしまった。","In the meantime"];
EXAMPLES[3498]=["What he says is true to some extent.","彼の言っていることはある程度本当である。","to some extent"];
EXAMPLES[3499]=["We must prevent war at any cost.","何としても戦争は防がねばならない。","at any cost"];
EXAMPLES[3501]=["You really made me lose face.","よくも顔をつぶしてくれたな。","lose face"];
EXAMPLES[3502]=["If you use the money, you will have to answer for it later.","そのお金を使うなら後で責任を持てよ。","answer for"];
EXAMPLES[3503]=["If you insist on going alone, please do so.","あなたがあえて一人で行きたいならどうぞ。","insist on"];
EXAMPLES[3504]=["Tom and I have nothing in common.","トムと私は共通したところが何もない。","in common"];
EXAMPLES[3506]=["Luckily, he found a good seat.","運良く彼はいい席を見つけた。","Luckily"];
EXAMPLES[3507]=["Tom is not yet able to swim.","トムはまだ泳げない。","not yet"];
EXAMPLES[3512]=["Are you related to him?","あなたは彼と親戚ですか。","related to"];
EXAMPLES[3513]=["She is as active as she looks.","見かけ通り彼女は行動力がある。","active"];
EXAMPLES[3516]=["The room was in disorder.","その部屋は騒然としていた。","disorder"];
EXAMPLES[3518]=["For the time being, I intend to stay at a hotel.","私は当分ホテルにいるつもりです。","intend to"];
EXAMPLES[3519]=["Everything is going well at present.","今のところ、すべてうまくいっている。","at present"];
EXAMPLES[3520]=["I came to the realization too late to make a difference.","違いが分かるには遅すぎた。","make a difference"];
EXAMPLES[3522]=["He was so kind as to show me around the town.","彼は親切にも私に町を案内してくれた。","as to"];
EXAMPLES[3523]=["The old bridge is in danger of collapse.","その古い橋は今にも崩れ落ちそうだ。","collapse"];
EXAMPLES[3524]=["It is an insult to her.","それは彼女に対する屈辱だ。","insult"];
EXAMPLES[3525]=["The village was isolated by the heavy storm.","その村はひどい嵐によって孤立した。","isolated"];
EXAMPLES[3526]=["She is always punctual in coming.","彼女はいつも遅れずに来る。","punctual"];
EXAMPLES[3527]=["No one's frightened of playing it.","誰ひとり気づいていない。","frightened"];
EXAMPLES[3528]=["Who can guarantee his success?","彼が成功するとだれが保証できようか。","guarantee"];
EXAMPLES[3529]=["It is you who is to blame.","悪いのはきみのほうだ。","blame"];
EXAMPLES[3531]=["We ask you to account for your delay.","遅れたわけを説明してもらいたい。","delay"];
EXAMPLES[3534]=["Strangely enough, he failed.","不思議なことに彼は失敗した。","Strangely"];
EXAMPLES[3535]=["The young girl was chased by the old man.","若い女性はその老人に追いかけられる。","chased"];
EXAMPLES[3536]=["Please pour me a little tea.","私にお茶を少し注いで下さい。","pour"];
EXAMPLES[3537]=["I saw him at one time or another.","以前彼に会ったことがある。","at one time"];
EXAMPLES[3538]=["I appreciate your coming all the way.","はるばる来ていただいてありがとうございます。","all the way"];
EXAMPLES[3541]=["For what purpose did you break into the house?","どんな目的で君はその家に侵入したのですか。","break into"];
EXAMPLES[3542]=["I'm afraid I'll have to call it a day.","残念ながら今日はこれで終わりにします。","call it a day"];
EXAMPLES[3546]=["I stayed indoors because it rained.","雨が降っていたので家の中にいた。","indoors"];
EXAMPLES[3548]=["I want specific information.","具体的に話して欲しい。","specific"];
EXAMPLES[3555]=["He is young and, what is more, handsome.","彼は若いし、おまけに、二枚目だ。","what is more"];
EXAMPLES[3556]=["Would you mind my staying here for some time?","しばらくここにいてもいいですか。","for some time"];
EXAMPLES[3557]=["He carried six boxes at a time.","彼は一度に６個の箱を運んだ。","at a time"];
EXAMPLES[3559]=["This book is still copyrighted.","この本はまだ版権が生きている。","copyrighted"];
EXAMPLES[3560]=["I want to see the director of the company.","私は社長に会いたいのです。","director"];
EXAMPLES[3564]=["Take care not to throw away this chance.","この機会を無駄にしないように気を付けよ。","throw away"];
EXAMPLES[3568]=["The doctor told him to cut down on smoking.","医者は彼に煙草を減らすように言った。","cut down on"];
EXAMPLES[3569]=["What is the harm in doing that?","それをして何が悪いのか。","harm"];
EXAMPLES[3571]=["No woman is as arrogant as she is.","彼女ほど傲慢な女性はいない。","arrogant"];
EXAMPLES[3572]=["The ship is now in the harbor.","その船は今港にいる。","harbor"];
EXAMPLES[3573]=["I'm sometimes in a bad temper.","私は時々機嫌が悪くなる。","temper"];
EXAMPLES[3574]=["That story is household legend.","その話は誰でも知っている有名な話だ。","legend"];
EXAMPLES[3575]=["She gave us a vague answer.","彼女は私たちにあいまいな返事をした。","vague"];
EXAMPLES[3577]=["The town fell into ruin.","その町は廃墟となった。","ruin"];
EXAMPLES[3578]=["He launched his son in the world.","息子を世間に出した。","launched"];
EXAMPLES[3579]=["The president refused to answer the question.","大統領はその質問に答えることを拒否した。","refused"];
EXAMPLES[3580]=["If you hurry, you will overtake him.","もし急ぐならば、あなたは彼に追い付くでしょう。","overtake"];
EXAMPLES[3582]=["Bill has stock in that company.","ビルはあの会社の株を持っている。","stock"];
EXAMPLES[3587]=["You should concentrate on the road when you're driving.","運転している時は、道路に集中すべきだ。","concentrate on"];
EXAMPLES[3588]=["You may laugh at me.","君は私を笑うかもしれない。","laugh at"];
EXAMPLES[3589]=["She is well off now.","彼女は今裕福である。","well off"];
EXAMPLES[3590]=["Go straight on, and you will find the store.","まっすぐ行きなさい。そうすれば店が見えます。","straight on"];
EXAMPLES[3592]=["He is not equal to his father.","彼は父親には及ばない。","equal"];
EXAMPLES[3593]=["Can I drop off the car?","乗り捨てる事ができますか。","drop off"];
EXAMPLES[3594]=["Leave out anything that is useless.","役に立たないものは省きなさい。","Leave out"];
EXAMPLES[3595]=["I know one of them but not the other.","一方は知っているが他方は知らない。","the other"];
EXAMPLES[3597]=["There were hundreds of cars on the street.","通りには何百もの車があった。","hundreds of"];
EXAMPLES[3599]=["I'll be no party to this arrangement.","この取り決めには関係したくない。","arrangement"];
EXAMPLES[3602]=["You will do well to take my advice.","私の忠告を聞いた方がいい。","do well"];
EXAMPLES[3603]=["I'm sorry for the short deadline.","締め切りまでにあまり時間が無くてすいません？","deadline"];
EXAMPLES[3606]=["A lot of funds are necessary to travel.","たくさんの資金は旅行のために必要です。","funds"];
EXAMPLES[3607]=["That cost me a lot in the long run.","その買い物は結局高くついた。","in the long run"];
EXAMPLES[3612]=["It's making a great stir.","大変評判になっている。","stir"];
EXAMPLES[3616]=["The hotel has a good prospect.","そのホテルは見晴らしがよい。","prospect"];
EXAMPLES[3617]=["I wonder if she will marry him.","彼女は彼と結婚するのかなあ。","marry"];
EXAMPLES[3618]=["You're really a hard worker.","君はよくがんばるね。","worker"];
EXAMPLES[3622]=["We bought a pound of tea.","我々はお茶を一ポンド買った。","pound"];
EXAMPLES[3623]=["Such a problem is hard to deal with.","このような問題は扱いにくい。","deal with"];
EXAMPLES[3624]=["Carelessness often result in accidents.","不注意が事故になることが多い。","result in"];
EXAMPLES[3625]=["He no longer lives here.","彼はもはやここに住んでいない。","no longer"];
EXAMPLES[3626]=["For a while she did nothing but stare at me.","彼女はしばらくは私を見つめてばかりいた。","stare at"];
EXAMPLES[3627]=["I am in charge of this.","これは、私の担当だ。","in charge of"];
EXAMPLES[3628]=["What does the company produce?","その会社は何を作っているのですか。","produce"];
EXAMPLES[3629]=["This computer can cope with much work.","このコンピューターは多くの仕事に対処できる。","cope with"];
EXAMPLES[3630]=["She didn't show up.","彼女は来なかった。","show up"];
EXAMPLES[3632]=["You should carry out his offer.","君は最初の計画を実行すべきだ。","carry out"];
EXAMPLES[3633]=["I paid him the money due to him.","私は彼に支払うべき金を払った。","due to"];
EXAMPLES[3634]=["Please defend me from such bad men.","どうかあのような悪人から私を守ってください。","defend"];
EXAMPLES[3635]=["This table is at an angle.","このテーブルは傾いている。","angle"];
EXAMPLES[3637]=["I will look into the matter.","その件については確認します。","look into"];
EXAMPLES[3638]=["Our idea did not work in practice.","私たちの考えは実際には役に立たなかった。","in practice"];
EXAMPLES[3639]=["The plane arrived at new york on schedule.","飛行機は定刻にニューヨークについた。","on schedule"];
EXAMPLES[3642]=["He went on talking as though nothing had happened.","彼は何事もなかったかのように話し続けた。","as though"];
EXAMPLES[3643]=["She may well be pleased with the success.","彼女がその成功を喜ぶものももっともだ。","be pleased with"];
EXAMPLES[3644]=["The game was postponed due to rain.","試合が雨で延期した。","postponed"];
EXAMPLES[3645]=["The end justifies the means.","結果良ければすべて良し。","justifies"];
EXAMPLES[3646]=["You must fulfill your promise without fail.","あなたは必ず約束を果たさなければならない。","fulfill"];
EXAMPLES[3650]=["That's it for your medical exam.","診察は以上です。","medical"];
EXAMPLES[3657]=["She put away her clothes.","彼女は服を片付けた。","put away"];
EXAMPLES[3659]=["The participants were for the most part women.","参加者の大部分は女性だった。","participants"];
EXAMPLES[3663]=["He is anything but a reliable man.","彼は決して信頼できる男ではない。","reliable"];
EXAMPLES[3664]=["In other words, I don't like to work with him.","言い換えれば、私は彼と働きたくない。","In other words"];
EXAMPLES[3665]=["I have been associated with him for ten years.","私は彼と１０年間つきあっている。","associated with"];
EXAMPLES[3666]=["To start with, I want to thank you all.","初めに、みなさんに感謝します。","To start with"];
EXAMPLES[3667]=["First of all, may I have your name, please?","まず、最初にお名前をお聞かせ下さい。","First of all"];
EXAMPLES[3668]=["Congratulations on being accepted to the school you've always wanted to go to.","行きたい学校に入れてよかったね。","Congratulations on"];
EXAMPLES[3669]=["Nothing is as precious as love.","愛より尊い物はない。","precious"];
EXAMPLES[3672]=["I congratulate you on your success.","私はあなたの成功を祝福しなければならない。","congratulate"];
EXAMPLES[3673]=["I'll give you a check-up.","診察しましょう。","check"];
EXAMPLES[3676]=["Not having a telephone is an inconvenience.","電話がないのは不便なことだ。","inconvenience"];
EXAMPLES[3682]=["I don't want to be involved in that matter.","私はその問題に巻き込まれたくない。","be involved in"];
EXAMPLES[3685]=["What did you major in at college?","あなたは大学で何を専攻されましたか。","major"];
EXAMPLES[3689]=["The policeman was rather abrupt with me.","その警官は私に対してかなりぞんざいだった。","abrupt"];
EXAMPLES[3690]=["Jane is familiar with the Japanese language.","ジェーンは日本語に精通している。","familiar"];
EXAMPLES[3692]=["You're going to get much publicity with this book.","この本で、君はかなり評判になるよ。","publicity"];
EXAMPLES[3695]=["The teacher will illustrate how to do it.","先生がそのやり方を説明するだろう。","illustrate"];
EXAMPLES[3699]=["I could live peacefully here.","ここでなら平和に暮らせるだろう。","peacefully"];
EXAMPLES[3701]=["He went on a voyage to America.","彼はアメリカに向かって航海にでた。","voyage"];
EXAMPLES[3702]=["He was the envy of his friends.","彼は友人たちの羨望の的であった。","envy"];
EXAMPLES[3703]=["You are exaggerating the problem.","あなたは問題を大袈裟に考えている。","exaggerating"];
EXAMPLES[3704]=["We refer to this city as little Kyoto.","我々はこの町を小京都と呼ぶ。","refer to"];
EXAMPLES[3705]=["Not worth speaking of.","言葉にすることさえ虚しい。","speaking of"];
EXAMPLES[3706]=["I was in trouble with the police last night.","私は昨晩警察といざこざを起こした。","in trouble"];
EXAMPLES[3707]=["At best I can do only half of what you did.","私にはせいぜいあなたの半分しか出来ない。","At best"];
EXAMPLES[3708]=["Except for one person, everybody went home.","一人を除いてみんな帰った。","Except for"];
EXAMPLES[3710]=["This dress was in fashion in those days.","このドレスはあのころは流行していた。","in fashion"];
EXAMPLES[3712]=["What transportation will we take?","交通機関は何を使うんですか。","transportation"];
EXAMPLES[3714]=["I couldn't recognize him at first.","わたしは始めは彼が誰なのかわからなかった。","recognize"];
EXAMPLES[3718]=["An unexpected result was arrived at.","予期しない結果に達した。","unexpected"];
EXAMPLES[3719]=["I can't stand humidity.","私は湿気が我慢できない。","humidity"];
EXAMPLES[3720]=["The policeman was on duty on that day.","その警官は、その日は当直であった。","on duty"];
EXAMPLES[3721]=["That bridge has been out of use for a long time.","その橋は長い間使われていない。","out of use"];
EXAMPLES[3722]=["She is very exact in her job.","彼女は仕事が非常にきちょうめんだ。","exact"];
EXAMPLES[3723]=["Such behavior may bring about an accident.","そのような行動が事故を引き起こすかもしれない。","bring about"];
EXAMPLES[3724]=["She has been ill for three weeks.","彼女が病気になってから３週間だ。","ill"];
EXAMPLES[3725]=["Your remarks were rather out of place.","あなたが言ったことは、かなり場違いでした。","out of place"];
EXAMPLES[3726]=["He is my only living relative.","彼は私の生きているただ一人の親類だ。","relative"];
EXAMPLES[3727]=["This fish is free from poison.","この魚は毒がない。","poison"];
EXAMPLES[3731]=["He dedicated his life to peace.","彼は平和のため一生を捧げた。","dedicated"];
EXAMPLES[3732]=["He amused us with a funny story.","彼はおもしろい話で私達を楽しませた。","amused"];
EXAMPLES[3733]=["The subject is out of one's sphere.","自分の領域外にある。","sphere"];
EXAMPLES[3734]=["I will take my revenge on him.","私は彼に報復するつもりだ。","revenge"];
EXAMPLES[3735]=["The police are suspicious of the old man.","警察はその老人を疑っている。","suspicious"];
EXAMPLES[3736]=["He was delicate as a child.","彼は子供の頃体が弱かった。","delicate"];
EXAMPLES[3737]=["We did everything for the welfare of our children.","私たちは子供の幸福のためにあらゆることをした。","welfare"];
EXAMPLES[3738]=["May I interrupt you a while?","ちょっとお話の邪魔をしてもよいですか。","interrupt"];
EXAMPLES[3740]=["You cannot substitute money for health.","お金は健康の代わりにはならない。","substitute"];
EXAMPLES[3742]=["Thank you very much for your hospitality.","お邪魔しました。","hospitality"];
EXAMPLES[3743]=["The tragedy happened suddenly.","悲劇は突然起こった。","tragedy"];
EXAMPLES[3745]=["He instructed students in history at school.","彼は学校で歴史を教えていた。","instructed"];
EXAMPLES[3746]=["Soon you'll get used to living by yourself.","すぐに一人住まいに慣れますよ。","get used to"];
EXAMPLES[3747]=["This machine is now out of date.","この機械はもう時代遅れだ。","out of date"];
EXAMPLES[3750]=["When did life come into being?","生命はいつ誕生したのですか。","come into being"];
EXAMPLES[3751]=["You are in need of a holiday.","君は休暇が必要だ。","in need of"];
EXAMPLES[3752]=["I was at a loss for words.","私は言葉に詰まった。","at a loss"];
EXAMPLES[3754]=["The students missed class three times in a row.","その学生達は続けて３回授業に出席しなかった。","in a row"];
EXAMPLES[3762]=["A young child has a small vocabulary.","幼い子供は語いが少ない。","vocabulary"];
EXAMPLES[3767]=["He commutes to his office by bus.","彼はバスで会社に通っている。","commutes"];
EXAMPLES[3768]=["He mentioned the incident to his wife.","彼はその事件のことを妻に話した。","incident"];
EXAMPLES[3769]=["We yelled at her to take care.","私達は彼女に気をつけるように叫んだ。","yelled"];
EXAMPLES[3770]=["I sneeze a lot.","よくくしゃみが出ます。","sneeze"];
EXAMPLES[3772]=["You could try and be a bit more civilized.","もうちょっと上品にできないの。","civilized"];
EXAMPLES[3773]=["He always imposes his opinion on me.","彼はいつも私に彼の意見を押し付けます。","imposes"];
EXAMPLES[3776]=["Did you acquaint him with the fact?","彼にその事実を知らせたか。","acquaint"];
EXAMPLES[3780]=["He sees everything in terms of money.","彼はすべてをお金で考える。","in terms of"];
EXAMPLES[3781]=["It's going to rain, for sure.","きっと雨が降るだろう。","for sure"];
EXAMPLES[3782]=["I arrived just in time for the plane.","私は飛行機にちょうど間に合った。","in time"];
EXAMPLES[3783]=["I have no objection to your plan.","私はあなたの計画に反対はありません。","objection"];
EXAMPLES[3785]=["Do you have adequate money for the trip?","旅行に十分なお金がありますか。","adequate"];
EXAMPLES[3787]=["Will I have a scar?","傷あとが残りますか。","scar"];
EXAMPLES[3789]=["The supplies will give out soon.","補給がまもなく不足するでしょう。","give out"];
EXAMPLES[3790]=["Can you prove it?","それを証明できますわ？","prove"];
EXAMPLES[3791]=["What's the name of your insurance company?","保険の名前は何ですか。","insurance"];
EXAMPLES[3792]=["Those men are of a generation.","あの人たちは同じ世代です。","generation"];
EXAMPLES[3793]=["She tried to take down every word the teacher said.","彼女は先生の言う言葉をすべて書き留めようとした。","take down"];
EXAMPLES[3794]=["He was irritated by the sound.","彼はその音にいらいらしている。","irritated"];
EXAMPLES[3795]=["All the money put together still won't be enough.","お金を全部合わしても足りないだろう。","put together"];
EXAMPLES[3796]=["The student failed to account for the mistake.","その学生はまちがいの理由を説明することができなかった。","account for"];
EXAMPLES[3798]=["I commit my son to your care.","息子はあなたにおまかせする。","commit"];
EXAMPLES[3799]=["We decided to put off the meeting until next Sunday.","私達は会合を次の日曜まで延期することに決めた。","put off"];
EXAMPLES[3801]=["We differ from them in some respects.","われわれはいくつかの点で彼らと違う。","differ"];
EXAMPLES[3802]=["Will the fine weather keep up till tomorrow?","この天気は明日までもちますか。","keep up"];
EXAMPLES[3803]=["You can get a better look over here.","ここならもっとよく見えるよ。","look over"];
EXAMPLES[3806]=["My mother is a psychology teacher.","私の母は心理学の先生である。","psychology"];
EXAMPLES[3807]=["I have a cough.","せきが出ます。","cough"];
EXAMPLES[3808]=["I sincerely hope for their happiness.","私は彼らの幸福を心から願っています。","sincerely"];
EXAMPLES[3811]=["The man finally confessed what he had done.","その男はついに自分のしたことを白状した。","confessed"];
EXAMPLES[3812]=["Could you make a reservation for me?","ここで予約をしてもらえますか。","reservation"];
EXAMPLES[3814]=["Not being tall isn't a disadvantage.","背が高くないことは不利ではない。","disadvantage"];
EXAMPLES[3817]=["Please tell me your location.","場所を教えてください。","location"];
EXAMPLES[3818]=["You can't live without oxygen.","酸素が無ければ生きられない。","oxygen"];
EXAMPLES[3819]=["We should do away with these old rules.","この古い規則は廃止すべきだ。","do away with"];
EXAMPLES[3820]=["Don't neglect your business.","仕事を怠ってはいけない。","neglect"];
EXAMPLES[3823]=["Do not touch the exhibits.","陳列品に手を出すな。","exhibits"];
EXAMPLES[3824]=["He has just become a principal.","彼は校長になり立てだ。","principal"];
EXAMPLES[3826]=["In short, he was too honest.","要するに、彼はあまりにも正直すぎた。","In short"];
EXAMPLES[3827]=["Finally, he gave in to my persuasion.","ついに、彼は私の説得に成功した。","persuasion"];
EXAMPLES[3829]=["His view is quite logical.","彼の意見はたいへん論理的である。","logical"];
EXAMPLES[3832]=["Can I use the laundry any time?","洗濯はいつやってもいいですか。","laundry"];
EXAMPLES[3833]=["As for me, I have nothing to complain of.","私はどうかといえば何も不平はない。","complain of"];
EXAMPLES[3839]=["You should drink a lot of liquid.","水分をたくさん取ってください。","liquid"];
EXAMPLES[3841]=["What a ridiculous opinion that is!","それはなんてばかげた意見なのだろう！","ridiculous"];
EXAMPLES[3843]=["You are to blame for the accident.","その事故では君が悪いのだ。","blame for"];
EXAMPLES[3846]=["A cat can see in the dark.","猫は闇で物が見える。","see in"];
EXAMPLES[3848]=["It is terribly hot this morning.","今朝はひどく暑い。","terribly"];
EXAMPLES[3849]=["What do you want to go after you finish college?","大学を卒業したあとはどうしたいのですか。","go after"];
EXAMPLES[3850]=["She is kind by nature.","彼女は生まれつき親切である。","by nature"];
EXAMPLES[3851]=["How astonished I was to see this.","これを見たときの私の驚きといったら。","astonished"];
EXAMPLES[3852]=["Please don't distract me from my work.","仕事の邪魔をしないでください。","distract"];
EXAMPLES[3853]=["Let me go in place of him.","彼のかわりにぼくに行かせて下さい。","in place"];
EXAMPLES[3855]=["How do you figure out this problem?","どうやってこの問題を解くのですか。","figure"];
EXAMPLES[3856]=["His speech inspired all the boys.","彼の話は少年たちみんなを元気づけた。","inspired"];
EXAMPLES[3858]=["He lives in the suburbs of Tokyo.","彼は東京近郊に住んでいる。","suburbs"];
EXAMPLES[3859]=["The talk dragged on till three o'clock.","話は三時までだらだらと続いた。","dragged"];
EXAMPLES[3861]=["My cat has come out from under the table.","私の猫がテーブルの下から出てきた。","come out"];
EXAMPLES[3862]=["There was a tremble in her voice.","彼女の声は震えていた。","tremble"];
EXAMPLES[3864]=["Did you come across anyone you know on your way here?","ここへくる途中で誰か知り合いに会いましたか。","come across"];
EXAMPLES[3867]=["My father was deaf to our opinions.","父は私たちの意見に耳を貸さなかった。","deaf"];
EXAMPLES[3869]=["This train is bound for Tokyo.","この列車は東京行きです。","bound for"];
EXAMPLES[3871]=["He delivered a very long speech yesterday.","昨日彼はとても長いスピーチをした。","delivered"];
EXAMPLES[3873]=["This is a tropical storm. it'll be over soon.","通り雨だからすぐ止むよ。","tropical"];
EXAMPLES[3874]=["I'll act on your advice.","ご忠告に従います。","act on"];
EXAMPLES[3876]=["The party was not altogether pleasant.","そのパーティーが何から何まで楽しかったわけではない。","altogether"];
EXAMPLES[3878]=["She explained her idea by means of pictures.","彼女は自分の考えを絵によって説明した。","by means of"];
EXAMPLES[3879]=["I insist on your being present.","私はあなたにぜひ出席してもらいたい。","insist"];
EXAMPLES[3881]=["You should persist in your efforts to learn English.","あなたは英語を学ぶ努力をずっと続けるべきです。","persist in"];
EXAMPLES[3882]=["She tried in vain to please him.","彼女は彼を喜ばそうとしたが無駄だった。","in vain"];
EXAMPLES[3883]=["Are you off duty tonight?","今夜は非番ですか。","off duty"];
EXAMPLES[3884]=["The Japanese live on rice.","日本人は米を食べて生きている。","live on"];
EXAMPLES[3886]=["I expect that he will help us.","彼が我々を援助してくれると思います。","expect"];
EXAMPLES[3889]=["They decided to pull down the old building.","古い建物を取り壊すことに決めた。","pull down"];
EXAMPLES[3890]=["It's my business to investigate such things.","そのような事を調査するのが私の仕事だ。","investigate"];
EXAMPLES[3891]=["The beauty of the lake is beyond description.","その湖の美しさは言葉に表せない。","description"];
EXAMPLES[3892]=["The results were as follows.","結果は次の通りだった。","as follows"];
EXAMPLES[3893]=["It is not right to put a man to death for punishment.","人を死刑にするのは正しいことではない。","punishment"];
EXAMPLES[3894]=["The ship went up in flames.","船が炎上した。","flames"];
EXAMPLES[3895]=["Please send an ambulance.","救急車を呼んでください。","ambulance"];
EXAMPLES[3896]=["It was impossible to find an answer.","答えを見つけるのは不可能だった。","impossible"];
EXAMPLES[3898]=["We were in danger of losing our lives.","私たちは命を失う危険が有った。","in danger of"];
EXAMPLES[3899]=["All the boys spoke each in turn.","少年たちは順々にしゃべった。","in turn"];
EXAMPLES[3901]=["Do you look up to your parents?","あなたは両親を尊敬していますか。","look up to"];
EXAMPLES[3902]=["It'll add to the same thing.","結局は同じ事になるだろう。","add to"];
EXAMPLES[3904]=["She tried in vain to please him.","彼女は彼を喜ばそうとしたが無駄だった。","vain"];
EXAMPLES[3905]=["You have to make up the time you have lost.","失った時間を取り返さなければならない。","make up"];
EXAMPLES[3906]=["Every mother has affection for her child.","すべての母は子に愛情を持っている。","affection"];
EXAMPLES[3907]=["I could recite the story by heart.","私はその話を暗唱することができた。","by heart"];
EXAMPLES[3909]=["Need I go to the dentist's?","私は歯医者さんに行く必要がありますか。","dentist"];
EXAMPLES[3910]=["The boy is clinging to his mother.","その男の子は母親にしがみついている。","clinging"];
EXAMPLES[3912]=["Let me relieve you of your baggage.","あなたの荷物を持たせて下さい。","relieve"];
EXAMPLES[3914]=["The plan is not mature.","その計画は熟していない。","mature"];
EXAMPLES[3917]=["Don't carry anything to excess.","何事もやりすぎてはいけない。","excess"];
EXAMPLES[3919]=["He seems to live in harmony with all his friends.","彼はすべての友達と仲良くやってるようだ。","harmony"];
EXAMPLES[3921]=["How do you assess your students?","あなたはどのようにして学生を評価しますか。","assess"];
EXAMPLES[3924]=["They were kind enough to assist us.","彼らは親切にも我々を援助してくれた。","assist"];
EXAMPLES[3925]=["I can ensure a job for you.","私はあなたに仕事を確保できる。","ensure"];
EXAMPLES[3926]=["I don't have any classical music.","クラシックはありません。","classical"];
EXAMPLES[3927]=["He tried to hold back his anger.","彼は怒りを見せまいとした。","anger"];
EXAMPLES[3928]=["He is a man of virtue.","彼は美徳の人です。","virtue"];
EXAMPLES[3929]=["Could you take me to this seat?","この席まで案内してくれますか。","seat"];
EXAMPLES[3930]=["Most Japanese drink water from the tap.","たいていの日本人は水道の水を飲みます。","tap"];
EXAMPLES[3932]=["The committee are all for the plan.","委員は全員その計画に賛成である。","committee"];
EXAMPLES[3933]=["Could you take me to the grand hotel?","グランドホテルまで、行ってください。","grand"];
EXAMPLES[3934]=["We made the boy our guide.","私達はその少年をガイドにした。","guide"];
EXAMPLES[3936]=["Please don't interfere with my plan.","私の計画に横やりを入れないでください。","interfere"];
EXAMPLES[3937]=["Their patience was about to give out.","彼らの我慢も限界だった。","patience"];
EXAMPLES[3940]=["The mother was practically worn out.","母親はひどく疲れていた。","practically"];
EXAMPLES[3942]=["What was his motive for doing it?","彼はそれをした動機は何だったのだろう。","motive"];
EXAMPLES[3943]=["The job will take a minimum of ten days.","その仕事は最小限１０日はかかるだろう。","minimum"];
EXAMPLES[3945]=["Technically he is still a student.","規則の上では彼はまだ学生だ。","Technically"];
EXAMPLES[3949]=["Look before you leap.","飛ぶ前に見よ。","leap"];
EXAMPLES[3950]=["Not all the candidates can pass the examination.","志望者全員が試験に合格できるわけではない。","candidates"];
EXAMPLES[3951]=["The dream was a mystery to me.","その夢は私には神秘だった。","mystery"];
EXAMPLES[3952]=["He said that with dignity.","彼はそれを威厳をもって言った。","dignity"];
EXAMPLES[3953]=["It is rude of you to say so.","そんなことを言うのは失礼だ。","rude"];
EXAMPLES[3955]=["Let's tip a few tonight.","今晩少し飲まないか。","tip"];
EXAMPLES[3956]=["Why did you use up all the money?","君はなぜお金を使い果たしたのか。","use up"];
EXAMPLES[3957]=["She asked him to adjust the tv set.","彼女はテレビの調節を彼に頼んだ。","adjust"];
EXAMPLES[3959]=["Don't spoil your child.","子供を甘やかすな。","spoil"];
EXAMPLES[3960]=["There are few mistakes in your composition.","君の作文にはほとんど間違いはありません。","composition"];
EXAMPLES[3961]=["Tom has many talents.","トムには多くの才能がある。","talents"];
EXAMPLES[3963]=["Who is ultimately responsible for this?","この責任は結局だれにあるのか。","ultimately"];
EXAMPLES[3966]=["I was exhausted from work.","私は仕事で疲れ果てた。","exhausted"];
EXAMPLES[3967]=["She is a twin.","彼女は双子です。","twin"];
EXAMPLES[3968]=["We must deal with the problem instantly.","その問題をすぐ処理しなければならない。","instantly"];
EXAMPLES[3969]=["Do you have rain gear with you?","雨具をお持ちになりましたか。","gear"];
EXAMPLES[3970]=["Nothing is impossible to a willing heart.","やる気があれば、不可能なことはない。","willing"];
EXAMPLES[3971]=["Can you get by on your wages?","君は今の給料でやって行けるか。","wages"];
EXAMPLES[3972]=["I had an abortion two years ago.","２年前中絶しました。","abortion"];
EXAMPLES[3973]=["He is no less smart than his brother.","彼はお兄さんと同じように頭がいい。","smart"];
EXAMPLES[3974]=["They shed tears at the news.","彼らはそのニュースを聞いて涙を流した。","shed"];
EXAMPLES[3976]=["He became more and more famous as a critic.","彼は評論家として次第に有名になった。","critic"];
EXAMPLES[3977]=["My brother has been friendly to him.","弟は彼に優しくしてきた。","friendly"];
EXAMPLES[3980]=["Please connect me with Mr smith.","スミスさんにつないで下さい。","connect"];
EXAMPLES[3981]=["He made the plan along with his colleagues.","彼は同僚と一緒にその計画を作った。","colleagues"];
EXAMPLES[3982]=["He was made my servant.","彼は私の召使にさせられました。","servant"];
EXAMPLES[3984]=["The seeds will become flowers in the summer.","種子は夏になると花になる。","seeds"];
EXAMPLES[3987]=["She could not refrain from tears.","彼女は涙をこらえることが出来なかった。","refrain from"];
EXAMPLES[3989]=["We all wish for permanent world peace.","私たちはみんな恒久的な平和を願っている。","permanent"];
EXAMPLES[3991]=["I beg you forgive me.","どうか私のことをお許しください。","beg"];
EXAMPLES[3994]=["I take the liberty of going home.","悪いけれど帰ります。","liberty"];
EXAMPLES[3995]=["His house was built of logs.","彼の家は丸太でできていた。","logs"];
EXAMPLES[3996]=["This new camera is a snap to use.","このカメラは使いやすい。","snap"];
EXAMPLES[3997]=["His tale came home to me.","彼の話は身にしみた。","tale"];
EXAMPLES[3999]=["A cold confined him to his house.","風邪のため彼は家に閉じ込もっていた。","confined"];
EXAMPLES[4000]=["He took it from beneath his coat.","彼はそれを上着の下から出した。","beneath"];
EXAMPLES[4001]=["I believe she is a charming girl.","彼女は魅力的な子だと思う。","charming"];
EXAMPLES[4003]=["The explanation is by no means satisfactory.","その説明は決して満足するものではない。","satisfactory"];
EXAMPLES[4006]=["My mother worked hard in order to rear us.","母は私たちを育てるために一生懸命働いた。","rear"];
EXAMPLES[4007]=["How could I resist?","私に何ができたの？","resist"];
EXAMPLES[4008]=["He made a resolve to stop smoking.","タバコをやめようと彼は決心した。","resolve"];
EXAMPLES[4009]=["The fact is apparent to everybody.","その事実はだれにでもわかりきったことだ。","apparent"];
EXAMPLES[4012]=["She used to pray before going to bed.","彼女は寝る前に祈ったものだ。","pray"];
EXAMPLES[4013]=["There is not a ray of truth in it.","それには真実のかけらもない。","ray"];
EXAMPLES[4016]=["All at once there was an explosion.","突然爆発が起こった。","explosion"];
EXAMPLES[4017]=["This medicine will cure you of your cold.","この薬であなたの風邪はよくなるでしょう。","cure"];
EXAMPLES[4018]=["The news had an impact on him.","そのニュースは彼に影響を与えた。","impact"];
EXAMPLES[4019]=["I'm studying economics at university.","私は大学で経済学を勉強しています。","economics"];
EXAMPLES[4020]=["Every pupil in the class is present.","クラスの中のどの生徒もみな出席している。","pupil"];
EXAMPLES[4021]=["There's something unusual about him.","彼にはどこか、変わった所がある。","unusual"];
EXAMPLES[4025]=["They have mutual respect.","彼らは互いに尊敬しあっている。","mutual"];
EXAMPLES[4026]=["He was guilty of making a mistake.","彼は間違いを犯していた。","guilty"];
EXAMPLES[4027]=["We were fascinated by her voice.","彼女の声にうっとりとした。","fascinated"];
EXAMPLES[4028]=["Could you say that in plain English?","易しい英語で言ってください。","plain"];
EXAMPLES[4029]=["I stretched out my hand for the book.","私はその本を取ろうと手を伸ばした。","stretched"];
EXAMPLES[4031]=["I had her sweep my room.","彼女が私の部屋を掃除する。","sweep"];
EXAMPLES[4033]=["He is an aggressive person.","彼は喧嘩早い人だ。","aggressive"];
EXAMPLES[4035]=["This is by no means easy reading.","これは決してやさしい読み物ではない。","means"];
EXAMPLES[4036]=["Tom always makes fun of John because of his dialect.","トムはいつもジョンの言葉のなまりを理由にからかう。","dialect"];
EXAMPLES[4037]=["What do you call this insect in English?","英語でこの昆虫を何といいますか。","insect"];
EXAMPLES[4042]=["This is a plan of my own devising.","これは私が工夫した計画です。","devising"];
EXAMPLES[4046]=["It was a relief to hear the news.","その知らせを聞いて安心した。","relief"];
EXAMPLES[4047]=["My worst vice is smoking.","私の最も悪い習慣はタバコを吸うことです。","vice"];
EXAMPLES[4048]=["I travel to all parts of the globe.","私は世界中を旅行する。","globe"];
EXAMPLES[4049]=["Have you ever read the constitution of Japan?","日本国憲法を読んだことがありますか。","constitution"];
EXAMPLES[4050]=["It is essentially a question of time.","それは本質的に時間の問題だ。","essentially"];
EXAMPLES[4051]=["She selected a hat to match her new dress.","彼女は新しいドレスに合う帽子を選んだ。","selected"];
EXAMPLES[4054]=["I don't understand this novel's plot.","その小説の筋はわからない。","plot"];
EXAMPLES[4058]=["That cat has beautiful fur.","あの猫の毛はとてもきれいだ。","fur"];
EXAMPLES[4063]=["The man's behavior was very odd.","その男の行動はとても変だった。","odd"];
EXAMPLES[4067]=["There were a great many people present at the assembly.","その集会に多くの人が出席した。","assembly"];
EXAMPLES[4068]=["You have got a lot of nerve.","度胸があるな。","nerve"];
EXAMPLES[4070]=["He's depressed about the result.","彼はその結果に気落ちしている。","depressed"];
EXAMPLES[4071]=["He is very peculiar in his behavior.","彼は振る舞いがとても変わっている。","peculiar"];
EXAMPLES[4072]=["She urged him to do the job.","彼女は彼にその仕事をするよう強く勧めた。","urged"];
EXAMPLES[4073]=["The institution must be protected.","その習慣は守らなくてはならない。","institution"];
EXAMPLES[4074]=["He wrote a letter with great facility.","彼はたやすく手紙を書いた。","facility"];
EXAMPLES[4076]=["We had an unpleasant experience there.","私達そこで不快な経験をした。","unpleasant"];
EXAMPLES[4078]=["Do you go to an elementary school?","あなたは小学校に通っているの。","elementary"];
EXAMPLES[4080]=["The medicine is hard to swallow.","この薬は飲みにくい。","swallow"];
EXAMPLES[4081]=["The more danger, the more honor.","危険が大きければ大きいほど名誉も大きくなる。","honor"];
EXAMPLES[4082]=["The bus was late because of the traffic jam.","バスは交通渋滞のために遅れた。","traffic jam"];
EXAMPLES[4083]=["His advice inclined me to change my mind.","彼のアドバイスで考えを変える気になった。","inclined"];
EXAMPLES[4084]=["I owe my success to your help.","私の成功はあなたの援助のおかげだ。","owe"];
EXAMPLES[4085]=["We accustomed our children to sleeping alone.","私たちは子供にひとり寝の習慣をつけた。","accustomed"];
EXAMPLES[4087]=["They still haven't found a buyer for that house.","あの家はまだ買い手がつかない。","buyer"];
EXAMPLES[4089]=["He found a good companion in his dog.","彼は犬をよき友とした。","companion"];
EXAMPLES[4090]=["I am confronted with a great danger.","私は非常な危険に直面している。","confronted"];
EXAMPLES[4092]=["We shall go when the rain ceases.","私達は雨がやんだら行く。","ceases"];
EXAMPLES[4094]=["I'll cover for you.","僕が証人になってあげるよ。","cover"];
EXAMPLES[4095]=["The sound was distinct from here.","その音はここからはっきり聞こえた。","distinct"];
EXAMPLES[4097]=["My brother did it on my behalf.","弟が私に代わってそれをやった。","behalf"];
EXAMPLES[4099]=["His idea is identical with mine.","彼の考えは私と同じだ。","identical"];
EXAMPLES[4100]=["One must be an executive in some company.","彼はどこかの会社の重役に違いない。","executive"];
EXAMPLES[4101]=["We won the game by three goals to one.","我々のチームは３対１で試合に勝った。","goals"];
EXAMPLES[4102]=["Do you know if he has a girlfriend?","あの人に彼女がいるかどうか知ってる？","girlfriend"];
EXAMPLES[4103]=["When did you learn of Mary's divorce?","メアリーの離婚をいつ知ったのか。","divorce"];
EXAMPLES[4105]=["He is passive in everything.","彼は何をするにも消極的だ。","passive"];
EXAMPLES[4107]=["Most people live in pursuit of happiness.","たいていの人々は幸福を求めて生きている。","pursuit"];
EXAMPLES[4108]=["Nothing is ever done here without dispute.","ここで何かやろうとすると必ず論争がある。","dispute"];
EXAMPLES[4110]=["The students bowed to their teacher.","生徒達は先生におじぎをした。","bowed"];
EXAMPLES[4111]=["I firmly believe that your time will come.","私はあなたの番が来ると確信しているよ。","firmly"];
EXAMPLES[4113]=["But, I'm going steady.","でも、わたしには恋人がいるの。","steady"];
EXAMPLES[4114]=["In comparison with Tokyo, London is small.","東京と比べたら、ロンドンは小さい。","comparison"];
EXAMPLES[4117]=["He proceeded in the face of danger.","彼は危険に直面しても進んでいった。","proceeded"];
EXAMPLES[4118]=["I tried everything to keep him alive.","何とか生きてほしいと全力を尽くした。","alive"];
EXAMPLES[4119]=["I dare say he will not come.","多分彼は来ないだろう。","dare"];
EXAMPLES[4121]=["He could not do so for shame.","彼は恥ずかしくてそうすることができなかった。","shame"];
EXAMPLES[4122]=["He's always running short of cash.","彼はいつも現金が不足している。","cash"];
EXAMPLES[4124]=["I am positive that he has finished.","彼が終えたことは確かだ。","positive"];
EXAMPLES[4125]=["He lived in a house remote from the village.","彼は人里離れた家に住んでいた。","remote"];
EXAMPLES[4126]=["That Japanese word has no equivalent in English.","その日本語に対応する英語はない。","equivalent"];
EXAMPLES[4128]=["My father was in the navy.","父は海軍にいた。","navy"];
EXAMPLES[4129]=["We have had enough of empty words.","くだらない話はもうたくさんだ。","empty"];
EXAMPLES[4133]=["Here comes a copper!","お巡りがやってきたぞ。","copper"];
EXAMPLES[4135]=["He nodded to her to come along.","彼は彼女に来るようにとうなずいた。","nodded"];
EXAMPLES[4138]=["He is a man with enterprise.","彼は冒険心を持つ男だ。","enterprise"];
EXAMPLES[4141]=["He is without parallel.","彼には匹敵するものがない。","parallel"];
EXAMPLES[4142]=["He should be given preference over the others.","彼は他の人より優先されるべきだ。","preference"];
EXAMPLES[4144]=["She carried that habit to her grave.","彼女はその習慣を死ぬまでやめなかった。","grave"];
EXAMPLES[4145]=["I want to look at the reference books.","参考書をみたいのですが。","reference"];
EXAMPLES[4146]=["Snow was been falling steadily since this morning.","朝から休みなく雪が降り続いている。","steadily"];
EXAMPLES[4147]=["He is a doctor by profession.","彼の職業は医者です。","profession"];
EXAMPLES[4149]=["No one could find the cave.","だれもほらあなを見つけ出すことはできなかった。","cave"];
EXAMPLES[4150]=["I took a fancy to the singer.","僕はその歌手が好きになった。","fancy"];
EXAMPLES[4151]=["The tv is on the blink.","そのテレビは調子が悪い。","blink"];
EXAMPLES[4152]=["He is thought of as a scholar.","彼は学者だと思われている。","scholar"];
EXAMPLES[4153]=["I want to get rid of it.","どうしても治したいのです。","rid"];
EXAMPLES[4154]=["It is a privilege to meet you.","あなたにお会いできて光栄です。","privilege"];
EXAMPLES[4155]=["You ought to read English aloud.","英語を声を出して読むべきだ。","aloud"];
EXAMPLES[4156]=["He is master of his own time.","彼は自分の時間は自由に使える。","master"];
EXAMPLES[4159]=["Can you weigh this, please?","この重さを計ってもらえませんか。","weigh"];
EXAMPLES[4160]=["They are unlikely to marry.","彼らは結婚しそうもない。","unlikely"];
EXAMPLES[4164]=["It is desirable that you stop smoking.","君はタバコをやめた方がいい。","desirable"];
EXAMPLES[4166]=["He has a good grasp of English.","彼は英語をよく理解している。","grasp"];
EXAMPLES[4168]=["That's against the contract.","それでは契約と違う。","contract"];
EXAMPLES[4170]=["I will go regardless of the weather.","私は天気に関係なく行くだろう。","regardless"];
EXAMPLES[4171]=["He is dead and buried now.","彼は今地下に眠っている。","buried"];
EXAMPLES[4173]=["I am glad to make your acquaintance.","初めてお目にかかります。","acquaintance"];
EXAMPLES[4174]=["This is the absolute best.","これが断然一番良い。","absolute"];
EXAMPLES[4176]=["It'll add to the same thing.","結局は同じ事になるだろう。","add"];
EXAMPLES[4178]=["I shall stay here for the time being.","私は当分のあいだここに滞在します。","for the time being"];
EXAMPLES[4179]=["I have a good appetite this morning.","今朝はとても食欲がありました。","appetite"];
EXAMPLES[4181]=["I heard the gay voices of children.","子供たちの楽しそうな声が聞こえた。","gay"];
EXAMPLES[4182]=["It is definite that he will go.","彼が行くのは確実だ。","definite"];
EXAMPLES[4184]=["I got a bang out of her party.","彼女のパーティーは実に楽しかった。","bang"];
EXAMPLES[4185]=["She burst into tears at the news.","彼女はその知らせを聞いてわっと泣き出した。","burst"];
EXAMPLES[4186]=["You have to account for your absence.","君は欠席の理由を説明しなければならない。","absence"];
EXAMPLES[4187]=["He is much inferior to me in English.","彼は英語ではわたしよりずっと劣っている。","inferior"];
EXAMPLES[4188]=["It is evident that he did it.","彼がそれをやったことは明らかだ。","evident"];
EXAMPLES[4189]=["He is a man of profound knowledge.","彼は深い学識のある人だ。","profound"];
EXAMPLES[4190]=["What time do you usually turn in?","あなたはいつもは何時に寝ますか。","turn in"];
EXAMPLES[4191]=["I can assure you of your success.","私は君の成功を保証できる。","assure"];
EXAMPLES[4192]=["I acknowledge it to be true.","私はそれを真実だと認める。","acknowledge"];
EXAMPLES[4193]=["She sat gazing out of the window.","彼女は座って、窓の外をじっと見ていた。","gazing"];
EXAMPLES[4194]=["That is really a load off my mind.","それが私の心からなくなった重圧だ。","load"];
EXAMPLES[4195]=["It was inevitable that they would meet.","彼らが会うことは避けられなかった。","inevitable"];
EXAMPLES[4196]=["Have some enthusiasm for your job.","仕事に熱中しなさい。","enthusiasm"];
EXAMPLES[4198]=["As a matter of fact, it is true.","実はそれ、本当なんだ。","As a matter of fact"];
EXAMPLES[4200]=["I will give you five day's grace.","もう５日間待ちましょう。","grace"];
EXAMPLES[4201]=["He has distorted my speech.","彼は私の話をゆがめて伝えた。","distorted"];
EXAMPLES[4204]=["They don't always obey their parents.","彼らはいつも両親に従うとは限らない。","obey"];
EXAMPLES[4205]=["We cannot rule out the possibility of an accident.","事故が起きる可能性は否定できない。","rule out"];
EXAMPLES[4207]=["The woman goes by the name of sue.","その女性はスーです。","sue"];
EXAMPLES[4208]=["He succeeded to his uncle's fortune.","彼は叔父の財産をついだ。","fortune"];
EXAMPLES[4210]=["As far as I know, she is a very good person.","私が知るかぎり彼女は大変よい人だ。","As far as I know"];
EXAMPLES[4212]=["I felt as if I were dreaming.","まるで夢を見ているかのような気分だった。","as if"];
EXAMPLES[4216]=["We must get to our destination.","私たちは目的地に着かなければならない。","destination"];
EXAMPLES[4221]=["I cannot tell my opinion without provoking him.","私の意見を言うと、彼は必ず腹を立てる。","provoking"];
EXAMPLES[4224]=["Tom is going to apply for a job with a computer company.","トムは、コンピューター会社に職を求めるつもりだ。","apply for"];
EXAMPLES[4225]=["Fatigue showed on her face.","疲れが彼女の顔に見えた。","Fatigue"];
EXAMPLES[4226]=["The rain was preceded by wind.","雨になる前に風が吹いた。","preceded"];
EXAMPLES[4227]=["He is a very decent fellow.","彼は非常に親切だ。","decent"];
EXAMPLES[4228]=["She is an utter stranger to me.","彼女は全く私の知らない人です。","utter"];
EXAMPLES[4229]=["Our teacher is stern to us.","我々の先生はきびしい。","stern"];
EXAMPLES[4230]=["Don't forget to polish your shoes before you go out!","外出の前に必ず靴を磨きなさい。","polish"];
EXAMPLES[4231]=["I will go provided that the others go.","他の人が行くなら私も行きます。","provided that"];
EXAMPLES[4232]=["What's the weather forecast for tomorrow?","明日の天気はどうですか。","forecast"];
EXAMPLES[4233]=["Japanese people tend to think that way.","日本人はそのように考える傾向がある。","tend"];
EXAMPLES[4234]=["They require me to work harder.","彼らは私にもっと働けといっている。","require"];
EXAMPLES[4237]=["The food is very good in the dormitory where he lives.","彼のはいっている寮は食事が大変よい。","dormitory"];
EXAMPLES[4238]=["How do you pronounce your name?","あなたのお名前はどのように発音するのですか。","pronounce"];
EXAMPLES[4243]=["The price is not reasonable.","ちょっと高すぎて手が出ません。","reasonable"];
EXAMPLES[4244]=["Sorry, I can't accommodate you.","すみません、お役に立てなくて。","accommodate"];
EXAMPLES[4246]=["They're in aisle two.","２番通路です。","aisle"];
EXAMPLES[4247]=["There is no reason why he should resign.","彼が辞職しなければならない理由はない。","resign"];
EXAMPLES[4249]=["We must pay a toll to drive on this road.","この道路は有料です。","toll"];
EXAMPLES[4250]=["Do you wish to make any other transaction?","続けてお取り引きなさいますか。","transaction"];
EXAMPLES[4251]=["Shoes are stiff when they are new.","靴は新しい間は固い。","stiff"];
EXAMPLES[4252]=["I cannot put up with his idleness any longer.","彼の怠惰にはもうこれ以上我慢することができない。","put up with"];
EXAMPLES[4257]=["She tried to conceal the fact.","彼女は事実を隠そうとした。","conceal"];
EXAMPLES[4260]=["Taro will come here before long.","太郎はまもなくここへ来ます。","before long"];
EXAMPLES[4262]=["He is a man of great wealth.","彼は大富豪だ。","wealth"];
EXAMPLES[4264]=["His opinion is free from prejudice.","彼の意見には偏見がない。","prejudice"];
EXAMPLES[4265]=["What souvenir do you think she would like most?","彼女へのお土産には何が一番いいと思う？","souvenir"];
EXAMPLES[4266]=["I want to bring up my son as my father did me.","私は父が私を育てたように息子を育てたい。","bring up"];
EXAMPLES[4270]=["The rain soaked through my clothes.","雨は服にしみ込んだ。","soaked"];
EXAMPLES[4275]=["We must conform to the rules.","私達は規則には従わなければならない。","conform"];
EXAMPLES[4276]=["Rain is scarce in this country.","この国は雨がとぼしい。","scarce"];
EXAMPLES[4277]=["He easily gets angry at trivial things.","彼はちょっとしたことですぐ怒る。","trivial"];
EXAMPLES[4278]=["You had better study English thoroughly.","君は徹底的に英語を学んだほうがよい。","thoroughly"];
EXAMPLES[4283]=["I was embarrassed by what she said.","彼女の言葉を聞いてどぎまぎした。","embarrassed"];
EXAMPLES[4290]=["We'll go along with your suggestion.","私たちは君の提案に賛成しよう。","along with"];
EXAMPLES[4291]=["Don't make fun of that child.","その子をからかってはいけない。","make fun of"];
EXAMPLES[4293]=["I hold the converse opinion.","私は逆の意見を持っている。","converse"];
EXAMPLES[4294]=["The rule should be revised.","その規則は修正されるべきだ。","revised"];
EXAMPLES[4295]=["I dipped into his book.","彼の本にざっと目を通した。","dipped"];
EXAMPLES[4296]=["He has an optimistic turn of mind.","彼は得な性分だ。","optimistic"];
EXAMPLES[4297]=["His room is anything but neat.","彼の部屋は決してきちんとしていない。","neat"];
EXAMPLES[4303]=["I'm not a bit interested in chemistry.","私は化学にまったく興味がない。","chemistry"];
EXAMPLES[4306]=["The rain is coming down in earnest.","雨は本降りになった。","earnest"];
EXAMPLES[4307]=["Excuse me. may I get by?","すみません、通してください。","get by"];
EXAMPLES[4308]=["He is quite a savage.","彼は全くの野蛮人だ。","savage"];
EXAMPLES[4309]=["He says things on the spur of the moment.","その場限りのことを言う。","spur"];
EXAMPLES[4310]=["Do you have any bleeding?","出血はありますか。","bleeding"];
EXAMPLES[4311]=["He has good eyesight.","彼は視力がいい。","eyesight"];
EXAMPLES[4313]=["I do not care for fame.","私は名声を求めない。","fame"];
EXAMPLES[4314]=["We need accommodation for six.","６人宿泊させて欲しい。","accommodation"];
EXAMPLES[4315]=["The old man was starved to death.","その老人は餓死した。","starved"];
EXAMPLES[4317]=["He used to bully his friends.","彼はよく友人をいじめたものだ。","bully"];
EXAMPLES[4323]=["You should enrich your mind when young.","若いころに心を豊かにすべきだ。","enrich"];
EXAMPLES[4324]=["I'd like to get a refund.","払い戻してください。","refund"];
EXAMPLES[4326]=["The rumor turned out to be true.","うわさは事実だとわかった。","rumor"];
EXAMPLES[4328]=["What he said is irrelevant to the matter.","彼の言ったことはその問題に関係ない。","irrelevant"];
EXAMPLES[4329]=["She is endowed with beauty.","彼女は美しさを備えています。","endowed"];
EXAMPLES[4331]=["This vending machine is out of order.","この自動販売機は故障しています。","vending machine"];
EXAMPLES[4334]=["He left the room in a rage.","彼は激怒して部屋を出た。","rage"];
EXAMPLES[4337]=["He is getting better by degrees.","彼の病気はだんだん良くなってきている。","by degrees"];
EXAMPLES[4338]=["Great was the sorrow of her parents.","彼女の両親の悲しみは大きかった。","sorrow"];
EXAMPLES[4339]=["He doesn't approve of women smoking.","彼は女性の喫煙をいいものだと認めない。","approve"];
EXAMPLES[4340]=["I have a mind to undertake the work.","その仕事を引き受けようと思っている。","undertake"];
EXAMPLES[4341]=["They paid their compliment to me.","彼らは、私に挨拶をした。","compliment"];
EXAMPLES[4342]=["Hang up and wait a moment, please.","電話を切って少々お待ち下さい。","Hang up"];
EXAMPLES[4345]=["What would you do if war were to break out?","仮に戦争が起こるとしたらどうしますか。","break out"];
EXAMPLES[4347]=["He asked an awkward question.","彼は答えにくい質問をした。","awkward"];
EXAMPLES[4350]=["Down went the bus over the cliff.","崖からバスは落ちていった。","cliff"];
EXAMPLES[4351]=["He was a man of great ambition.","彼は大変な野心家だった。","ambition"];
EXAMPLES[4352]=["I sat for a scholarship.","私は奨学金の試験を受けた。","scholarship"];
EXAMPLES[4354]=["The dog was out of breath.","その犬は息を切らしていた。","out of breath"];
EXAMPLES[4357]=["He never shrinks from danger.","彼は危険をものともしない。","shrinks"];
EXAMPLES[4360]=["My mother takes a nap every afternoon.","私の母は、毎日午後昼寝をします。","nap"];
EXAMPLES[4361]=["Everyone was more or less interested in the arts.","だれでも芸術にはいくらか興味を持っていた。","more or less"];
EXAMPLES[4368]=["I can see his hand in this.","これは彼の手がけたものと私には分かる。","hand in"];
EXAMPLES[4371]=["I'm taking a couple of days off.","私は数日間休みを取ります。","a couple of"];
EXAMPLES[4375]=["Your answer does not make sense.","あなたの答えは答えになっていない。","make sense"];
EXAMPLES[4376]=["The room was anything but tidy.","部屋は全く整頓されていなかった。","tidy"];
EXAMPLES[4377]=["He didn't reveal his secret.","彼は秘密を明かさなかった。","reveal"];
EXAMPLES[4381]=["How can we abolish war?","どうしたら戦争をなくすことができるか。","abolish"];
EXAMPLES[4382]=["My house is old and ugly.","私の家は古くて不格好だ。","ugly"];
EXAMPLES[4383]=["She is as modest as anything.","彼女はとてもおしとやかだ。","modest"];
EXAMPLES[4384]=["The flowers are already out of bloom.","花はもう盛りをすぎている。","bloom"];
EXAMPLES[4385]=["He assigned me three books to read.","彼は私に読むべき本を３冊指定した。","assigned"];
EXAMPLES[4388]=["How come you didn't say anything?","なぜ何も言わないの。","How come"];
EXAMPLES[4389]=["She drinks a little wine at times.","彼女は時々酒を飲む。","at times"];
EXAMPLES[4391]=["How much is the fare on the bus?","このバスの料金はいくらですか。","fare"];
EXAMPLES[4394]=["No matter how fast you may walk, you can't catch up with him.","どんなに速く歩いてもあなたは彼に追いつけない。","catch up"];
EXAMPLES[4395]=["She seemed happy in contrast to the man.","彼女はその男と違ってとても幸福そうだ。","in contrast to"];
EXAMPLES[4396]=["She is careful about her child's nutrition.","彼女は子供の栄養に気をつけている。","nutrition"];
EXAMPLES[4398]=["The secret seems to have leaked out.","秘密が漏れたらしい。","leaked"];
EXAMPLES[4399]=["You don't exert yourself much.","君はあまり努力しない。","exert"];
EXAMPLES[4409]=["He is sincere about what he says.","彼の言葉には表裏がない。","sincere"];
EXAMPLES[4411]=["He walked back and forth in the room.","彼は部屋の中を行きつもどりつした。","back and forth"];
EXAMPLES[4416]=["Don't sit up till late.","遅くまで起きていてはいけない。","sit up"];
EXAMPLES[4421]=["It gets hot and humid in summer.","夏になると、むし暑くなる。","humid"];
EXAMPLES[4423]=["This food is too salty.","この料理は塩がききすぎている。","salty"];
EXAMPLES[4424]=["So many countries, so many customs.","国の数だけ習慣がある。","customs"];
EXAMPLES[4429]=["His heart beat fast at the news.","その知らせで彼はどきんとした。","beat"];
EXAMPLES[4431]=["Somehow I cannot settle down to work.","どうも仕事が手に着かない。","settle down"];
EXAMPLES[4432]=["I really spoke too harshly.","ちょっと言い過ぎました。","harshly"];
EXAMPLES[4434]=["He is humble about his opinion.","彼の意見は控え目である。","humble"];
EXAMPLES[4438]=["A lot of trees were cut down.","たくさんの木が切り倒された。","cut down"];
EXAMPLES[4439]=["It is bold of you to say such a thing.","そんな事を言う君は大胆だ。","bold"];
EXAMPLES[4441]=["I have seen nothing of her lately.","最近彼女に全然会ってない。","lately"];
EXAMPLES[4443]=["Nothing is more vivid than a picture.","写真ほど鮮明なものはない。","vivid"];
EXAMPLES[4444]=["We're out of stock.","在庫がありません。","out of stock"];
EXAMPLES[4448]=["He acquired the ability to speak English.","彼は英語を話す能力を身につけた。","acquired"];
EXAMPLES[4453]=["The pity is that he has failed.","残念なのは彼が失敗したことだ。","pity"];
EXAMPLES[4456]=["Hang on my lips.","僕の言う事を良く聞いてくれ。","Hang on"];
EXAMPLES[4458]=["That chimney is very high.","あの煙突はとても高い。","chimney"];
EXAMPLES[4459]=["Does it bark at her?","それは彼女に吠えますか。","bark"];
EXAMPLES[4460]=["He has been intent on learning French.","彼はフランス語を懸命に勉強してきた。","intent"];
EXAMPLES[4464]=["Please forgive me for telling a lie.","嘘をついたことを許して下さい。","forgive"];
EXAMPLES[4465]=["He has her under his thumb.","彼女は彼の言いなりです。","thumb"];
EXAMPLES[4466]=["Two robbers broke into a store.","泥棒二人がある店に押し入った。","robbers"];
EXAMPLES[4467]=["I put it in the drawer.","それは引き出しに入れておきました。","drawer"];
EXAMPLES[4471]=["Pat's going to Jim's birthday party.","パットはジムの誕生日パーティーに行く予定です。","Pat"];
EXAMPLES[4472]=["I asked him to mend my shoes.","私は彼に靴を修繕するように頼んだ。","mend"];
EXAMPLES[4474]=["I can't afford to pay so much.","ぼくにそんなに金は出せない。","afford to"];
EXAMPLES[4476]=["My mind is a blank.","私の心は空虚である。","blank"];
EXAMPLES[4478]=["In the meantime, he went to sleep.","そうしているうちに彼は眠ってしまった。","meantime"];
EXAMPLES[4481]=["His brother was nasty to me.","彼の兄は私に意地が悪かった。","nasty"];
EXAMPLES[4482]=["It's really horrible.","まったく恐ろしいことだわ。","horrible"];
EXAMPLES[4484]=["There's no soap.","石鹸がありません。","soap"];
EXAMPLES[4485]=["He came in spite of bad weather.","彼は悪天候をついて来た。","spite"];
EXAMPLES[4486]=["They got a warm reception.","彼らは暖かく迎えられた。","reception"];
EXAMPLES[4487]=["He was born into a noble family.","彼は名門の生まれなのだ。","noble"];
EXAMPLES[4488]=["I like this blend of coffee.","私はこのブレンドのコーヒーが好きだ。","blend"];
EXAMPLES[4490]=["He has no religious mind.","彼は宗教心がない。","religious"];
EXAMPLES[4491]=["There was a long interval before he answered.","彼が答えるまでに長い間があった。","interval"];
EXAMPLES[4492]=["The accident robbed him of his sight.","事故のために彼は視力を失った。","robbed"];
EXAMPLES[4494]=["What shall I do with his luggage?","この荷物をどう処理しようか。","luggage"];
EXAMPLES[4495]=["This will bring you to grief.","後で憂き目をみる。","grief"];
EXAMPLES[4499]=["I remember last summer's adventure.","私は去年の夏の冒険を覚えている。","adventure"];
EXAMPLES[4500]=["It was yesterday morning that I saw Mr carter.","カーターさんに会ったのは昨日の朝でした。","carter"];
EXAMPLES[4501]=["He has come out of his shell.","彼はうちとけた。","shell"];
EXAMPLES[4503]=["Don't boast too much about that.","あまりそれを鼻にかけるな。","boast"];
EXAMPLES[4506]=["I didn't remember his name until afterward.","彼の名前を後になってやっと思い出した。","afterward"];
EXAMPLES[4512]=["He is little better than a beggar.","彼はほとんど乞食と同じだ。","beggar"];
EXAMPLES[4513]=["I can remember the warmth of her hands.","私は彼女の手の温かさを覚えている。","warmth"];
EXAMPLES[4517]=["Do you have a fountain pen with you?","万年筆を持っていますか。","fountain"];
EXAMPLES[4519]=["She wants to become thin very much.","彼女はとても痩せたがっている。","thin"];
EXAMPLES[4520]=["You should free those animals from the cage.","おりの中の動物を自由にしてやるべきだ。","cage"];
EXAMPLES[4521]=["Excuse me, could I get past?","ちょっと失礼、通していただけますか。","get past"];
EXAMPLES[4522]=["Thank you for your invitation.","ご招待をありがとうございます。","invitation"];
EXAMPLES[4523]=["Everybody was jealous of my success.","みんなが私の成功をねたんだ。","jealous"];
EXAMPLES[4526]=["He wants to go to the united states.","彼はアメリカへ行きたがっています。","united"];
EXAMPLES[4528]=["Comb your hair before you go out.","外出する前に髪を櫛でときなさい。","Comb"];
EXAMPLES[4529]=["This is a fact, not a fiction.","これは事実であって作り話ではありません。","fiction"];
EXAMPLES[4530]=["The business is in the red.","商売は赤字だ。","in the red"];
EXAMPLES[4531]=["Let me hear your frank opinion.","率直な意見を聞きたい。","frank"];
EXAMPLES[4533]=["He is eager to go abroad.","彼は外国に行きたがっている。","eager to"];
EXAMPLES[4537]=["He will ultimately pass the exam.","結局は彼は試験に合格するでしょう。","ultimately"];
EXAMPLES[4538]=["The children were playing in the backyard.","子供たちは裏庭で遊んでいた。","backyard"];
EXAMPLES[4539]=["I will put up at my friend's tonight.","今夜は、友人の所に泊まるつもりだ。","put up at"];
EXAMPLES[4541]=["Is it all right to use a flash here?","フラッシュを使ってもいいですか。","flash"];
EXAMPLES[4545]=["The fish are striking well today.","今日は魚の食いつきがいい。","striking"];
EXAMPLES[4548]=["Why don't you pull over and take a rest for a while?","車を止めて少し休んだらどう。","pull over"];
EXAMPLES[4549]=["He heard the news calmly.","彼はその知らせにも泰然としていた。","calmly"];
EXAMPLES[4552]=["How old is your elder son?","あなたの上の息子さんは何歳か。","elder"];
EXAMPLES[4556]=["You must not go up the stairs.","その階段を上ってはいけません。","stairs"];
EXAMPLES[4559]=["Every boy and every girl was delighted.","どの少年もどの少女も、喜んでいた。","delighted"];
EXAMPLES[4565]=["I have a lot of discharge.","おりものが多いのです。","discharge"];
EXAMPLES[4568]=["They felt weary after their hard work.","熱心に勉強して彼らは疲れを感じた。","weary"];
EXAMPLES[4569]=["She found her purse under the desk.","彼女は机の下で財布を見つけた。","purse"];
EXAMPLES[4573]=["There is a little chill in the air.","少し肌寒い。","chill"];
EXAMPLES[4575]=["I want to send this parcel at once.","この小包をすぐ送りたい。","parcel"];
EXAMPLES[4578]=["He has no friends to fall back on.","彼には頼れる友人がいない。","fall back on"];
EXAMPLES[4580]=["I am blessed if I know it.","そんなこと知るもんか。","blessed"];
EXAMPLES[4581]=["Stand the ladder against the wall.","はしごを壁に立てかけなさい。","ladder"];
EXAMPLES[4583]=["It's always darkest before the dawn.","朝の来ない夜はない。","dawn"];
EXAMPLES[4586]=["If you try for too much, you'll end up with nothing at all.","結局は虻蜂とらずになってしまった。","end up with"];
EXAMPLES[4587]=["The poor little girl did nothing but weep.","かわいそうに、その女の子は泣いてばかりいた。","weep"];
EXAMPLES[4589]=["What did you do with my baggage?","私の荷物はどうしましたか。","baggage"];
EXAMPLES[4590]=["She was deliberate in everything she did.","彼女は何をするにも慎重であった。","deliberate"];
EXAMPLES[4591]=["School will soon break up for the summer vacation.","学校はもうすぐ夏休みになる。","break up"];
EXAMPLES[4595]=["You no doubt bore people.","あなたは間違いなく人々を退屈させる。","bore"];
EXAMPLES[4599]=["I found it something of a disappointment.","それにはかなりがっかりした。","disappointment"];
EXAMPLES[4602]=["I got her a wrist watch.","私は彼女に腕時計を買って上げた。","wrist"];
EXAMPLES[4605]=["I am going to get that sucker.","あの野郎は、いただきだ。","sucker"];
EXAMPLES[4606]=["I was cut off while I was speaking.","電話中に切れてしまいました。","cut off"];
EXAMPLES[4607]=["We could not open the box anyhow.","どうしても箱が開かなかった。","anyhow"];
EXAMPLES[4609]=["He is bound to solve this question.","彼は必ずこの問題を解決する。","bound"];
EXAMPLES[4611]=["He has decided to turn over his business to his son.","彼は息子に仕事を譲ることに決めました。","turn over"];
EXAMPLES[4613]=["He put off his departure till Sunday.","彼は出発を日曜まで延期した。","departure"];
EXAMPLES[4614]=["He has always devoted himself to music.","彼はいつも音楽に専念した。","devoted"];
EXAMPLES[4616]=["He has a beard.","彼は顎鬚を生やしている。","beard"];
EXAMPLES[4620]=["He was fortunate to pass the exam.","彼は試験に通って幸運だった。","fortunate"];
EXAMPLES[4632]=["There is a vase on the table.","テーブルの上に花瓶がある。","vase"];
EXAMPLES[4633]=["It goes against the grain with me.","僕はそれが気にいらない。","grain"];
EXAMPLES[4634]=["He crushed the box.","彼はその箱を壊した。","crushed"];
EXAMPLES[4636]=["She was deadly tired.","彼女はひどく疲れていた。","deadly"];
EXAMPLES[4641]=["I am all ears.","全身すべてが耳だ。","all ears"];
EXAMPLES[4643]=["It is uncertain if will come.","彼がやってくるかどうか確かではない。","uncertain"];
EXAMPLES[4644]=["I could scarcely stand on my feet.","立っているのがやっとだった。","scarcely"];
EXAMPLES[4645]=["Give me five tokens, please.","トークンを５枚ください。","tokens"];
EXAMPLES[4646]=["Japan is hot and sticky in summer.","日本は夏には蒸し暑い。","sticky"];
EXAMPLES[4647]=["Don't give up halfway.","途中であきらめるな。","halfway"];
EXAMPLES[4648]=["There is only one pass over the mountain.","その山を越える山道は一つしかない。","pass over"];
EXAMPLES[4650]=["They asserted that it was true.","彼らはそれが本当だと言い張った。","asserted"];
EXAMPLES[4653]=["Their baby has just started to crawl.","彼らの赤ちゃんはちょうど這い始めたところです。","crawl"];
EXAMPLES[4655]=["My lips are sealed.","言っちゃいけないんだけど。","sealed"];
EXAMPLES[4657]=["My flight will depart in an hour.","私の飛行機はあと１時間で出発です。","depart"];
EXAMPLES[4658]=["He was quite decided in his determination.","彼の決心は確固たるものだった。","determination"];
EXAMPLES[4661]=["This mountain scenery is very beautiful.","この山の景色はとても美しい。","scenery"];
EXAMPLES[4665]=["The ship was at the mercy of the storm.","彼は嵐に翻弄されていた。","mercy"];
EXAMPLES[4667]=["Formerly this building was a hospital.","昔はこの建物は病院だった。","Formerly"];
EXAMPLES[4668]=["His answer was not favorable.","彼の答えは好意的ではなかった。","favorable"];
EXAMPLES[4669]=["She can sew very well.","彼女は裁縫が上手です。","sew"];
EXAMPLES[4672]=["Please lie on your stomach.","うつ伏せになってください。","lie on"];
EXAMPLES[4675]=["There was a fine scent in the room.","部屋の中は良い香りがしていた。","scent"];
EXAMPLES[4676]=["It is wicked of you to do such things.","そんなことをするなんてひどい人ですね。","wicked"];
EXAMPLES[4678]=["Our team triumphed over theirs.","私達のチームは彼らのチームに勝った。","triumphed"];
EXAMPLES[4684]=["Make haste in case you are late.","時間に遅れないように急ぎなさい。","haste"];
EXAMPLES[4686]=["Do you think he resembles his father?","彼は父親に似ていると思いますか。","resembles"];
EXAMPLES[4687]=["She bought it at the butcher's.","彼女はそれを肉屋で買った。","butcher"];
EXAMPLES[4688]=["Do you have any engagement tomorrow?","明日は約束がありますか。","engagement"];
EXAMPLES[4693]=["They did not clap for us.","彼らはわたしたちに拍手をしませんでした。","clap"];
EXAMPLES[4695]=["Don't be unkind to your friends.","友達に意地悪をしてはいけません。","unkind"];
EXAMPLES[4696]=["Walk on the pavement.","歩道を歩きなさい。","pavement"];
EXAMPLES[4701]=["He is nothing more than a coward.","彼は臆病者にすぎない。","coward"];
EXAMPLES[4702]=["The boy is obedient to his parents.","その少年は両親の言うことを聞く。","obedient"];
EXAMPLES[4704]=["I broke your ashtray.","灰皿を割ってしまいました。","ashtray"];
EXAMPLES[4705]=["She could pass for twenty.","彼女は２０歳といっても通用する。","pass for"];
EXAMPLES[4707]=["He was always faithful to his wife.","彼は決して浮気をしなかった。","faithful"];
EXAMPLES[4709]=["Where is it hidden?","それはどこに隠されているのか。","hidden"];
EXAMPLES[4711]=["The town has an air of prosperity.","その町は繁栄しているようだ。","prosperity"];
EXAMPLES[4712]=["He is enthusiastic about tennis.","彼は、テニスに夢中だ。","enthusiastic"];
EXAMPLES[4713]=["He finally surrendered to her.","彼は最後には彼女に屈した。","surrendered"];
EXAMPLES[4714]=["She died a miserable death.","彼女は悲惨な死に方をした。","miserable"];
EXAMPLES[4715]=["There is nothing that does not decay.","朽ちない物は何もない。","decay"];
EXAMPLES[4716]=["His letter enclosed a picture.","彼の手紙には写真が一枚同封されていた。","enclosed"];
EXAMPLES[4717]=["She was very ambitious for her children.","彼女は子供たちにとても大きな望みをかけていた。","ambitious"];
EXAMPLES[4720]=["Let's occasionally change where we go to eat out.","いつもと変えてたまに外で食事しよう。","occasionally"];
EXAMPLES[4722]=["It is great fun to play with a puppy.","小犬と遊ぶのはとても楽しい。","puppy"];
EXAMPLES[4723]=["She was greedy for love.","彼女は愛を切望していた。","greedy"];
EXAMPLES[4726]=["It was only a partial success.","それは部分的な成功でしかなかった。","partial"];
EXAMPLES[4727]=["It's awfully cold this evening.","恐ろしく寒いな、今日の夜は。","awfully"];
EXAMPLES[4730]=["I rejoice in your success.","あなたのご成功をうれしく思います。","rejoice"];
EXAMPLES[4732]=["Four multiplied by two is eight.","４掛ける２は８だ。","multiplied"];
EXAMPLES[4733]=["Make haste, and you will be in time.","急ぎなさい、そうすれば間に合います。","Make haste"];
EXAMPLES[4738]=["That boy is a handful.","あの子は手がかかる。","handful"];
EXAMPLES[4742]=["She began to despair of success.","彼女は成功をあきらめ始めた。","despair"];
EXAMPLES[4743]=["He has an eye for antiques.","彼は骨董品を見る目がある。","antiques"];
EXAMPLES[4744]=["We ran for the glory of the school.","私達は学校の名誉のために走った。","glory"];
EXAMPLES[4745]=["This is an immense show.","これはすばらしいショーだ。","immense"];
EXAMPLES[4746]=["I think I'm going to faint.","気絶しそうだ。","faint"];
EXAMPLES[4749]=["I would like to repay him for his kindness.","私は彼の親切にこたえたい。","repay"];
EXAMPLES[4751]=["Frankly, I don't like him.","あからさまに言えば彼は嫌いだ。","Frankly"];
EXAMPLES[4753]=["I ache all over after the exercises.","運動の後は体中が痛い。","ache"];
EXAMPLES[4756]=["He's living from hand to mouth.","彼はその日暮らしだ。","from hand to mouth"];
EXAMPLES[4761]=["The flowers are still in bud.","花はまだ蕾だ。","bud"];
EXAMPLES[4762]=["He has a hatred for his father.","彼は父を憎悪している。","hatred"];
EXAMPLES[4763]=["He hit on a splendid idea.","彼はすばらしい考えを思い付いた。","splendid"];
EXAMPLES[4766]=["I took part in the athletic meeting.","私はその競技会に参加した。","athletic"];
EXAMPLES[4767]=["This window won't fasten.","この窓はどうしても閉まらない。","fasten"];
EXAMPLES[4769]=["She spoke through an interpreter.","彼女は、通訳を使って話をしました。","interpreter"];
EXAMPLES[4770]=["He will scold us no matter what.","彼は必ず私達を叱るだろう。","scold"];
EXAMPLES[4772]=["I studied it thoroughly.","私はそれを徹底的に調べた。","thoroughly"];
EXAMPLES[4773]=["Start a new paragraph here.","ここで改行しなさい。","paragraph"];
EXAMPLES[4774]=["He cast off the problem from his mind.","彼はその問題を頭の中から放り出した。","cast off"];
EXAMPLES[4775]=["What a marvelous sight!","何とすばらしい景色だろう。","marvelous"];
EXAMPLES[4781]=["I ate a hasty lunch.","私は急いで昼食をとった。","hasty"];
EXAMPLES[4783]=["Let me go in place of him.","彼のかわりにぼくに行かせて下さい。","in place of"];
EXAMPLES[4784]=["Life is short and time is swift.","人生は短く時のたつのは速い。","swift"];
EXAMPLES[4785]=["She had an oral examination in English.","彼女は英語の口頭試験を受けた。","oral"];
EXAMPLES[4786]=["Don't eat to excess.","食べ過ぎるな。","to excess"];
EXAMPLES[4788]=["I concentrated on what he was saying.","彼の言うことに注意を注いだ。","concentrated"];
EXAMPLES[4789]=["I was in bed with the flu.","私はインフルエンザで寝てたんです。","flu"];
EXAMPLES[4790]=["He lives in the suburbs of Tokyo.","彼は東京近郊に住んでいる。","in the suburbs of"];
EXAMPLES[4793]=["They hastened to execute the plan.","彼らはその計画の実行を急いだ。","hastened"];
EXAMPLES[4794]=["She is out on an errand.","彼女はお使いに出ています。","errand"];
EXAMPLES[4799]=["I was left out in the cold by everyone.","みんなで私をのけ者にした。","out in the cold"];
EXAMPLES[4806]=["We must deal with the problem instantly.","その問題をすぐ処理しなければならない。","instantly"];
EXAMPLES[4809]=["The statesman is now in full vigor.","その政治家は今元気いっぱいだ。","vigor"];
EXAMPLES[4811]=["We should try to make the conquest of peace.","我々は平和を獲得するべきだ。","conquest"];
EXAMPLES[4815]=["She attained her success through hard work.","彼女は一生懸命働いたので成功した。","attained"];
EXAMPLES[4816]=["You should not speak ill of others.","他人のを悪口を言うべきでない。","speak ill of"];
EXAMPLES[4822]=["No one conceived his words to be important.","だれも彼の言葉を重要なものと思わなかった。","conceived"];
EXAMPLES[4824]=["The very idea of it is disgusting.","それを思うだけでも気持ちが悪い。","disgusting"];
EXAMPLES[4825]=["What about having fish for dinner?","ディナーに魚はどうですか。","fish for"];
EXAMPLES[4826]=["Wondering what makes it so fascinating.","そんなに面白いのかと思い。","fascinating"];
EXAMPLES[4841]=["He fell under the suspicion of the police.","彼は警察の嫌疑を受けた。","suspicion"];
EXAMPLES[4843]=["I was fine and startled.","本当にびっくりした。","startled"];
EXAMPLES[4847]=["She mourned over the death of her only son.","彼女は一人息子の死をいたみ悲しんだ。","mourned"];
EXAMPLES[4850]=["I feel ill at ease in her company.","彼女と一緒にいると気詰まりだ。","ill at ease"];
EXAMPLES[4857]=["They furnished the library with new books.","図書館に新しい本が備え付けられた。","furnished"];
EXAMPLES[4858]=["He says daring things.","彼は大胆なことを言う。","daring"];
EXAMPLES[4859]=["He sent me a letter of appreciation.","彼は僕に礼状を送ってくれた。","appreciation"];
EXAMPLES[4866]=["She was disguised in men's clothes.","彼女は男の服を着て変装していた。","disguised"];
EXAMPLES[4867]=["Please consult with your parents about the trip.","旅行についてはご両親と相談してください。","consult"];
EXAMPLES[4873]=["I think it's absurd to do so.","私はそうするのはばかげていると思う。","absurd"];
EXAMPLES[4874]=["The house is quite run down.","その家はかなりぼろ屋になっている。","run down"];
EXAMPLES[4878]=["This expedition will be expensive.","この探検には、お金がかかる。","expedition"];
EXAMPLES[4893]=["We anticipate it with much pleasure.","私たちはそれを楽しみに待っています。","anticipate"];
EXAMPLES[4896]=["Mary is a girl full of sentiment.","メアリーは気持ちのやさしい女の子だ。","sentiment"];
EXAMPLES[4898]=["Her husband's death has tried her severely.","夫に死なれて彼女はひどく苦しんだ。","severely"];
EXAMPLES[4901]=["It would be good for you to study eagerly.","あなたは懸命に勉強をすればよい。","eagerly"];
EXAMPLES[4905]=["Why he did it is beyond my comprehension.","なぜ彼がそれをやったかがわからない。","comprehension"];
EXAMPLES[4908]=["They don't do a lick of work.","彼らは少しも仕事をしない。","lick"];
EXAMPLES[4910]=["You can get anything less expensive in bulk.","物はすべて一括して買うとやすい。","bulk"];
EXAMPLES[4912]=["She is grieved at her husband's death.","彼女は夫の死に心を痛めている。","grieved"];
EXAMPLES[4917]=["I'd like to insure this, please.","これに保険をかけたいのですが。","insure"];
EXAMPLES[4921]=["I want to be a statesman.","政治家になりたいです。","statesman"];
EXAMPLES[4925]=["Tom is tall and likewise strong.","トムは背が高い上に力も強い。","likewise"];
EXAMPLES[4926]=["You can bank on that.","君はそれを当てにできる。","bank on"];
EXAMPLES[4927]=["What is the best remedy for colds?","風邪に一番良い薬はなんですか。","remedy"];
EXAMPLES[4929]=["She is fluent in English and French.","彼女は英語とフランス語を流暢に話す。","fluent"];
EXAMPLES[4930]=["The farewell party will be given next week.","送別会は来週行われるでしょう。","farewell"];
EXAMPLES[4933]=["It began to sprinkle.","雨がぱらぱら降り出しました。","sprinkle"];
EXAMPLES[4934]=["I was prevailed upon to go to the party.","私はパーティーに行くように説得された。","prevailed"];
EXAMPLES[4937]=["He fetched some water from the well.","彼は井戸へ行って水をくんできた。","fetched"];
EXAMPLES[4940]=["I don't remember my father's face accurately.","僕は父の顔を正確には覚えていない。","accurately"];
EXAMPLES[4942]=["This stain won't come out.","この染みはどうしても落ちない。","stain"];
EXAMPLES[4956]=["The man was in rags.","その男はボロを着ていた。","rags"];
EXAMPLES[4960]=["I'm at my wit's end.","私はどうしていいかわからない。","wit"];
EXAMPLES[4962]=["He was unaware of the situation.","彼は事態を知らなかった。","unaware"];
EXAMPLES[4966]=["It is not good, to say the least.","控え目に言ってもこれは良くない。","to say the least"];
EXAMPLES[4967]=["He is less diligent than his brother.","彼は兄ほど勤勉ではない。","diligent"];
EXAMPLES[4976]=["They came to the hospital to inquire after me.","彼らは私の見舞いに病院へ来た。","inquire after"];
EXAMPLES[4979]=["Please make your reservations promptly.","すぐに予約して下さい。","promptly"];
EXAMPLES[4980]=["In my hurry I bumped into someone.","急いだあまり私はだれか人に突き当たった。","bumped"];
EXAMPLES[4981]=["I'll cover for you.","僕が証人になってあげるよ。","cover for"];
EXAMPLES[4984]=["His speech is very refined.","彼の話し方はたいへん洗練されている。","refined"];
EXAMPLES[4985]=["It's impossible to work in a room this dim.","こんな薄暗い部屋では仕事にならない。","dim"];
EXAMPLES[4986]=["He resumed reading after lunch.","彼は昼食後また読書を始めた。","resumed"];
EXAMPLES[4992]=["I have a great esteem for you.","あなたにはとても頭が上がりません。","esteem"];
EXAMPLES[4995]=["He didn't do a stitch of work.","彼は少しも仕事をしなかった。","stitch"];
EXAMPLES[5001]=["She keeps moaning that she has no time.","彼女は時間がないといつも不平たらたらだ。","moaning"];
EXAMPLES[5006]=["She is a woman of singular beauty.","彼女はまれにみる美しい女性だ。","singular"];
EXAMPLES[5021]=["Let's hit the hay.","じゃあ寝ようよ。","hay"];
EXAMPLES[5024]=["This will keep bugs off.","これは虫除けになります。","bugs"];
EXAMPLES[5027]=["He has something to do with the robbery.","彼はその強盗事件と関係がある。","robbery"];
EXAMPLES[5028]=["She slapped him in the face.","彼女は彼の顔をひっぱたいた。","slapped"];
EXAMPLES[5031]=["I'm dying to see my mother.","母に会いたくてたまらない。","dying"];
EXAMPLES[5034]=["He works for the good of the country.","彼は国のために働いている。","for the good of"];
EXAMPLES[5035]=["Why do you think animals dread fire?","動物はなぜ火を恐れると思いますか。","dread"];
EXAMPLES[5036]=["I am much obliged to you.","あなたにとても感謝している。","obliged"];
EXAMPLES[5038]=["We'll carry it to the barn.","私たちでそれを納屋に持っていこう。","barn"];
EXAMPLES[5040]=["It's always delightful to see you.","君に会うのはいつも楽しい。","delightful"];
EXAMPLES[5042]=["Don't give way to their request.","彼らの要求に屈してはいけません。","give way"];
EXAMPLES[5045]=["They live together in unity.","和合して生活している。","unity"];
EXAMPLES[5047]=["The students are having a recess now.","学生たちは今休憩時間中です。","recess"];
EXAMPLES[5049]=["We have food in abundance.","食べ物は豊富にある。","abundance"];
EXAMPLES[5054]=["It is damp and cold today, isn't it?","今日は、じめじめして寒いですね。","damp"];
EXAMPLES[5055]=["How will you dispose of this problem?","君はこの問題にどう片をつける気かね。","dispose of"];
EXAMPLES[5059]=["My shoes hurt. I'm in agony.","靴が痛くてとてもつらい。","agony"];
EXAMPLES[5061]=["What tempted him to come home?","何が彼を帰宅する気にさせたのか。","tempted"];
EXAMPLES[5063]=["Fish abound in this lake.","この湖には魚が多い。","abound in"];
EXAMPLES[5064]=["There was a happy twinkle in her eyes.","彼女は幸福そうに目を輝かせていた。","twinkle"];
EXAMPLES[5070]=["He is easily flattered.","彼はお調子者だ。","flattered"];
EXAMPLES[5073]=["He is young, and yet he is prudent.","彼は若い、それなのに分別がある。","prudent"];
EXAMPLES[5075]=["Right now I want for nothing.","今のところ何一つ不自由はない。","want for"];
EXAMPLES[5076]=["The famous conductor lives in new york.","その有名な指揮者はニューヨークに住んでいる。","conductor"];
EXAMPLES[5079]=["Let's wind up our work.","この辺で仕事を切り上げよう。","wind up"];
EXAMPLES[5081]=["The house was in a blaze.","その家は一面火となった。","blaze"];
EXAMPLES[5082]=["I feel heaps better after a sound sleep.","ぐっすり眠った後はずっと気分がよい。","heaps"];
EXAMPLES[5083]=["He exclaimed that she was beautiful.","彼女が美しいので彼は感嘆の声をあげた。","exclaimed"];
EXAMPLES[5084]=["The poor little girl did nothing but sob all day.","かわいそうにその少女は一日中泣いてばかりだ。","sob"];
EXAMPLES[5089]=["She was in the mood for a walk.","彼女は散歩したい気分だった。","in the mood for"];
EXAMPLES[5091]=["He succeeded by dint of effort.","彼は努力によって成功した。","by dint of"];
EXAMPLES[5092]=["I'm reluctant to visit him.","彼の所に行くのは足が重い。","reluctant"];
EXAMPLES[5104]=["He's very forgetful of things.","とても物心を忘れやすい。","forgetful"];
EXAMPLES[5106]=["My mother was disappointed by my failure.","私の母は私の失敗にがっかりした。","disappointed"];
EXAMPLES[5110]=["He took it in his stride.","彼はそのことに関して平然としていた。","stride"];
EXAMPLES[5111]=["She was impatient to leave the party.","彼女はパーティーをでたくてしょうがなかった。","impatient"];
EXAMPLES[5112]=["They came to the hospital to inquire after me.","彼らは私の見舞いに病院へ来た。","inquire"];
EXAMPLES[5113]=["That child murmured something in his sleep.","その子は眠りながら何かをぶつぶつ言った。","murmured"];
EXAMPLES[5115]=["I rest on your promise.","君の約束を当てにしている。","rest on"];
EXAMPLES[5117]=["We plunged into the river.","私達は川に飛び込んだ。","plunged"];
EXAMPLES[5119]=["Traffic was halted for several hours.","事故で交通は数時間止められた。","halted"];
EXAMPLES[5121]=["That child is full of mischief.","あの子は本当にいたずら好きだ。","mischief"];
EXAMPLES[5129]=["Where is the Japanese embassy?","日本大使館はどこにありますか。","embassy"];
EXAMPLES[5133]=["I found her graceful.","彼女は優雅な人だとわかった。","graceful"];
EXAMPLES[5134]=["The boy carved his name on the tree.","少年は木に自分の名前を刻んだ。","carved"];
EXAMPLES[5140]=["The rain will revive this tree.","雨が降ればこの木は生き返るでしょう。","revive"];
EXAMPLES[5141]=["The accident deprived him of his sight.","その事故で彼は目が見えなくなった。","deprived"];
EXAMPLES[5144]=["I cannot consent to your going alone.","あなたが一人で行くことに同意できない。","consent"];
EXAMPLES[5151]=["Here's some medicine for diarrhea.","下痢止めです。","diarrhea"];
EXAMPLES[5153]=["His eyes were brimming over with tears.","彼の目から涙があふれ出てきた。","brimming"];
EXAMPLES[5156]=["She pledged herself never to do it again.","彼女は二度とそんなことをしないと誓った。","pledged"];
EXAMPLES[5157]=["Thanking you in anticipation.","前もってお願いします。","anticipation"];
EXAMPLES[5160]=["Mr crouch, what do you do?","クラウチさんは何をなさっているのですか。","crouch"];
EXAMPLES[5162]=["We have food in abundance.","食べ物は豊富にある。","in abundance"];
EXAMPLES[5166]=["I counseled her to wait a little longer.","私は彼女にもう少し待っているように勧めた。","counseled"];
EXAMPLES[5169]=["I promise you every possible compensation.","できる限りの償いはするつもりだ。","compensation"];
EXAMPLES[5175]=["Don't talk rubbish.","変なこと言うなよ。","rubbish"];
EXAMPLES[5179]=["I was asked to umpire the game.","私はその試合の審判をするように頼まれた。","umpire"];
EXAMPLES[5181]=["You would make a good diplomat.","かけ引きがお上手ですね。","diplomat"];
EXAMPLES[5184]=["The ship swayed in the strong wind.","船は強い風を受けて揺れた。","swayed"];
EXAMPLES[5187]=["We're having an examination in geometry tomorrow.","明日幾何の試験があります。","geometry"];
EXAMPLES[5190]=["She is incapable of deceit.","彼女は嘘のつけない人だ。","deceit"];
EXAMPLES[5192]=["Please lay down your coat.","コートをどうぞ下へ置いて下さい。","lay down"];
EXAMPLES[5195]=["I can't think out the design any more.","もうこれ以上、デザインを考えられない。","think out"];
EXAMPLES[5196]=["Who will be the chairperson today?","今日は誰が議長になるのでしょうか。","chairperson"];
EXAMPLES[5197]=["We have a plentiful supply of water.","我々は、水をたくさん持っている。","plentiful"];
EXAMPLES[5198]=["When it comes to making things, I'm all thumbs.","物を作るとなると、私は不器用です。","all thumbs"];
EXAMPLES[5200]=["I took his attendance for granted.","私は当然彼が出席するものだと思っていた。","attendance"];
EXAMPLES[5201]=["If you are free, come around to see me.","暇なら遊びにおいでよ。","come around"];
EXAMPLES[5209]=["Nobody is able to succeed without endurance.","忍耐なくしてはだれも成功することはできない。","endurance"];
EXAMPLES[5211]=["You don't have to stand over me.","見てなくたっていいよ。","stand over"];
EXAMPLES[5215]=["It is difficult to execute the task.","その仕事を実行するのは困難だ。","execute"];
EXAMPLES[5220]=["A car bouncing along a bad road.","悪い道路をガクンガクンと走って行く自動車。","bouncing"];
EXAMPLES[5222]=["I hope I'm not disturbing you.","お邪魔じゃないでしょうか。","disturbing"];
EXAMPLES[5223]=["They were most attentive to his speech.","みんなは彼の話を注意深く聞いた。","attentive"];
EXAMPLES[5229]=["The old shrine used to stand there.","その古い神社は以前はそこにありました。","shrine"];
EXAMPLES[5230]=["He likes to take a solitary walk.","彼は一人で散歩をするのが好きだ。","solitary"];
EXAMPLES[5239]=["He is hostile to the proposal.","彼はその提案に反対である。","hostile"];
EXAMPLES[5245]=["We know that all men are mortal.","人はすべて死すべきものと承知している。","mortal"];
EXAMPLES[5251]=["Please go over the script.","台本に目を通しておいてください。","script"];
EXAMPLES[5254]=["We have ample time to catch our train.","列車に十分間に合うだけの時間がある。","ample"];
EXAMPLES[5259]=["It comes to my remembrance.","私はそれを思い出します。","remembrance"];
EXAMPLES[5260]=["The train jerked forward.","電車は急に発進した。","jerked"];
EXAMPLES[5265]=["That's very naughty of you.","それはひどいいたずらだ。","naughty"];
EXAMPLES[5268]=["They say that old house is haunted.","あの古い家には幽霊が出るそうだ。","haunted"];
EXAMPLES[5269]=["I live on the outskirts of Tokyo.","私は東京の郊外に住んでいる。","outskirts"];
EXAMPLES[5278]=["It was chilly that day.","その日は寒い１日であった。","chilly"];
EXAMPLES[5280]=["This computer will prove costly in the long run.","このコンピューターは、長い目で見れば高くつく。","costly"];
EXAMPLES[5283]=["What's the accusation against him?","彼を告訴する理由は何ですか。","accusation"];
EXAMPLES[5286]=["He left the house without so much as saying good-bye.","彼はさよならも言わずその家を出た。","without so much as"];
EXAMPLES[5296]=["In all likelihood, it will rain this afternoon.","おそらく今日の午後は雨が降るだろう。","In all likelihood"];
EXAMPLES[5297]=["It was irresponsible of him to break a promise.","約束を破るとは彼も無責任だ。","irresponsible"];
EXAMPLES[5301]=["Nothing is more important than sincerity.","誠実さほど重要なものはない。","sincerity"];
EXAMPLES[5302]=["Barbara's success is beyond question.","バーバラの成功は問題にならない。","beyond question"];
EXAMPLES[5305]=["I'm sorry. it was just a slip of the tongue.","すいません。私の言い間違いでした。","slip of the tongue"];
EXAMPLES[5314]=["She would not disclose the secret.","彼女はどうしても秘密を明かさなかった。","disclose"];
EXAMPLES[5323]=["It is right up his alley.","彼にはそんなことはお手の物だ。","alley"];
EXAMPLES[5324]=["She was shivering with cold.","彼女は寒さで震えていた。","shivering"];
EXAMPLES[5325]=["I felt inadequate to the task.","私はその仕事に向かないと思った。","inadequate"];
EXAMPLES[5330]=["He was stumped by the problem.","彼はその問題で閉口していた。","stumped"];
EXAMPLES[5334]=["A seat became vacant at that station.","その駅で席が一つ空いた。","vacant"];
EXAMPLES[5338]=["I was compelled to do the work alone.","私は一人でその仕事を無理矢理させられた。","compelled"];
EXAMPLES[5342]=["Bear down in one's studies.","勉強に身を入れる。","Bear down"];
EXAMPLES[5344]=["He is proficient in English.","英語に熟達している。","proficient"];
EXAMPLES[5347]=["These books are accessible to all students.","ここの本は学生が誰でも利用できます。","accessible"];
EXAMPLES[5358]=["I caught a glimpse of him from the bus.","私はバスから彼をちらりと見た。","glimpse"];
EXAMPLES[5359]=["I made a fuss of her family.","僕は彼女の家族を大いにもてなしたよ。","fuss"];
EXAMPLES[5362]=["Should I insert coins first?","お金を先に入れるのですか。","insert"];
EXAMPLES[5364]=["Her success was due to sheer hard work.","彼女の成功は全くの熱心な努力のおかげであった。","sheer"];
EXAMPLES[5365]=["To begin with, we have no money now.","初めに、我々には今お金がない。","To begin with"];
EXAMPLES[5371]=["Too much rest is rust.","休みすぎは錆びる。","rust"];
EXAMPLES[5375]=["He has transmitted all his knowledge to his son.","彼は息子にすべての知識を伝えた。","transmitted"];
EXAMPLES[5380]=["You always talk back to me, don't you?","君はいつも言い返す。","talk back to"];
EXAMPLES[5381]=["I am depressed by my illness.","私は病気のために憂うつだ。","depressed"];
EXAMPLES[5384]=["I am looking forward very much to the school excursion.","私は修学旅行を大変楽しみにしている。","excursion"];
EXAMPLES[5386]=["My father is getting bald.","父は頭がはげてきている。","bald"];
EXAMPLES[5387]=["She is muttering to herself.","彼女はひとりでブツブツ言っている。","muttering"];
EXAMPLES[5388]=["You'd better back off.","手を引いた方がいいよ。","back off"];
EXAMPLES[5393]=["Cooperate with your friends in doing the work.","その仕事をするの友人と協力しなさい。","Cooperate"];
EXAMPLES[5394]=["Were you sober at that time?","あの時は素面だったのですか。","sober"];
EXAMPLES[5396]=["She is envious of my success.","彼女は私の成功をねたんでいる。","envious"];
EXAMPLES[5403]=["I marvel how you could agree to the proposal.","君がなぜ提案に賛成なのか不思議だ。","marvel"];
EXAMPLES[5407]=["She endeavored to live up to their expectations.","彼女は彼らの期待にそうよう努力した。","endeavored"];
EXAMPLES[5408]=["I will just hang around here for a while.","僕はしばらくここにいるよ。","hang around"];
EXAMPLES[5409]=["He is a physicist.","彼は物理学者だ。","physicist"];
EXAMPLES[5412]=["I have been writing this manuscript for a year.","私はこの一年原稿を書いている。","manuscript"];
EXAMPLES[5415]=["You will banish him.","あなたは彼を追放するだろう。","banish"];
EXAMPLES[5417]=["We must conform to the rules.","私達は規則には従わなければならない。","conform to"];
EXAMPLES[5418]=["The new team has the capability to win.","新しいチームには優勝する力がある。","capability"];
EXAMPLES[5419]=["What if he should happen to come late?","もし万一彼が遅れて来たらどうしよう。","What if"];
EXAMPLES[5420]=["We encourage your participation.","あなたの参加をお待ちしています。","participation"];
EXAMPLES[5423]=["The English are known for their courtesy.","イギリス人は礼儀正しいことで知られている。","courtesy"];
EXAMPLES[5427]=["Stand the ladder against the wall.","はしごを壁に立てかけなさい。","ladder"];
EXAMPLES[5429]=["I tried to ask her a riddle.","私は彼女に謎かけをしてみた。","riddle"];
EXAMPLES[5435]=["The family has been cursed with poor health.","その家族は病気で苦しんでいる。","cursed"];
EXAMPLES[5439]=["He isn't a man to take a bribe.","彼はわいろを取るような人ではない。","bribe"];
EXAMPLES[5441]=["Don't go against your father.","お父さんに逆らってはいけない。","go against"];
EXAMPLES[5447]=["I look to him for help.","私は彼の助けをあてにしています。","look to"];
EXAMPLES[5448]=["What will become of the world thirty years hence?","今から３０年後に世界はどうなるだろう？","hence"];
EXAMPLES[5449]=["You need to have a stool examination.","検便をする必要があります。","stool"];
EXAMPLES[5454]=["Cross out the incorrect words.","正しくない語は消しなさい。","Cross out"];
EXAMPLES[5457]=["At last, the gem was in his hands.","ついに彼はその宝石を手に入れた。","gem"];
EXAMPLES[5464]=["He will live up to his father's expectations.","彼は父の期待にこたえるだろう。","live up to"];
EXAMPLES[5467]=["How many idioms have we studied so far?","今まで私たちは熟語をいくつ勉強しましたか。","idioms"];
EXAMPLES[5470]=["The earth revolves on its axis.","地球は自転している。","revolves"];
EXAMPLES[5474]=["He is a man of intellect.","彼は知的な人です。","intellect"];
EXAMPLES[5475]=["I can only speak for myself.","私は自分に関してのことだけしかいえない。","speak for"];
EXAMPLES[5477]=["We had a heavy rainfall last night.","昨夜は激しい雨が降った。","rainfall"];
EXAMPLES[5484]=["French has many more vowels than Japanese.","フランス語には日本語よりずっと多くの母音がある。","vowels"];
EXAMPLES[5485]=["A man cannot be made in a mold.","人間は鋳型に入れて作るわけにはいかない。","mold"];
EXAMPLES[5487]=["I saw the ship sink in the sea.","私は船が海に沈むのを見た。","sink in"];
EXAMPLES[5494]=["The failure in business left me penniless.","仕事に失敗して私は文無しになった。","penniless"];
EXAMPLES[5499]=["What are the dimensions of the room?","その部屋の大きさはどれぐらいですか。","dimensions"];
EXAMPLES[5501]=["Jane makes the utmost effort to win.","ジェーンは勝つためにこの上ない努力をする。","utmost"];
EXAMPLES[5507]=["I have a pricking pain here.","ここがちくちく痛みます。","pricking"];
EXAMPLES[5514]=["We are taking a fortnight's holiday.","私たちは２週間の休暇をとります。","fortnight"];
EXAMPLES[5516]=["Today is my second day of my side job.","アルバイトを始めて今日で２日目です。","side job"];
EXAMPLES[5519]=["She gave a narrative of her strange experience.","彼女は自分の奇妙な経験を語った。","narrative"];
EXAMPLES[5520]=["She has scorn for me.","彼女は私を軽蔑している。","scorn"];
EXAMPLES[5521]=["It is said that she looked after the orphan.","彼女はその孤児の世話をしたそうです。","orphan"];
EXAMPLES[5530]=["The weather's rather jolly today.","今日は随分気持ちのいい天気だ。","jolly"];
EXAMPLES[5531]=["You should persist in your efforts to learn English.","あなたは英語を学ぶ努力をずっと続けるべきです。","persist"];
EXAMPLES[5535]=["Did you make out what he said?","彼の言うことがわかったか。","make out"];
EXAMPLES[5542]=["Never make a nuisance of yourself.","迷惑にならないようにしなさい。","nuisance"];
EXAMPLES[5546]=["He looks very vigorous, considering his age.","年の割には、彼はとても元気そうである。","vigorous"];
EXAMPLES[5551]=["He was absent owing to illness.","彼は病気のため欠席した。","owing"];
EXAMPLES[5552]=["They are very interested in astronomy.","彼らは天文学に非常に興味を持っている。","astronomy"];
EXAMPLES[5555]=["Go and sit by your father.","お父さんのそばに座りなさい。","sit by"];
EXAMPLES[5556]=["Take care lest you should fall asleep.","眠ってしまわないように気をつけなさい。","lest"];
EXAMPLES[5558]=["Stick with it and you'll succeed.","成功するまでへこたれるな。","Stick with"];
EXAMPLES[5562]=["I have a graze here.","ここにすり傷があります。","graze"];
EXAMPLES[5574]=["Do you eat seaweed in your country?","あなたの国では海草を食べますか。","seaweed"];
EXAMPLES[5576]=["It's folly to eat so much.","そんなにたくさん食べるのはばかげたことだ。","folly"];
EXAMPLES[5581]=["I've never heard anything more dreadful.","こんな恐ろしいことは聞いたことがない。","dreadful"];
EXAMPLES[5595]=["This box is a trifle too heavy.","この箱は少し重すぎる。","trifle"];
EXAMPLES[5601]=["Your plan must fit in with mine.","あなたの計画を私に合わせなさい。","fit in"];
EXAMPLES[5607]=["The doctor felt my pulse.","医者は私の脈をとった。","pulse"];
EXAMPLES[5608]=["I can testify to that.","私はそれを立証する。","testify"];
EXAMPLES[5611]=["Bob became a pastor.","ボブは牧師になりました。","pastor"];
EXAMPLES[5613]=["The seasoning is just right.","いい塩梅だ。","seasoning"];
EXAMPLES[5618]=["Two and three halves to London, please.","ロンドン行き大人２枚子供３枚ください。","halves"];
EXAMPLES[5619]=["This book should be read with diligence.","この本は丹念に読まなければならない。","diligence"];
EXAMPLES[5624]=["This information is confidential.","この情報は秘密です。","confidential"];
EXAMPLES[5628]=["He embarked on a new study.","彼は新しい研究に乗り出した。","embarked"];
EXAMPLES[5629]=["What a queer story!","なんて奇妙な話だろう。","queer"];
EXAMPLES[5630]=["Bad weather oppressed me.","ひどい天気でまいった。","oppressed"];
EXAMPLES[5631]=["We aided him in his business.","私たちは彼の仕事を援助した。","aided"];
EXAMPLES[5635]=["Subtract three from eight and you get five.","８から３を引けば５になる。","Subtract"];
EXAMPLES[5645]=["They are of kin to each other.","彼らは互いに親類関係にある。","kin"];
EXAMPLES[5657]=["No one will be caught by his flattery.","彼のお世辞にはだれものらない。","flattery"];
EXAMPLES[5660]=["Our school is situated on a hill.","私達の学校は丘の上にある。","situated"];
EXAMPLES[5663]=["I could recite the story by heart.","私はその話を暗唱することができた。","recite"];
EXAMPLES[5665]=["His proposal is out of the question.","彼の提案は問題にならない。","out of the question"];
EXAMPLES[5669]=["You had better go by tram.","電車で行った方がよい。","tram"];
EXAMPLES[5670]=["The work should let up by a week from today.","仕事は来週の今日までに一段落するはずです。","let up"];
EXAMPLES[5678]=["I hope the bus will come before long.","バスが早く来るといいが。","come before"];
EXAMPLES[5686]=["The problem perplexed him.","その問題は彼を悩ませた。","perplexed"];
EXAMPLES[5689]=["Will you please lend me a stapler?","ホッチキスを貸してくれませんか。","stapler"];
EXAMPLES[5693]=["It was a revelation to me.","それは私にとって意外な話だった。","revelation"];
EXAMPLES[5694]=["Thereafter we heard no more from him.","その後彼からは便りが無かった。","Thereafter"];
EXAMPLES[5697]=["I'll stand up for you.","私はあなたを支持します。","up for"];
EXAMPLES[5700]=["That's just a yarn.","それはただの作り話だ。","yarn"];
EXAMPLES[5708]=["How does the preface run?","序文にはなんと書いてありますか。","preface"];
EXAMPLES[5710]=["He was tumbled out of the car.","彼は車から放りだされた。","tumbled"];
EXAMPLES[5711]=["He is no better than a fool.","彼はでくの坊にすぎない。","no better than"];
EXAMPLES[5712]=["He contemplated taking a trip to Paris.","彼はパリへ行こうともくろんでいた。","contemplated"];
EXAMPLES[5713]=["The fire devoured the town.","その火事は町を焼き尽くした。","devoured"];
EXAMPLES[5714]=["We have a traitor among us.","我々の中に裏切り者がいる。","traitor"];
EXAMPLES[5716]=["You're so set in your ways!","あなたって本当に頑固ね。","set in"];
EXAMPLES[5721]=["The students adore the new English teacher.","生徒たちはその新しい英語の先生にあこがれている。","adore"];
EXAMPLES[5722]=["Please point out my mistake.","私の誤りを指摘して下さい。","point out"];
EXAMPLES[5723]=["He was so angry that his veins stood out.","彼は青筋を立てて怒った。","veins"];
EXAMPLES[5731]=["I decided to make medicine my vocation.","私は医者を職業とすることに決めた。","vocation"];
EXAMPLES[5734]=["It's time you had a dose of your medicine.","もう薬を一服飲む時間ですよ。","dose"];
EXAMPLES[5735]=["Could you send me a brochure?","案内書を送ってもらえますか。","brochure"];
EXAMPLES[5736]=["She could not refrain from tears.","彼女は涙をこらえることが出来なかった。","refrain"];
EXAMPLES[5748]=["There's a lot of glare.","太陽の照り返しが強い。","glare"];
EXAMPLES[5750]=["Nobody can surpass him.","誰も彼には勝てない。","surpass"];
EXAMPLES[5751]=["The time will come when she will repent of it.","彼女がそれを後悔する時が来るだろう。","repent"];
EXAMPLES[5755]=["No one shall dictate to me.","私は誰の指図も受けない。","dictate"];
EXAMPLES[5772]=["Spring is just around the corner.","春はすぐそこまで来ている。","just around the corner"];
EXAMPLES[5776]=["Do you take pride in your work?","自分の仕事に誇りを持ってますか。","take pride in"];
EXAMPLES[5779]=["I feel a bit feverish tonight.","今晩は少し熱っぽいのです。","feverish"];
EXAMPLES[5780]=["Are you the prophet?","あなたは預言者ですか。","prophet"];
EXAMPLES[5782]=["He contradicted the news.","彼はそのニュースを否定した。","contradicted"];
EXAMPLES[5783]=["You must stick to your promise.","君はあくまでも約束を守らなければならない。","stick to"];
EXAMPLES[5788]=["I make it a rule to get up early in the morning.","毎朝早起きするのを習慣にしている。","make it"];
EXAMPLES[5795]=["He studied hard in order to get into college.","彼は大学に入れるように一生懸命勉強した。","get into"];
EXAMPLES[5800]=["He did it with great zeal.","彼はとても熱心にそれをやった。","zeal"];
EXAMPLES[5808]=["I like to adorn her room with flowers.","私は部屋を花で飾るのが好きだ。","adorn"];
EXAMPLES[5818]=["All the flowers in the garden withered.","庭の花はすべて枯れた。","withered"];
EXAMPLES[5819]=["He is enchanted by the girl's beauty.","彼はその女性の美しさにうっとりしている。","enchanted"];
EXAMPLES[5823]=["The eyes are as eloquent as the tongue.","目は口ほどに物を言う。","eloquent"];
EXAMPLES[5826]=["She became reconciled with her friend.","彼女は友達と仲直りした。","reconciled"];
EXAMPLES[5829]=["My eyes are dazzled by the sun.","太陽がまぶしい。","dazzled"];
EXAMPLES[5830]=["I will go regardless of the weather.","私は天気に関係なく行くだろう。","regardless of"];
EXAMPLES[5836]=["They lamented the death of their father.","彼らは父親の死を哀しんだ。","lamented"];
EXAMPLES[5839]=["Your answer is to the point.","君の答えは適切である。","to the point"];
EXAMPLES[5845]=["She's disgusted with the job.","彼女はその仕事にうんざりしている。","disgusted"];
EXAMPLES[5846]=["She excels her class in music.","彼女は音楽ではクラスの誰よりも優れている。","excels"];
EXAMPLES[5849]=["Could you put your seat back up a little?","倒した座席の背を少し戻していただけますか。","back up"];
EXAMPLES[5855]=["The riot got out of hand.","暴動は手がつけられなくなった。","riot"];
EXAMPLES[5857]=["Their married life was full bliss.","彼らの結婚生活は幸福で満たされていた。","bliss"];
EXAMPLES[5866]=["It's insanely hot today.","今日はばかに暑い。","insanely"];
EXAMPLES[5872]=["I always have to give in to him.","私はいつも彼に服従しなければならない。","give in"];
EXAMPLES[5874]=["She gave her oath that she would not drink.","彼女は酒をやめると誓った。","oath"];
EXAMPLES[5876]=["His plan was discarded.","彼の計画は退けられた。","discarded"];
EXAMPLES[5878]=["Your efforts will soon pay off.","君の努力はもうじき実るだろう。","pay off"];
EXAMPLES[5884]=["He avoided the bait.","彼はその手にはのらなかった。","bait"];
EXAMPLES[5886]=["With all her faults, I still like her.","彼女には欠点があるけど、私は彼女が好きだ。","With all"];
EXAMPLES[5900]=["All the students will partake in the play.","学生全員が劇に参加しています。","partake"];
EXAMPLES[5901]=["You must avail yourself of every opportunity.","あらゆる機会を利用せよ。","avail"];
EXAMPLES[5902]=["He slumbered out the whole day.","彼は一日中うとうとしていた。","slumbered"];
EXAMPLES[5908]=["My hair is so messy!","髪がめちゃくちゃ！！","messy"];
EXAMPLES[5909]=["He sipped the hot coffee slowly.","彼は熱いコーヒーをゆっくりすすった。","sipped"];
EXAMPLES[5912]=["Beware! there's a car coming!","気をつけて！車が来るから。","Beware"];
EXAMPLES[5913]=["He is a man to be reckoned with.","彼は無視できない人だ。","reckoned"];
EXAMPLES[5923]=["Two can play at that game.","そのゲームなら相手になろう。","play at"];
EXAMPLES[5927]=["Have you finished writing your thesis?","論文を書き終えましたか。","thesis"];
EXAMPLES[5928]=["She became drowsy after supper.","彼女は夕食後眠くなった。","drowsy"];
EXAMPLES[5940]=["Do you have a vacancy?","空き部屋はありますか。","vacancy"];
EXAMPLES[5943]=["He is very sullen now.","彼は今、とっても不機嫌だ。","sullen"];
EXAMPLES[5945]=["He propped his bike against the wall.","彼は自転車を壁に立てかけた。","propped"];
EXAMPLES[5947]=["I can't forsake a friend in trouble.","困っている友人を見捨てることはできない。","forsake"];
EXAMPLES[5950]=["She had an itch to see her child.","彼女は子供に会いたくてたまらなかった。","itch"];
EXAMPLES[5952]=["Nobody can foresee when the war will end.","いつ戦争が終わるかだれにも予見できない。","foresee"];
EXAMPLES[5956]=["She will fail eventually.","結局は、彼女も、失敗するだろう。","eventually"];
EXAMPLES[5957]=["The news paralyzed him.","そのニュースを聞いて彼はぼうぜんとした。","paralyzed"];
EXAMPLES[5961]=["He is alleged to have been a thief.","彼は泥棒だったそうだ。","alleged"];
EXAMPLES[5966]=["Mary was scornful of Tom.","メアリーはトムを馬鹿にしていた。","scornful"];
EXAMPLES[5969]=["They were flushed with success.","彼は成功して得意になった。","flushed"];
EXAMPLES[5970]=["I don't like to take on the heavy responsibilities.","私はその重い責任を引き受けたくはない。","take on"];
EXAMPLES[5974]=["She is gracious to everyone.","彼女は誰にも優しい。","gracious"];
EXAMPLES[5984]=["I will carry through the work.","私は、その仕事をやり遂げるでしょう。","carry through"];
EXAMPLES[5992]=["He is clumsy with his hands.","彼は手が不器用だ。","clumsy"];
EXAMPLES[5998]=["The dog growled at a little boy.","その犬は小さな男の子に向かって唸った。","growled"];
EXAMPLES[6002]=["You should always apologize in person.","いつでも自分で謝るべきだ。","in person"];
EXAMPLES[6004]=["He made amends for his mistakes.","彼は失敗の償いをした。","amends"];
EXAMPLES[6005]=["The news gratified us.","その知らせを聞いて私たちは喜んだ。","gratified"];
EXAMPLES[6009]=["They furnished the library with many books.","彼らは図書館に多くの本を備え付けた。","furnished"];
EXAMPLES[6010]=["There was no malice in what he did.","悪意でしたのではない。","malice"];
EXAMPLES[6016]=["Tom happened to let out the secret to his friends.","トムはたまたま友人たちにその秘密を漏らしてしまった。","let out"];
EXAMPLES[6017]=["The plane will get in on time.","飛行機は定刻に到着するでしょう。","get in on"];
EXAMPLES[6019]=["He is boastful of his success.","彼は自分の成功を鼻にかけている。","boastful"];
EXAMPLES[6020]=["It is in order to hear your voice well.","それは、おまえの声をよく聞くためだよ。","in order"];
EXAMPLES[6021]=["If you do that, you're going to subject yourself to ridicule.","そんなことをすれば笑いものの種なるよ。","ridicule"];
EXAMPLES[6023]=["These shoes will stand up to hard use.","この靴はどんなに乱暴にはいても大丈夫です。","stand up to"];
EXAMPLES[6030]=["He reproached me for carelessness.","彼は不注意だと私をしかった。","reproached"];
EXAMPLES[6033]=["Don't tell on me.","僕の告げ口をするな。","tell on"];
EXAMPLES[6034]=["Pay heed to your food.","食物に注意してください。","heed"];
EXAMPLES[6043]=["I couldn't catch on to the joke he told us.","私は彼のジョークが理解できなかった。","catch on"];
EXAMPLES[6044]=["This is a hazard to your health.","これはあなたの健康にとって危険なものだ。","hazard"];
EXAMPLES[6055]=["We like to look feminine.","私達は女性らしく見せたい。","feminine"];
EXAMPLES[6067]=["This river is not polluted.","この川は汚染されていない。","polluted"];
EXAMPLES[6070]=["The post office is just across from the store.","郵便局はあの店のちょうど真向かいにあります。","across from"];
EXAMPLES[6071]=["A storm is brewing.","嵐が起ころうとしている。","brewing"];
EXAMPLES[6074]=["I see the tower from my house.","家からその塔が見える。","tower"];
EXAMPLES[6076]=["He is in anguish over her child.","彼は子供のことでひどく悩んでいる。","anguish"];
EXAMPLES[6078]=["It's time to leave off work.","仕事を辞めるべき時間だ。","leave off"];
EXAMPLES[6082]=["Didn't you lock up your car?","車に鍵をかけておかなかったの？","lock up"];
EXAMPLES[6084]=["She set off on a trip last week.","彼女は先週旅行に出かけた。","set off"];
EXAMPLES[6088]=["He was bewildered on that day.","その日彼は困惑した。","bewildered"];
EXAMPLES[6093]=["All the other issues are subordinate to this one.","他の問題はこの問題ほど重要ではない。","subordinate"];
EXAMPLES[6101]=["He lured her away from her husband.","彼女を夫の手からおびき出した。","lured"];
EXAMPLES[6107]=["He always speaks at random.","彼はいつも口からでまかせを言う。","at random"];
EXAMPLES[6135]=["A life barren of pleasure.","楽しみのない生活。","barren"];
EXAMPLES[6137]=["My opinion doesn't count for much at the office.","私の意見は会社では買ってくれない。","count for"];
EXAMPLES[6142]=["The man was on the brink of death.","その男は死にかけていた。","brink"];
EXAMPLES[6146]=["I am relying on you to be honest.","私はあなたが正直であると信頼しています。","to be honest"];
EXAMPLES[6147]=["Everyone is an entrepreneur.","だれもが「企業家」なのである。","entrepreneur"];
EXAMPLES[6153]=["The two of them split up.","二人は別れたんだ。","split up"];
EXAMPLES[6156]=["I often call on him.","私はたびたび彼を訪ねます。","call on"];
EXAMPLES[6163]=["Can you get by on your wages?","君は今の給料でやって行けるか。","wages"];
EXAMPLES[6175]=["She was aging quickly.","彼女は急に老け込んできた。","aging"];
EXAMPLES[6180]=["His ideas are up to date.","彼の考えは新しい。","to date"];
EXAMPLES[6185]=["Mother transplanted the flowers to the garden.","母は庭へ花を移植した。","transplanted"];
EXAMPLES[6186]=["Look out for pickpockets.","すりに注意しなさい。","pickpockets"];
EXAMPLES[6191]=["In the first place, we must be careful about what we eat and drink.","第一に飲食に注意しなければならない。","In the first place"];
EXAMPLES[6201]=["The man was held in police custody.","その男は拘留された。","custody"];
EXAMPLES[6205]=["Will you notify me after 3 minutes?","３分たったら教えてもらえますか。","notify"];
EXAMPLES[6208]=["The baseball match will come off next week.","その野球の試合は来週行われる。","come off"];
EXAMPLES[6214]=["Is there any likelihood of his coming?","彼が来る見込みはありますか。","likelihood"];
EXAMPLES[6231]=["It is money that many people worship most.","多くの人が最も崇拝するものはお金である。","worship"];
EXAMPLES[6232]=["You must hold up your hands.","あなたは、手をあげなければならない。","hold up"];
EXAMPLES[6240]=["He is alleged to have been a thief.","彼は泥棒だったそうだ。","alleged"];
EXAMPLES[6243]=["Her car collided with a bus from behind.","彼女の車はバスに追突した。","collided"];
EXAMPLES[6251]=["I am in a terrible dilemma.","これは困ったことになった。","dilemma"];
EXAMPLES[6259]=["He has been speculating on his future.","彼は自分の将来について思い巡らせていた。","speculating"];
EXAMPLES[6269]=["Suffice it to say that, after all, this won't do.","結局これでは駄目だとだけ言っておこう。","Suffice"];
EXAMPLES[6273]=["I think you have the wrong number.","番号を間違っていると思います。","number"];
EXAMPLES[6278]=["She is considerate of others.","彼女は他人に思いやりがある。","considerate"];
EXAMPLES[6279]=["His son was expelled from school.","その息子は放校された。","expelled"];
EXAMPLES[6290]=["You look very dignified.","貫禄がついたね。","dignified"];
EXAMPLES[6297]=["The boy went down the river on a raft.","少年たちはいかだで川をくだった。","raft"];
EXAMPLES[6298]=["The fire was extinguished at once.","火事はただちに消された。","extinguished"];
EXAMPLES[6303]=["I couldn't take in the lecture at all.","私はその講義が全く理解できなかった。","take in"];
EXAMPLES[6308]=["What do your words add up to?","結局お言葉はどういう意味になるのですか。","add up to"];
EXAMPLES[6309]=["Her eyes gushed with tears.","彼女の目には涙が湧きあふれていた。","gushed"];
EXAMPLES[6321]=["He is going to run for the presidency.","彼は大統領に立候補するだろう。","presidency"];
EXAMPLES[6322]=["I have a hangover today.","今日は、私は二日酔いだ。","hangover"];
EXAMPLES[6323]=["Until what time does your pharmacy stay open?","薬局は何時まで開いていますか。","pharmacy"];
EXAMPLES[6329]=["All students have access to the library.","全学生はみんな図書館に入ることができる。","have access to"];
EXAMPLES[6331]=["She spent her life in pursuit of the truth.","彼女は一生を真実を追い求めて過ごした。","in pursuit of"];
EXAMPLES[6332]=["Fish abound in this lake.","この湖には魚が多い。","abound"];
EXAMPLES[6350]=["He has integrity, so he has many friends.","彼は正直なのでたくさん友達がいる。","integrity"];
EXAMPLES[6352]=["Men are subject to temptation.","人間は誘惑にかかりやすい。","subject to"];
EXAMPLES[6354]=["They could barely make ends meet.","彼らは生きていくのがやっとだった。","make ends meet"];
EXAMPLES[6355]=["I shudder to think of it.","それを考えるとぞっとする。","shudder"];
EXAMPLES[6356]=["I feel for you deeply.","わたしは深く同情します。","feel for"];
EXAMPLES[6375]=["We ascertained her dead.","我々は彼女が死んだことを確かめた。","ascertained"];
EXAMPLES[6377]=["They are very compatible.","彼ら二人はよく肌が合う。","compatible"];
EXAMPLES[6384]=["Close things look blurred.","近くの物がかすんで見えます。","blurred"];
EXAMPLES[6385]=["The prophecy came to pass.","その予言は本当になった。","prophecy"];
EXAMPLES[6389]=["He was held in captivity.","彼は捕虜になった。","captivity"];
EXAMPLES[6406]=["Please conserve water in summer.","夏には節水して下さい。","conserve"];
EXAMPLES[6412]=["I can't do with his arrogance.","彼の傲慢さには我慢できない。","arrogance"];
EXAMPLES[6416]=["All at once the ship left the pier.","突然船は埠頭を離れた。","pier"];
EXAMPLES[6417]=["Here were some relics.","ここにいくつかの遺跡がありました。","relics"];
EXAMPLES[6428]=["He was humiliated by her.","彼は彼女に恥をかかされた。","humiliated"];
EXAMPLES[6441]=["The walls close in on me.","壁が迫ってくる。","close in"];
EXAMPLES[6465]=["Will you take your hand off me?","私から手を離してくださらない？","hand off"];
EXAMPLES[6469]=["She works as hard as her siblings.","彼女は兄弟たちと同じくらい一生懸命に働く。","siblings"];
EXAMPLES[6476]=["The rich are often misers.","金持ちはけちであることが多い。","misers"];
EXAMPLES[6485]=["I dissent from what he said.","私は彼の言ったことに反対する。","dissent"];
EXAMPLES[6515]=["Do you like baseball, bin?","ビンは野球が好きですか。","bin"];
EXAMPLES[6516]=["It is inconceivable to me that he would do such a thing.","彼がそんなことをするなんて私には考えられない。","inconceivable"];
EXAMPLES[6528]=["Don't let the children monopolize the television.","子供たちにテレビを独占させるな。","monopolize"];
EXAMPLES[6532]=["His novel had a great vogue for a long time.","彼の小説は長い間たいへん人気があった。","vogue"];
EXAMPLES[6540]=["Let it all hang out.","気楽にしよう。","hang out"];
EXAMPLES[6548]=["He has the subject at his fingertips.","彼はその問題に精通している。","fingertips"];
EXAMPLES[6550]=["A baby craves its mother's milk.","赤ん坊は母乳を欲しがる。","craves"];
EXAMPLES[6553]=["She is amiable to everybody.","彼女はだれにでも愛想がいい。","amiable"];
EXAMPLES[6555]=["There is no precedent for such a case.","このような問題の前例はない。","precedent"];
EXAMPLES[6561]=["When spring arrives, I'm going to take up a new sport.","春になったら新しいスポーツを始めるつもりです。","take up"];
EXAMPLES[6571]=["My advice is predicated on my experience.","私の忠告は、私の経験に基づいている。","predicated"];
EXAMPLES[6572]=["She told the child to eat up the food.","彼女は子供に食べ物を食べてしまうように言った。","eat up"];
EXAMPLES[6579]=["Stop pestering me, I'm busy.","いいかげんにしてくれよ忙しいから。","pestering"];
EXAMPLES[6601]=["Try to bring out the best in him.","彼のいいところを引き出すようにしなさい。","bring out"];
EXAMPLES[6604]=["We haven't seen her of late.","最近彼女を見かけない。","haven"];
EXAMPLES[6610]=["Tokyo is more populous than any other city in Japan.","東京は日本の他のどの都市よりも人口が多い。","populous"];
EXAMPLES[6613]=["Please bear this fact in mind.","この事実を心に留めておいて下さい。","in mind"];
EXAMPLES[6620]=["Don't cut in while we're talking.","僕たちの話の邪魔をするなよ。","cut in"];
EXAMPLES[6622]=["Do you often have fish for dinner?","ディナーによく魚を食べますか。","dinner"];
EXAMPLES[6625]=["They obstructed our plan.","彼らは我々の計画を邪魔した。","obstructed"];
EXAMPLES[6632]=["Their morale is high.","彼らはやる気がある。","morale"];
EXAMPLES[6641]=["He stood aloof from her.","彼は彼女から離れていた。","aloof"];
EXAMPLES[6647]=["She is very cynical about life.","彼女は人生に対してとても冷笑的だ。","cynical"];
EXAMPLES[6653]=["His opinion comes into conflict with mine.","彼の意見は私のと合わない。","conflict with"];
EXAMPLES[6656]=["I'm afraid I have an inflammation in my eyes.","目が炎症を起こしているようですが。","inflammation"];
EXAMPLES[6660]=["He has her on a pedestal.","彼は彼女をあがめたてています。","pedestal"];
EXAMPLES[6669]=["Why don't you stop by for a little while?","ちょっと寄ってかない？","stop by"];
EXAMPLES[6674]=["I don't know what to do about his shoplifting.","彼の万引きはどうしたものかわからない。","shoplifting"];
EXAMPLES[6679]=["I'll be damned if it's true.","そんなことが本当でたまるか。","damned"];
EXAMPLES[6691]=["The lake was adjacent to his house.","湖が彼の家のそばにあった。","adjacent"];
EXAMPLES[6698]=["You must persevere before you can succeed.","辛抱しなければ成功することはできない。","persevere"];
EXAMPLES[6705]=["He went as far as to call you a hypocrite.","彼は君のことを偽善者とまで言った。","hypocrite"];
EXAMPLES[6723]=["Please sum up your idea.","君の考えを要約して下さい。","sum up"];
EXAMPLES[6737]=["A chauffeur sat in front.","前の席に運転手が座っていた。","chauffeur"];
EXAMPLES[6748]=["You should go over a house before buying it.","あなたは家を買う前に良く調べるべきだ。","go over"];
EXAMPLES[6754]=["The train is 30 minutes overdue.","列車は３０分遅れている。","overdue"];
EXAMPLES[6759]=["They renounced their son.","彼らは息子を勘当した。","renounced"];
EXAMPLES[6761]=["I have a lot of problems at the moment.","私は今たくさんの問題を抱えている。","at the moment"];
EXAMPLES[6776]=["This dictionary is great boon up to us.","この辞書は私たちにとってありがたいものだ。","boon"];
EXAMPLES[6778]=["Many a true word is spoken in jest.","嘘から出た真実。","jest"];
EXAMPLES[6782]=["Who broke that pane of glass?","誰が窓ガラスを割ったのだろう。","pane"];
EXAMPLES[6788]=["It is not mine to foretell the future.","将来を予見するのは私の責任ではない。","foretell"];
EXAMPLES[6795]=["I want to eat French cuisine.","フランス料理が食べたいです。","cuisine"];
EXAMPLES[6812]=["No one can avert death.","人間は誰しも死を避けられない。","avert"];
EXAMPLES[6814]=["They cannot do without camels in this country.","この国では、ラクダはなくてはならない。","camels"];
EXAMPLES[6823]=["Down came the rain in torrents.","ざあっと雨が降ってきた。","torrents"];
EXAMPLES[6831]=["Last night I began to nod off in front of the tv.","昨夜、私はテレビの前で居眠りをしてしまった。","nod off"];
EXAMPLES[6841]=["He often spends his time idly.","彼はよく時間を無駄に過ごす。","idly"];
EXAMPLES[6857]=["The town was exactly the same as before.","そのまちは昔のままだった。","as before"];
EXAMPLES[6866]=["He was agitated by the news.","彼はその知らせに心を乱した。","agitated"];
EXAMPLES[6867]=["I thought you'd jump at the chance.","喜んでとびつくかと思ったけど。","jump at"];
EXAMPLES[6876]=["She pondered the question for a while.","彼女はしばらくの間その問題を熟考した。","pondered"];
EXAMPLES[6879]=["She was radiant with love.","彼女は愛に輝いていた。","radiant"];
EXAMPLES[6881]=["I took a doze after coming home.","私は家に帰ってからうたた寝した。","doze"];
EXAMPLES[6889]=["I've become impotent.","不能になりました。","impotent"];
EXAMPLES[6890]=["He'll always come through.","彼ならいつでも力になってくれるよ。","come through"];
EXAMPLES[6895]=["She put her head out of the window.","彼女は窓から顔を出した。","head out"];
EXAMPLES[6907]=["Nothing is as great as maternal love.","母の愛ほど偉大なものはない。","maternal"];
EXAMPLES[6911]=["That's the way the cookie crumbles.","人生とはそんなものさ。","crumbles"];
EXAMPLES[6924]=["So, when are you going to break down and buy a house?","いつになったら家を買うつもりなの？","break down"];
EXAMPLES[6931]=["I feel like a brand new person.","とても気分がリフレッシュされる。","brand"];
EXAMPLES[6934]=["You've got to get down to your work.","落ちついて勉強しなくてはダメだよ。","get down to"];
EXAMPLES[6935]=["I have kidney trouble.","腎臓が悪いのです。","kidney"];
EXAMPLES[6937]=["Is there any hope whatsoever?","少しは希望があるのか。","whatsoever"];
EXAMPLES[6938]=["Would you like to come along?","君も一緒に来たいですか。","come along"];
EXAMPLES[6942]=["How long have you been alienated from your family?","君はいつから家族と疎遠になっているのか。","alienated"];
EXAMPLES[6944]=["They decided to put an end to the discussion.","彼らは議論をやめることに決めた。","put an end to"];
EXAMPLES[6945]=["They made a great tumult last night.","彼らは昨夜大騒ぎをした。","tumult"];
EXAMPLES[6946]=["Play out of doors on a fine day.","天気の良い日には外で遊びなさい。","Play out"];
EXAMPLES[6950]=["Do you get on with your friends?","友達と仲良くやっていますか。","get on with"];
EXAMPLES[6955]=["It isn't futile to go to university.","大学へ行くことは無駄ではない。","futile"];
EXAMPLES[6956]=["She entrusted her husband with a letter.","彼女は夫に手紙を預けた。","entrusted"];
EXAMPLES[6961]=["In hot weather, water evaporates quickly.","暑い日に水は早く蒸発する。","evaporates"];
EXAMPLES[6967]=["She could always call her parents when she was in a crunch.","彼女は困ったらいつも両親を呼ぶことができた。","crunch"];
EXAMPLES[6969]=["Nick didn't pass the exam, did he?","ニックは試験に合格しなかったのですね。","Nick"];
EXAMPLES[6982]=["I've been sluggish recently.","最近私、だれてるの。","sluggish"];
EXAMPLES[6993]=["I'm on a paid vacation.","今、有給休暇中だ。","paid vacation"];
EXAMPLES[7003]=["He was critical of me.","あの人は私には口うるさかった。","critical of"];
EXAMPLES[7006]=["He is the last person to give away the secret.","彼は秘密をもらすような人ではない。","give away"];
EXAMPLES[7028]=["He was impeded in his work.","彼は仕事の邪魔をされた。","impeded"];
EXAMPLES[7029]=["There are no hospitals in the vicinity of his house.","彼の家の近くには病院がない。","vicinity"];
EXAMPLES[7033]=["I got much benefit from that book.","その本から大いに得るところがあった。","benefit from"];
EXAMPLES[7035]=["My friend is opposed to my opinion.","友人は私の意見に反対だ。","opposed"];
EXAMPLES[7036]=["Has the sick child improved any?","病院の子どもは少しはよくなりましたか。","improved"];
EXAMPLES[7057]=["I'll abstain from going out today.","私は今日、外出することを控えよう。","abstain"];
EXAMPLES[7060]=["They will tear down the old building in two days.","彼らは２日でその古い建物を壊すでしょう。","tear down"];
EXAMPLES[7064]=["She will start her maternity leave next week.","彼女は来週から産休に入る。","maternity"];
EXAMPLES[7072]=["How long will it take for alterations?","直しはどれくらいかかりますか。","alterations"];
EXAMPLES[7073]=["You should inspect the car well before you buy it.","車を買う前によく調べてみたほうがいい。","inspect"];
EXAMPLES[7077]=["He was careful not to disrupt the meeting.","彼は会議を混乱させないように気をつけた。","disrupt"];
EXAMPLES[7080]=["Why does he look grumpy?","なぜ彼は不機嫌な顔をしてるんだい。","grumpy"];
EXAMPLES[7081]=["Stop chattering and finish your work.","おしゃべりはやめて仕事をすませなさい。","chattering"];
EXAMPLES[7088]=["The earth revolves on its axis.","地球は自転している。","axis"];
EXAMPLES[7089]=["How do you figure out this problem?","どうやってこの問題を解くのですか。","figure out"];
EXAMPLES[7090]=["I tried to soothe the child.","私はその子をなだめようとした。","soothe"];
EXAMPLES[7101]=["The English are a hardy people.","イギリス人は我慢強い国民だ。","hardy"];
EXAMPLES[7102]=["It is very courteous of you to call on me.","訪ねてきてくださって本当にありがとうございます。","courteous"];
EXAMPLES[7106]=["I was admonished against being late.","私は遅刻しないように注意された。","admonished"];
EXAMPLES[7107]=["He ascribed his success to hard work.","彼は自分の成功は努力したせいだと言った。","ascribed"];
EXAMPLES[7108]=["I like him in that he is honest and candid.","私は彼が正直で気さくであるから彼が好きだ。","candid"];
EXAMPLES[7112]=["All the traffic was brought to a standstill by the accident.","事故ですべての交通は止まった。","standstill"];
EXAMPLES[7125]=["It was a week of alternate snow and rain.","雨と雪が交互に降った一週間だった。","alternate"];
EXAMPLES[7128]=["The sky looks ominous. I wonder if it will rain.","空が怪しい。雨が降るかな。","ominous"];
EXAMPLES[7129]=["It is worthwhile to read the book.","その本は、読む価値がある。","worthwhile"];
EXAMPLES[7133]=["We must abide by the rules of the game.","私たちは試合の規則を守らねばならない。","abide by"];
EXAMPLES[7136]=["Let me see your wound.","傷口を見せてください。","wound"];
EXAMPLES[7141]=["Don't hinder me in my work.","私の仕事を邪魔しないでくれ。","hinder"];
EXAMPLES[7143]=["He finished his chores in no time.","彼はすぐに雑用を終えた。","chores"];
EXAMPLES[7144]=["Please don't mumble.","もごもご言うのはやめてください。","mumble"];
EXAMPLES[7147]=["She was on the verge of crying.","彼女は今にも泣き出しそうだった。","verge"];
EXAMPLES[7151]=["She was dismayed at the news.","彼女はその知らせに当惑した。","dismayed"];
EXAMPLES[7180]=["I am in accord with his view.","彼の意見に賛成だ。","accord"];
EXAMPLES[7181]=["I can't dispense with watching television.","私はテレビなしには過ごせない。","dispense"];
EXAMPLES[7182]=["I got a famous singer's autograph.","私は有名人のサインをもらった。","autograph"];
EXAMPLES[7197]=["He seems to have apprehensions of age.","彼は老後を心配しているようだ。","apprehensions"];
EXAMPLES[7204]=["The weather outlook for tomorrow is not good.","明日の天気は良くなるだろう。","outlook"];
EXAMPLES[7209]=["Water is essential to life.","水は生きていくのに不可欠である。","essential"];
EXAMPLES[7221]=["I have a phobia for that.","そういうのって恐いですね。","phobia"];
EXAMPLES[7222]=["He is no better than a thief.","彼は泥棒同然だ。","thief"];
EXAMPLES[7229]=["Where does it stop over?","経由地はどこですか。","stop over"];
EXAMPLES[7231]=["We are too busy to be idle.","私たちは忙しくてのらくらしていられない。","idle"];
EXAMPLES[7236]=["You will soon accustom yourself to the new life.","新生活にすぐに慣れますよ。","accustom"];
EXAMPLES[7238]=["We should put out a call for bids.","あいみつ取るべきだね。","bids"];
EXAMPLES[7243]=["He is competent for the job.","彼にはその仕事をする力量がある。","competent"];
EXAMPLES[7249]=["The boy was wandering about the town.","その少年は町をさまよっていた。","wandering"];
EXAMPLES[7250]=["She did not let failure discourage her.","失敗しても彼女は落胆しなかった。","discourage"];
EXAMPLES[7255]=["There is a gulf between our opinions.","私たちの意見は大きく違う。","gulf"];
EXAMPLES[7263]=["It is true that he went bankrupt.","彼が破産したというのは本当だ。","bankrupt"];
EXAMPLES[7268]=["His behavior did not correspond with his words.","彼の行動は言葉と一致していなかった。","correspond"];
EXAMPLES[7274]=["I adhered to my decision.","私は決して自分の決心を変えない。","adhered"];
EXAMPLES[7276]=["That old man is a fussy eater.","あの老人は食べ物に難しい。","fussy"];
EXAMPLES[7278]=["I'll abstain from going out today.","私は今日、外出することを控えよう。","abstain from"];
EXAMPLES[7282]=["The store is choked with customers.","店は客でいっぱいだ。","choked"];
EXAMPLES[7332]=["It is paramount to all the others.","それは他のいっさいに勝っている。","paramount"];
EXAMPLES[7335]=["Not all of the books are instructive.","その本のすべてがためになるわけではない。","instructive"];
EXAMPLES[7340]=["We hold out no expectation of success.","成功することはまったく期待してない。","hold out"];
EXAMPLES[7342]=["A burglar broke in while he was asleep.","彼が眠っている間に泥棒が入った。","burglar"];
EXAMPLES[7355]=["I have a hunch that it will rain.","雨が降るような気がする。","hunch"];
EXAMPLES[7377]=["I see life differently now.","今では人生に対する考え方が変わった。","differently"];
EXAMPLES[7402]=["Harry couldn't keep up with the class.","ハリーはクラスのみんなについていけなかった。","Harry"];
EXAMPLES[7403]=["I am forbidden to use this telephone.","私はこの電話を使うのを禁じられている。","forbidden"];
EXAMPLES[7407]=["His help has been invaluable.","彼の援助は非常に貴重なものであった。","invaluable"];
EXAMPLES[7414]=["I'm adamant that you should go.","君に行ってもらわねば承知しない。","adamant"];
EXAMPLES[7418]=["I have a bad sunburn.","日焼けし過ぎました。","sunburn"];
EXAMPLES[7424]=["You have come at an opportune time.","あなたはちょうどよい折に来た。","opportune"];
EXAMPLES[7432]=["The road ascends to the village.","道は上り坂になってその村に出る。","ascends"];
EXAMPLES[7457]=["Give me a hoist.","引き上げてくれ。","hoist"];
EXAMPLES[7468]=["I'll impart a secret to you.","君に秘密を打ち明けよう。","impart"];
EXAMPLES[7490]=["Few boys are dainty about their food.","男の子で食べ物にうるさいのは少ない。","dainty"];
EXAMPLES[7493]=["These shoes are a little loose.","この靴は少し緩い。","loose"];
EXAMPLES[7495]=["The young girl was haughty to me.","その若い娘は私に対して高慢だった。","haughty"];
EXAMPLES[7508]=["It's in your interest to go.","行くほうが君のためだ。","interest"];
EXAMPLES[7537]=["It is not necessary to be meticulous.","こせこせする必要はない。","meticulous"];
EXAMPLES[7546]=["They live in a wretched little house.","彼らはみすぼらしい小さな家に住んでいる。","wretched"];
EXAMPLES[7550]=["She beguiled me of my money.","彼女は私をだまして金を取った。","beguiled"];
EXAMPLES[7565]=["He is quite indifferent to money.","彼はお金には全く無頓着だ。","indifferent"];
EXAMPLES[7573]=["The cat was basking in the sun.","猫は日なたぼっこをしていた。","basking"];
EXAMPLES[7580]=["He is very stingy with his money.","彼はとてもけちだ。","stingy"];
EXAMPLES[7616]=["It is incumbent on you to do so.","そうするのはあなたの責任だ。","incumbent"];
EXAMPLES[7617]=["He has a wistful look on his face.","彼は悲しそうな顔つきをしている。","wistful"];
EXAMPLES[7624]=["I entreat you to go and see him.","どうか彼に会いに行ってください。","entreat"];
EXAMPLES[7626]=["She coaxed the letter out of her brother.","彼女はうまく弟からその手紙を取り上げた。","coaxed"];
EXAMPLES[7630]=["He avenged his friend on them.","彼は彼らに対して友人の復讐をした。","avenged"];
EXAMPLES[7633]=["His name eludes me.","その人の名を思い出せない。","eludes"];
EXAMPLES[7635]=["A storm is imminent.","今にも嵐になりそうだ。","imminent"];
EXAMPLES[7642]=["My urine is a little red.","尿が少し赤いです。","urine"];
EXAMPLES[7655]=["I was ushered to my seat.","私は自分の席まで案内してもらった。","ushered"];
EXAMPLES[7670]=["After the rain, there were puddles on the street.","雨のあと、道路に水溜まりができた。","puddles"];
EXAMPLES[7684]=["The children whirled about the garden.","子供達が庭をぐるぐる回っていた。","whirled"];
EXAMPLES[7712]=["The country fell into the invader's hand.","その国は侵略者の手に落ちた。","invader"];
EXAMPLES[7740]=["Who is going to sit in for you?","誰が君の代わりをするんだい。","sit in"];
EXAMPLES[7744]=["Clean out the room in the morning.","午前中に部屋をきれいに掃除しなさい。","Clean out"];
EXAMPLES[7765]=["He came to Tokyo in search of employment.","彼は仕事を求めて東京へやってきた。","in search of"];
EXAMPLES[7768]=["You can go to the ballpark on this bus.","このバスに乗れば球場に行けます。","ballpark"];
EXAMPLES[7774]=["He was put under anesthesia.","彼は麻酔をかけられた。","anesthesia"];
EXAMPLES[7786]=["I think I'll stay put in this town for a while.","しばらくこの町に腰を落ちつけようと思う。","put in"];
EXAMPLES[7788]=["He is a psycho.","彼はサイコだ。","psycho"];
EXAMPLES[7789]=["They look up to him as their benefactor.","彼らは彼を恩人として尊敬している。","benefactor"];
EXAMPLES[7802]=["Get your carcass out of here!","出ていけ。","carcass"];
EXAMPLES[7825]=["Money doesn't grow on trees, you know.","金のなる木はないんだよ。","grow on"];
EXAMPLES[7837]=["He was tense with his new business.","新しい仕事で彼は気が張っていた。","tense"];
EXAMPLES[7849]=["I'm cooked meals by my mother.","食事は母に作ってもらっている。","mother"];
EXAMPLES[7861]=["They were on the lookout for a storm.","彼らは嵐を警戒していた。","lookout"];
EXAMPLES[7897]=["This word is still in use.","この語はまだ使われている。","in use"];
EXAMPLES[7901]=["It's best to drink in moderation.","酒は飲んでも飲まれるな。","moderation"];
EXAMPLES[7919]=["Now, go about your study.","さあ、勉強に取りかかりなさい。","go about"];
EXAMPLES[7935]=["This was faulty information.","その情報には誤りがあった。","faulty"];
EXAMPLES[7965]=["His success is contingent upon his efforts.","彼の成功は努力次第だ。","contingent"];
EXAMPLES[7988]=["He purposed writing something for the paper.","彼は新聞に何か寄稿しようと思った。","writing"];
EXAMPLES[8008]=["Let's have a talk over a couple of drinks.","ちょっといっぱいやりながら話そう。","talk over"];
EXAMPLES[8030]=["Hum baby to sleep.","歌で子供を寝かしつける。","Hum"];
EXAMPLES[8055]=["He is not such a man as to flinch from danger.","彼は危険からしりごみするような人ではなかった。","flinch"];
EXAMPLES[8072]=["He has a nimble mind.","彼は頭の働きが早い。","nimble"];
EXAMPLES[8075]=["She is dearly loved by everybody.","彼女はみんなから深く愛されている。","dearly"];
EXAMPLES[8080]=["The weather is fickle.","気まぐれなお天気だ。","fickle"];
EXAMPLES[8126]=["He is lavish with his money.","彼は金を惜しみなく使う。","lavish"];
EXAMPLES[8166]=["I am apprehensive of the outcome.","結果がどうなるか心配だ。","apprehensive"];
EXAMPLES[8180]=["Health is indispensable to a happy life.","幸福な人生には健康が不可欠です。","indispensable"];
EXAMPLES[8187]=["You will debase yourself by such behavior.","そんなふるまいをすると安く見られますよ。","debase"];
EXAMPLES[8221]=["The accident happened because of the driver's negligence.","その事故は運転手の不注意から起きた。","negligence"];
EXAMPLES[8227]=["Frankly speaking, you are in the wrong.","正直言って君は間違っている。","Frankly speaking"];
EXAMPLES[8231]=["We asked ten people to the luncheon.","昼食会に１０人を招待した。","luncheon"];
EXAMPLES[8260]=["It's just too good to pass up.","これは絶対見逃せないよ。","pass up"];
EXAMPLES[8267]=["Peter didn't come after all.","ピーターは結局来なかった。","Peter"];
EXAMPLES[8271]=["We should hold old people in reverence.","我々は老人を敬わなければならない。","reverence"];
EXAMPLES[8285]=["Why did you call me at this unearthly hour?","どうしてこんなとんでもない時間に電話をするのだ。","unearthly"];
EXAMPLES[8287]=["I haven't heard a word from him as yet.","彼からはまだ何も言ってきていない。","as yet"];
EXAMPLES[8289]=["I put handcuffs on him.","私は彼に手錠をかけた。","handcuffs"];
EXAMPLES[8317]=["He's only shamming.","彼はただそういう振りをしているだけだ。","shamming"];
EXAMPLES[8328]=["That's a farce.","あれは茶番だ。","farce"];
EXAMPLES[8337]=["Don't scribble here.","ここに落書きするな。","scribble"];
EXAMPLES[8348]=["At that store, they deal in fish and meat.","あの店では、魚と肉を売っている。","deal in"];
EXAMPLES[8369]=["He is still on the payroll of the company.","彼はまだその会社に雇われている。","payroll"];
EXAMPLES[8373]=["The examination is close at hand.","試験がすぐ間近にせまっている。","at hand"];
EXAMPLES[8397]=["You're my good omen.","お守りはあなたよ。","omen"];
EXAMPLES[8398]=["The rain is teeming down.","土砂降りに降っている。","teeming"];
EXAMPLES[8414]=["After us the deluge.","後は野となれ山となれ。","deluge"];
EXAMPLES[8424]=["You can't back out of your responsibilities.","責任から逃れようことはできない。","back out"];
EXAMPLES[8431]=["I had a miscarriage last year.","去年流産しました。","miscarriage"];
EXAMPLES[8481]=["She consecrated her life to the work.","彼女はその仕事に一生を捧げた。","consecrated"];
EXAMPLES[8493]=["I've given my best for the company.","私は会社のために精一杯やってきた。","best for"];
EXAMPLES[8520]=["I am right for once.","今度こそは私が正しい。","for once"];
EXAMPLES[8549]=["This room has fine ventilation.","この部屋は風通しがよい。","ventilation"];
EXAMPLES[8565]=["He turned his coat inside out.","彼はコートを裏返した。","inside out"];
EXAMPLES[8584]=["He has distorted my speech.","彼は私の話をゆがめて伝えた。","distorted"];
EXAMPLES[8586]=["He acceded to my proposal.","彼は私の提案に同意した。","acceded"];
EXAMPLES[8612]=["They are scant of money.","彼らは金が不足している。","scant"];
EXAMPLES[8613]=["I burst into tears.","急に涙がこぼれてきた。","burst into"];
EXAMPLES[8623]=["He speaks with a lisp.","その子は舌足らずに話す。","lisp"];
EXAMPLES[8627]=["It is hardly conceivable to me that he will fail.","彼が失敗することは私にはまず考えられない。","conceivable"];
EXAMPLES[8647]=["The house was ablaze.","その家は燃えていた。","ablaze"];
EXAMPLES[8650]=["My eyes feel gritty.","目がゴロゴロします。","gritty"];
EXAMPLES[8666]=["Light has come into the world.","光が世にやって来た。","come into"];
EXAMPLES[8669]=["He is working intently.","彼は熱心に仕事をしている。","intently"];
EXAMPLES[8719]=["That child's free time is circumscribed.","その子供の自由時間は制限されている。","circumscribed"];
EXAMPLES[8720]=["I drank too much. my face is swollen!","飲み過ぎた！顔がむくんでる！","swollen"];
EXAMPLES[8764]=["We'll never live this fiasco down.","この失敗、きっと一生、言われつづけるなあ。","fiasco"];
EXAMPLES[8805]=["She had a touch of a cold last night.","昨晩彼女は風邪気味だった。","a touch of"];
EXAMPLES[8822]=["Father vouched for his friend.","父が友人の保証人となった。","vouched"];
EXAMPLES[8834]=["How do I get reimbursed?","払い戻しはどうしたらいいのですか。","reimbursed"];
EXAMPLES[8836]=["It's raining. you might just as well stay home.","雨が降っている。今日は家にいたら。","just as well"];
EXAMPLES[8845]=["Can't you bring down the price a bit?","もう少し安くならない？","bring down"];
EXAMPLES[8847]=["He is young, and yet he is prudent.","彼は若い、それなのに分別がある。","and yet"];
EXAMPLES[8855]=["I have a bruise.","打撲傷があります。","bruise"];
EXAMPLES[8880]=["She left her room in haste.","彼女は慌てて部屋を出ていった。","in haste"];
EXAMPLES[8883]=["The old man was plodding along.","老人がとぼとぼ歩いていた。","plodding"];
EXAMPLES[8894]=["I haven't touched a tennis racket in years.","ぼくはもう何年もテニスをやっていない。","in years"];
EXAMPLES[8897]=["I can sleep in peace after this.","これからは安心して眠れます。","sleep in"];
EXAMPLES[8901]=["There is little water left in the canteen.","水筒にはほとんど水が残っていない。","canteen"];
EXAMPLES[8919]=["A new road is under construction.","新しい道路が建設中である。","under construction"];
EXAMPLES[8924]=["This is true to life.","これは生き写しだ。","true to life"];
EXAMPLES[8935]=["Speak well of the dead.","死者はほめよ。","Speak well of"];
EXAMPLES[8941]=["The old man is the epitome of kindness.","その老人は非常に親切だ。","epitome"];
EXAMPLES[8949]=["He was absent owing to illness.","彼は病気のため欠席した。","owing to"];
EXAMPLES[8953]=["I'll sleep on it.","よく考えておきましょう。","sleep on"];
EXAMPLES[8958]=["Are you still in doubt about what I have said?","ぼくのことばをまだ疑っているんですか。","in doubt"];
EXAMPLES[8970]=["We looked for it high and low.","我々はあちこちそれを探した。","high and low"];
EXAMPLES[8974]=["I spring with a start.","ぎょっとして飛び上がる。","with a start"];
EXAMPLES[8977]=["He was in prison for life.","彼は死ぬまで刑務所にいた。","for life"];
EXAMPLES[8985]=["He will be back in a second.","彼は今すぐ帰ってきます。","in a second"];
EXAMPLES[9002]=["He forfeited his health.","彼は健康を失った。","forfeited"];
EXAMPLES[9018]=["In addition to English, he can speak French.","英語のほかに彼はフランス語も話せる。","In addition to"];
EXAMPLES[9022]=["He made amends for his mistakes.","彼は失敗の償いをした。","amends"];
EXAMPLES[9049]=["We call on her now and again.","私達は時たま彼女を訪ねる。","now and again"];
EXAMPLES[9051]=["He is a brute to his children.","彼は子供に残酷だ。","brute"];
EXAMPLES[9054]=["The teacher called the roll in class.","先生は出席を取った。","roll in"];
EXAMPLES[9059]=["Young people tend to think so.","若い人はそう考える傾向がある。","tend to"];
EXAMPLES[9062]=["I fall behind him in this respect.","この点で私は彼に劣る。","fall behind"];
EXAMPLES[9086]=["Clear away the table things.","テーブルの上を片づけなさい。","Clear away"];
EXAMPLES[9096]=["You should not interfere in other people's business.","他人の事に干渉しないほうがいいよ。","interfere in"];
EXAMPLES[9119]=["They worked around the clock.","彼らは昼夜休みなく働いた。","around the clock"];
EXAMPLES[9120]=["You can't wring any more money from me.","わたしからはこれ以上お金は絞り取れませんよ。","wring"];
EXAMPLES[9123]=["Everything will turn out for the best.","結局万事旨く行くだろう。","turn out for"];
EXAMPLES[9142]=["He was put through university with money left by his uncle.","彼は叔父の残したお金で大学を卒業した。","put through"];
EXAMPLES[9144]=["We've been friends ever since.","以来ずっと友人です。","ever since"];
EXAMPLES[9159]=["He tried to be less obtrusive.","彼はでしゃばらないようにしようとした。","obtrusive"];
EXAMPLES[9161]=["The sun is shining in the sky.","空には太陽が輝いています。","shining"];
EXAMPLES[9176]=["An eye for an eye, a tooth for a tooth.","目には目を、歯には歯を。","An eye for an eye"];
EXAMPLES[9184]=["Do you engage in any sport?","君は何かスポーツをやりますか。","engage in"];
EXAMPLES[9188]=["I think I'll stay put in this town for a while.","しばらくこの町に腰を落ちつけようと思う。","stay put"];
EXAMPLES[9192]=["He was impertinent to his father.","彼は父親に生意気な事を言った。","impertinent"];
EXAMPLES[9194]=["We've really hit it off.","今のところ本当に旨く行っているわ。","hit it off"];
EXAMPLES[9197]=["I could not make up my mind out of hand.","私はすぐには決心することができなかった。","out of hand"];
EXAMPLES[9205]=["Don't go to extremes.","極端に走ってはならない。","go to extremes"];
EXAMPLES[9216]=["My cat has come out from under the table.","私の猫がテーブルの下から出てきた。","under the table"];
EXAMPLES[9248]=["Such an idea is abhorrent to her.","彼女はそうした考えをひどく嫌う。","abhorrent"];
EXAMPLES[9256]=["It's all right to drink, but drink in moderation.","酒もいいが大概にしておきなさい。","drink in"];
EXAMPLES[9266]=["He works hard so as to succeed.","彼は成功のために熱心に勉強する。","so as to"];
EXAMPLES[9285]=["We must make do with what we have got.","我々は、手持ちのもので間に合わせなければならない。","make do with"];
EXAMPLES[9291]=["I had a quarrel with my sister","僕は姉と口喧嘩をした。","quarrel with"];
EXAMPLES[9307]=["He changed his mind in consequence of the marriage.","結婚の結果、彼は心が変わった。","in consequence"];
EXAMPLES[9318]=["He was incredulous of the story.","彼はその話を信じなかった。","incredulous"];
EXAMPLES[9323]=["Let's drink to his success.","彼の成功を祈って乾杯しよう。","drink to"];
EXAMPLES[9347]=["I do not have much money on hand.","私はあまりお金を持ち合わせていない。","on hand"];
EXAMPLES[9354]=["Don't associate with them.","彼らと交わるな。","associate with"];
EXAMPLES[9360]=["That was a close call.","間一髪！危ないところでした。","close call"];
EXAMPLES[9365]=["You must, above all, be faithful to your friends.","何よりもまず友人に誠実でなければならない。","be faithful to"];
EXAMPLES[9368]=["I hope I can hold on to my job.","会社をクビにならなきゃいいけどね。","hold on to"];
EXAMPLES[9374]=["You must not come in contact with him.","彼と接触してはいけない。","come in contact with"];
EXAMPLES[9375]=["The plans are still up in the air.","計画はまだ未定である。","up in the air"];
EXAMPLES[9386]=["Let's ease up.","息抜きをしようよ。","ease up"];
EXAMPLES[9391]=["You look very dignified.","貫禄がついたね。","dignified"];
EXAMPLES[9412]=["You may get it free of charge.","無料でそれが得られる。","free of charge"];
EXAMPLES[9428]=["She lay in bed all the time.","彼女はずっと寝ていました。","lay in"];
EXAMPLES[9448]=["When it comes to making things, I'm all thumbs.","物を作るとなると、私は不器用です。","When it comes to"];
EXAMPLES[9450]=["What is the child up to now?","今度はあの子は何をねらっているのか。","up to now"];
EXAMPLES[9453]=["I hiccup a lot.","しゃっくりがよく出ます。","hiccup"];
EXAMPLES[9454]=["What do your words add up to?","結局お言葉はどういう意味になるのですか。","add up"];
EXAMPLES[9459]=["He made ten blunders in as many lines.","彼は１０行で１０もの間違いをやった。","blunders"];
EXAMPLES[9461]=["It's a cinch to learn to swim.","泳ぎを身につけるのは簡単なことだ。","cinch"];
EXAMPLES[9462]=["What sports do you go in for?","どのようなスポーツをなさいますか。","go in for"];
EXAMPLES[9468]=["Don't meddle in other people's affair.","人の事に手を出すな。","meddle"];
EXAMPLES[9481]=["You must go through with your plan.","君は計画を遣り通さなければならない。","go through with"];
EXAMPLES[9488]=["He is quite at home with computers.","彼はコンピューターに精通している。","at home with"];
EXAMPLES[9505]=["My mother tongue is Japanese.","私の母語は日本語です。","mother tongue"];
EXAMPLES[9506]=["He makes everybody feel at ease.","彼はみんなの気持ちを楽にしてくれます。","at ease"];
EXAMPLES[9514]=["As is often the case with her, she broke her promise.","彼女にはよくある事だが、約束を破った。","As is"];
EXAMPLES[9517]=["Let's not deviate from the subject.","本題からそれないようにしましょう。","deviate"];
EXAMPLES[9520]=["Don't lean on my desk.","私の机によりかかるな。","lean on"];
EXAMPLES[9544]=["She blanched at the bad news.","彼女はその悪い知らせを聞いて青くなった。","blanched"];
EXAMPLES[9549]=["I do beseech you, hear me through.","お願いいたします、最後までお聞きください。","beseech"];
EXAMPLES[9552]=["Don't hesitate to ask if you want anything.","欲しいものがあれば遠慮なく言いなさい。","hesitate to"];
EXAMPLES[9571]=["This answer may not necessarily be wrong.","この答えが必ずしも間違いとは限らないだろう。","not necessarily"];
EXAMPLES[9576]=["He decided to give up smoking once and for all.","彼はきっぱり煙草を止めようと決心した。","once and for all"];
EXAMPLES[9586]=["Let's stop off and see a movie.","映画でも見ていこうか。","stop off"];
EXAMPLES[9589]=["It is no less than ten miles to the hospital.","病院まで１０マイルもある。","no less than"];
EXAMPLES[9598]=["I visit my friend's house at intervals.","私は時々友達の家を訪ねる。","at intervals"];
EXAMPLES[9606]=["The dog was frozen to death.","その犬は凍死した。","to death"];
EXAMPLES[9609]=["No one knows what has become of her.","彼女はどうなったのか誰も知らない。","become of"];
EXAMPLES[9612]=["Hang in there, and you can do it.","頑張れよ、そうすればできるから。","Hang in"];
EXAMPLES[9624]=["I cannot consent to your going alone.","あなたが一人で行くことに同意できない。","consent to"];
EXAMPLES[9628]=["Either way's fine with me.","私はどちらでも結構です。","Either way"];
EXAMPLES[9641]=["I'm sometimes in a bad temper.","私は時々機嫌が悪くなる。","in a bad temper"];
EXAMPLES[9643]=["I got the gist of what he was saying.","彼が言っていることの要点はわかった。","gist"];
EXAMPLES[9655]=["At length, I found his house.","私はやっと彼の家を見つけた。","At length"];
EXAMPLES[9666]=["He is good for nothing.","彼は何の役にも立たない。","good for nothing"];
EXAMPLES[9680]=["I worked hand in hand with him.","私は彼と協力して仕事をした。","hand in hand with"];
EXAMPLES[9682]=["We hope she will take heart soon.","彼女がすぐに元気になるといいのだが。","take heart"];
EXAMPLES[9684]=["This problem is difficult for me to some degree.","この問題は私にとっては幾分難しい。","to some degree"];
EXAMPLES[9693]=["This dress creases easily.","この服はすぐしわになる。","creases"];
EXAMPLES[9701]=["I wonder which way to go.","どちらへ行けばよいのだろう。","way to go"];
EXAMPLES[9728]=["I tried to get it, but to no purpose.","私はそれを得ようとしたが、無駄だった。","to no purpose"];
EXAMPLES[9743]=["He took the car on trial.","彼は試しにその車に乗ってみた。","on trial"];
EXAMPLES[9774]=["She went to austria for the purpose of studying music.","彼女は音楽の勉強をするためにオーストリアに行った。","for the purpose of"];
EXAMPLES[9812]=["Why does it draw out lunch every day?","なぜ毎日昼食を抜くのですか。","draw out"];
EXAMPLES[9821]=["The man was on the brink of death.","その男は死にかけていた。","on the brink of"];
EXAMPLES[9834]=["Love me lithe, love me long.","細く長く愛して。","lithe"];
EXAMPLES[9835]=["He had enough to do to catch up on his work.","彼はどうやらやっと仕事の遅れを取りもどした。","catch up on"];
EXAMPLES[9844]=["She is estranged from her parents.","彼女は両親とうまくいっていない。","estranged"];
EXAMPLES[9849]=["Drink up your milk.","ミルクを全部飲んでしまいなさい。","Drink up"];
EXAMPLES[9868]=["This was his one and only hope.","これが彼のたった一つの希望であった。","one and only"];
EXAMPLES[9881]=["Fish cannot live out of water.","魚は水の外では生きられない。","live out"];
EXAMPLES[9886]=["I bump into her.","彼女と偶然出会う。","bump into"];
EXAMPLES[9889]=["It leaves nothing much to be desired.","それは遺憾なところが多い。","nothing much"];
EXAMPLES[9894]=["Ten to one he will get married to her.","十中八、九まで彼は彼女と結婚するだろう。","Ten to one"];
EXAMPLES[9898]=["There is quite a bit of water remaining.","水はかなり多く残っている。","quite a bit"];
EXAMPLES[9900]=["Let's play truant and go to see the movie.","学校をずる休みし、その映画を見に行こう。","truant"];
EXAMPLES[9902]=["She was on the verge of crying.","彼女は今にも泣き出しそうだった。","on the verge of"];
EXAMPLES[9929]=["He was to all appearances a strong man.","彼はどう見ても実力者だ。","to all appearances"];
EXAMPLES[9939]=["My mother used to be into tennis.","母はかつてテニスに夢中だった。","be into"];
EXAMPLES[9941]=["He is popular with the people at large.","彼は一般に人々に人気がある。","at large"];
EXAMPLES[9949]=["We enjoyed ourselves to the full.","我々は心ゆくまで楽しんだ。","to the full"];
EXAMPLES[9955]=["I'm afraid she may have the mumps.","おたふく風邪ではないでしょうか。","mumps"];
EXAMPLES[9957]=["He worked at the cost of his own time.","彼は自分の時間を犠牲にして働いた。","at the cost of"];
EXAMPLES[9970]=["His play ended in large success.","彼の芝居は大成功に終わった。","in large"];
EXAMPLES[9973]=["It was sultry last night.","昨夜は暑くるしかった。","sultry"];
EXAMPLES[9992]=["The little boy disappeared down the road.","その少年は通りの先の方で見えなくなった。","down the road"];
EXAMPLES[9995]=["He took a glance at the girl.","彼は少女をちらっと見た。","glance at"];
EXAMPLES[10005]=["I saw my sister tear up the letter.","私は姉がその手紙をひきさくのを見た。","tear up"];
EXAMPLES[10024]=["Keep an eye on the baby while I am away.","僕がいない間、この赤ちゃんをお願いするよ。","Keep an eye on"];
EXAMPLES[10030]=["Don't talk so impudently.","ずうずうしいことを言うな。","impudently"];
EXAMPLES[10034]=["He is very mercenary.","彼はとても打算的だ。","mercenary"];
EXAMPLES[10036]=["That is the sort of job I am cut out for.","それは僕にうってつけの仕事だ。","cut out for"];
EXAMPLES[10038]=["The old man was hard of hearing.","その老人は耳が遠かった。","hard of hearing"];
EXAMPLES[10043]=["Let's keep in touch.","交際を続けましょう。","keep in"];
EXAMPLES[10075]=["Have an old head on young shoulders.","若いのにしっかりしている。","head on"];
EXAMPLES[10076]=["We walked three abreast.","私達は三人並んで歩いた。","abreast"];
EXAMPLES[10078]=["Spring is just around the corner.","春はすぐそこまで来ている。","around the corner"];
EXAMPLES[10093]=["Beware of the dog!","猛犬に注意！","Beware of"];
EXAMPLES[10098]=["Don't interfere with her.","彼女のじゃまをしないでくれ。","interfere with"];
EXAMPLES[10109]=["Don't live off your sister any more.","これ以上姉さんのすねかじりはやめたまえ！","live off"];
EXAMPLES[10112]=["I did nothing out of the ordinary.","おかしなことは何もしなかった。","out of the ordinary"];
EXAMPLES[10160]=["The accident bereaved her of her son.","事故は彼女から息子さんを奪った。","bereaved"];
EXAMPLES[10221]=["He is obstinate in his opinion.","彼は絶対に意見を変えない。","obstinate"];
EXAMPLES[10248]=["Don't let the cat out of the bag.","秘密を漏らしてはいけない。","let the cat out of the bag"];
EXAMPLES[10278]=["We queued up for the bus.","私たちは一列にならんでバスを待った。","queued"];
EXAMPLES[10288]=["The storm didn't abate for several hours.","嵐は数時間静まらなかった。","abate"];
EXAMPLES[10337]=["He is very zealous in his study of English.","彼は英語の勉強に非常に熱心です。","zealous"];
EXAMPLES[10356]=["Don't try to pass the buck.","責任逃れをするな。","pass the buck"];
EXAMPLES[10373]=["Let's hit the hay.","じゃあ寝ようよ。","hit the hay"];
EXAMPLES[10379]=["He absconded with the money.","彼はその金を持ち逃げした。","absconded"];
EXAMPLES[10380]=["He was bereft of all hope.","彼はあらゆる希望を失った。","bereft"];
EXAMPLES[10384]=["I always have to give in to him.","私はいつも彼に服従しなければならない。","give in to"];
